/* eslint-disable quote-props, max-len */
// German NPC texts. Keys are the English dialog lines and NPC names.
// [[pokemon::Name]] inserts the translated Pokémon name.

export const bundledNpcDialogsDe: Record<string, string> = {
    // The Air Mail
    'Oh no, oh no... Champion! You came at just the right time!': 'Oje, oje ... Champ! Du kommst genau richtig!',
    'Our delivery Pokémon caught a cold and the mail for Pewter City, Cerulean City and Lavender Town is piling up.': 'Unser Liefer-Pokémon hat sich erkältet, und die Post für Pewter City, Cerulean City und Lavender Town stapelt sich.',
    'Could you deliver these three letters for me? I would be so grateful!': 'Könntest du diese drei Briefe für mich zustellen? Ich wäre dir so dankbar!',
    'A letter for me? From my brother in Vermilion City! Thank you, that was quick!': 'Ein Brief für mich? Von meinem Bruder aus Vermilion City! Danke, das ging aber schnell!',
    'Is that the fishing magazine I ordered? Finally! Now I know where the big ones bite.': 'Ist das die Angelzeitschrift, die ich bestellt habe? Endlich! Jetzt weiß ich, wo die Großen beißen.',
    'A postcard from my grandson... He writes that his Dratini learned to fly. Dratini can\'t fly, can it? Hohoho!': 'Eine Postkarte von meinem Enkel ... Er schreibt, sein [[pokemon::Dratini]] hat fliegen gelernt. [[pokemon::Dratini]] kann doch gar nicht fliegen, oder? Hohoho!',
    'You delivered everything and even got the stolen letters back from those bird Pokémon? Amazing!': 'Du hast alles zugestellt und sogar die gestohlenen Briefe von den Vogel-Pokémon zurückgeholt? Großartig!',
    'Look, this little one hatched at our office. It has been wearing my old cap ever since and follows every mail bag around.': 'Schau mal, dieser Kleine ist bei uns im Büro geschlüpft. Seitdem trägt er meine alte Mütze und folgt jeder Posttasche.',
    'I think it wants to deliver mail with you. Please take good care of our little postman Dratini!': 'Ich glaube, er will mit dir Post austragen. Pass gut auf unseren kleinen [[pokemon::Dratini (Postman)]] auf!',
    'Good of you to come see me. I need you to pick up something for me. A special kind of Poké Ball, found by Professor Ivy. She lives on one of the Sevii Islands, east of Three Island.': 'Schön, dass du vorbeischaust. Ich möchte dich bitten, etwas für mich abzuholen. Eine besondere Art Pokéball, gefunden von Professor Ivy. Sie lebt auf einer der Sevii Islands, östlich von Three Island.',
    'I don\'t know who else to trust with this. It\'s very important and very valuable.': 'Ich wüsste nicht, wem ich das sonst anvertrauen könnte. Es ist sehr wichtig und sehr wertvoll.',
    'Feel free to take your time, but please don\'t get distracted for the duration of an entire filler anime season.': 'Lass dir ruhig Zeit, aber bitte lass dich nicht eine ganze Filler-Staffel lang ablenken.',
    'Ah, the fabled GS Ball. Let me have a look.': 'Ah, der sagenumwobene GS-Ball. Lass mich mal sehen.',
    'Hm. I just can\'t figure this out. There\'s clearly something inside, but I just can\'t get the darned thing to open.': 'Hm. Ich werde einfach nicht schlau daraus. Da ist eindeutig etwas drin, aber ich bekomme das verflixte Ding einfach nicht auf.',
    'I know just the man for the job! Kurt, a Poké Ball expert. He lives in Azalea Town, in Johto. Please deliver the GS Ball to him.': 'Ich kenne genau den richtigen Mann dafür! Kurt, ein Pokéball-Experte. Er lebt in Azalea Town in Johto. Bitte bring ihm den GS-Ball.',
    'So you\'re really leaving on your very own Pokémon journey. I\'m so proud of you. Let me give you some words of wisdom for your travels.': 'Du brichst also wirklich zu deiner eigenen Pokémon-Reise auf. Ich bin so stolz auf dich. Lass mich dir ein paar weise Worte mit auf den Weg geben.',
    'Traveling on your own can be scary. But remember that there are nice people everywhere you go. So strike up a conversation! You will probably learn something useful.': 'Allein zu reisen kann beängstigend sein. Aber denk daran, dass es überall nette Leute gibt. Also sprich sie ruhig an! Du wirst bestimmt etwas Nützliches lernen.',
    'Remember that there are nice people everywhere you go. So strike up a conversation! You will probably learn something useful.': 'Denk daran, dass es überall nette Leute gibt. Also sprich sie ruhig an! Du wirst bestimmt etwas Nützliches lernen.',
    'Leave me alone. I need my coffee.': 'Lass mich in Ruhe. Ich brauche meinen Kaffee.',
    'Ahh, I\'ve had my coffee now and I feel great!': 'Ahh, jetzt habe ich meinen Kaffee getrunken und fühle mich großartig!',
    'You can use the Poké Ball Selector to select which type of Poké Ball to use on specific Pokémon based on caught status.': 'Mit der Pokéball-Auswahl kannst du festlegen, welche Art Pokéball du je nach Fangstatus auf bestimmte Pokémon wirfst.',
    'For example, if you click on the empty ball next to the word "Caught" and assign a Poké Ball, you will then start throwing Poké Balls at Pokémon you\'ve already caught before. This can be very useful if you need Dungeon Tokens.': 'Wenn du zum Beispiel auf den leeren Ball neben dem Wort „Gefangen“ klickst und einen Pokéball zuweist, wirfst du ab dann Pokébälle auf Pokémon, die du schon einmal gefangen hast. Das kann sehr nützlich sein, wenn du Dungeon-Token brauchst.',
    'Here, let me show you how it works.': 'Hier, ich zeige dir, wie das funktioniert.',
    'I\'ll always be here to explain it again if you forget.': 'Ich bin immer hier, um es dir noch einmal zu erklären, falls du es vergisst.',
    'So, you said you want to know where you might find Mewtwo\'s Mega Stones, right?': 'Du wolltest also wissen, wo du [[pokemon::Mewtwo]]s Mega-Steine finden könntest, richtig?',
    'Well, you\'re in luck! I was talking to an old rival of mine the other day, and she said she was looking for Mewtwo, and that she already had two of its Mega Stones. Unfortunately for her, they were the same one.': 'Da hast du Glück! Ich habe neulich mit einer alten Rivalin von mir gesprochen. Sie sagte, sie sei auf der Suche nach [[pokemon::Mewtwo]] und hätte schon zwei seiner Mega-Steine. Pech für sie: Es waren zweimal dieselben.',
    'Not much use in having two of the same Mega Stone, so she might be willing to give one up. If you want to find her, you should check out Cerulean Cave.': 'Zweimal denselben Mega-Stein zu haben bringt nicht viel, also gibt sie vielleicht einen davon ab. Wenn du sie finden willst, sieh dich mal in der Cerulean Cave um.',
    'Hey kid, you look new! Let me offer some advice: Battle Items like X Attack can be acquired along Routes, inside Dungeons and in Shops!': 'Hey, du siehst neu aus! Lass mich dir einen Tipp geben: Kampf-Items wie X-Angriff bekommst du auf Routen, in Dungeons und in Shops!',
    'Use them to help you out whenever you feel like time is against you!': 'Setz sie ein, wann immer du das Gefühl hast, dass dir die Zeit davonläuft!',
    'I say, the trek from here to Cerulean City can be a tiring one.': 'Also wirklich, der Weg von hier nach Cerulean City kann ganz schön ermüdend sein.',
    'If it wasn\'t for the Pokémon Center outside Mt. Moon, I don\'t think I\'d ever make it!': 'Wäre da nicht das Pokémon Center vor dem Mt. Moon, ich würde es wohl nie schaffen!',
    '...What\'s that? You\'ve never seen a Pokémon Center there?': '...Wie bitte? Du hast dort noch nie ein Pokémon Center gesehen?',
    'Hmm, it is somewhat out of the way. Maybe if you look closer?': 'Hmm, es liegt etwas abseits. Vielleicht musst du genauer hinsehen?',
    'I see you are carrying a Gem Case. Here at the museum we study space, fossils and gems!': 'Wie ich sehe, trägst du eine Juwelentasche bei dir. Hier im Museum erforschen wir den Weltraum, Fossilien und Juwelen!',
    'When you defeat a Pokémon you gain a gem of that Pokémon\'s type. If the Pokémon has two types you gain one for each! Defeating very strong Pokémon, such as those owned by gym leaders, gets you five!': 'Wenn du ein Pokémon besiegst, erhältst du ein Juwel seines Typs. Hat das Pokémon zwei Typen, bekommst du für jeden eines! Für sehr starke Pokémon, etwa die von Arenaleitern, bekommst du sogar fünf!',
    'You can click Gems in the Start Menu to boost your damage using these gems. For example, using rock gems you can boost the super effective damage of your rock type Pokémon! Those flying types had better watch out for your might!': 'Klicke im Start Menu auf „Juwelen“, um mit diesen Juwelen deinen Schaden zu erhöhen. Mit Gesteinjuwelen kannst du zum Beispiel den sehr effektiven Schaden deiner Gestein-Pokémon verstärken! Da sollten sich Flug-Pokémon vor deiner Stärke in Acht nehmen!',
    'You can even use this to eliminate immunities! By using electric gems to boost your electric type immune damage, your electric Pokémon can suddenly do damage against ground types!': 'Damit kannst du sogar Immunitäten aufheben! Wenn du mit Elektrojuwelen den Schaden deiner Elektro-Pokémon gegen immune Typen verstärkst, können sie plötzlich auch Boden-Pokémon Schaden zufügen!',
    'Have I got a deal just for you!': 'Hab ich ein Angebot für dich!',
    'I\'ll let you have a super secret Pokémon. For the right price! Buying this pokemon Takes No Effort, you should Value it.': 'Ich überlasse dir ein supergeheimes Pokémon. Zum richtigen Preis! Dieses Pokémon zu kaufen Kostet Keine Mühe, du solltest es Wertschätzen.',
    'Bah! You younglings have no appreciation of the art of Berry farming!': 'Pah! Ihr jungen Hüpfer wisst die Kunst des Beerenanbaus einfach nicht zu schätzen!',
    'Come back when you are ready to learn!': 'Komm wieder, wenn du bereit bist zu lernen!',
    'One day I was tending to my Passho berries and a Squirtle suddenly appeared! If only I knew about this before spending all of my Quest Points on Water Eggs..': 'Eines Tages kümmerte ich mich um meine Kerzalbeeren, und plötzlich tauchte ein [[pokemon::Squirtle]] auf! Hätte ich das nur gewusst, bevor ich all meine Questpunkte für Wasser-Eier ausgegeben habe...',
    'If I try mutating different berries maybe I can catch new Pokémon while saving my Quest Points!': 'Wenn ich versuche, verschiedene Beeren mutieren zu lassen, kann ich vielleicht neue Pokémon fangen und dabei meine Questpunkte sparen!',
    'In my spare time I like to play this kickass browser game. It takes ages to get all the best stuff.': 'In meiner Freizeit spiele ich gern dieses mega geile Browserspiel. Es dauert ewig, bis man all die besten Sachen hat.',
    'Then one day, all my progress was gone. I don\'t know exactly what happened. Something updated, some cookies got cleaned up, I don\'t know. I had to start all over from the beginning.': 'Und eines Tages war mein ganzer Fortschritt weg. Ich weiß nicht genau, was passiert ist. Irgendein Update, irgendwelche Cookies wurden gelöscht, keine Ahnung. Ich musste ganz von vorne anfangen.',
    'That day I learned that I should frequently download a save.': 'An diesem Tag habe ich gelernt, dass man regelmäßig einen Spielstand herunterladen sollte.',
    'You were wise to seek me out. Howard Clifford has been deceiving you. He is the one making the R drug, and....': 'Es war klug von dir, mich aufzusuchen. Howard Clifford hat dich getäuscht. Er ist derjenige, der die Droge R herstellt, und....',
    '<i>A sphere of energy envelops Mewtwo, and he is dragged away by some sort of helicopter. The helicopter has a logo on it: Clifford Industries!</i>': '<i>Eine Energiekugel umhüllt [[pokemon::Mewtwo]] und es wird von einer Art Hubschrauber davongezogen. Auf dem Hubschrauber prangt ein Logo: Clifford Industries!</i>',
    'Thank you for your help. I have little to offer you in return, but perhaps this will help.': 'Danke für deine Hilfe. Ich habe dir wenig im Gegenzug zu bieten, aber vielleicht hilft dir das hier.',
    'I found Detective Pikachu\'s partner some days ago injured on the side of the road, and have nursed him back to health. I hope this reunion will suffice.': 'Ich habe den Partner von [[pokemon::Detective Pikachu]] vor einigen Tagen verletzt am Straßenrand gefunden und ihn gesund gepflegt. Ich hoffe, dieses Wiedersehen genügt.',
    'Thanks for your help, kid! I\'ll stick along with you until our next mystery comes along.': 'Danke für deine Hilfe, Kleiner! Ich bleibe bei dir, bis unser nächstes Rätsel auftaucht.',
    'Oh, a visitor! Come in, come in. You won\'t believe what I found while working on my PC system.': 'Oh, Besuch! Komm rein, komm rein. Du glaubst nicht, was ich bei der Arbeit an meinem PC-System entdeckt habe.',
    'When I transferred a Ditto, its DNA got mixed with another Pokémon in the transfer stream. For a moment there was a creature that was both at once!': 'Als ich ein [[pokemon::Ditto]] übertragen habe, hat sich seine DNA im Übertragungsstrom mit einem anderen Pokémon vermischt. Für einen Moment gab es ein Wesen, das beides zugleich war!',
    'I think I can rebuild that by accident on purpose. I need fresh Ditto DNA and a lot of energy - the strange energy deep inside Cerulean Cave should do.': 'Ich glaube, ich kann das absichtlich aus Versehen nachbauen. Ich brauche frische [[pokemon::Ditto]]-DNA und jede Menge Energie – die seltsame Energie tief in der Cerulean Cave sollte reichen.',
    'You did it! Ditto DNA and Cerulean Cave energy... let me just plug this in... and...': 'Du hast es geschafft! [[pokemon::Ditto]]-DNA und Energie aus der Cerulean Cave... ich schließe das nur kurz an... und...',
    'It worked! The fusions are stable - but they can only exist inside the fusion space I opened. It is a whole little world of its own!': 'Es hat funktioniert! Die Fusionen sind stabil – aber sie können nur in dem Fusionsraum existieren, den ich geöffnet habe. Das ist eine ganz eigene kleine Welt!',
    'I prepared three fusion partners for you. Pick one and explore the Fusion Island. Everything you do there stays there.': 'Ich habe drei Fusionspartner für dich vorbereitet. Wähle einen aus und erkunde die Fusion Island. Alles, was du dort tust, bleibt auch dort.',
    'Hm? You know Bill? He\'s my grandson. He\'s not here right now. He does something with PCs, so I\'m house-sitting.': 'Hm? Du kennst Bill? Er ist mein Enkel. Er ist gerade nicht da. Er macht irgendwas mit PCs, also hüte ich das Haus.',
    'I like Pokémon but I\'m not as knowledgeable as my grandson. My grandson Bill told me about a Pokémon that is pink and like a balloon.': 'Ich mag Pokémon, aber ich weiß nicht so viel wie mein Enkel. Mein Enkel Bill hat mir von einem Pokémon erzählt, das rosa ist und wie ein Ballon aussieht.',
    'Would you catch that Pokémon and show it to me, please?': 'Würdest du dieses Pokémon bitte fangen und es mir zeigen?',
    'Ah, so that is Jigglypuff? Isn\'t it cute! That\'s so kind of you. Thanks! This Moon Stone is a token of my appreciation.': 'Ah, das ist also [[pokemon::Jigglypuff]]? Ist das nicht niedlich! Wie lieb von dir. Danke! Dieser Mondstein ist ein Zeichen meiner Dankbarkeit.',
    'Ah, my grandson mentioned a round, green Pokémon, wait not green, it\'s blue, a blue Pokémon that has leaves growing on its head.': 'Ah, mein Enkel hat ein rundes, grünes Pokémon erwähnt, nein, warte, nicht grün, blau, ein blaues Pokémon, dem Blätter auf dem Kopf wachsen.',
    'If you encounter that Pokémon and catch it, would you, please, bring it here?': 'Wenn du diesem Pokémon begegnest und es fängst, würdest du es bitte herbringen?',
    'Oh, the Pokémon was called Oddish? It is adorable! Thank you so much for bringing it to me! Please, accept this Leaf Stone.': 'Oh, das Pokémon heißt [[pokemon::Oddish]]? Es ist hinreißend! Vielen Dank, dass du es mir gebracht hast! Bitte nimm diesen Blattstein an.',
    'By the way, do you know of a sea Pokémon that has a red sphere on its body? You know, the one that\'s shaped like a star?': 'Übrigens, kennst du ein Meeres-Pokémon mit einer roten Kugel am Körper? Du weißt schon, das, das wie ein Stern geformt ist?',
    'When you get one, could you, please, come back here so I can see it?': 'Wenn du eins hast, könntest du dann bitte wiederkommen, damit ich es sehen kann?',
    'Ah, you brought it to me. Staryu is the name, you said? It\'s certainly shaped like a star. You are so kind for coming back with it! This Water Stone should be really useful to you.': 'Ah, du hast es mir gebracht. [[pokemon::Staryu]] heißt es, sagst du? Es ist wirklich wie ein Stern geformt. Wie nett, dass du damit zurückgekommen bist! Dieser Wasserstein sollte dir sehr nützlich sein.',
    'I was thinking, Bill told me about a Pokémon that is very loyal to its trainer. It\'s supposed to roar well.': 'Ich habe nachgedacht, Bill hat mir von einem Pokémon erzählt, das seinem Trainer sehr treu ist. Es soll gut brüllen können.',
    'I would really like to meet one, can you stop by if you capture one, please?': 'Ich würde wirklich gern eins kennenlernen. Kannst du bitte vorbeikommen, wenn du eins fängst?',
    'Ah, so this little puppy is Growlithe? I cannot begin to imagine its roaring! I\'m so happy that you are doing all this for me. Thank you so much! I was saving this Fire Stone for a rainy day, but I want you to have it instead.': 'Ah, dieser kleine Welpe ist also [[pokemon::Growlithe]]? Ich kann mir sein Gebrüll gar nicht vorstellen! Ich freue mich so, dass du das alles für mich tust. Vielen Dank! Diesen Feuerstein hatte ich für schlechte Zeiten aufgehoben, aber ich möchte, dass du ihn bekommst.',
    'Did you think I was done by the way? I wanted to ask if you knew that hugely popular Pokémon? The Pokémon that has a yellow body and red cheeks. I would love to see what it looks like.': 'Dachtest du etwa, ich wäre schon fertig? Ich wollte fragen, ob du dieses unglaublich beliebte Pokémon kennst? Das Pokémon mit dem gelben Körper und den roten Backen. Ich würde zu gern sehen, wie es aussieht.',
    'This is the one I\'m most excited to meet. Please come back once you catch it, I will have tea prepared for you.': 'Auf dieses Pokémon freue ich mich am meisten. Bitte komm wieder, sobald du es gefangen hast, ich mache dir dann einen Tee.',
    'Yes! That\'s the one! It\'s Pikachu, right? Ohhh, I\'ve wanted to meet it for so long. Such a cutie. You deserve this Thunder Stone!': 'Ja! Das ist es! Das ist [[pokemon::Pikachu]], richtig? Ohhh, ich wollte es schon so lange kennenlernen. So ein Schnuckel. Du hast dir diesen Donnerstein verdient!',
    'You\'ve shown me everything I wanted to see and more. You have been a very nice trainer! My grandson could learn one thing or two from you, ho, ho!': 'Du hast mir alles gezeigt, was ich sehen wollte, und noch mehr. Du bist ein sehr netter Trainer! Mein Enkel könnte sich von dir noch das ein oder andere abschauen, ho, ho!',
    'There is one more thing I would like to ask you, would you battle this old man? I promise I\'ll make it worth your while. Let\'s go outside.': 'Eine Sache möchte ich dich noch fragen: Würdest du gegen diesen alten Mann kämpfen? Ich verspreche dir, es wird sich für dich lohnen. Gehen wir nach draußen.',
    'Let me tell you though, in my youth, I was strong enough to beat Viridian City\'s Gym, so don\'t expect me to be a pushover.': 'Aber lass dir gesagt sein: In meiner Jugend war ich stark genug, um die Arena von Viridian City zu besiegen, also rechne nicht damit, dass ich leichte Beute bin.',
    'As I said, that was one of the best battles I\'ve ever had.': 'Wie gesagt, das war einer der besten Kämpfe, die ich je hatte.',
    'There is someone I would like to go with you, it\'s my partner, Eevee.': 'Da ist jemand, der dich begleiten soll: mein Partner, [[pokemon::Eevee]].',
    'I think Eevee is gonna be better with you than with me. I\'m sure that, with you, Eevee is gonna grow up healthy and strong!': 'Ich glaube, [[pokemon::Eevee]] ist bei dir besser aufgehoben als bei mir. Ich bin mir sicher, dass [[pokemon::Eevee]] bei dir gesund und stark heranwachsen wird!',
    'Hello again, I see you are treating Eevee very well.': 'Hallo nochmal, wie ich sehe, behandelst du [[pokemon::Eevee]] sehr gut.',
    'I\'m still house-sitting for my grandson, I\'m sure he\'s doing well.': 'Ich hüte immer noch das Haus für meinen Enkel, ich bin sicher, es geht ihm gut.',
    'Puff, puff... I am...no match for you. ...As I predicted.': 'Puh, puh... Ich bin... dir nicht gewachsen. ...Wie ich es vorhergesehen habe.',
    'Go ahead. Since I met you in Ecruteak City, I\'ve sort of known that Suicune would choose you.': 'Nur zu. Seit ich dich in Ecruteak City getroffen habe, habe ich irgendwie geahnt, dass [[pokemon::Suicune]] dich wählen würde.',
    'Take a look at it! Suicune is still there waiting for you! It has been waiting for a worthy Trainer to whom it can entrust itself!': 'Sieh es dir an! [[pokemon::Suicune]] wartet dort immer noch auf dich! Es hat auf einen würdigen Trainer gewartet, dem es sich anvertrauen kann!',
    'Did you find all of the Santa Jynx?': 'Hast du alle [[pokemon::Santa Jynx]] gefunden?',
    'I hope they don\'t come back!': 'Ich hoffe, sie kommen nicht wieder!',
    'You won’t find a Pokémon as wonderful as my favorite Rapidash in those Typed Eggs in the shops, but they might hatch rare Pokémon you can’t find anywhere else!': 'In den Typ-Eiern aus den Shops wirst du kein so wundervolles Pokémon wie mein geliebtes [[pokemon::Rapidash]] finden, aber vielleicht schlüpfen daraus seltene Pokémon, die du nirgendwo sonst findest!',
    'Are you looking for some Shards? You can find them in many Dungeons! Except in Viridian Forest and Mt. Moon. I\'ve never found any Shards there for some reason.': 'Suchst du Scherben? Die findest du in vielen Dungeons! Außer im Viridian Forest und im Mt. Moon. Dort habe ich aus irgendeinem Grund nie Scherben gefunden.',
    'I happen to know that there are some Yellow and Blue Shards in Diglett\'s Cave. Just look inside the chests!': 'Ich weiß zufällig, dass es in Diglett\'s Cave ein paar Gelbe und Blaue Scherben gibt. Sieh einfach in den Truhen nach!',
    'Shards can have lots of different colors. Different Dungeons will have different colors, so keep an eye out! Most of them can\'t even be found in Kanto!': 'Scherben gibt es in vielen verschiedenen Farben. In verschiedenen Dungeons gibt es verschiedene Farben, also halte die Augen offen! Die meisten davon findet man nicht mal in Kanto!',
    'Watch out for mischievous Squirtle around here.': 'Nimm dich hier vor frechen [[pokemon::Squirtle]] in Acht.',
    'You can\'t miss them: they wear black glasses and they\'ll try to play tricks on you.': 'Du kannst sie nicht übersehen: Sie tragen schwarze Sonnenbrillen und versuchen, dir Streiche zu spielen.',
    'That was so close! I thought I could corner it by ambushing it here... But running on the water... is beyond me. Still, I am starting to see a pattern. Suicune prefers water! That means...': 'Das war knapp! Ich dachte, ich könnte es in die Enge treiben, wenn ich ihm hier auflauere... Aber über das Wasser laufen... das übersteigt meine Fähigkeiten. Trotzdem erkenne ich langsam ein Muster. [[pokemon::Suicune]] mag Wasser! Das heißt...',
    'Sorry, I\'ve got to go!': 'Tut mir leid, ich muss los!',
    'Welcome. In our Volunteer House here we take in all kinds of Pokémon to care for them.': 'Willkommen. Hier in unserem Freiwilligenhaus nehmen wir alle möglichen Pokémon auf, um sie zu pflegen.',
    'Did you know that sparkling Pokémon are more often found in Dungeons, on Farms, from Eggs, and even from Shops, the Safari Zone, and Evolutions from Items?': 'Wusstest du, dass funkelnde Pokémon häufiger in Dungeons, auf Farmen, aus Eiern und sogar in Shops, in der Safari-Zone und durch Entwicklungen mit Items zu finden sind?',
    'I know a lot of useful stuff. Like the odds of finding a shiny Pokémon or how to increase Click Attack.': 'Ich weiß eine Menge nützlicher Dinge. Zum Beispiel, wie hoch die Chance auf ein schillerndes Pokémon ist oder wie man den Klick-Angriff verbessert.',
    'No, I didn\'t learn this from talking to ghosts, don\'t be silly. There\'s a FAQ button in the Start Menu. It\'s very useful.': 'Nein, das habe ich nicht von Geistern erfahren, sei nicht albern. Im Start Menu gibt es einen FAQ-Button. Der ist sehr nützlich.',
    'I always seem to run out of Great Balls. Luckly this shop always have them in stock!': 'Mir gehen ständig die Superbälle aus. Zum Glück hat dieser Laden sie immer vorrätig!',
    'They even have an offer today! They give you free Great Balls if you give them the code <code class="text-nowrap">THE-GREATEST-POKEBALL</code>': 'Heute gibt es sogar ein Angebot! Sie schenken dir Superbälle, wenn du ihnen den Code <code class="text-nowrap">THE-GREATEST-POKEBALL</code> nennst.',
    'I love shopping! When I come in, the cashiers know I want tons of items.': 'Ich liebe Shoppen! Wenn ich reinkomme, wissen die Kassierer schon, dass ich Unmengen an Items will.',
    'You can use the Shop Amount Button settings to make it easy for big purchases, too!': 'Mit den Einstellungen für die Kaufmengen-Buttons kannst du auch ganz leicht große Einkäufe machen!',
    'It\'s outrageous! I go through these dungeons over and over again, and the Trainers inside simply refuse to give me more money!': 'Unerhört! Ich gehe immer und immer wieder durch diese Dungeons, und die Trainer darin weigern sich einfach, mir mehr Geld zu geben!',
    'No matter what I do, they always give me the same amount of Pokédollars and Dungeon Tokens.': 'Egal, was ich tue, sie geben mir immer dieselbe Menge Pokédollar und Dungeon-Token.',
    'Be it Token Collectors, Lucky Incense, holding an Amulet Coin or even having a higher Achievement Bonus, it seems you simply cannot change what Dungeon Trainers will give you.': 'Ob Token-Sammler, Glücksrauch, ein getragenes Münzamulett oder sogar ein höherer Erfolgsbonus – anscheinend kann man einfach nicht ändern, was einem die Trainer in Dungeons geben.',
    'I sure do love candy. The rarer, the better!': 'Ich liebe Süßigkeiten über alles. Je seltener, desto besser!',
    'I\'ve got a real <code class="text-nowrap">SWEET-TOOTH</code>': 'Ich bin eine echte <code class="text-nowrap">SWEET-TOOTH</code>',
    'Hello... Isn\'t the spring weather so relaxing? I adore how lovely the blooming flowers look during this time of year...': 'Hallo... Ist das Frühlingswetter nicht so entspannend? Ich liebe es, wie schön die blühenden Blumen um diese Jahreszeit aussehen...',
    'Oh! I\'m sorry, I almost dozed off. I was reminiscing about my stroll in Viridian Forest earlier today. I came across the loveliest patch of flowers over there and...': 'Oh! Verzeihung, ich wäre fast eingenickt. Ich habe an meinen Spaziergang heute im Viridian Forest zurückgedacht. Dort bin ich auf ein ganz entzückendes Blumenbeet gestoßen und...',
    'Zzz... Hm? Oh yes, the forest. It was most peculiar - when I laid down upon the flowerbed I had the strangest dream of a basket full of Pokémon. At least, I think it was a dream... It did not strike me as one of the usual inhabitants of the area.': 'Zzz... Hm? Ach ja, der Wald. Es war höchst sonderbar – als ich mich auf das Blumenbeet legte, hatte ich einen ganz seltsamen Traum von einem Korb voller Pokémon. Zumindest glaube ich, dass es ein Traum war... Es schien mir keines der üblichen Pokémon aus der Gegend zu sein.',
    'Do I know you? Wait... Have you met my worthless rival? Ha! Let me guess, he gave you some unwanted advice?': 'Kenne ich dich? Moment... Hast du meinen nichtsnutzigen Rivalen getroffen? Ha! Lass mich raten, er hat dir ungebetene Ratschläge gegeben?',
    'I bet he forget to tell you that although all Battle Items only last for 30 seconds, they can stack and last for days! Now scram!': 'Ich wette, er hat vergessen dir zu sagen, dass alle Kampf-Items zwar nur 30 Sekunden halten, sich aber stapeln lassen und dann tagelang wirken! Und jetzt verschwinde!',
    'You can leave your level 100 Pokémon with us up at the Hatchery. Breeding them will reset their level, but they will be stronger! They gain 25% of their base attack!': 'Du kannst deine Pokémon auf Level 100 bei uns in der Hatchery abgeben. Durch die Zucht wird ihr Level zurückgesetzt, aber sie werden stärker! Sie erhalten 25 % ihres Basisangriffs dazu!',
    'And the best part is you can keep doing it over and over and over again! The sky is the limit! Reach for the stars!': 'Und das Beste ist, du kannst das immer und immer und immer wieder tun! Nach oben gibt es keine Grenzen! Greif nach den Sternen!',
    'With Protein your Pokémon will become even stronger when you breed them. I hear they sell it at the Indigo Plateau.': 'Mit Protein werden deine Pokémon bei der Zucht sogar noch stärker. Ich habe gehört, dass es am Indigo Plateau verkauft wird.',
    '<i>In a shady warehouse, you find the informant. He is a Mr. Mime, and he doesn\'t seem willing to divulge the information you need.</i>': '<i>In einer zwielichtigen Lagerhalle findest du den Informanten. Es ist ein [[pokemon::Mr. Mime]], und es scheint nicht gewillt, die Informationen preiszugeben, die du brauchst.</i>',
    '<i>The Mr. Mime signals to you that this is an illicit drug called R. It is frequently used in the underground fighting rings near the Battle Frontier.</i>': '<i>Das [[pokemon::Mr. Mime]] gibt dir zu verstehen, dass es sich um eine illegale Droge namens R handelt. Sie wird häufig in den Untergrund-Kampfarenen nahe der Battle Frontier verwendet.</i>',
    'There\'s been some recent sightings of roaming Pokémon on {ROUTE_NAME}!': 'Auf {ROUTE_NAME} wurden kürzlich umherstreifende Pokémon gesichtet!',
    'You! Not again! I\'ll be there first next time! Having followed it here, I\'m starting to understand what Suicune is after.': 'Du! Nicht schon wieder! Nächstes Mal bin ich zuerst da! Seit ich ihm hierher gefolgt bin, verstehe ich langsam, worauf [[pokemon::Suicune]] aus ist.',
    'To be honest, I would like to keep this information to myself. But I want to be an honest Trainer in front of Suicune! That\'s why I am sharing a clue with you.': 'Ehrlich gesagt würde ich diese Information gern für mich behalten. Aber ich möchte vor [[pokemon::Suicune]] ein ehrlicher Trainer sein! Deshalb verrate ich dir einen Hinweis.',
    'It seems that... Suicune prefers a hilly place near water... Somewhere north. I don\'t know exactly where, yet. It will be just you and me! Who\'ll find it first? I challenge you!': 'Es scheint, dass... [[pokemon::Suicune]] einen hügeligen Ort in der Nähe von Wasser bevorzugt... Irgendwo im Norden. Wo genau, weiß ich noch nicht. Es geht nur um dich und mich! Wer findet es zuerst? Ich fordere dich heraus!',
    'I heard there was a stone hidden in the Safari Zone that makes Pinsir stronger!': 'Ich habe gehört, dass in der Safari Zone ein Stein versteckt ist, der [[pokemon::Pinsir]] stärker macht!',
    'But... I don\'t have a high enough Safari Level to find it.': 'Aber... mein Safari-Level ist nicht hoch genug, um ihn zu finden.',
    'That Explorer Kit is a must-have for any Fossil Fanatic! Why, it\'s how I found my very first Old Amber.': 'Dieses Forscher-Set ist ein Muss für jeden Fossilienfan! Damit habe ich schließlich meinen allerersten Altbernstein gefunden.',
    'Hrm, yes! I see that gleam in your eye! It may look expensive now, but the treasures you\'ll find in the Underground are priceless! And what\'s more- with each new region you travel to, the more adept you will become at identifying new curios!': 'Hrm, ja! Ich sehe das Funkeln in deinen Augen! Es mag jetzt teuer aussehen, aber die Schätze, die du im Untergrund findest, sind unbezahlbar! Und mehr noch – mit jeder neuen Region, die du bereist, wirst du geschickter darin, neue Kuriositäten zu erkennen!',
    'Speaking of, our very own Kanto is home to three: the Helix Fossil, Dome Fossil, and Old Amber! You can revive them into living Pokémon using techniques developed by the Devon Corporation and a research laboratory on Cinnabar Island! There are also other scientists around the Pokémon world who can revive Fossils using these techniques.': 'Apropos, unser Kanto beherbergt gleich drei: das Helixfossil, das Domfossil und den Altbernstein! Du kannst sie mit Techniken, die von der Devon Corporation und einem Forschungslabor auf Cinnabar Island entwickelt wurden, zu lebenden Pokémon wiederbeleben! Es gibt auch andere Wissenschaftler auf der Pokémon-Welt, die Fossilien mit diesen Techniken wiederbeleben können.',
    'They were trying to clone an ancient Pokémon in the mansion... I wonder if they succeeded.': 'Sie haben in der Villa versucht, ein uraltes Pokémon zu klonen... Ob es ihnen wohl gelungen ist?',
    'Apparently the ancient Pokémon escaped, and can be found roaming around Kanto!': 'Anscheinend ist das uralte Pokémon entkommen und streift nun durch Kanto!',
    'I don\'t have time to listen to people explain stuff I already know.': 'Ich habe keine Zeit, mir von Leuten Sachen erklären zu lassen, die ich schon weiß.',
    'Some old man tried to teach me how to catch Pokémon earlier.': 'Vorhin wollte mir irgendein alter Mann beibringen, wie man Pokémon fängt.',
    'I just shouted <code class="text-nowrap">HOW-BLU-COIN?</code> at him and left.': 'Ich habe ihm nur <code class="text-nowrap">HOW-BLU-COIN?</code> entgegengebrüllt und bin gegangen.',
    'Ah, yes. Welcome! Welcome! Almost didn\'t see you there. I\'m just so busy trying to get this darned thing to work. Once it\'s complete we can finally have a direct communications network between the Sevii Islands and Kanto!': 'Ah, ja. Willkommen! Willkommen! Ich hätte dich beinahe übersehen. Ich bin so damit beschäftigt, dieses verflixte Ding zum Laufen zu bringen. Sobald es fertig ist, haben wir endlich ein direktes Kommunikationsnetz zwischen den Sevii Islands und Kanto!',
    'I don\'t even have time to go and pick up an important package. A meteorite, found by the owner of the game corner on Two Island. It contains important materials for my machine.': 'Ich habe nicht einmal Zeit, ein wichtiges Paket abzuholen. Einen Meteoriten, gefunden vom Besitzer der Spielhalle auf Two Island. Er enthält wichtige Materialien für meine Maschine.',
    'You seem like the adventuring type. Tell you what. How about Bill stays here with me to work on this machine, and you go fetch my Meteorite for me.': 'Du scheinst mir der abenteuerlustige Typ zu sein. Weißt du was? Wie wäre es, wenn Bill hier bei mir bleibt und an der Maschine arbeitet, und du holst mir meinen Meteoriten.',
    'Back already? That didn\'t take very long.': 'Schon zurück? Das ging aber schnell.',
    'What? It did take long? You went on a whole rescue mission? Seems like I lost track of time while working on my machine with Bill. It\'s been a lot of fun.': 'Was? Es hat doch lange gedauert? Du warst auf einer ganzen Rettungsmission? Scheint, als hätte ich bei der Arbeit an meiner Maschine mit Bill die Zeit vergessen. Es hat viel Spaß gemacht.',
    'I\'m glad to hear Lostelle is all right. You can hand the meteorite to me. Bill, thank you for your assistance, I\'ll take it from here. I can see that your friend is eager to get back to Kanto and challenge the Pokémon League.': 'Ich bin froh zu hören, dass es Lostelle gut geht. Du kannst mir den Meteoriten geben. Bill, danke für deine Hilfe, ab hier übernehme ich. Ich sehe doch, dass dein Freund es kaum erwarten kann, nach Kanto zurückzukehren und die Pokémon-Liga herauszufordern.',
    'Thank you both very much.': 'Vielen Dank euch beiden.',
    'You\'ve been a great help. Thanks again. Maybe we\'ll meet again some day...': 'Du warst eine große Hilfe. Nochmals danke. Vielleicht sehen wir uns ja eines Tages wieder...',
    'How have things been for you? Oh, is that right? You\'ve caught more Pokémon. Do you know what? Maybe I can be useful to you. I\'m modifying the Network Machine right now. I\'m changing it so it can handle trades over long distances. When I get finished, you\'ll be trading for exotic Pokémon from Trainers far away.': 'Wie ist es dir ergangen? Ach, wirklich? Du hast weitere Pokémon gefangen. Weißt du was? Vielleicht kann ich dir nützlich sein. Ich baue die Netzwerkmaschine gerade um. Ich ändere sie so, dass sie Tauschgeschäfte über weite Entfernungen abwickeln kann. Wenn ich fertig bin, kannst du exotische Pokémon von Trainern aus fernen Ländern eintauschen.',
    'But, there is a slight catch. For the link to work, the Machine needs a special gemstone. It\'s supposed to be on One Island, but I haven\'t found one yet. Who knows where it could be.': 'Aber es gibt einen kleinen Haken. Damit die Verbindung funktioniert, braucht die Maschine einen besonderen Edelstein. Er soll auf One Island sein, aber ich habe noch keinen gefunden. Wer weiß, wo er sein könnte.',
    'Oh! Th-that\'s... Thank you! You\'re simply amazing. ... ... ... ... Um... May I ask one more giant favor of you?': 'Oh! D-das ist... Danke! Du bist einfach unglaublich. ... ... ... ... Ähm... Darf ich dich um noch einen riesigen Gefallen bitten?',
    'While I was studying gemstones, I discovered something important. There is another gem that forms a pair with this Ruby. That other gemstone is supposed to be in the Sevii Islands. Please, I need you to go find the other gem.': 'Während ich Edelsteine untersucht habe, habe ich etwas Wichtiges entdeckt. Es gibt noch einen weiteren Edelstein, der mit diesem Rubin ein Paar bildet. Dieser andere Edelstein soll auf den Sevii Islands sein. Bitte, du musst den anderen Edelstein finden.',
    'Here, take my ferry pass. It will let you get to all of the Sevii Islands. Please, I can\'t do it without your help.': 'Hier, nimm meinen Fährpass. Damit kommst du zu allen Sevii Islands. Bitte, ohne deine Hilfe schaffe ich es nicht.',
    'So this is the gem that forms a pair with the Ruby... You\'ve gone through a lot to get this, didn\'t you? You don\'t have to tell me. I know it wasn\'t easy. Thank you so much! Now it\'s my turn to work for you! Please give me a little time.': 'Das ist also der Edelstein, der mit dem Rubin ein Paar bildet... Du hast viel durchgemacht, um ihn zu bekommen, nicht wahr? Du musst es mir nicht erzählen. Ich weiß, dass es nicht leicht war. Vielen, vielen Dank! Jetzt bin ich an der Reihe, für dich zu arbeiten! Bitte gib mir ein wenig Zeit.',
    'Okay, this is good... I did it! I linked up with Lanette! I did it! I\'ve managed to link up with Trainers in the Hoenn region! Finally, the Network Machine is fully operational! I owe it all to you! Thanks to you, my dream came true...': 'Okay, das sieht gut aus... Geschafft! Ich habe eine Verbindung zu Lanette hergestellt! Geschafft! Ich habe es geschafft, mich mit Trainern in der Hoenn-Region zu verbinden! Endlich ist die Netzwerkmaschine voll einsatzbereit! Das verdanke ich alles dir! Dank dir ist mein Traum wahr geworden...',
    'I... I\'m not crying. That\'s enough about me! You\'re going to keep looking for exotic Pokémon, right? I wish you the best of luck!': 'Ich... Ich weine nicht. Genug von mir! Du wirst weiter nach exotischen Pokémon suchen, nicht wahr? Ich wünsche dir viel Glück!',
    'Isn\'t it strange how Mol<b><i>tres</i></b> lives on <b><i>One</i></b> Island?': 'Ist es nicht seltsam, dass Mol<b><i>tres</i></b> auf <b><i>One</i></b> Island lebt?',
    'Whew, punched through at last. Let\'s go treasure hunting! Any treasure we find, we haul back to the Warehouse, understood?': 'Puh, endlich durchgebrochen. Auf zur Schatzsuche! Alle Schätze, die wir finden, schaffen wir zurück ins Lagerhaus, verstanden?',
    '...Oh, what are the passwords? At the Rocket Warehouse, I mean.': '...Oh, wie lauten noch mal die Passwörter? Für das Rocket-Lagerhaus, meine ich.',
    'What, you forgot the password? There\'re actually two. The first one\'s "Goldeen need log". And the second one is...': 'Was, du hast das Passwort vergessen? Es sind eigentlich zwei. Das erste lautet „Goldeen need log“. Und das zweite ist...',
    'Hey! This snoop\'s been listening in!': 'Hey! Dieser Schnüffler hat gelauscht!',
    'Hello stranger. I\'m afraid the Game Corner is currently closed.': 'Hallo, Fremder. Leider ist die Spielhalle zurzeit geschlossen.',
    'What? The meteorite for Celio? Yes, I can give that to you. But I need you to do something for me first.': 'Was? Der Meteorit für Celio? Ja, den kann ich dir geben. Aber zuerst musst du etwas für mich tun.',
    'My daughter Lostelle is missing. She likes to pick berries in the Berry Forest on Three Island. She does it all the time. But this time she hasn\'t come back. Please go find her.': 'Meine Tochter Lostelle wird vermisst. Sie pflückt gern Beeren im Berry Forest auf Three Island. Das macht sie ständig. Aber diesmal ist sie nicht zurückgekommen. Bitte finde sie.',
    'My sweet Lostelle! I\'m so glad you\'re all right.': 'Meine süße Lostelle! Ich bin so froh, dass es dir gut geht.',
    'Thank you very much kind stranger. Please take the Meteorite.': 'Vielen Dank, freundlicher Fremder. Bitte nimm den Meteoriten.',
    'You know what sucks? The other islands are off limits for some arbitrary reason. There is no explanation. Just can\'t go there.': 'Weißt du, was echt mies ist? Die anderen Inseln sind aus irgendeinem willkürlichen Grund gesperrt. Keine Erklärung. Man kann einfach nicht hin.',
    'Alright, you want the real truth? Some weird old dude told me this: "The other islands are locked behind part of a "Quest Line" You have to progress to unlock it."': 'Na gut, willst du die echte Wahrheit hören? So ein komischer alter Kerl hat mir das erzählt: „Die anderen Inseln sind hinter einem Teil einer ‚Questreihe‘ gesperrt. Du musst Fortschritte machen, um sie freizuschalten.“',
    'I don\'t know what half those words mean. All I know is I can\'t go back to Kanto with the rest of the gang. This sucks.': 'Ich weiß nicht, was die Hälfte dieser Wörter bedeuten soll. Ich weiß nur, dass ich nicht mit dem Rest der Gang nach Kanto zurückkann. Echt mies.',
    'Alright, you want the real truth? Some weird old dude told me this: "The other islands are locked behind part of a Questline. You can unlock it at a Bulletin Board."': 'Na gut, willst du die echte Wahrheit hören? So ein komischer alter Kerl hat mir das erzählt: „Die anderen Inseln sind hinter einem Teil einer Questreihe gesperrt. Du kannst sie an einem Schwarzen Brett freischalten.“',
    'Wait, you got to them? Good for you. Not that it matters to me, I\'m still stuck here. This sucks.': 'Moment, du bist dorthin gekommen? Schön für dich. Nicht, dass mir das was bringt, ich sitze immer noch hier fest. Echt mies.',
    'Welcome to Valencia Island! Well, this tiny beach on Valencia Island. I don\'t know why I decided to have this lab built below this giant cliff... Can\'t even get to the rest of the island from here.': 'Willkommen auf Valencia Island! Na ja, an diesem winzigen Strand von Valencia Island. Ich weiß nicht, warum ich dieses Labor unbedingt unter dieser riesigen Klippe bauen lassen wollte... Von hier kommt man nicht einmal zum Rest der Insel.',
    'This is the GS Ball. I found it here recently. Professor Oak seemed very interested. Please deliver it to him at your earliest convenience.': 'Das ist der GS-Ball. Ich habe ihn kürzlich hier gefunden. Professor Eich schien sehr interessiert. Bitte bring ihn ihm so bald wie möglich.',
    'But first, wanna get involved in our regional Pokémon League? No? Maybe another time then.': 'Aber zuerst: Hast du Lust, bei unserer regionalen Pokémon-Liga mitzumachen? Nein? Dann vielleicht ein andermal.',
    '<i>Welcome to Client Island!</i>': '<i>Willkommen auf Client Island!</i>',
    '<i>This island is exclusive to those dedicated to reducing server load by downloading the client.</i>': '<i>Diese Insel ist exklusiv für alle, die durch das Herunterladen des Clients die Serverlast reduzieren.</i>',
    '<i>Without your support, Red Spearow here wouldn\'t have any time to relax!</i>': '<i>Ohne deine Unterstützung hätte dieses [[pokemon::Red Spearow]] hier keine Zeit zum Entspannen!</i>',
    '<i>Please drop by the Gift Shop on your way out to make a whole new line of friends.</i>': '<i>Bitte schau auf dem Weg nach draußen im Geschenkeladen vorbei und finde ganz neue Freunde.</i>',
    '<b><i>SQUAWK! SQUAWK!</i></b>': '<b><i>KRÄCHZ! KRÄCHZ!</i></b>',
    '<i>The Red Spearow seems to appreciate your visit.</i>': '<i>Das [[pokemon::Red Spearow]] scheint sich über deinen Besuch zu freuen.</i>',
    'Pirate crew battles are part of our everyday life out here. According to the old pirate code, I must hand over a reward if you manage to defeat us…': 'Kämpfe gegen Piratencrews gehören hier draußen zu unserem Alltag. Nach dem alten Piratenkodex muss ich dir eine Belohnung überreichen, wenn du es schaffst, uns zu besiegen…',
    'Apparently some kid released one of his Pokémon around here. That Pokémon, its partner, and for whatever reason, the Legendary Beasts from Johto have been seen roaming on {ROUTE_NAME}.': 'Anscheinend hat irgendein Junge hier in der Gegend eines seiner Pokémon freigelassen. Dieses Pokémon, sein Partner und aus irgendeinem Grund auch die legendären Bestien aus Johto wurden auf {ROUTE_NAME} gesichtet.',
    'I can\'t figure out how I\'m supposed to get inside. Let me tell you, I found this place. Don\'t look so envious, will you?': 'Ich komme einfach nicht dahinter, wie man hier reinkommen soll. Eins sag ich dir, ich habe diesen Ort gefunden. Schau nicht so neidisch, ja?',
    'Fufu... Fufufufu... I guessed right. I was right in tailing you! I knew there was a Sapphire here, so it belongs to me! I\'ll sell it to Team Rocket for serious money.': 'Fufu... Fufufufu... Ich lag richtig. Es war richtig, dir zu folgen! Ich wusste, dass hier ein Saphir ist, also gehört er mir! Ich verkaufe ihn für richtig viel Geld an Team Rocket.',
    '...D-don\'t glare at me like that! If you want it back, why don\'t you go get it after I sell it? I\'ll even tell you one of the passwords to Team Rocket\'s Warehouse. The Warehouse password I know is "Yes, nah, Chansey." I\'m done. Don\'t think badly of me!': '...S-schau mich nicht so finster an! Wenn du ihn zurückwillst, warum holst du ihn dir nicht, nachdem ich ihn verkauft habe? Ich verrate dir sogar eines der Passwörter für das Lagerhaus von Team Rocket. Das Passwort, das ich kenne, lautet „Yes, nah, [[pokemon::Chansey]].“ Mehr gibt\'s nicht. Denk nicht schlecht von mir!',
    'Hello again! I see you too found a way around the giant cliff.': 'Hallo nochmal! Wie ich sehe, hast du auch einen Weg um die riesige Klippe herum gefunden.',
    'On this island, Pokémon have changed over the years. I am here to study them.': 'Auf dieser Insel haben sich die Pokémon im Laufe der Jahre verändert. Ich bin hier, um sie zu erforschen.',
    'Oh, you have already encountered them? And you are busy with the Orange League?': 'Oh, du bist ihnen schon begegnet? Und du bist mit der Orange League beschäftigt?',
    'Well, good luck to you, then.': 'Na, dann wünsche ich dir viel Glück.',
    'Have you seen the Pinkan Berries? That is what makes all the Pokémon on this island turn pink.': 'Hast du die Pinkan-Beeren gesehen? Durch sie werden alle Pokémon auf dieser Insel rosa.',
    'Hang on, this island is strictly off limits! Pinkan is a protected Pokémon reserve. How did you get here?': 'Moment mal, diese Insel ist streng gesperrt! Pinkan ist ein geschütztes Pokémon-Reservat. Wie bist du hierhergekommen?',
    'Well I suppose you did deal with that Team Rocket branch on Five Island, so I guess I\'ll let you stay, as thanks.': 'Na ja, du hast dich ja um diese Team-Rocket-Zweigstelle auf Five Island gekümmert, also darfst du als Dank wohl bleiben.',
    'I\'m afraid I can\'t allow you into Pinkan Mountain though. The Pokémon there are extremely territorial.': 'In den Pinkan Mountain kann ich dich aber leider nicht lassen. Die Pokémon dort verteidigen ihr Revier äußerst heftig.',
    'If you want to prove you can deal with such dangerous Pokémon safely, I suggest defeating the Orange League.': 'Wenn du beweisen willst, dass du sicher mit so gefährlichen Pokémon umgehen kannst, schlage ich vor, dass du die Orange League besiegst.',
    'And since you\'ve conquered the Orange League, I suppose it should be safe to let you into Pinkan Mountain. Just be careful.': 'Und da du die Orange League bezwungen hast, sollte es wohl sicher sein, dich in den Pinkan Mountain zu lassen. Sei einfach vorsichtig.',
    'Don\'t even think about taking any Pinkan berries off this island though! They\'re a heavily restricted item. If you want to get one, you\'ll simply have to grow it yourself.': 'Denk aber nicht mal daran, Pinkan-Beeren von dieser Insel mitzunehmen! Sie unterliegen strengen Beschränkungen. Wenn du eine haben willst, musst du sie eben selbst anbauen.',
    'Oh it\'s you again! Got some Pinkan Berries to trade?': 'Oh, du bist es wieder! Hast du Pinkan-Beeren zum Tauschen dabei?',
    'So long as you\'re not helping those Rocket clowns, we\'ll let you trade for some of those rare Pinkan Pokémon that have only just come to the island.': 'Solange du diesen Rocket-Clowns nicht hilfst, lassen wir dich ein paar dieser seltenen Pinkan-Pokémon eintauschen, die gerade erst auf die Insel gekommen sind.',
    '...Additionally, since you\'ve proven yourself a skilled farmer, feel free to pick up any loose Pinkan Berries you come across on the mountain.': '...Außerdem darfst du, da du dich als geschickter Farmer erwiesen hast, gern alle losen Pinkan-Beeren aufsammeln, die du am Berg findest.',
    'Oh hello there trainer! What do you mean we\'re not supposed to be here? We toootally got permission from Officer Jenny!': 'Oh, hallo Trainer! Wie meinst du das, wir dürften nicht hier sein? Wir haben gaaanz bestimmt die Erlaubnis von Officer Rocky!',
    'Isn\'t your whole "thing" being helpful? We want to build a theme park to help fund the Pinkan Reserve, but this meddlesome twerp named Ash keeps getting in the way. He\'s even electrocuted us with his damn Pikachu!': 'Ist es nicht dein ganzes „Ding“, hilfsbereit zu sein? Wir wollen einen Freizeitpark bauen, um das Pinkan-Reservat zu finanzieren, aber dieser lästige Knirps namens Ash kommt uns ständig in die Quere. Er hat uns sogar mit seinem verdammten [[pokemon::Pikachu]] unter Strom gesetzt!',
    'We need a bunch of Pinkan Berries to help feed the Pokémon at our theme park, but the twerp keeps zapping us when we try to go collect them.': 'Wir brauchen jede Menge Pinkan-Beeren, um die Pokémon in unserem Freizeitpark zu füttern, aber der Knirps grillt uns jedes Mal, wenn wir versuchen, welche zu sammeln.',
    'Would you mind farming some Pinkan Berries to help us grow our supply? We don\'t know how to, but we\'ve heard the Berry Master in Kanto could be helpful?': 'Würdest du ein paar Pinkan-Beeren anbauen, um unseren Vorrat aufzustocken? Wir wissen nicht, wie das geht, aber wir haben gehört, dass der Beerenmeister in Kanto helfen könnte?',
    'Whoa! An actual Pinkan Berry! Now our evil plo- plan! Definitely not evil, our very helpful and good plan!...Ahem. Our plan can now proceed.': 'Wow! Eine echte Pinkan-Beere! Jetzt kann unser fieser Pl- Plan! Ganz bestimmt nicht fies, unser sehr hilfreicher und guter Plan!... Ähem. Jetzt kann unser Plan weitergehen.',
    'Now we can get us some Pinkan\'s for the theme park! Would you mind defeating 500 Pinkan Pokémon in the forest and out in the plains? We\'ll do the catching, you just need to beat \'em': 'Jetzt können wir uns ein paar Pinkan-Pokémon für den Freizeitpark holen! Würdest du 500 Pinkan-Pokémon im Wald und draußen in der Ebene besiegen? Wir übernehmen das Fangen, du musst sie nur verhauen.',
    'Nice! Well, it would be nice. Now we have all these berries and Pinkan Pokémon, but nowhere to put \'em all!': 'Super! Na ja, es wäre super. Jetzt haben wir all diese Beeren und Pinkan-Pokémon, aber keinen Platz, um sie alle unterzubringen!',
    'We need a bunch of Pixie Plates, and we need some Fairy Gems to help...uh...pay off the contractor?': 'Wir brauchen jede Menge Pixietafeln, und wir brauchen ein paar Feenjuwelen, um... äh... den Bauunternehmer zu bezahlen?',
    'Hahahaha! Now our plan can really start! Prepare for trouble, and make it double, because you just built us a profit machine!': 'Hahahaha! Jetzt kann unser Plan richtig losgehen! Jetzt gibt es Ärger, und es kommt noch härter, denn du hast uns gerade eine Gelddruckmaschine gebaut!',
    'We\'re going to make these Pinkan Pokémon perform silly routines and make us a ton of money, no days off for these suckers!': 'Wir werden diese Pinkan-Pokémon alberne Kunststücke aufführen lassen und damit einen Haufen Geld verdienen, keine freien Tage für diese Trottel!',
    'What\'s that? You\'re gonna stop us!? Heh, yeah right! Bring it on twerp!': 'Was ist? Du willst uns aufhalten!? Heh, na klar! Nur her damit, Knirps!',
    'Oh! Hi! You\'re not a member of Team Rocket! You came to save us? Why thank you!': 'Oh! Hallo! Du gehörst nicht zu Team Rocket! Du bist gekommen, um uns zu retten? Na, vielen Dank!',
    'I want you to have this Pokémon for saving us.': 'Ich möchte dir dieses Pokémon dafür schenken, dass du uns gerettet hast.',
    'Mewtwo has created an army of Clones. Please help me fight them, I have to save Pikachu!': '[[pokemon::Mewtwo]] hat eine Armee von Klonen erschaffen. Bitte hilf mir, sie zu bekämpfen, ich muss [[pokemon::Pikachu]] retten!',
    'There are still Clones left in Mewtwos army! Help me fight them!': 'Es sind noch Klone in [[pokemon::Mewtwo]]s Armee übrig! Hilf mir, sie zu bekämpfen!',
    'Mewtwo\'s Clones have escaped and are Roaming freely across Kanto. Will you help us track them down? It\'s for a good cause, we swear.': 'Die Klone von [[pokemon::Mewtwo]] sind entkommen und streifen frei durch Kanto. Hilfst du uns, sie aufzuspüren? Es ist für einen guten Zweck, ehrlich.',
    '<i>Ow! You were hit by a low-flying Poké Ball!</i>': '<i>Autsch! Du wurdest von einem tief fliegenden Pokéball getroffen!</i>',
    'Oh, whoops! You\'re not a Pokémon! Sorry, it\'s so dark in here, I saw you and thought you were some kind of Pokémon.': 'Oh, hoppla! Du bist ja gar kein Pokémon! Tut mir leid, es ist so dunkel hier drin, ich habe dich gesehen und dachte, du wärst irgendein Pokémon.',
    'Well, uh... nice to meet you. I\'m Green! So hey, I\'m just curious... Are you here because you\'re also looking for... y\'know, something special?': 'Also, äh... freut mich, dich kennenzulernen. Ich bin Grün! Sag mal, ich bin nur neugierig... Bist du hier, weil du auch nach... du weißt schon, etwas Besonderem suchst?',
    'R-right! Mewtwo! ...Drat, so you knew about it already, huh.......': 'G-genau! [[pokemon::Mewtwo]]! ...Mist, du wusstest also schon davon, was.......',
    'Whaaaaaaaaaat?! You\'ve already caught it?! Hey, no fair! I was planning on catching it first!': 'Waaaaaaaaaas?! Du hast es schon gefangen?! Hey, das ist unfair! Ich wollte es doch als Erste fangen!',
    'Wow, you\'re strong! Well, I guess that\'s that. Here, you can have this.': 'Wow, du bist stark! Na ja, dann ist das wohl so. Hier, das kannst du haben.',
    '</i></br><img src="assets/images/megaStone/Mewtwonite_X.png"/></br><i>You obtained the Mewtwonite X!</i>': '</i></br><img src="assets/images/megaStone/Mewtwonite_X.png"/></br><i>Du hast Mewtunit X erhalten!</i>',
    'Oh, I know! Why don\'t you become one of my Pokémon, together with Mewtwo?': 'Oh, ich weiß! Warum wirst du nicht eines meiner Pokémon, zusammen mit [[pokemon::Mewtwo]]?',
    '<i>A Poké Ball came flying at you!</i>': '<i>Ein Pokéball kommt auf dich zugeflogen!</i>',
    'Hee hee hee... <i>A Poké Ball came flying at you!</i>': 'Hi hi hi... <i>Ein Pokéball kommt auf dich zugeflogen!</i>',
    '<i>A Poké Ball came flying at you!</i> Think about it, ok?': '<i>Ein Pokéball kommt auf dich zugeflogen!</i> Denk drüber nach, okay?',
    '<i>That child... She wished to possess me, like a mere animal. She would have cared little for my own desires. I wish only to live in peace, without being disturbed.</i>': '<i>Dieses Kind... Es wollte mich besitzen, wie ein gewöhnliches Tier. Meine eigenen Wünsche wären ihm gleichgültig gewesen. Ich will nur in Frieden leben, ohne gestört zu werden.</i>',
    '<i>You say you would help me? But you are no different. You even possess another of my kind. You do not fool me.</i>': '<i>Du sagst, du würdest mir helfen? Aber du bist nicht anders. Du besitzt sogar einen weiteren meiner Art. Du kannst mich nicht täuschen.</i>',
    '<i>I will leave this place now, to find what I desire. Do not follow me.</i>': '<i>Ich werde diesen Ort nun verlassen, um zu finden, wonach ich mich sehne. Folge mir nicht.</i>',
    '<i>You found a Ruby!</i>': '<i>Du hast einen Rubin gefunden!</i>',
    'Thank you. But this is awful... I was born and raised here on these islands. I had no idea that those horrible criminals were loose here…': 'Danke. Aber das ist schrecklich... Ich bin hier auf diesen Inseln geboren und aufgewachsen. Ich hatte keine Ahnung, dass diese schrecklichen Verbrecher hier ihr Unwesen treiben…',
    'Hello. You want to know what I\'m doing in this pointless dead end cave?': 'Hallo. Du willst wissen, was ich in dieser sinnlosen Sackgassen-Höhle mache?',
    'Well, I\'m trying to dig to a secluded island north of here. I\'ve heard there are some unusual Pokémon there.': 'Nun, ich versuche, mich zu einer abgelegenen Insel nördlich von hier durchzugraben. Ich habe gehört, dass es dort ein paar ungewöhnliche Pokémon gibt.',
    'Want to help me? No? Ah, you\'re busy dealing with a group of Team Rocket? Well, I wish you luck with that': 'Willst du mir helfen? Nein? Ah, du bist damit beschäftigt, dich um eine Gruppe von Team Rocket zu kümmern? Na dann wünsche ich dir viel Glück dabei',
    'Once I finish it you\'ll have a way to get to get to that island too, so make sure to come back later!': 'Sobald ich fertig bin, kannst du auch auf diese Insel gelangen, also komm später unbedingt wieder!',
    'Wow, that was some back breaking work... But I have done it!': 'Puh, das war vielleicht eine Knochenarbeit... Aber ich hab\'s geschafft!',
    'I\'ve dug a tunnel to Pinkan Island! Though, I think I\'ll need to rest for a while first... You go on ahead.': 'Ich habe einen Tunnel nach Pinkan Island gegraben! Aber ich glaube, ich muss mich erst mal eine Weile ausruhen... Geh du schon mal vor.',
    'Hello again! I see you too found your way to these ancient ruins!': 'Hallo noch mal! Wie ich sehe, hast du auch den Weg zu diesen uralten Ruinen gefunden!',
    'A peculiar Pokémon known as Unown lives here. There are 28 different forms of Unown, but not all appear at the same time.': 'Hier lebt ein eigenartiges Pokémon namens [[pokemon::Unown]]. Es gibt 28 verschiedene Formen von [[pokemon::Unown]], aber nicht alle tauchen gleichzeitig auf.',
    'There are 2 other ruins like this, one in Johto, and one in Sinnoh. I have heard that in each ruins, there are forms that only appear there. For example, the forms that resemble a question mark and an exclamation point have only been seen here.': 'Es gibt noch 2 weitere Ruinen wie diese, eine in Johto und eine in Sinnoh. Ich habe gehört, dass es in jeder dieser Ruinen Formen gibt, die nur dort vorkommen. Zum Beispiel wurden die Formen, die einem Fragezeichen und einem Ausrufezeichen ähneln, bisher nur hier gesehen.',
    'Speaking of peculiar Pokémon, I found this unusual variant of Dodrio on an island in this area. Hmm. If you want, you could buy it from me. I am needing some research funds.': 'Apropos eigenartige Pokémon: Ich habe diese ungewöhnliche Variante von [[pokemon::Dodrio]] auf einer Insel in dieser Gegend gefunden. Hmm. Wenn du willst, kannst du es mir abkaufen. Ich brauche nämlich etwas Geld für meine Forschung.',
    'I am the lead scientist specializing in all things related to Unown. If you have any questions, don\'t hesitate to ask. Our study has revealed three key patterns regarding the appearance of Unown:': 'Ich bin die leitende Wissenschaftlerin für alles, was mit [[pokemon::Unown]] zu tun hat. Wenn du Fragen hast, frag ruhig. Unsere Studie hat drei wichtige Muster beim Auftauchen von [[pokemon::Unown]] aufgedeckt:',
    '1. <b>Increased Frequency with Clears</b>: The deeper one ventures into the dungeon, the more Unown emerge. Our most daring researchers have observed up to three Unown at a time.': '1. <b>Häufigeres Auftreten mit Abschlüssen</b>: Je tiefer man in den Dungeon vordringt, desto mehr [[pokemon::Unown]] tauchen auf. Unsere wagemutigsten Forscher haben bis zu drei [[pokemon::Unown]] gleichzeitig beobachtet.',
    '2. <b>Daily Variations</b>: Different types of Unown seem to appear each day, following what appears to be a specific sequence.': '2. <b>Tägliche Schwankungen</b>: Jeden Tag scheinen andere Arten von [[pokemon::Unown]] aufzutauchen, und zwar in einer scheinbar festen Reihenfolge.',
    '3. <b>Limited Variety in the Region</b>: Not all versions of Unown are found here. Although 28 forms exist, some have only been encountered in other regions.': '3. <b>Begrenzte Vielfalt in der Region</b>: Nicht alle Versionen von [[pokemon::Unown]] sind hier zu finden. Obwohl es 28 Formen gibt, wurden einige bisher nur in anderen Regionen angetroffen.',
    'Prof. Elm\'s research is focused on eggs. Pokémon eggs hatch faster when the trainer is battling strong trainers like Gym leaders.': 'Professor Linds Forschung dreht sich um Eier. Pokémon-Eier schlüpfen schneller, wenn der Trainer gegen starke Trainer wie Arenaleiter kämpft.',
    'Welcome to Johto! This is where the first ever Pokémon egg was found long ago.': 'Willkommen in Johto! Hier wurde vor langer Zeit das allererste Pokémon-Ei gefunden.',
    'Astounding breakthroughs have been made since then. We can now store Pokémon eggs for longer and queue them up for breeding.': 'Seitdem gab es erstaunliche Durchbrüche. Wir können Pokémon-Eier jetzt länger aufbewahren und sie für die Zucht in eine Warteschlange stellen.',
    'This new technology only allows up to four stored eggs for now, though.': 'Diese neue Technologie erlaubt allerdings vorerst nur bis zu vier aufbewahrte Eier.',
    'You’re a trainer, right? It’s me, the Poké Dude! I’m the guy on Teachy TV!': 'Du bist doch ein Trainer, oder? Ich bin\'s, der Poké Dude! Der Typ aus dem Teachy TV!',
    'Your Item Bag has a bunch of nifty features! Take stuff in the Held Items pocket, for instance. You can use a Held Item to empower your Pokémon or acquire unique effects. How do you use it? Well, here’s how it works.': 'Dein Beutel hat jede Menge praktische Funktionen! Nimm zum Beispiel die Sachen in der Tasche für getragene Items. Mit einem getragenen Item kannst du deine Pokémon stärken oder besondere Effekte erhalten. Wie man das benutzt? Na, so funktioniert\'s.',
    'Once you have obtained a Held Item, visit your Item Bag. They are most often found in Dungeons, but some, like the Wonder Chest, are for sale!': 'Sobald du ein getragenes Item erhalten hast, schau in deinen Beutel. Meistens findet man sie in Dungeons, aber manche, wie die Wonder Chest, kann man auch kaufen!',
    'From there, go into your Held Items pocket and once an item is selected, you can use it by choosing from the list of available Pokémon to hold it.': 'Geh dort in die Tasche für getragene Items, und sobald du ein Item ausgewählt hast, kannst du es benutzen, indem du aus der Liste der verfügbaren Pokémon eines auswählst, das es tragen soll.',
    'Choose who you select carefully! Once you remove a Held Item from your Pokémon, the item will break!': 'Wähle gut aus, wen du nimmst! Sobald du einem Pokémon ein getragenes Item wieder abnimmst, geht das Item kaputt!',
    'All righty, be seeing you and your <code class="text-nowrap">NEW-COLLECTION</code>!': 'Alles klar, bis bald, du und deine <code class="text-nowrap">NEW-COLLECTION</code>!',
    'Earl, I am! Teach you, I will! To be a better trainer!': 'Earl, ich bin! Lehren dich, ich werde! Ein besserer Trainer zu sein!',
    'Some Pokémon babies, only from Day Care they come! Hatch! Hatch! Hatch!': 'Manche Pokémon-Babys, nur aus der Pension sie kommen! Schlüpfen! Schlüpfen! Schlüpfen!',
    'Professor Elm tells me you are a master trainer. Please, show me your skills by training your Pokémon.': 'Professor Lind hat mir erzählt, dass du ein Meistertrainer bist. Bitte zeig mir dein Können, indem du deine Pokémon trainierst.',
    'You want to know about Celebi? It hasn\'t been seen in a long time.': 'Du willst etwas über [[pokemon::Celebi]] wissen? Es wurde schon lange nicht mehr gesehen.',
    'I remember, back in the day, it was the Guardian of Ilex Forest. It was a playful Pokémon. It loved playing with children.': 'Ich erinnere mich, früher war es der Hüter des Ilex Forest. Es war ein verspieltes Pokémon. Es liebte es, mit Kindern zu spielen.',
    'It was especially close to a kid named Samuel Oak. When he suddenly moved to Kanto, Celebi was quite sad. He never even said goodbye! I wonder what became of that boy. Maybe he knows more of where Celebi is right now. They certainly have Unfinished Business.': 'Besonders nahe stand es einem Jungen namens Samuel Eich. Als er plötzlich nach Kanto zog, war [[pokemon::Celebi]] ziemlich traurig. Er hat sich nicht einmal verabschiedet! Ich frage mich, was aus dem Jungen geworden ist. Vielleicht weiß er mehr darüber, wo [[pokemon::Celebi]] jetzt ist. Die beiden haben bestimmt noch eine Rechnung offen.',
    'Celebi got over it very quick, playful as it is. There are always other kids to play with. Then, some time later, a strange figure went into the forest with a golden Poké Ball. The Guardian hasn\'t been seen since.': '[[pokemon::Celebi]] kam schnell darüber hinweg, verspielt wie es ist. Es gibt ja immer andere Kinder zum Spielen. Doch einige Zeit später ging eine seltsame Gestalt mit einem goldenen Pokéball in den Wald. Seitdem wurde der Hüter nicht mehr gesehen.',
    'The PokéManiacs in Union Cave are restless. They have been ranting and raving about a weekly visitor.': 'Die Pokémaniacs in der Union Cave sind ganz aufgeregt. Sie reden ununterbrochen von einem wöchentlichen Besucher.',
    'According to them, a strange Pokémon\'s cries can be heard from a lake deep inside the cave.': 'Ihnen zufolge kann man die Rufe eines seltsamen Pokémon von einem See tief in der Höhle hören.',
    'I\'ve never heard it myself. Apparently it only happens on Fridays.': 'Ich selbst habe es noch nie gehört. Angeblich passiert das nur freitags.',
    'Those poor Slowpoke! I\'m not doing anything until those disgusting Rockets are gone!': 'Die armen [[pokemon::Slowpoke]]! Ich rühre keinen Finger, bis diese widerlichen Rockets verschwunden sind!',
    'Thank you for your help at the Slowpoke Well! You have something for me?': 'Danke für deine Hilfe im Slowpoke Well! Du hast etwas für mich?',
    'So this is it then? The GS Ball. I can see why old Oak wants me to have a crack at it.': 'Das ist er also? Der GS-Ball. Ich verstehe, warum der alte Eich will, dass ich mich daran versuche.',
    'I will need some time to figure this out. Please come back later.': 'Dafür brauche ich etwas Zeit. Bitte komm später wieder.',
    'Getting closer to the solution...': 'Ich komme der Lösung näher...',
    'I think I know what\'s in there... Better give Oak a call.': 'Ich glaube, ich weiß, was da drin ist... Ich sollte lieber Eich anrufen.',
    'What? Oh, I\'m just talking to myself. I\'m not done yet. Please come back later.': 'Was? Oh, ich rede nur mit mir selbst. Ich bin noch nicht fertig. Bitte komm später wieder.',
    'Welcome back Champ! I have good news and bad news.': 'Willkommen zurück, Champ! Ich habe gute und schlechte Neuigkeiten.',
    'Bad news first. I didn\'t manage to open the ball. It\'s just stuck. No way to get in there. Better give up on it. This story ends here.': 'Zuerst die schlechte. Ich habe den Ball nicht aufbekommen. Er klemmt einfach. Keine Chance, da reinzukommen. Gib ihn lieber auf. Die Geschichte endet hier.',
    'Naah! Just kidding! Imagine though, how disappointing that would be. What an anticlimax!': 'Neee! War nur ein Scherz! Stell dir aber mal vor, wie enttäuschend das wäre. Was für eine Antiklimax!',
    'Good news first then, I managed to open the ball! And there was a Celebi inside! Bad news, the Celebi immediately left. It just flew away.': 'Dann zuerst die gute: Ich habe den Ball aufbekommen! Und da war ein [[pokemon::Celebi]] drin! Die schlechte: Das [[pokemon::Celebi]] ist sofort verschwunden. Es ist einfach davongeflogen.',
    'Old Oak apparently had an encounter with this Celebi back when he was still young Oak. And he\'s here! He might know where the Celebi went, you should have a chat with him.': 'Der alte Eich hatte anscheinend schon eine Begegnung mit diesem [[pokemon::Celebi]], als er noch der junge Eich war. Und er ist hier! Vielleicht weiß er, wohin das [[pokemon::Celebi]] geflogen ist. Du solltest mit ihm sprechen.',
    'I knew it! I knew that Celebi was in there! Well, I didn\'t actually know. I had a feeling.': 'Ich wusste es! Ich wusste, dass [[pokemon::Celebi]] da drin war! Na ja, eigentlich wusste ich es nicht. Ich hatte so ein Gefühl.',
    'That Celebi is an old friend of mine. Back in the day it liked to hang out at the old shrine in Ilex Forest. You should go check it out and try to catch Celebi.': 'Dieses [[pokemon::Celebi]] ist ein alter Freund von mir. Früher hielt es sich gern beim alten Schrein im Ilex Forest auf. Du solltest dort nachsehen und versuchen, [[pokemon::Celebi]] zu fangen.',
    'I can\'t think of a better trainer for this Celebi.': 'Ich kann mir keinen besseren Trainer für dieses [[pokemon::Celebi]] vorstellen.',
    'Celebi wasn\'t there? Strange, usually it loves to play with young people at the shrine.': '[[pokemon::Celebi]] war nicht da? Seltsam, normalerweise spielt es so gern mit jungen Leuten am Schrein.',
    'Wait. You saw a Pichu with a spiked ear?! We used to play with it at that shrine way back when! Looks like it hasn\'t aged a day!': 'Moment. Du hast ein [[pokemon::Pichu]] mit einem Zackenohr gesehen?! Mit dem haben wir damals an diesem Schrein gespielt! Sieht aus, als wäre es keinen Tag älter geworden!',
    'It sounds like you encountered a Time Distortion. Celebi is sensitive to time, it must be distressed. I have heard rumors of something similar going on at Tohjo Falls. Maybe if you clear up that Time Distortion, Celebi will want to come out to play?': 'Es klingt, als wärst du auf eine Zeitverzerrung gestoßen. [[pokemon::Celebi]] ist empfindlich gegenüber der Zeit, es muss in Not sein. Ich habe Gerüchte gehört, dass an den Tohjo Falls etwas Ähnliches vor sich geht. Wenn du diese Zeitverzerrung beseitigst, will [[pokemon::Celebi]] vielleicht herauskommen und spielen?',
    'So Giovanni was there at the Falls while you were dealing with that mess at the Radio Tower? If only we had known, we could have had him arrested right then and there.': 'Giovanni war also an den Fällen, während du dich um das Chaos am Radio Tower gekümmert hast? Hätten wir das nur gewusst, dann hätten wir ihn auf der Stelle verhaften lassen können.',
    'The Time Distortion seems to have cleared up. Celebi should be happy now. You should go check out the Shrine again.': 'Die Zeitverzerrung scheint sich aufgelöst zu haben. [[pokemon::Celebi]] sollte jetzt glücklich sein. Du solltest noch einmal beim Schrein nachsehen.',
    'What\'s that? Celebi went back into the forest? Well, follow it!': 'Was sagst du? [[pokemon::Celebi]] ist zurück in den Wald gegangen? Na, dann folge ihm!',
    'If it wants to play I\'m sure a great trainer such as yourself can figure out a way that you can be friends and play all the time!': 'Wenn es spielen will, findet ein großartiger Trainer wie du bestimmt einen Weg, damit ihr Freunde werdet und die ganze Zeit zusammen spielen könnt!',
    'I\'m glad Celebi has been released from that wretched prison and has found a home with a great young trainer like yourself. I\'m going back to Kanto.': 'Ich bin froh, dass [[pokemon::Celebi]] aus diesem elenden Gefängnis befreit wurde und bei einem großartigen jungen Trainer wie dir ein Zuhause gefunden hat. Ich kehre nach Kanto zurück.',
    'Goodbye Celebi.': 'Leb wohl, [[pokemon::Celebi]].',
    'We\'re working on construction of a Magnet Train line to shuttle people <b>east to Kanto</b>. Once it\'s completed, people will be able to get to Saffron City in record time!': 'Wir bauen gerade an einer Magnetzug-Strecke, um Leute <b>nach Osten bis Kanto</b> zu bringen. Sobald sie fertig ist, kommt man in Rekordzeit nach Saffron City!',
    'I\'m supposed to meet my sisters, but the streets here just aren\'t safe! Can you protect me from Team Rocket?': 'Ich soll mich mit meinen Schwestern treffen, aber die Straßen hier sind einfach nicht sicher! Kannst du mich vor Team Rocket beschützen?',
    '<i>You look around the city in search of clues, and are set upon by a gang of angry Aipoms!</i>': '<i>Du suchst in der Stadt nach Hinweisen und wirst von einer Bande wütender [[pokemon::Aipom]] angegriffen!</i>',
    'I am Howard Clifford, CEO of Clifford Industries. I hear you have been investigating both my company, and a mysterious drug called R.': 'Ich bin Howard Clifford, Geschäftsführer von Clifford Industries. Wie ich höre, ermittelst du sowohl gegen meine Firma als auch wegen einer mysteriösen Droge namens R.',
    'I have reason to believe that a high ranking official in the company is manufacturing this drug, but have been unable to get to the bottom of it myself.': 'Ich habe Grund zu der Annahme, dass ein hochrangiger Mitarbeiter der Firma diese Droge herstellt, konnte der Sache aber selbst nicht auf den Grund gehen.',
    'There is a journalist in Hearthome City who may be able to help us both. Please make contact with her and report anything you find back to me.': 'In Hearthome City gibt es eine Journalistin, die uns beiden vielleicht helfen kann. Bitte nimm Kontakt mit ihr auf und berichte mir alles, was du herausfindest.',
    'You are too late to stop me! The R drug puts Pokémon in a frenzied state, and allows us to control them with the right equipment! You led me straight to Mewtwo, and now I will take control of the most powerful Pokémon in the world!': 'Du kommst zu spät, um mich aufzuhalten! Die Droge R versetzt Pokémon in einen Rauschzustand, und mit der richtigen Ausrüstung können wir sie kontrollieren! Du hast mich direkt zu [[pokemon::Mewtwo]] geführt, und jetzt werde ich die Kontrolle über das mächtigste Pokémon der Welt übernehmen!',
    '<i>Howard puts on a headset and pushes a button. The energy sphere containing Mewtwo comes into view, and it has a crazed look in its eyes. Howard pushes a button on his headset and slumps back in his chair.</i>': '<i>Howard setzt ein Headset auf und drückt einen Knopf. Die Energiekugel, in der sich [[pokemon::Mewtwo]] befindet, kommt in Sicht, und in seinen Augen liegt ein wahnsinniger Blick. Howard drückt einen Knopf an seinem Headset und sinkt in seinem Stuhl zusammen.</i>',
    '<i>Mewtwo makes eye contact with you, and you hear Howard\'s voice in your mind, laughing maniacally. An armed man comes into the room, and warns you not to move.</i>': '<i>[[pokemon::Mewtwo]] sieht dir direkt in die Augen, und du hörst Howards Stimme in deinem Kopf, wie er wahnsinnig lacht. Ein bewaffneter Mann betritt den Raum und warnt dich, dich nicht zu bewegen.</i>',
    'UNLIMITED POWER! YOU\'LL NEVER STOP ME!': 'UNBEGRENZTE MACHT! DU WIRST MICH NIEMALS AUFHALTEN!',
    'I traveled here all the way from Goldenrod to buy a Soothe Bell for my Eevee.': 'Ich bin extra aus Goldenrod hierher gereist, um eine Sanftglocke für mein [[pokemon::Eevee]] zu kaufen.',
    'When I use a Soothe Bell on Eevee it can evolve into Espeon or Umbreon. It depends on the time. Espeon during the day, Umbreon at night.': 'Wenn ich eine Sanftglocke bei [[pokemon::Eevee]] einsetze, kann es sich zu [[pokemon::Espeon]] oder [[pokemon::Umbreon]] entwickeln. Das hängt von der Tageszeit ab. [[pokemon::Espeon]] am Tag, [[pokemon::Umbreon]] in der Nacht.',
    'I only brought enough Quest Points for one Soothe Bell. It\'s so hard to choose...': 'Ich habe nur genug Questpunkte für eine Sanftglocke mitgebracht. Die Entscheidung ist so schwer...',
    'Legends say that when the Brass Tower burned down and became the Burned Tower, three unnamed Pokémon perished in the flames...': 'Der Legende nach kamen drei namenlose Pokémon in den Flammen um, als der Brass Tower niederbrannte und zum Burned Tower wurde...',
    'Ho-Oh came down from the Tin Tower and revived those Pokémon. They became the Legendary Beasts. Some say these Beasts still inhabit the basement of the Burned Tower.': '[[pokemon::Ho-Oh]] kam vom Tin Tower herab und erweckte diese Pokémon wieder zum Leben. Sie wurden zu den legendären Bestien. Manche sagen, dass diese Bestien noch immer im Keller des Burned Tower hausen.',
    'Could you please clear Burned Tower for me and see if this is true?': 'Könntest du bitte den Burned Tower für mich abschließen und nachsehen, ob das stimmt?',
    'I saw it! Did you see it?! I saw you go in there! I don\'t know what you did in the Burned Tower, but three great Beasts came running out of there!': 'Ich hab\'s gesehen! Hast du\'s gesehen?! Ich hab gesehen, wie du da reingegangen bist! Ich weiß nicht, was du im Burned Tower gemacht hast, aber drei große Bestien sind da herausgerannt!',
    'It was a great sight to behold. They all went in different directions. I think they are just roaming the region now. My friend Trevor in Blackthorn City can tell you more.': 'Das war ein großartiger Anblick. Sie sind alle in verschiedene Richtungen gelaufen. Ich glaube, sie streifen jetzt einfach durch die Region. Mein Freund Trevor in Blackthorn City kann dir mehr erzählen.',
    'Eusine was here a second ago. He seemed very excited, but then he suddenly left. I don\'t know where he went, but he seemed to be particularly interested in the blue one.': 'Eusin war gerade eben noch hier. Er wirkte sehr aufgeregt, aber dann ist er plötzlich gegangen. Ich weiß nicht, wohin, aber er schien sich besonders für das blaue zu interessieren.',
    'My sisters Zuki and Naoko tell me you have helped them, and I thank you. Please help find my other two sisters, Sayo and Kuni. Please accept this as a token of my gratitude.': 'Meine Schwestern Zuki und Naoko haben mir erzählt, dass du ihnen geholfen hast, und dafür danke ich dir. Bitte hilf mir, meine beiden anderen Schwestern Sayo und Kuni zu finden. Bitte nimm dies als Zeichen meiner Dankbarkeit an.',
    'We have been watching you, and see that you have tamed the three Pokémon revived by Ho-Oh in the Burned Tower. Show us your power and we shall give you the Clear Bell, which will call Ho-Oh to the Tin Tower.': 'Wir haben dich beobachtet und sehen, dass du die drei Pokémon gezähmt hast, die [[pokemon::Ho-Oh]] im Burned Tower wiederbelebt hat. Zeig uns deine Stärke, und wir geben dir die Klarglocke, die [[pokemon::Ho-Oh]] zum Tin Tower rufen wird.',
    'Aye! At this here dock you can travel to faraway regions! But only ones you’ve travelled to before; I’ve heard the Professor has his own vessel to take ye’ to new lands!': 'Aye! Von diesem Dock aus kannst du in ferne Regionen reisen! Aber nur in solche, in denen du schon einmal warst; ich hab gehört, der Professor hat sein eigenes Schiff, das dich in neue Länder bringt!',
    'Cameron the Photographer isn’t here right now; he’s off taking photos of Pokémon on Berry Farms. Did you know that some Berries can even attract rare Pokémon?': 'Cameron der Fotograf ist gerade nicht da; er fotografiert Pokémon auf Beerenfarmen. Wusstest du, dass manche Beeren sogar seltene Pokémon anlocken können?',
    'Yo, wasn\'t that Suicune just now? I only caught a quick glimpse, but I thought I saw Suicune running on the waves.': 'Hey, war das nicht gerade [[pokemon::Suicune]]? Ich habe es nur ganz kurz gesehen, aber ich dachte, ich hätte [[pokemon::Suicune]] über die Wellen laufen sehen.',
    'Suicune is beautiful and grand. And it races through towns and roads at simply awesome speeds. It\'s wonderful... I want to see Suicune up close....': '[[pokemon::Suicune]] ist wunderschön und erhaben. Und es rast mit einfach unglaublicher Geschwindigkeit durch Städte und über Straßen. Es ist wundervoll... Ich will [[pokemon::Suicune]] aus der Nähe sehen....',
    'I\'ve decided. I\'ll battle you as a trainer to earn Suicune\'s respect! Come on! Let\'s battle now!': 'Ich habe mich entschieden. Ich kämpfe als Trainer gegen dich, um mir [[pokemon::Suicune]]s Respekt zu verdienen! Los! Lass uns jetzt kämpfen!',
    'Huh? You need medicine? Your Pokémon appear to be fine. Is something worrying you?': 'Hä? Du brauchst Medizin? Deine Pokémon scheinen doch in Ordnung zu sein. Bedrückt dich etwas?',
    'The Lighthouse Pokémon is in trouble? I\'ll prepare some medicine right now but it will take some time!': 'Das Pokémon im Leuchtturm ist in Schwierigkeiten? Ich bereite sofort etwas Medizin vor, aber das wird eine Weile dauern!',
    'I got it! This ought to do the trick.': 'Ich hab\'s! Damit sollte es klappen.',
    '<i>You got a \'Secret Potion\'</i>': '<i>Du hast eine „Geheimmedizin“ erhalten</i>',
    'We’ve got stuff here nobody else has got! But keep any Dowsing Machines you have away from the merchandise… especially the RageCandyBars.': 'Hier gibt\'s Sachen, die sonst keiner hat! Aber halt deine Itemradare von der Ware fern... besonders von den Wutkeksen.',
    'Keep ‘em outside where they belong! I’ve heard those machines can attract Pokémon with Held Items more often, and even more so in Dungeons!': 'Lass sie draußen, wo sie hingehören! Ich habe gehört, dass diese Geräte öfter Pokémon mit getragenen Items anlocken, und in Dungeons sogar noch mehr!',
    'You made it to Mahogany without troubles? Did you see anything suspicious?': 'Du hast es ohne Probleme nach Mahogany geschafft? Hast du etwas Verdächtiges gesehen?',
    'Some adventurers reported criminal activities on route 42. Team Rocket are allegedly attempting to steal newborn Phanpy...': 'Einige Abenteurer haben kriminelle Aktivitäten auf Route 42 gemeldet. Team Rocket versucht angeblich, neugeborene [[pokemon::Phanpy]] zu stehlen...',
    'Suicune... How brave it is! How refreshing it is! How beautiful it is! And how quickly it moves! It seems to be heading east.': '[[pokemon::Suicune]]... Wie mutig es ist! Wie erfrischend es ist! Wie wunderschön es ist! Und wie schnell es sich bewegt! Es scheint nach Osten zu ziehen.',
    'You seem to be around where Suicune would appear. Well, that\'s OK. My desire to search for Suicune is far beyond yours... My grandpa was...quite into myths. I\'ve heard so many stories about Suicune from him.': 'Du scheinst dich dort aufzuhalten, wo [[pokemon::Suicune]] auftauchen würde. Na ja, schon gut. Mein Wunsch, [[pokemon::Suicune]] zu finden, ist viel größer als deiner... Mein Großvater war... ganz vernarrt in Mythen. Ich habe so viele Geschichten über [[pokemon::Suicune]] von ihm gehört.',
    'Suicune... I won\'t stop following you until I\'ve found out what you\'re after... You hear me!': '[[pokemon::Suicune]]... Ich werde dir folgen, bis ich herausgefunden habe, was du vorhast... Hörst du mich!',
    'On the news, they are getting more reports of roaming Pokémon appearing on {ROUTE_NAME}!': 'In den Nachrichten gibt es immer mehr Berichte über umherstreifende Pokémon, die auf {ROUTE_NAME} auftauchen!',
    'Welcome to the National Park!': 'Willkommen im National Park!',
    'Lots of people come through here to take a stroll, and some come from far away to participate in our Bug Catching Contest!': 'Viele Leute kommen hierher, um spazieren zu gehen, und manche kommen sogar von weit her, um an unserem Käferturnier teilzunehmen!',
    'All kinds of Bug Pokémon can be found in the park! Each one can be caught for Contest Tokens, and more powerful Pokémon are worth more Tokens!': 'Im Park gibt es alle möglichen Käfer-Pokémon! Jedes davon kann gegen Wettbewerbs-Token gefangen werden, und stärkere Pokémon sind mehr Token wert!',
    'Thanks to recent breakthroughs in the field of alloying and electroplating, we have discovered a way to coat some Pokémon in metal!': 'Dank neuer Durchbrüche im Bereich der Legierung und Galvanisierung haben wir einen Weg entdeckt, manche Pokémon mit Metall zu überziehen!',
    'An experimental specimen can be bought here: A Sudowoodo that is no longer weak against Water attacks!': 'Hier kann man ein Versuchsexemplar kaufen: ein [[pokemon::Sudowoodo]], das nicht mehr anfällig für Wasser-Attacken ist!',
    '<i>Something strange is going on here. The air seems to curve around itself. You feel like you\'re here, but also not here at the same time.</i>': '<i>Hier geht etwas Seltsames vor sich. Die Luft scheint sich um sich selbst zu krümmen. Du fühlst dich, als wärst du hier und gleichzeitig auch nicht hier.</i>',
    '<i>No sign of Celebi, but you do see a strange looking Pichu approaching.</i>': '<i>Keine Spur von [[pokemon::Celebi]], aber du siehst ein seltsam aussehendes [[pokemon::Pichu]] näherkommen.</i>',
    '<i>Everything is normal.</i>': '<i>Alles ist normal.</i>',
    '<i>Celebi is here! It seems to want to play with you, but every time you approach it backs off. It\'s luring you deeper into the forest!</i>': '<i>[[pokemon::Celebi]] ist hier! Es scheint mit dir spielen zu wollen, aber jedes Mal, wenn du dich näherst, weicht es zurück. Es lockt dich tiefer in den Wald!</i>',
    '<i>What would the professor do?</i>': '<i>Was würde der Professor tun?</i>',
    'I\'m looking for a strange Pichu, have you seen it? According to rumors, its favorite hiding spots are chests...': 'Ich suche ein seltsames [[pokemon::Pichu]], hast du es gesehen? Gerüchten zufolge versteckt es sich am liebsten in Truhen...',
    'I seem to have lost my way in the forest. Can you show me the way out?': 'Ich habe mich wohl im Wald verirrt. Kannst du mir den Weg hinaus zeigen?',
    '...This Pokémon always kept the sea lit at night... But it suddenly got sick... It’s gasping for air...': '...Dieses Pokémon hat das Meer nachts immer beleuchtet... Aber plötzlich ist es krank geworden... Es ringt nach Luft...',
    '...I understand that there is a wonderful Pharmacy in Cianwood... But that’s across the sea... And I can’t leave Amphy unattended...': '...Ich habe gehört, dass es in Cianwood eine wunderbare Apotheke gibt... Aber die liegt auf der anderen Seite des Meeres... Und ich kann Ampi nicht allein lassen...',
    'May I ask you to get some medicine for me? Please?': 'Darf ich dich bitten, Medizin für mich zu besorgen? Bitte?',
    ' ...Oh, I’m so relieved... This is just so wonderful... Thank you so very, very much.': ' ...Oh, ich bin so erleichtert... Das ist einfach so wunderbar... Vielen, vielen herzlichen Dank.',
    '...I will return to the Gym...': '...Ich werde in die Arena zurückkehren...',
    '<i>Ampharos seems to feel better.</i>': '<i>[[pokemon::Ampharos]] scheint es besser zu gehen.</i>',
    'With the power of the Tidal Bell, we call to Lugia! Guardian of the Whirl Islands!': 'Mit der Kraft der Gischtglocke rufen wir [[pokemon::Lugia]]! Den Hüter der Whirl Islands!',
    'Excuse me! I\'m stuck out here on the ice, can you give me a quick push?': 'Entschuldigung! Ich stecke hier draußen auf dem Eis fest, kannst du mir kurz einen Schubs geben?',
    '<i>You are experiencing that same feeling again. Like you\'re not really here.</i>': '<i>Du hast wieder dasselbe Gefühl. Als wärst du nicht wirklich hier.</i>',
    '<i>A man sits in the back of the cave. He is listening to a portable radio.</i>': '<i>Im hinteren Teil der Höhle sitzt ein Mann. Er hört ein tragbares Radio.</i>',
    '...I don\'t know why you have come here. Anyway, I have to warn you that this is not a place for kids like you.': '...Ich weiß nicht, warum du hergekommen bist. Jedenfalls muss ich dich warnen, dass dies kein Ort für Kinder wie dich ist.',
    'You have a certain look... You\'re the kid who stood in front of me in Viridian City! I\'m on my way to Goldenrod City to answer the call and join my team. Are you going to get in my way?': 'Du hast so einen gewissen Blick... Du bist das Kind, das mir in Viridian City gegenübergestanden hat! Ich bin auf dem Weg nach Goldenrod City, um dem Ruf zu folgen und mich meinem Team anzuschließen. Willst du mir etwa im Weg stehen?',
    'This young fellow comes here every day.': 'Dieser junge Bursche kommt jeden Tag hierher.',
    'He is a sore loser, poor boy. But he always comes back next day!': 'Er ist ein schlechter Verlierer, der arme Junge. Aber er kommt immer am nächsten Tag wieder!',
    'But even though he is a sore loser, he will always give his opponent a shiny ball, as a reward for winning.': 'Aber obwohl er ein schlechter Verlierer ist, gibt er seinem Gegner immer eine schillernde Kugel als Belohnung für den Sieg.',
    'We have received word from Mr. Pokémon in Johto! He has made another breakthrough.': 'Wir haben Nachricht von Mr. Pokémon aus Johto erhalten! Ihm ist ein weiterer Durchbruch gelungen.',
    'You can now store an additional four eggs in the queue! His research has really gained speed.': 'Du kannst jetzt vier weitere Eier in der Warteschlange aufbewahren! Seine Forschung kommt wirklich schnell voran.',
    'He wants you to know that he will have an additional eight slots ready by the time you reach Sinnoh.': 'Er lässt dir ausrichten, dass er acht weitere Plätze bereit haben wird, bis du Sinnoh erreichst.',
    'Reports are coming in from across Hoenn that two fast-moving Pokémon have appeared!': 'Aus ganz Hoenn kommen Berichte, dass zwei schnelle Pokémon aufgetaucht sind!',
    'These elusive Pokémon are Blue and Red and White all over, and our reporters will give you the latest updates as we try to discern their identity and location!': 'Diese schwer fassbaren Pokémon sind über und über blau, rot und weiß, und unsere Reporter halten dich auf dem Laufenden, während wir versuchen, ihre Identität und ihren Aufenthaltsort herauszufinden!',
    'A hot new vacation spot is waiting for you!': 'Ein angesagtes neues Urlaubsziel wartet auf dich!',
    'Come to the Hoenn Pokémon League to claim your free Eon Ticket today!': 'Komm noch heute zur Hoenn Pokémon League und hol dir dein kostenloses Äon-Ticket!',
    'Supplies are limited, reserve your spot on a cruise to the Southern Island!': 'Das Angebot ist begrenzt, reserviere dir deinen Platz auf einer Kreuzfahrt zur Southern Island!',
    'Funny meeting you here, $playername$! I was just going to meet up with Professor Birch to discuss this weird stone I found. It seems to have a powerful energy hidden inside. I wonder if it\'s one of the Key Stones I\'ve heard let Pokémon Mega Evolve?': 'Was für ein Zufall, dich hier zu treffen, $playername$! Ich wollte mich gerade mit Professor Birk treffen, um über diesen seltsamen Stein zu sprechen, den ich gefunden habe. Er scheint eine mächtige Energie in sich zu bergen. Ob das wohl einer der Schlüsselsteine ist, mit denen Pokémon die Mega-Entwicklung vollziehen können?',
    'Who\'s this? You have a new friend? Zinnia is her name? Nice to meet you!': 'Wer ist das? Du hast eine neue Freundin? Sie heißt Amalia? Schön, dich kennenzulernen!',
    'Tell you what, I\'ll show Zinnia around town for a little bit, you should go see the Professor. He had some interesting news.': 'Weißt du was, ich zeige Amalia ein bisschen die Stadt, und du solltest zum Professor gehen. Er hatte interessante Neuigkeiten.',
    '<i>Zinnia and May head off to May\'s house, discussing Pokémon.': '<i>Amalia und Maike gehen zu Maikes Haus und unterhalten sich über Pokémon.',
    'Hello again, $playername$! It\'s been a while since you last visited!': 'Hallo noch mal, $playername$! Es ist schon eine Weile her, seit du zuletzt hier warst!',
    'There\'s been a lot of hubbub and excitement in the region since the Mossdeep Space Center announced that a meteor was headed our way. This has lead to a lot of new faces in Hoenn.': 'In der Region herrscht viel Trubel und Aufregung, seit das Mossdeep Space Center bekannt gegeben hat, dass ein Meteor auf uns zukommt. Das hat viele neue Gesichter nach Hoenn gebracht.',
    'Some of them have been carrying small but powerful items known as Key Stones. These have the power to let Pokémon Mega Evolve! You may have experienced something like that in Kalos, but it\'s new to us here.': 'Einige von ihnen tragen kleine, aber mächtige Gegenstände bei sich, die man Schlüsselsteine nennt. Sie haben die Kraft, Pokémon die Mega-Entwicklung zu ermöglichen! Vielleicht hast du so etwas schon in Kalos erlebt, aber für uns hier ist es neu.',
    'Keep an eye out for new faces in familiar places!': 'Halte Ausschau nach neuen Gesichtern an vertrauten Orten!',
    'Whats the big idea, $playername$?!?': 'Was soll das, $playername$?!?',
    'Your new friend waited until my back was turned, stole my Key Stone, and skipped town!': 'Deine neue Freundin hat gewartet, bis ich ihr den Rücken zugedreht habe, hat meinen Schlüsselstein gestohlen und sich aus dem Staub gemacht!',
    'She was headed towards Petalburg City. You better help me get my Key Stone back!': 'Sie war auf dem Weg nach Petalburg City. Du hilfst mir besser, meinen Schlüsselstein zurückzubekommen!',
    'Hey trainer, look at these footprints! Huh, I’ve never seen footprints like these before… They look like they came from two different Pokémon, and I saw two blurs, one red and one blue, quickly fly away just as I exited the Pokémon Center.': 'Hey, Trainer, sieh dir diese Fußspuren an! Hm, solche Fußspuren habe ich noch nie gesehen... Sie sehen aus, als stammten sie von zwei verschiedenen Pokémon, und ich habe zwei verschwommene Gestalten gesehen, eine rote und eine blaue, die schnell davonflogen, gerade als ich aus dem Pokémon Center kam.',
    'They were flying really fast, I bet Pokémon that fast will only challenge trainers who have proven they are as strong as Champion Wallace...': 'Sie flogen wirklich schnell. Ich wette, so schnelle Pokémon fordern nur Trainer heraus, die bewiesen haben, dass sie so stark sind wie Champ Wassili...',
    'Hello? Is that you, $playername$? It\'s me. Steven. Have you been doing well?': 'Hallo? Bist du das, $playername$? Ich bin\'s. Troy. Geht es dir gut?',
    'I imagine you must be quite shocked. This is a communication mode that Devon is still currently developing. It comes installed on every Holo Caster. I thought I would only use it if I needed to contact you urgently.': 'Du bist bestimmt ziemlich überrascht. Das ist eine Kommunikationsfunktion, die Devon noch entwickelt. Sie ist auf jedem Holo-Log installiert. Ich dachte, ich würde sie nur benutzen, wenn ich dich dringend erreichen muss.',
    'But it looks as though that time has already come. I\'m sorry to ask this of you, but I need your help getting some materials for Devon Corporation\'s new rocket project. We think we can help Dr. Cozmo stop the incoming meteor.': 'Aber es sieht so aus, als wäre dieser Zeitpunkt schon gekommen. Es tut mir leid, dich darum zu bitten, aber ich brauche deine Hilfe, um Materialien für das neue Raketenprojekt der Devon Corporation zu besorgen. Wir glauben, dass wir Dr. Cozmo helfen können, den herannahenden Meteor aufzuhalten.',
    'Our company\'s records indicate that a meteor landed in Granite Cave thousands of years ago. Can you search the area for fragments of that meteor?': 'Laut den Aufzeichnungen unserer Firma ist vor Tausenden von Jahren ein Meteor in der Granite Cave eingeschlagen. Kannst du die Gegend nach Bruchstücken dieses Meteors absuchen?',
    'Oh, and my father was asking about you. Look out for him in Rustboro City.': 'Ach, und mein Vater hat nach dir gefragt. Halte in Rustboro City nach ihm Ausschau.',
    'Thank you so much, $playername$... those strange people suddenly attacked me, demanding that I hand over my Key Stone! The truth is that I couldn\'t give it to them even if I wanted to.': 'Vielen Dank, $playername$... Diese seltsamen Leute haben mich plötzlich angegriffen und verlangt, dass ich ihnen meinen Schlüsselstein gebe! Ehrlich gesagt hätte ich ihn ihnen nicht einmal geben können, wenn ich gewollt hätte.',
    'My Key Stone is gone. I left it in the house when I went out, and it just disappeared. What in the world is going on? If someone like that ever shows up again... I\'ve gotta protect my mom and dad. You be careful, too!': 'Mein Schlüsselstein ist weg. Ich habe ihn im Haus gelassen, als ich rausgegangen bin, und er ist einfach verschwunden. Was um alles in der Welt ist hier los? Falls so jemand noch mal auftaucht... muss ich meine Mama und meinen Papa beschützen. Sei du auch vorsichtig!',
    'Every so often, I\'ll snag an old fossil from the seafloor. It weirds me out to think of all the Pokémon that used to crawl around the ocean so many years ago, but it also reminds me that life is fleeting and precious.': 'Ab und zu ziehe ich ein altes Fossil vom Meeresgrund hoch. Es ist mir unheimlich, an all die Pokémon zu denken, die vor so vielen Jahren im Ozean herumgekrochen sind, aber es erinnert mich auch daran, dass das Leben vergänglich und kostbar ist.',
    'So far I\'ve found two that I relate to, a kind of flower-looking thing and one that looks like a bug pincer.': 'Bisher habe ich zwei gefunden, mit denen ich etwas anfangen kann: eine Art blumenähnliches Ding und eines, das wie eine Käferzange aussieht.',
    'I wonder what you\'ll feel the next time you find one.': 'Ich frage mich, was du fühlen wirst, wenn du das nächste Mal eines findest.',
    'Our sources indicate that roaming Pokémon are gathering on {ROUTE_NAME}!': 'Unseren Quellen zufolge versammeln sich umherstreifende Pokémon auf {ROUTE_NAME}!',
    'Hello, $playername$! It\'s good to see you again, but I have some dire news.': 'Hallo, $playername$! Schön, dich wiederzusehen, aber ich habe beunruhigende Neuigkeiten.',
    'Despite Zinnia having stolen their leaders Key Stones, Team Aqua and Team Magma seem to be at it again, cooking up a scheme involving something called "Primal Reversion".': 'Obwohl Amalia die Schlüsselsteine ihrer Anführer gestohlen hat, scheinen Team Aqua und Team Magma wieder etwas im Schilde zu führen. Sie hecken einen Plan aus, bei dem es um etwas namens „Protomorphose“ geht.',
    'My researchers tell me that there is a mural carved into the wall of Granite Cave that has some information about "Primal Reversion". Can you find it, and report back?': 'Meine Forscher sagen, dass es in der Granite Cave ein Wandbild gibt, das Informationen über die „Protomorphose“ enthält. Kannst du es finden und mir berichten?',
    'Thank you, $playername$! Your heroics have saved Hoenn once again!': 'Danke, $playername$! Deine Heldentaten haben Hoenn wieder einmal gerettet!',
    'My researchers tell me that since their defeat, Groudon and Kyogre have been reverting to their primal forms in the Cave of Origin during Harsh Sunlight and Rainy weather.': 'Meine Forscher sagen, dass [[pokemon::Groudon]] und [[pokemon::Kyogre]] seit ihrer Niederlage bei starkem Sonnenlicht und Regenwetter in der Cave of Origin wieder ihre Protoformen annehmen.',
    'They are certainly very dangerous, but it doesn\'t seem like they are a threat to the region anymore.': 'Sie sind sicherlich sehr gefährlich, aber es scheint nicht, als wären sie noch eine Bedrohung für die Region.',
    'There\'s some salesman offering rare fish east of New Mauville, out on the water.': 'Östlich von New Mauville bietet draußen auf dem Wasser irgendein Verkäufer seltene Fische an.',
    'I\'m a bit skeptical of his wares, especially since his shop isn\'t on any maps.': 'Ich bin bei seiner Ware etwas skeptisch, vor allem, weil sein Laden auf keiner Karte verzeichnet ist.',
    'The boss said to take a look around here and call him if I found anything cool!': 'Der Boss hat gesagt, ich soll mich hier umsehen und ihn anrufen, wenn ich was Cooles finde!',
    'I can\'t believe you beat up the boss! Better get out of here before he comes back!': 'Ich fasse es nicht, dass du den Boss verprügelt hast! Ich verschwinde besser, bevor er zurückkommt!',
    'Hoy thar, matey! What\'s that? You lookin\' for Cap\'n Stern, are ya? That ol\' Jack Tar! A loose cannon \'e is! You\'ll only see \'im ashore in a Thunderstorm. \'E\'ll say it\'s all due to protocol but the trut\' is lightnin\' scares \'im stem to stern! Didn\' \'ear that from me \'ough...': 'Ahoi, Landratte! Was? Du suchst nach Käpt\'n Stern, was? Diesem alten Seebären! \'n echtes Pulverfass is\' er! An Land siehst du \'n nur bei Gewitter. Er wird sagen, das wär\' alles Vorschrift, aber in Wahrheit jagt ihm der Blitz Angst ein, von Bug bis Heck! Hast du aber nich\' von mir gehört...',
    'If ya feel like meetin\' \'im, the fine folks at the Weather Insitute can tell you when the next storm\'s brewin\'.': 'Wenn du \'n treffen willst, können dir die netten Leute vom Weather Institute sagen, wann sich das nächste Unwetter zusammenbraut.',
    'Ahoy! What brings you to this port?': 'Ahoi! Was führt dich in diesen Hafen?',
    'On the search for mysteries of the sea, eh? Well then I have one whale of a tale for you! But are yeh worthy?': 'Auf der Suche nach den Geheimnissen des Meeres, was? Na dann hab ich ein gewaltiges Seemannsgarn für dich! Aber bist du dessen würdig?',
    'I see you can be trusted with the mysteries of the sea!': 'Ich sehe, man kann dir die Geheimnisse des Meeres anvertrauen!',
    'I have been seeing a lot of strange activity around the Seafloor Cavern recently. Whirlpools, thunderstorms, and all nature of strange beasts.': 'In letzter Zeit habe ich rund um die Seafloor Cavern viele seltsame Vorgänge beobachtet. Strudel, Gewitter und alle möglichen seltsamen Kreaturen.',
    'There\'s an old submarine around here that I\'ve been working on upgrading to go explore the lowest parts of that cavern, but need some help getting the parts.': 'Hier in der Nähe liegt ein altes U-Boot, das ich gerade aufrüste, um die tiefsten Stellen dieser Höhle zu erkunden, aber ich brauche Hilfe beim Beschaffen der Teile.',
    'The hull needs some new Metal Coating, the ballast tanks need filled with Mystic Water, and some Heat Rocks are needed for a dive that deep.': 'Der Rumpf braucht einen neuen Metallmantel, die Ballasttanks müssen mit Zauberwasser gefüllt werden, und für einen so tiefen Tauchgang braucht man ein paar Heißbrocken.',
    'Thanks for getting all the supplies together, $playername$!': 'Danke, dass du alle Vorräte zusammengetragen hast, $playername$!',
    'We\'re ready to set sail to the Seafloor Cavern!': 'Wir sind bereit, zur Seafloor Cavern in See zu stechen!',
    'I\'m hunting for rare stones! If I find any extras, I\'ll sell you some!': 'Ich bin auf der Jagd nach seltenen Steinen! Wenn ich welche übrig habe, verkaufe ich dir ein paar!',
    'I\'m selling some unusual stones for gems. Let me know if any of them strike your fancy!': 'Ich verkaufe ein paar ungewöhnliche Steine gegen Edelsteine. Sag mir Bescheid, wenn dir einer davon gefällt!',
    'Oh! Welcome, welcome. Do you by any chance have any Meteorites? No? Ah well, I’m studying the Pokémon Deoxys and I’ve heard that a Meteorite can cause it to change forms!': 'Oh! Willkommen, willkommen. Hast du zufällig Meteoriten dabei? Nein? Na ja, ich erforsche das Pokémon [[pokemon::Deoxys]], und ich habe gehört, dass ein Meteorit es dazu bringen kann, seine Form zu ändern!',
    'I’ve also heard that the Battle Frontier may have some secrets relevant to Deoxys and its forms… but I’m not strong enough to find out...': 'Ich habe auch gehört, dass es im Battle Frontier vielleicht Geheimnisse über [[pokemon::Deoxys]] und seine Formen gibt... aber ich bin nicht stark genug, um es herauszufinden...',
    'Reports are coming in from the Mossdeep Space Center that a meteor is headed our way!': 'Aus dem Mossdeep Space Center kommen Berichte, dass ein Meteor auf uns zukommt!',
    'It\'s on a collision course with an island north of Route 131. I\'ve been tasked with finding a way to stop this meteor.': 'Er ist auf Kollisionskurs mit einer Insel nördlich von Route 131. Ich wurde beauftragt, einen Weg zu finden, diesen Meteor aufzuhalten.',
    '$playername$, can you go to that island and look for anything that might be able to help us?': '$playername$, kannst du zu dieser Insel gehen und nach etwas suchen, das uns helfen könnte?',
    '<i>The Millennium Comet is about to make its long-awaited appearance in the sky again, supposedly granting the wishes of all those who see it in the skies above them.</i>': '<i>Der Millenniumskomet wird bald wieder lang ersehnt am Himmel erscheinen und angeblich die Wünsche all jener erfüllen, die ihn über sich am Himmel sehen.</i>',
    '<i>A festival celebrating the arrival of this comet is being held with rides, carnival games, and even a magic show by the Great Butler!</i>': '<i>Zur Ankunft des Kometen wird ein Fest mit Fahrgeschäften, Jahrmarktspielen und sogar einer Zaubershow des Großen Butler gefeiert!</i>',
    '<i>The magic show features many exciting tricks performed by humans and Pokémon, but it looks like someone is crashing the party!</i>': '<i>In der Zaubershow führen Menschen und Pokémon viele spannende Tricks vor, aber es sieht so aus, als würde jemand die Party stören!</i>',
    'I, the Great Butler, thank you for dealing with Team Rocket!': 'Ich, der Große Butler, danke dir, dass du dich um Team Rocket gekümmert hast!',
    'I have been preparing for the Millennium Festival my whole life, and have big plans for the wish-granting powers it possesses.': 'Ich habe mich mein ganzes Leben lang auf das Millenniumsfest vorbereitet und habe große Pläne mit seinen wunscherfüllenden Kräften.',
    'I have found what appears to be a crystalline cocoon that contains Jirachi, the Wish Pokémon! I would be honored if you would take this cocoon as thanks for helping me. Legend has it that Jirachi will appear for a trainer who is pure of heart and grant them a wish!': 'Ich habe etwas gefunden, das wie ein kristalliner Kokon aussieht, in dem sich [[pokemon::Jirachi]], das Wunsch-Pokémon, befindet! Es wäre mir eine Ehre, wenn du diesen Kokon als Dank für deine Hilfe annehmen würdest. Der Legende nach erscheint [[pokemon::Jirachi]] einem Trainer mit reinem Herzen und erfüllt ihm einen Wunsch!',
    '<i>Butler gives you a crystalline cocoon containing Jirachi.</i>': '<i>Butler gibt dir einen kristallinen Kokon, in dem sich [[pokemon::Jirachi]] befindet.</i>',
    'I have spent weeks finding the perfect fishing spot for Feebas, and finally got some! For a special low price, I\'ll sell you one!': 'Ich habe wochenlang nach dem perfekten Angelplatz für [[pokemon::Feebas]] gesucht und endlich welche gefangen! Zu einem besonders günstigen Preis verkaufe ich dir eines!',
    'All sales are final!': 'Umtausch ausgeschlossen!',
    'Castform is a very finicky Pokémon.': '[[pokemon::Castform]] ist ein sehr launisches Pokémon.',
    'It changes forms when the weather is drastically different.': 'Es ändert seine Form, wenn sich das Wetter drastisch ändert.',
    'If you want to collect them all, wait for the weather to change.': 'Wenn du alle sammeln willst, warte, bis sich das Wetter ändert.',
    'Have you seen this? It\'s horrific. Absolutely despicable.': 'Hast du das gesehen? Es ist grauenhaft. Absolut verabscheuungswürdig.',
    'Disposable Dowsing Machines! Who even came up with this?! People leave these everywhere. It\'s absolutely terrible for the environment. Some poor innocent Pokémon could choke on it!': 'Einweg-Itemradare! Wer hat sich das überhaupt ausgedacht?! Die Leute lassen die überall liegen. Das ist absolut schrecklich für die Umwelt. Ein armes, unschuldiges Pokémon könnte daran ersticken!',
    'Please recycle your used Dowsing Machines.': 'Bitte recycle deine benutzten Itemradare.',
    'Yo! What\'s up! I\'ve been wandering around here, trying to find the best atmosphere to practice.': 'Yo! Was geht! Ich ziehe hier herum und suche die beste Atmosphäre zum Üben.',
    'Strangely, while I was out and about earlier, I heard a strange chiming noise. Completely threw me off my rhythm, I\'ll tell you what. Terrible sound quality!': 'Seltsamerweise habe ich vorhin unterwegs ein seltsames Klingeln gehört. Hat mich total aus dem Rhythmus gebracht, das sag ich dir. Grauenhafte Klangqualität!',
    'If that\'s something that would interest you, then just keep an ear out for chimes, they must be happening for a reason.': 'Wenn dich so was interessiert, dann halt einfach die Ohren nach Glockenspiel offen, das muss ja einen Grund haben.',
    '...What\'s that? This game doesn\'t have music?': '...Was sagst du? Dieses Spiel hat keine Musik?',
    'Right, I\'ll choose to pretend I know what you mean by that. In that case I think I was sitting under a small tree when I heard it. Sorry I can\'t give any more information.': 'Na gut, ich tu einfach so, als wüsste ich, was du damit meinst. Jedenfalls glaube ich, dass ich unter einem kleinen Baum saß, als ich es gehört habe. Tut mir leid, mehr kann ich dir nicht sagen.',
    'I have been investigating the behavior of Kecleon, the Color Swap Pokémon.': 'Ich habe das Verhalten von [[pokemon::Kecleon]], dem Farbwechsel-Pokémon, untersucht.',
    'There are a few hidden near the city. If you can find them all, I will give you a wonderful prize!': 'Ein paar davon verstecken sich in der Nähe der Stadt. Wenn du sie alle findest, gebe ich dir einen wunderbaren Preis!',
    'Thank you for finding the hidden Kecleons for me! Please accept this picture of a camouflaged Kecleon as your reward.': 'Danke, dass du die versteckten [[pokemon::Kecleon]] für mich gefunden hast! Bitte nimm dieses Bild eines getarnten [[pokemon::Kecleon]] als Belohnung an.',
    'Step right up! Get your Chimecho while they last! Chimecho, a very rare Pokémon indeed, with a voice that\'s both beautiful and powerful. Look closer! I see it bringing a smile to your face, just gazing into those loving eyes! They say these are the most gentle, healing eyes in the Pokémon kingdom.': 'Immer hereinspaziert! Holt euch euer [[pokemon::Chimecho]], solange der Vorrat reicht! [[pokemon::Chimecho]], ein wirklich sehr seltenes Pokémon, mit einer Stimme, die zugleich wunderschön und kraftvoll ist. Sieh genauer hin! Ich sehe schon, wie es dir ein Lächeln ins Gesicht zaubert, wenn du nur in diese liebevollen Augen blickst! Man sagt, es seien die sanftesten, heilsamsten Augen im ganzen Pokémon-Reich.',
    'That\'s not all! Just look at the way Chimecho\'s tail swings and sways with the wind, like a weeping willow in a summer breeze. In really hot weather, it will act like a fan to help you cool off. And when it\'s cold outside, your Chimecho can wrap itself around your neck like a scarf, to keep you warm.': 'Und das ist noch nicht alles! Sieh nur, wie [[pokemon::Chimecho]]s Schweif im Wind schwingt und sich wiegt, wie eine Trauerweide in einer Sommerbrise. Bei richtig heißem Wetter dient es dir als Fächer, damit du dich abkühlen kannst. Und wenn es draußen kalt ist, kann sich dein [[pokemon::Chimecho]] wie ein Schal um deinen Hals wickeln, um dich warm zu halten.',
    'And one more thing. It\'s not widely known, but it\'s a true fact; Chimecho are able to choose winning lottery tickets! Soo you see, my friend, just having a Chimecho with you, is a sure-fire ticket to happiness and success. Let Chimecho give you total peace and happiness, for a good price!': 'Und noch etwas. Es ist nicht allgemein bekannt, aber es ist eine wahre Tatsache: [[pokemon::Chimecho]] können Lottoscheine mit Gewinn auswählen! Siehst du, mein Freund, ein [[pokemon::Chimecho]] bei dir zu haben, ist eine todsichere Eintrittskarte zu Glück und Erfolg. Lass dir von [[pokemon::Chimecho]] vollkommenen Frieden und Glück schenken, zu einem guten Preis!',
    'Hey did you know about the Millennium Comet? We can see it in the sky right now, and it only comes around once every thousand years!': 'Hey, wusstest du schon vom Millenniumskometen? Wir können ihn gerade am Himmel sehen, und er kommt nur alle tausend Jahre vorbei!',
    'There’s a legend that a mythical Wish Pokémon awakens when it passes over us. If you’re as strong as the Champion, maybe you’ll find it roaming around Hoenn granting wishes!': 'Einer Legende nach erwacht ein mysteriöses Wunsch-Pokémon, wenn er über uns hinwegzieht. Wenn du so stark bist wie der Champ, findest du es vielleicht, wie es durch Hoenn streift und Wünsche erfüllt!',
    'WHAT? Recheck the data! Update the course calculations and confirm the new trajectory! But changing trajectories midflight... It\'s almost like it\'s alive.': 'WAS? Überprüft die Daten noch einmal! Aktualisiert die Kursberechnungen und bestätigt die neue Flugbahn! Aber die Flugbahn mitten im Flug zu ändern... Es ist fast so, als wäre es lebendig.',
    'Oh, $playername$, I didn\'t see you there. And you brought the Meteorite Shard with you. Well done!': 'Oh, $playername$, ich habe dich gar nicht bemerkt. Und du hast das Meteoritenstück mitgebracht. Gut gemacht!',
    'Thank you for bringing it, this will really help our plan to stop the meteor. Our current plan involves using the Infinity Energy within our rocket, combined with the life energy of humans found in Key Stones.': 'Danke, dass du es hergebracht hast, das wird unserem Plan, den Meteor aufzuhalten, wirklich helfen. Unser aktueller Plan sieht vor, die Unendlichkeitsenergie in unserer Rakete mit der Lebensenergie von Menschen zu kombinieren, die in Schlüsselsteinen steckt.',
    'We will start off by artificially replicating the massive energy that is triggered at the time of Mega Evolution! We will fire the energy produced from our rocket into space... And create a "warp hole".': 'Zuerst werden wir die gewaltige Energie, die bei der Mega-Entwicklung freigesetzt wird, künstlich nachbilden! Wir werden die von unserer Rakete erzeugte Energie ins All abfeuern... und ein „Warp-Loch“ erschaffen.',
    'By creating a warp hole in the path of the incoming meteoroid, we hope to be able to transport it somewhere far away from here....': 'Indem wir ein Warp-Loch in die Flugbahn des herannahenden Meteoroiden setzen, hoffen wir, ihn an einen Ort weit weg von hier befördern zu können....',
    '<i>Zinnia bursts into the room and interrupts Dr. Cozmo!<i>': '<i>Amalia platzt in den Raum und unterbricht Dr. Cozmo!<i>',
    'So this is what has come of human technology and of hope and blood and sweat and tears and... Well, the list gets kinda long and boring.': 'Das ist also aus der Technologie der Menschen geworden, aus Hoffnung und Blut und Schweiß und Tränen und... Na ja, die Liste wird ziemlich lang und langweilig.',
    'But it contains everything, huh? I know all about it. About just what kinda energy you\'re using to fuel this rocket thing... The abominable technology humanity first thought up 3,000 years ago!': 'Aber es steckt alles drin, was? Ich weiß Bescheid. Darüber, mit welcher Art von Energie ihr dieses Raketending antreiben wollt ... Die abscheuliche Technologie, die sich die Menschheit vor 3.000 Jahren zum ersten Mal ausgedacht hat!',
    'So you\'re once again planning to claim that this is best for humanity, or best for the whole darn world? It\'s a snap of your fingers to repeat the sins of the past.': 'Ihr wollt also mal wieder behaupten, dass das das Beste für die Menschheit ist, oder gleich für die ganze verflixte Welt? Die Sünden der Vergangenheit sind schneller wiederholt als ein Fingerschnippen.',
    'Worse, if what I overheard is true then this time, you\'re about to commit an error more abominable than before!': 'Schlimmer noch: Wenn stimmt, was ich gehört habe, dann seid ihr diesmal dabei, einen noch abscheulicheren Fehler zu begehen als damals!',
    'Instead of trying to make something outta nothing, you\'d rather repeat the mistakes of the past, straight up? No, you\'re gonna add new mistakes on top—that really takes the cake. You guys need some imagination.': 'Statt zu versuchen, etwas aus dem Nichts zu erschaffen, wiederholt ihr lieber ganz unverblümt die Fehler der Vergangenheit? Nein, ihr packt sogar noch neue Fehler obendrauf – das ist echt die Krönung. Ihr braucht dringend etwas Fantasie.',
    '<i>Zinnia storms out of the building.</i>': '<i>Amalia stürmt aus dem Gebäude.</i>',
    'That was.... quite the interruption.': 'Das war ... eine ziemliche Unterbrechung.',
    'But there\'s no need to worry. Based on our theory, we can at least guarantee that we will be sending the meteor away from our planet if the plan is successful. Not sure where it will go.': 'Aber kein Grund zur Sorge. Unserer Theorie nach können wir zumindest garantieren, dass wir den Meteor von unserem Planeten wegschicken, wenn der Plan gelingt. Wohin er dann fliegt, wissen wir allerdings nicht.',
    'However, we\'ve realized that we will need more energy than originally anticipated to control the process properly... I\'m sorry to ask this of you, but we will need one more Meteorite Shard. There should be one at Meteor Falls.': 'Wir haben jedoch festgestellt, dass wir mehr Energie als ursprünglich erwartet brauchen, um den Vorgang richtig zu steuern ... Es tut mir leid, dich darum zu bitten, aber wir brauchen noch einen Meteoritensplitter. Bei den Meteor Falls sollte einer zu finden sein.',
    'Thank you, dear. Now then... That is an impressive machine. Snap your fingers, the asteroid vanishes, and we all live happily ever after? It\'s a good thing you saved it from those Aqua and Magma thugs.': 'Danke, Schätzchen. Also dann ... Das ist eine beeindruckende Maschine. Einmal mit den Fingern schnippen, der Asteroid verschwindet und wir leben alle glücklich bis ans Ende unserer Tage? Gut, dass du sie vor diesen Rüpeln von Team Aqua und Team Magma gerettet hast.',
    'This thing is the best hope we have of saving this planet and everything on it. But you know... It could also be the worst tragedy imaginable for some other world and everything on it.': 'Dieses Ding ist unsere größte Hoffnung, diesen Planeten und alles darauf zu retten. Aber weißt du ... Es könnte auch die schlimmste vorstellbare Tragödie für eine andere Welt und alles darauf sein.',
    'My people have passed down a story of another world, much like our own. In this other world, the world took a different path. The war in Kalos 3000 years ago never happened, and Mega Evolution is not known there.': 'Mein Volk hat eine Geschichte über eine andere Welt überliefert, ganz ähnlich wie unsere. In dieser anderen Welt hat die Welt einen anderen Weg eingeschlagen. Den Krieg in Kalos vor 3000 Jahren gab es dort nie, und die Mega-Entwicklung ist dort unbekannt.',
    'If a meteor appeared in that world because of the use of this warp hole technology, they would be unable to save themselves! We can\'t do that to the other world! We have to solve this problem a different way!': 'Wenn durch den Einsatz dieser Warp-Loch-Technologie ein Meteor in jener Welt auftauchen würde, könnten sie sich nicht retten! Das können wir der anderen Welt nicht antun! Wir müssen dieses Problem auf andere Weise lösen!',
    '<i>Zinnia smashes the complex machines Dr. Cozmo has been working on and flees.</i>': '<i>Amalia zertrümmert die komplexen Maschinen, an denen Dr. Kosmo gearbeitet hat, und flieht.</i>',
    'You did it! You saved Hoenn and maybe the whole planet by destroying the meteor!': 'Du hast es geschafft! Du hast Hoenn und vielleicht den ganzen Planeten gerettet, indem du den Meteor zerstört hast!',
    'We have been working on repairing all the damage your... friend did when she was here last. The rocket system here at the Space Center should be able to take you up to the debris field the meteor left behind any time you want!': 'Wir haben daran gearbeitet, all die Schäden zu reparieren, die deine ... Freundin bei ihrem letzten Besuch angerichtet hat. Das Raketensystem hier im Space Center sollte dich jederzeit zu dem Trümmerfeld bringen können, das der Meteor hinterlassen hat!',
    'Yo! Find any cool stuff in chests lately?': 'Yo! Hast du in letzter Zeit coole Sachen in Truhen gefunden?',
    'I\'ve heard that if you beat a Dungeon a lot then the stuff you find in chests gets even more awesome.': 'Ich habe gehört, dass die Sachen in den Truhen noch genialer werden, wenn man einen Dungeon richtig oft abschließt.',
    '<i>Groudon and Kyogre have been awakened by the efforts of Team Magma and Team Aqua! They are engaged in a fierce battle which threatens to destroy Sootopolis City... and more!</i>': '<i>[[pokemon::Groudon]] und [[pokemon::Kyogre]] wurden durch die Machenschaften von Team Magma und Team Aqua erweckt! Sie liefern sich einen erbitterten Kampf, der Sootopolis City zu zerstören droht ... und noch mehr!</i>',
    '<i>The locals in Sootopolis City take shelter from the raging battle. Some say that this sort of thing would never happen if Wallace was still around.</i>': '<i>Die Einwohner von Sootopolis City suchen Schutz vor dem tobenden Kampf. Manche sagen, so etwas wäre nie passiert, wenn Wassili noch hier wäre.</i>',
    '<i>Rayquaza appears above Kyogre and Groudon and utters a single intimidating roar. The battling Super-Ancient Pokémon stop their attacks, and a tense standoff ensues.</i>': '<i>[[pokemon::Rayquaza]] erscheint über [[pokemon::Kyogre]] und [[pokemon::Groudon]] und stößt ein einziges, furchteinflößendes Brüllen aus. Die kämpfenden Urzeit-Pokémon stellen ihre Angriffe ein, und es folgt ein angespanntes Kräftemessen.</i>',
    '<i>After what seems like an eternity, the three Super-Ancient Pokémon seem to have come to an understanding. They each depart the city, and peace is restored.</i>': '<i>Nach einer gefühlten Ewigkeit scheinen sich die drei Urzeit-Pokémon geeinigt zu haben. Jedes von ihnen verlässt die Stadt, und der Frieden ist wiederhergestellt.</i>',
    'Hello again, $playername$. I can see by the look on your face that this is not just a social call.': 'Hallo noch einmal, $playername$. Deinem Gesichtsausdruck nach ist das kein reiner Höflichkeitsbesuch.',
    '....Yes I do know about Zinnia, she is a Draconid and this generation\'s Lorekeeper. She may be acting in ways you disagree with, but everything she\'s doing is for a reason.': '... Ja, ich weiß von Amalia. Sie ist eine Drakonierin und die Hüterin der Überlieferung ihrer Generation. Vielleicht handelt sie auf eine Weise, die du nicht gutheißt, aber alles, was sie tut, hat einen Grund.',
    'I do know where she is, but I can\'t just tell you. If you can defeat me, you may be worthy of knowing.': 'Ich weiß, wo sie ist, aber ich kann es dir nicht einfach so sagen. Wenn du mich besiegst, bist du es vielleicht wert, es zu erfahren.',
    'Hey newcomer! I see you are the Hoenn Champion. You must be an amazing Trainer!': 'Hey, Neuling! Wie ich sehe, bist du der Champ von Hoenn. Du musst ein großartiger Trainer sein!',
    'At the Battle Frontier, you can test your skills against Trainers from all over the world.': 'In der Battle Frontier kannst du dich mit Trainern aus der ganzen Welt messen.',
    'Since some of these Trainers come from far away, you may see Pokémon that you might not be able to catch yet.': 'Da einige dieser Trainer von weit her kommen, siehst du vielleicht Pokémon, die du noch nicht fangen kannst.',
    'But don\'t worry, catching them all is only a matter of time. Just keep exploring and having fun and you\'ll encounter lots of different Pokémon, either in form, color, or even evolutions!': 'Aber keine Sorge, sie alle zu fangen ist nur eine Frage der Zeit. Erkunde einfach weiter und hab Spaß, dann wirst du jede Menge verschiedener Pokémon treffen, ob nun in anderen Formen, Farben oder sogar Entwicklungen!',
    'You have certainly noticed but one of the Pokémon you\'ve fought at the Giant Chasm is invading this town.': 'Du hast es sicher bemerkt, aber eines der Pokémon, gegen die du im Giant Chasm gekämpft hast, fällt gerade in diese Stadt ein.',
    'The charts on the gemstone analysis were off the charts while you were fighting. We are this close to solving the mystery.': 'Die Werte der Edelsteinanalyse sind während deines Kampfes völlig durch die Decke gegangen. Wir sind so kurz davor, das Rätsel zu lösen.',
    '<i>A shockwave is overcoming the building. You hear an explosion and the lights in the lab go out.</i>': '<i>Eine Schockwelle erfasst das Gebäude. Du hörst eine Explosion, und im Labor gehen die Lichter aus.</i>',
    'That Pokémon must have destroyed the generator... quick grab everything you can find and help us repair it.': 'Dieses Pokémon muss den Generator zerstört haben ... Schnell, schnapp dir alles, was du finden kannst, und hilf uns, ihn zu reparieren.',
    '<i>The Deoxys sync their lights, they seem to be happy to have found each other. </i>': '<i>Die [[pokemon::Deoxys]] lassen ihre Lichter im Gleichtakt leuchten. Sie scheinen froh zu sein, einander gefunden zu haben. </i>',
    '<i>Right as you wanted to leave them alone the Deoxys with the green gem send a light towards your way. It wants to thank you for your help.</i>': '<i>Gerade als du sie allein lassen willst, schickt dir das [[pokemon::Deoxys]] mit dem grünen Edelstein ein Licht entgegen. Es möchte sich für deine Hilfe bedanken.</i>',
    'You\'re a rather impressive trainer $playername$, but there\'s no way you can beat me. Come back when you\'re stronger.': 'Du bist ein ziemlich beeindruckender Trainer, $playername$, aber du kannst mich unmöglich besiegen. Komm wieder, wenn du stärker bist.',
    'Heh... You know, this experience really brought it home for me again that there is still so much about this world that I do not know. Thank you, $playername$ for all your help.': 'Heh ... Weißt du, diese Erfahrung hat mir wieder einmal gezeigt, dass es so vieles auf dieser Welt gibt, das ich nicht weiß. Danke für all deine Hilfe, $playername$.',
    'Thank you for reserving your Eon Ticket!': 'Danke, dass du dein Äon-Ticket reserviert hast!',
    'To claim the ticket, all you have to do is go to your Start Menu, select "Save / Enter Code", and enter the following code in the "Enter Code..." box:': 'Um das Ticket einzulösen, musst du nur dein Start Menu öffnen, „Save / Enter Code“ auswählen und den folgenden Code in das Feld „Enter Code...“ eingeben:',
    'What\'s up? I got here using my Eon Ticket, what about you?': 'Was geht? Ich bin mit meinem Äon-Ticket hergekommen, und du?',
    '<i>The Southern Island is a small but lush forest. The clearing near the center of the island is the perfect place for a tired Pokémon to rest.</i>': '<i>Southern Island ist ein kleiner, aber üppiger Wald. Die Lichtung in der Mitte der Insel ist der perfekte Ort für ein müdes Pokémon, um sich auszuruhen.</i>',
    '<i>Latios and Latias are resting in the clearing. You can approach one of them, but the other will probably flee.</i>': '<i>[[pokemon::Latios]] und [[pokemon::Latias]] ruhen sich auf der Lichtung aus. Du kannst dich einem von ihnen nähern, aber das andere wird wahrscheinlich fliehen.</i>',
    '<i>You look around the Outskirt Stand, and see two shady figures shuffling off into the horizon. As you move to get a closer look, some guy steps in your way.</i>': '<i>Du siehst dich am Outskirt Stand um und erblickst zwei zwielichtige Gestalten, die in Richtung Horizont davonschlurfen. Als du näher herangehen willst, stellt sich dir ein Typ in den Weg.</i>',
    'Hey there! You\'re a fresh face \'round these parts, aren\'tcha!': 'Hey du! Du bist neu in der Gegend, was?',
    'You\'ll have to let me welcome you with a battle, or my name ain\'t Willie!': 'Ich muss dich mit einem Kampf willkommen heißen, so wahr ich Willie heiße!',
    'Well partner, that was some dang fancy fighting, I\'ll tell you what.': 'Na, Partner, das war verdammt schickes Kämpfen, das sag ich dir.',
    'I dunno what your plans are round these parts, but you\'d best keep an eye out for some of them dang ole Shadow Pokémon. Give a stranger enough of a whooping an\' ya might see yourself face to face with one in a dungeon next time!': 'Weiß nich\', was du hier in der Gegend vorhast, aber halt besser die Augen offen nach diesen verflixten Crypto-Pokémon. Wenn du \'nem Fremden ordentlich den Hintern versohlst, stehst du beim nächsten Mal vielleicht in \'nem Dungeon einem davon gegenüber!',
    'I hear they are weaker than normal Pokémon but can hold a fancy incense. If you manage to purify their souls, they\'ll get a wee bit stronger!': 'Hab gehört, die sind schwächer als normale Pokémon, können aber \'nen schicken Rauch tragen. Wenn du\'s schaffst, ihre Seelen zu reinigen, werden sie \'n kleines bisschen stärker!',
    'There\'s been a lot of crime around here recently. But nothing I can\'t handle!': 'Hier gab\'s in letzter Zeit viele Verbrechen. Aber nichts, womit ich nicht fertig werde!',
    'Some folks have been corrupting their Pokémon and making them commit totally jank acts.': 'Ein paar Leute haben ihre Pokémon verdorben und sie total miese Sachen anstellen lassen.',
    'Those Pokémon would be better off in the hands of a radical trainer who knows how to use Catch Filters, like me!': 'Diese Pokémon wären bei einem krassen Trainer besser aufgehoben, der weiß, wie man Fangfilter benutzt – so wie ich!',
    '<i>You open the sack and a girl pops out!</i>': '<i>Du öffnest den Sack und ein Mädchen springt heraus!</i>',
    'Thanks for letting me out! I thought I was done for!': 'Danke, dass du mich rausgelassen hast! Ich dachte schon, es wäre aus mit mir!',
    'My name is Rui, by the way. I\'m a psychic of sorts, on a mission to save Pokémon who have had their souls corrupted by some evil folks in Orre.': 'Ich heiße übrigens Rui. Ich bin so eine Art Medium und habe es mir zur Aufgabe gemacht, Pokémon zu retten, deren Seelen von ein paar bösen Leuten in Orre verdorben wurden.',
    'There\'s a few in this city that need help. Can you come with me though? I\'m worried more shady guys will show up.': 'In dieser Stadt gibt es ein paar, die Hilfe brauchen. Kannst du mich aber begleiten? Ich habe Angst, dass noch mehr zwielichtige Typen auftauchen.',
    'I can point out which Pokémon have been corrupted, or turned into "Shadow Pokémon", and you can confiscate them from evildoers using your Pokéballs.': 'Ich kann dir zeigen, welche Pokémon verdorben bzw. in „Crypto-Pokémon“ verwandelt wurden, und du kannst sie den Übeltätern mit deinen Pokébällen abnehmen.',
    'You can adjust your Catch Filters to catch any Shadow Pokémon now too.': 'Du kannst deine Fangfilter jetzt auch so einstellen, dass du alle Crypto-Pokémon fängst.',
    'Ah, you must be travelers! Welcome to Phenac City! I am Es Cade, the Mayor. Now, you wanted to see me? Is there something that I may be able to assist you with?': 'Ah, ihr müsst Reisende sein! Willkommen in Phenac City! Ich bin Es Cade, der Bürgermeister. Ihr wolltet mich sprechen? Gibt es etwas, wobei ich euch behilflich sein kann?',
    'O-o-o-oh, my! Shadow Pokémon? And they attack people?! Now if that were true, that would be truly frightening. However, that is a little hard to believe.': 'O-o-o-oh, meine Güte! Crypto-Pokémon? Und sie greifen Menschen an?! Wenn das wahr wäre, wäre das wirklich beängstigend. Allerdings ist das ein wenig schwer zu glauben.',
    'I understand your concern, though. I will order an investigation at once.': 'Ich verstehe aber eure Sorge. Ich werde sofort eine Untersuchung anordnen.',
    'I promise you, we will obtain useful information about those sinister Pokémon. While we do so, I heartily recommend that you visit our Stadium, the symbol of our civic pride!': 'Ich verspreche euch, wir werden nützliche Informationen über diese finsteren Pokémon beschaffen. Währenddessen empfehle ich euch wärmstens, unser Stadion zu besuchen, das Symbol unseres Bürgerstolzes!',
    'There\'s something suspicious going on here, but I\'m not sure what our next move is here.': 'Hier geht irgendwas Verdächtiges vor, aber ich weiß nicht so recht, was unser nächster Schritt sein soll.',
    'The Stadium here isn\'t even open yet, I think the Mayor was just trying to get rid of us.': 'Das Stadion hier hat noch nicht einmal geöffnet. Ich glaube, der Bürgermeister wollte uns nur loswerden.',
    'Let\'s see if we can find out more in Pyrite Town.': 'Mal sehen, ob wir in Pyrite Town mehr herausfinden.',
    'Thank you, $playername$, for saving our town from Team Cipher once again.': 'Danke, $playername$, dass du unsere Stadt wieder einmal vor Team Cipher gerettet hast.',
    'I haven\'t seen Professor Krane around here, but hopefully this will be of some use to you.': 'Professor Krane habe ich hier nicht gesehen, aber hoffentlich ist dir das hier von Nutzen.',
    'I sense the presence of rare Pokémon at the {ROUTE_NAME}! Hurry, before the fates intervene!': 'Ich spüre die Anwesenheit seltener Pokémon auf {ROUTE_NAME}! Beeil dich, bevor das Schicksal eingreift!',
    '<i>Grr...</i>.': '<i>Grr ...</i>.',
    'Those masked trainers went and kidnapped my beloved Plusle! How dare they!': 'Diese maskierten Trainer haben mein geliebtes [[pokemon::Plusle]] entführt! Wie können sie es wagen!',
    'They told me that I had to let them have free reign in town, or there would be trouble. They\'re out at the Colosseum causing trouble.': 'Sie haben gesagt, ich soll ihnen in der Stadt freie Hand lassen, sonst gibt es Ärger. Sie sind draußen im Colosseum und machen Ärger.',
    'This town is pretty quiet. Most folks here are retired trainers.': 'Diese Stadt ist ziemlich ruhig. Die meisten Leute hier sind Trainer im Ruhestand.',
    'We\'re always happy to help out any young folks who come through though!': 'Aber wir helfen immer gern jungen Leuten, die hier vorbeikommen!',
    'Our only real tourist attraction is the Relic Stone north of town. Just passing by it is enough to make you feel calmer.': 'Unsere einzige richtige Touristenattraktion ist der Relic Stone nördlich der Stadt. Schon wenn man daran vorbeigeht, fühlt man sich ruhiger.',
    'This stone has the power to cleanse and purify the spirits of Pokémon.': 'Dieser Stein hat die Macht, die Seelen von Pokémon zu läutern und zu reinigen.',
    'If you train with your Pokémon, you will gain spiritual energy, or "Flow". You can use this Flow to purify your Pokémon.': 'Wenn du mit deinen Pokémon trainierst, gewinnst du spirituelle Energie, den sogenannten „Flow“. Mit diesem Flow kannst du deine Pokémon reinigen.',
    'Purification will take more flow with each Pokémon you purify.': 'Mit jedem Pokémon, das du reinigst, benötigt die Reinigung mehr Flow.',
    'It\'s said that there is a Flute with a time-altering effect. Playing it might help purify your Pokémon a bit faster.': 'Es heißt, es gebe eine Flöte, die die Zeit beeinflussen kann. Wenn du sie spielst, kannst du deine Pokémon vielleicht etwas schneller reinigen.',
    'Ah, $playername$! It\'s good to see you again, though I wish it was under better circumstances.': 'Ah, $playername$! Schön, dich wiederzusehen, auch wenn ich mir bessere Umstände gewünscht hätte.',
    'Yes, I heard that Professor Krane was kidnapped from the Pokémon HQ Lab. There\'s some shady characters up on Mount Battle who might know more.': 'Ja, ich habe gehört, dass Professor Krane aus dem Pokémon HQ Lab entführt wurde. Oben auf dem Mount Battle treiben sich ein paar zwielichtige Gestalten herum, die vielleicht mehr wissen.',
    'My, my. That certainly was a battle worth seeing. I must be honest with you. I never imagined that you would get this far.': 'Meine Güte. Das war wahrlich ein sehenswerter Kampf. Ich muss ehrlich zu dir sein. Ich hätte nie gedacht, dass du so weit kommst.',
    'Oh, dear me. Do you fail to understand still? You\'re such an innocent child. At times, I am the affable mayor of Phenac... And at others, I am the secret boss of the criminal syndicate Cipher!': 'Oh, du meine Güte. Verstehst du es immer noch nicht? Du bist so ein unschuldiges Kind. Manchmal bin ich der umgängliche Bürgermeister von Phenac ... Und manchmal bin ich der geheime Boss des Verbrechersyndikats Cipher!',
    'I am Evice, and I shall rule the world!': 'Ich bin Evice, und ich werde die Welt beherrschen!',
    '<i>The Mayor changes before your eyes, taking on a much more sinister appearance.</i>': '<i>Der Bürgermeister verwandelt sich vor deinen Augen und nimmt ein weitaus finstereres Aussehen an.</i>',
    'I\'ve been waiting for the S. S. Libra to come into port for HOURS!': 'Ich warte schon seit STUNDEN darauf, dass die S. S. Libra in den Hafen einläuft!',
    'Rumor has it that some giant Pokémon picked it up and flew away with it, but that has to be impossible.': 'Gerüchten zufolge hat ein riesiges Pokémon sie hochgehoben und ist mit ihr davongeflogen, aber das ist doch unmöglich.',
    'If such a Pokémon existed, Professor Krane at the Pokémon HQ Lab would know about it.': 'Wenn es so ein Pokémon gäbe, wüsste Professor Krane im Pokémon HQ Lab davon.',
    'Hohoho! You must be the $playername$ I\'m hearing so much about you from my.... employees.': 'Hohoho! Du musst $playername$ sein, von dem ich so viel von meinen ... Angestellten höre.',
    'There\'s a lot of rumors buzzing around about the S. S. Libra, but if you ask me, it\'s long gone and may never be found.': 'Über die S. S. Libra kursieren viele Gerüchte, aber wenn du mich fragst, ist sie längst verschwunden und wird vielleicht nie gefunden.',
    'You\'d have to be as crazy as Kaminko to go looking for it.': 'Man müsste schon so verrückt sein wie Kaminko, um nach ihr zu suchen.',
    '$playername$! Thank you for rescuing me from those fiends!': '$playername$! Danke, dass du mich vor diesen Unholden gerettet hast!',
    'In my time in captivity, I learned that the new Grand Master of Team Cipher has used a powerful Shadow Pokémon to kidnap all the trainers and Pokémon from the S. S. Libra and has taken them to Citadark Island!': 'Während meiner Gefangenschaft habe ich erfahren, dass der neue Großmeister von Team Cipher ein mächtiges Crypto-Pokémon benutzt hat, um alle Trainer und Pokémon von der S. S. Libra zu entführen und nach Citadark Island zu bringen!',
    'Snagging this powerful Shadow Pokémon will be hard, take this Master Ball!': 'Dieses mächtige Crypto-Pokémon zu schnappen wird schwer, nimm diesen Meisterball!',
    'Leave me alone! I\'m WORKING!': 'Lass mich in Ruhe! Ich ARBEITE!',
    'Chobin has heard all about the Shadow Pokémon from Dr. Kaminko!': 'Chobin hat von Dr. Kaminko alles über die Crypto-Pokémon gehört!',
    'There is a stone near Agate Village that can purify the souls of Pokémon, yes indeed.': 'In der Nähe von Agate Village gibt es einen Stein, der die Seelen von Pokémon reinigen kann, jawohl.',
    'Dr. Kaminko and Chobin have invented this most wonderful device! The Robo Groudon!': 'Dr. Kaminko und Chobin haben diese überaus wunderbare Vorrichtung erfunden! Den Robo-[[pokemon::Groudon]]!',
    'With this robot, we can explore the deserts of Orre! Surely Chobin and $playername$ will find something interesting!': 'Mit diesem Roboter können wir die Wüsten von Orre erkunden! Chobin und $playername$ werden bestimmt etwas Interessantes finden!',
    '<i>You rummage around in the wreckage of the S. S. Libra, and find evidence of a recent battle. It looks like something very strong beat up a lot of weaker Pokémon.</i>': '<i>Du durchstöberst das Wrack der S. S. Libra und findest Spuren eines kürzlichen Kampfes. Es sieht so aus, als hätte etwas sehr Starkes viele schwächere Pokémon verprügelt.</i>',
    '<i>Deep in the wreckage, you find a box that was left behind on accident.</i>': '<i>Tief im Wrack findest du eine Kiste, die versehentlich zurückgelassen wurde.</i>',
    'Only the toughest trainers in Orre are allowed to fight here! I\'m just watching until I get stronger.': 'Nur die stärksten Trainer von Orre dürfen hier kämpfen! Ich schaue nur zu, bis ich stärker werde.',
    'The rock is covered in moss. It feels pleasantly cool.': 'Der Felsen ist mit Moos bedeckt. Er fühlt sich angenehm kühl an.',
    'My eggs! They ran away!': 'Meine Eier! Sie sind weggelaufen!',
    'Can you help me get them back? They have most likely fled to a dungeon in Kanto, Hoenn or Johto.': 'Kannst du mir helfen, sie zurückzuholen? Sie sind wahrscheinlich in einen Dungeon in Kanto, Hoenn oder Johto geflohen.',
    'But be careful! If you defeat them, they will run away again!': 'Aber sei vorsichtig! Wenn du sie besiegst, laufen sie wieder weg!',
    'This is a prime camping spot! Gem and mineral hunters come from all over the world to explore here!': 'Das ist ein erstklassiger Zeltplatz! Edelstein- und Mineraliensammler kommen aus der ganzen Welt hierher, um die Gegend zu erkunden!',
    'Wow! I can\'t believe <b>THE</b> Kanto Gym Leader Brock came all this way! What an honor to meet him!': 'Wow! Ich kann nicht glauben, dass <b>DER</b> Arenaleiter Rocko aus Kanto den ganzen Weg hierher gekommen ist! Was für eine Ehre, ihn zu treffen!',
    'Hm, hm, hm. Well, seems like it\'s true. It really is just like the wall painting there. This one shows Primal Reversion... While that one shows Mega Evolution... I guess that proves it once and for all.': 'Hm, hm, hm. Scheint also wahr zu sein. Es ist wirklich genau wie auf dem Wandgemälde da. Dieses hier zeigt die Proto-Rückentwicklung ... Und jenes da die Mega-Entwicklung ... Damit ist es wohl ein für alle Mal bewiesen.',
    'Our great ancestors once lived here, too. The ancestors who passed down through me the knowledge of how to protect the world... How to avert the threat that will appear from space, as long was foretold... From a place higher even than the heavens...': 'Unsere großen Vorfahren haben auch einst hier gelebt. Die Vorfahren, die mir das Wissen überliefert haben, wie man die Welt beschützt ... Wie man die Bedrohung abwendet, die aus dem All kommen wird, wie es seit Langem prophezeit wurde ... Von einem Ort, der noch höher liegt als der Himmel ...',
    'What is it, Aster? Oh?': 'Was ist denn, Aster? Oh?',
    'We do seem to meet an awful lot, $playername$. Are you also interested in this old painting? Or are you here for something else? For one of the Meteorite Shards that can serve as a source of power for the Legendary Pokémon that lives in the heavens above.': 'Wir begegnen uns ja ganz schön oft, $playername$. Interessierst du dich auch für dieses alte Gemälde? Oder bist du aus einem anderen Grund hier? Wegen eines der Meteoritensplitter, die als Kraftquelle für das Legendäre Pokémon dienen können, das hoch oben im Himmel lebt.',
    'Either way... You know I adore you. That\'s it! I can\'t help it! I have to battle you! I\'ll play nice, though, and ask first... You\'re ready to battle me, right?': 'Wie auch immer ... Du weißt ja, dass ich dich total gernhabe. Das war\'s! Ich kann nicht anders! Ich muss gegen dich kämpfen! Aber ich bin nett und frage vorher ... Du bist doch bereit, gegen mich zu kämpfen, oder?',
    'That glittering Meteorite that you\'ve got there... Hmm... It\'s sure giving off some vibes. I\'d keep a tight hold on it if I were you, along with that shard I just gave you.': 'Dieser glitzernde Meteorit, den du da hast ... Hmm ... Der hat echt eine besondere Ausstrahlung. Ich an deiner Stelle würde ihn gut festhalten, genau wie den Splitter, den ich dir gerade gegeben habe.',
    'Hey... The actions that you\'re taking now... Are they based on the ideals you cling to? Or are they based on actual truths? And if they are... How much of the truth do you think you know?': 'Hey ... Die Dinge, die du gerade tust ... Beruhen sie auf den Idealen, an die du dich klammerst? Oder auf tatsächlichen Wahrheiten? Und wenn ja ... Wie viel von der Wahrheit glaubst du zu kennen?',
    '<i>A large mural depicting  some sort of fire-spewing lizard Pokémon. It seems to be engaged in a battle.</i>': '<i>Ein großes Wandgemälde, das eine Art feuerspeiendes Echsen-Pokémon zeigt. Es scheint in einen Kampf verwickelt zu sein.</i>',
    '<i>A large mural depicting  some sort of oceanic whale-like Pokémon. It seems to be engaged in a battle.</i>': '<i>Ein großes Wandgemälde, das eine Art walähnliches Meeres-Pokémon zeigt. Es scheint in einen Kampf verwickelt zu sein.</i>',
    '<i>You see someone else looking at the mural: Steven Stone!</i>': '<i>Du siehst, dass noch jemand das Wandgemälde betrachtet: Troy Trumm!</i>',
    'Hello again, $playername$! I see you\'re interested in these murals as well? They seem to be about Groudon and Kyogre.': 'Hallo noch einmal, $playername$! Interessierst du dich auch für diese Wandgemälde? Sie scheinen [[pokemon::Groudon]] und [[pokemon::Kyogre]] darzustellen.',
    'So in the ancient world, their primal forms once held this much power…? The super-ancient Pokémon… What terrible strength… But this appearance here… It seems somehow different from Mega Evolution, but somehow related.': 'In der Urzeit besaßen ihre Protoformen also einst so viel Macht ...? Die Urzeit-Pokémon ... Was für eine schreckliche Stärke ... Aber diese Erscheinung hier ... Sie scheint sich irgendwie von der Mega-Entwicklung zu unterscheiden und doch mit ihr verwandt zu sein.',
    'If you don\'t mind me asking… Do you feel anything in particular when you look up at this wall? A primal world, lost thousands of years in the past… A Legendary Pokémon of tremendous power became humanity\'s greatest threat…': 'Wenn ich fragen darf ... Fühlst du irgendetwas Bestimmtes, wenn du zu dieser Wand hinaufsiehst? Eine Urwelt, Tausende Jahre in der Vergangenheit verloren ... Ein Legendäres Pokémon von gewaltiger Macht wurde zur größten Bedrohung der Menschheit ...',
    'The terror aroused by that power is clear to see in this ancient artwork. You know who might know more about this? Captain Stern, a sailor who works for my father.': 'Der Schrecken, den diese Macht ausgelöst hat, ist in diesen uralten Kunstwerken deutlich zu sehen. Weißt du, wer vielleicht mehr darüber weiß? Kapitän Brigg, ein Seemann, der für meinen Vater arbeitet.',
    'He\'s usually out to sea, but you can find him in Sea Mauville if the weather is too stormy to sail.': 'Normalerweise ist er auf See, aber wenn das Wetter zu stürmisch zum Segeln ist, findest du ihn in Sea Mauville.',
    'Yes, I am one of the Draconid people. One of those ancient folk tasked with passing down the knowledge of Mega Evolution—with the great lore of Lord Rayquaza, who was the beginning of all.': 'Ja, ich gehöre zum Volk der Drakonier. Zu jenem alten Volk, dessen Aufgabe es ist, das Wissen über die Mega-Entwicklung weiterzugeben – zusammen mit der großen Überlieferung des erhabenen [[pokemon::Rayquaza]], das der Anfang von allem war.',
    'Since times long gone, Hoenn has repeatedly suffered great disasters. At times, the destruction took the form of a huge meteoroid, which fell upon our land from distant space.': 'Seit uralten Zeiten wurde Hoenn immer wieder von großen Katastrophen heimgesucht. Manchmal nahm die Zerstörung die Gestalt eines riesigen Meteoroiden an, der aus den Tiefen des Alls auf unser Land stürzte.',
    'At other times, the Primal Reversion of our own super-ancient Pokémon brought us to the brink of destruction. Each time, Lord Rayquaza has saved us from doom.': 'Ein anderes Mal brachte uns die Proto-Rückentwicklung unserer eigenen Urzeit-Pokémon an den Rand der Vernichtung. Jedes Mal hat uns der erhabene [[pokemon::Rayquaza]] vor dem Untergang bewahrt.',
    'The chosen Lorekeeper, standing before a stone that shone with rainbow light, offered up a wish to the great one. And Lord Rayquaza\'s body was suffused with a brilliant light and transformed.': 'Die auserwählte Hüterin der Überlieferung stand vor einem Stein, der in Regenbogenfarben leuchtete, und richtete einen Wunsch an den Großen. Und der Körper des erhabenen [[pokemon::Rayquaza]] wurde von einem strahlenden Licht erfüllt und verwandelte sich.',
    'In its transformed state, Rayquaza\'s power was more devastating than ever before, overcoming even the super-ancient Pokémon with all their primal power.': 'In seiner verwandelten Gestalt war die Kraft von [[pokemon::Rayquaza]] verheerender als je zuvor und überwand sogar die Urzeit-Pokémon mit all ihrer urtümlichen Macht.',
    'I want to tell you more, but first you must prove you are worthy.': 'Ich möchte dir mehr erzählen, aber zuerst musst du beweisen, dass du es wert bist.',
    'Zinnia is the current Lorekeeper of our people, who has inherited the knowledge and power to summon Lord Rayquaza when disaster imperils the world.': 'Amalia ist die derzeitige Hüterin der Überlieferung unseres Volkes. Sie hat das Wissen und die Kraft geerbt, den erhabenen [[pokemon::Rayquaza]] herbeizurufen, wenn der Welt eine Katastrophe droht.',
    'She has long known about the meteor approaching the planet, and has been trying to draw out the power of Rayquaza. Part of this plan was working with Teams Aqua and Magma to revive the Super-Ancient Pokémon.': 'Sie weiß schon lange von dem Meteor, der sich dem Planeten nähert, und versucht, die Kraft von [[pokemon::Rayquaza]] hervorzulocken. Teil dieses Plans war es, mit Team Aqua und Team Magma zusammenzuarbeiten, um die Urzeit-Pokémon wiederzuerwecken.',
    'She taught them the secrets needed to bring back these threats and summon the great Dragon itself. And now it seems she travels the land, scouring the world for Key Stones.': 'Sie lehrte sie die Geheimnisse, die nötig waren, um diese Bedrohungen zurückzubringen und den großen Drachen selbst herbeizurufen. Und nun scheint sie durchs Land zu reisen und die Welt nach Schlüsselsteinen abzusuchen.',
    'I do not know what you plan to do, but Zinnia will continue to follow her convictions to the very end. This may cost her her life, but she is dedicated. Please, help her if you can.': 'Ich weiß nicht, was du vorhast, aber Amalia wird ihren Überzeugungen bis zum bitteren Ende folgen. Es könnte sie das Leben kosten, aber sie ist fest entschlossen. Bitte hilf ihr, wenn du kannst.',
    'Take this Meteorite Shard, and please hurry! After you have helped Zinnia, please come back here and find me.': 'Nimm diesen Meteoritensplitter und beeil dich bitte! Wenn du Amalia geholfen hast, komm bitte zurück und such mich auf.',
    'Thank you for everything you\'ve done for the Draconid people, Hoenn, and me personally.': 'Danke für alles, was du für das Volk der Drakonier, für Hoenn und für mich persönlich getan hast.',
    'You will forever be a friend of the Draconid people.': 'Du wirst für immer ein Freund des Volkes der Drakonier sein.',
    '<i>The cocoon shifts, shimmers, and hatches to reveal Jirachi!</i>': '<i>Der Kokon bewegt sich, schimmert und schlüpft – heraus kommt [[pokemon::Jirachi]]!</i>',
    'I, the Great Butler, thank you for all of your help in fulfilling my greatest wish!': 'Ich, der Große Butler, danke dir für all deine Hilfe bei der Erfüllung meines größten Wunsches!',
    'Meta Groudon has been revived! It is safely contained in this crater. Catch it whenever you are ready!': '[[pokemon::Meta Groudon]] wurde wiederbelebt! Es ist sicher in diesem Krater eingeschlossen. Fang es, wann immer du bereit bist!',
    'I, the Great Butler, thank you for saving me from the wrath of Meta Groudon.': 'Ich, der Große Butler, danke dir, dass du mich vor dem Zorn von [[pokemon::Meta Groudon]] gerettet hast.',
    'My wish was to resurrect Groudon for Team Magma, but it proved too difficult, and you have showed me that it would be irresponsible to put that much power in the hands of evil doers.': 'Mein Wunsch war es, [[pokemon::Groudon]] für Team Magma wiederauferstehen zu lassen, aber es erwies sich als zu schwierig, und du hast mir gezeigt, dass es unverantwortlich wäre, so viel Macht in die Hände von Übeltätern zu legen.',
    'I can try the experiment again using what was learned from the previous failure, but I will need your help. If we are successful, I will give you the opportunity to catch the resulting Meta Groudon to you.': 'Ich kann das Experiment mit dem, was ich aus dem vorherigen Fehlschlag gelernt habe, erneut versuchen, aber ich brauche deine Hilfe. Wenn wir Erfolg haben, gebe ich dir die Gelegenheit, das daraus entstehende [[pokemon::Meta Groudon]] zu fangen.',
    'To rebuild my machine, I will need a hundred power-generating Pokémon to run the machine, shiny pokemon to stabilize the energy matrix, and to conduct a new dig for fossilized Groudon materials. After that, I will need to calibrate the machine using DNA from Groudon itself.': 'Um meine Maschine wieder aufzubauen, brauche ich hundert energieerzeugende Pokémon, um die Maschine zu betreiben, schillernde Pokémon, um die Energiematrix zu stabilisieren, und eine neue Ausgrabung nach fossilen Überresten von [[pokemon::Groudon]]. Danach muss ich die Maschine mit DNA von [[pokemon::Groudon]] selbst kalibrieren.',
    '<i>Pressure readings are indicating that a huge storm is brewing in Hoenn. All instruments point to Mt. Pyre as the center of the disturbance.</i>': '<i>Die Luftdruckwerte deuten darauf hin, dass sich in Hoenn ein gewaltiger Sturm zusammenbraut. Alle Instrumente zeigen auf Mt. Pyre als Zentrum der Störung.</i>',
    'Bwahahahaha! At last… AT LAST! I\'ve finally done it!!! It hasn\'t even finished reversion, and it still has this much power!!! With this I can return everything to its natural beginning! It\'s time at last!': 'Bwahahahaha! Endlich ... ENDLICH! Ich habe es endlich geschafft!!! Die Rückentwicklung ist noch nicht einmal abgeschlossen, und es hat schon so viel Macht!!! Damit kann ich alles an seinen natürlichen Ursprung zurückführen! Endlich ist es so weit!',
    'Is that crew outside?': 'Ist das die Crew draußen?',
    'What is it…? Oh? So the great deluge has begun… Bwahahahaha! But of course it has! That is exactly what I have―': 'Was ist ...? Oh? Die große Sintflut hat also begonnen ... Bwahahahaha! Aber natürlich! Genau das habe ich ―',
    'What…? What do you mean far more than we thought?! It can\'t be… Then if it completes its Primal Reversion… N-never mind that! Just keep an eye on it!': 'Was ...? Was soll das heißen, weit mehr als gedacht?! Das kann nicht sein ... Wenn es dann seine Proto-Rückentwicklung abschließt ... V-vergesst das! Behaltet es einfach im Auge!',
    'All that matters is… That I have used the Blue Orb to awaken Kyogre… And now… I will return this world to its natural state… The state that is best for Pokémon!': 'Alles, was zählt, ist ... Dass ich mit der Blauen Kugel [[pokemon::Kyogre]] erweckt habe ... Und jetzt ... werde ich diese Welt in ihren natürlichen Zustand zurückversetzen ... Den Zustand, der für Pokémon am besten ist!',
    '... Hm? A message from our members outside? What is it? So the sun has turned mercilessly fierce in its heat. I should expect so. That is what I have long—': '... Hm? Eine Nachricht von unseren Mitgliedern draußen? Was gibt es? Die Sonne ist also gnadenlos heiß geworden. Das war zu erwarten. Genau das habe ich mir lange —',
    'No, what WE have long wished for. What?! The heat is greater than simulations predicted? It will be a risk to our own safety if it continues?! That cannot be...': 'Nein, das haben WIR uns lange gewünscht. Was?! Die Hitze ist größer, als die Simulationen vorhergesagt haben? Es wird ein Risiko für unsere eigene Sicherheit, wenn das so weitergeht?! Das kann nicht sein ...',
    'It has only just awoken... Where is it getting so much power from? And how much more will it gain when it does undergo Primal Reversion... C-continue your readings! Then report back!': 'Es ist doch gerade erst erwacht ... Woher bekommt es so viel Kraft? Und wie viel mehr wird es gewinnen, wenn es die Proto-Rückentwicklung durchläuft ... M-messt weiter! Und dann erstattet Bericht!',
    'All that matters is... That I have used the red orb to awaken Groudon. And now... I will transform this planet to a land ideal for humanity.': 'Alles, was zählt, ist ... Dass ich mit der Roten Kugel [[pokemon::Groudon]] erweckt habe. Und jetzt ... werde ich diesen Planeten in ein Land verwandeln, das ideal für die Menschheit ist.',
    'There\'s no way I can beat you!': 'Ich kann dich unmöglich besiegen!',
    'Zinnia.... I thought I could trust her after she found the Red Orb for me, but I guess not. She stole my Key Stone!': 'Amalia ... Ich dachte, ich könnte ihr vertrauen, nachdem sie die Rote Kugel für mich gefunden hatte, aber wohl nicht. Sie hat meinen Schlüsselstein gestohlen!',
    'Oh uh... forget I said that. Zinnia\'s already gone. I have no idea where she went, but another Draconid or even an ancient Sootopolitan might know. Maybe try talking to Wallace?': 'Oh, äh ... Vergiss, was ich gesagt habe. Amalia ist schon weg. Ich habe keine Ahnung, wohin sie gegangen ist, aber ein anderer Drakonier oder sogar ein alter Bewohner von Sootopolis könnte es wissen. Versuch\'s doch mal bei Wassili?',
    'Baah, what\'s the use in fighting you?': 'Pah, was bringt es schon, gegen dich zu kämpfen?',
    'That Dragon twerp stole my Key Stone, there\'s no way I can win without it. Looks like you\'re after her too, huh?': 'Diese Drachengöre hat meinen Schlüsselstein geklaut, ohne den kann ich unmöglich gewinnen. Sieht so aus, als wärst du auch hinter ihr her, was?',
    'Last I saw, she was headed towards Mt. Chimney. Hopefully she messes up Maxie\'s day too! At least she didn\'t take the.... uuh...': 'Als ich sie zuletzt gesehen habe, war sie auf dem Weg zum Mt. Chimney. Hoffentlich vermasselt sie Marc auch den Tag! Wenigstens hat sie nicht die ... äh ... mitgenommen.',
    'Never you mind that, get outta here!': 'Das geht dich nichts an, verschwinde!',
    'The rock is encrusted in ice. It is freezing to touch.': 'Der Felsen ist mit Eis überzogen. Er ist eiskalt, wenn man ihn berührt.',
    'Hi! I\'m collecting shells while I fish. There\'s a lot of neat stuff lying around here.': 'Hi! Ich sammle Muscheln, während ich angle. Hier liegt jede Menge cooles Zeug herum.',
    'Oh well. Back to fishin\'.': 'Na ja. Zurück zum Angeln.',
    '<i>A large, icy boulder sits in the corner of the cave. Maybe you can move it when you\'re stronger?</i>': '<i>In der Ecke der Höhle liegt ein großer, vereister Felsbrocken. Vielleicht kannst du ihn bewegen, wenn du stärker bist?</i>',
    'Ah, so you are the new trainer in the region? I\'ve heard tales of your exploits. My name is Wallace. I was once the Gym Leader of Sootopolis, but something came up. So now, I\'ve entrusted my mentor Juan with the Gym\'s operation.': 'Ah, du bist also der neue Trainer in der Region? Ich habe Geschichten über deine Taten gehört. Mein Name ist Wassili. Ich war einst Arenaleiter von Sootopolis, aber dann kam etwas dazwischen. Deshalb habe ich die Leitung der Arena meinem Mentor Juan anvertraut.',
    'Groudon and Kyogre, the two Pokémon wreaking havoc in Sootopolis City, are considered to be Super-Ancient Pokémon. But there aren\'t just two Super-Ancient Pokémon. Somewhere, there is a Super-Ancient Pokémon named Rayquaza. It\'s said that it was Rayquaza that becalmed the two combatants in the distant past.': '[[pokemon::Groudon]] und [[pokemon::Kyogre]], die beiden Pokémon, die in Sootopolis City Chaos anrichten, gelten als Urzeit-Pokémon. Aber es gibt nicht nur zwei Urzeit-Pokémon. Irgendwo existiert ein Urzeit-Pokémon namens [[pokemon::Rayquaza]]. Es heißt, [[pokemon::Rayquaza]] habe die beiden Kontrahenten in ferner Vergangenheit besänftigt.',
    'I have heard that Rayquaza once lived high atop the Sky Pillar, maybe that\'s where it is now?': 'Ich habe gehört, dass [[pokemon::Rayquaza]] einst hoch oben auf der Spitze der Sky Pillar lebte. Vielleicht ist es jetzt dort?',
    'My eyes didn\'t deceive me. Thanks to your help, Sootopolis...': 'Meine Augen haben mich nicht getäuscht. Dank deiner Hilfe wurde Sootopolis ...',
    'No, all of Hoenn was saved. On behalf of the people, I thank you.': 'Nein, ganz Hoenn gerettet. Im Namen der Menschen danke ich dir.',
    'Now that their battle is over, the Super-Ancient Pokémon have retreated to rest and recuperate. You will likely find Rayquaza back in the Sky Pillar.': 'Jetzt, da ihr Kampf vorbei ist, haben sich die Urzeit-Pokémon zurückgezogen, um sich auszuruhen und zu erholen. [[pokemon::Rayquaza]] findest du wahrscheinlich wieder in der Sky Pillar.',
    'Kyogre and Groudon are rumored to live deep within this very cave, but they are unlikely to show themselves to any normal trainer. Maybe the champion of Hoenn could earn their respect.': 'Gerüchten zufolge leben [[pokemon::Kyogre]] und [[pokemon::Groudon]] tief in genau dieser Höhle, aber einem gewöhnlichen Trainer werden sie sich wohl kaum zeigen. Vielleicht könnte der Champ von Hoenn ihren Respekt gewinnen.',
    'Wow, $playername$! You\'ve been busy!': 'Wow, $playername$! Du warst ja fleißig!',
    'Now that things are calmer in Hoenn, I\'ve decided to keep an eye on Kyogre and Groudon and make sure they don\'t cause any more trouble.': 'Jetzt, wo es in Hoenn ruhiger ist, habe ich beschlossen, [[pokemon::Kyogre]] und [[pokemon::Groudon]] im Auge zu behalten und dafür zu sorgen, dass sie keinen Ärger mehr machen.',
    'Groudon reverts to its Primal form when the sun is harsh, and Kyogre reverts to its Primal form in the rain.': '[[pokemon::Groudon]] nimmt bei starkem Sonnenlicht seine Protoform an, und [[pokemon::Kyogre]] nimmt im Regen seine Protoform an.',
    'Archie and Maxie are still lurking somewhere in Hoenn, but without the Orbs I think they\'re mostly harmless. If you need some help smacking em down again, come get me!': 'Adrian und Marc treiben sich noch irgendwo in Hoenn herum, aber ohne die Kugeln sind sie wohl größtenteils harmlos. Wenn du Hilfe brauchst, um sie wieder plattzumachen, komm einfach zu mir!',
    'You must be $playername$, the trainer Wa... People are talking about.': 'Du musst $playername$ sein, der Trainer, von dem Wa... Von dem alle reden.',
    'If you\'re here, it means you\'ve heard the same news that I have: a meteor is headed towards this island.': 'Wenn du hier bist, heißt das, du hast dieselben Neuigkeiten gehört wie ich: Ein Meteor fliegt auf diese Insel zu.',
    'Who am I? My name is Zinnia, nice to meet you. I have a certain.... connection to the Pokémon of this region, but we can get into that later.': 'Wer ich bin? Mein Name ist Amalia, freut mich. Ich habe eine gewisse ... Verbindung zu den Pokémon dieser Region, aber darüber können wir später reden.',
    'For now, I think we can help each other out. I need you to introduce me to your rival, May. If you do that, I\'ll tell you my plan to stop the meteor.': 'Vorerst denke ich, dass wir uns gegenseitig helfen können. Du musst mich deiner Rivalin Maike vorstellen. Wenn du das tust, erzähle ich dir meinen Plan, wie wir den Meteor aufhalten.',
    '<i>Your Rayquaza approaches Zinnia.</i>': '<i>Dein [[pokemon::Rayquaza]] nähert sich Amalia.</i>',
    'Yes! Finally! The moment I have been waiting for! I have gathered enough Key Stones to draw out the latent power in Rayquaza and stop the impending disaster!': 'Ja! Endlich! Der Moment, auf den ich gewartet habe! Ich habe genug Schlüsselsteine gesammelt, um die verborgene Kraft von [[pokemon::Rayquaza]] hervorzulocken und die drohende Katastrophe aufzuhalten!',
    'Huh?! H-how can this be? I did everything I was supposed to, and you\'re not changing! <b>Come on! Do it! Mega Evolve! Why?!</b>': 'Was?! W-wie kann das sein? Ich habe alles getan, was ich tun sollte, und du verwandelst dich nicht! <b>Komm schon! Mach schon! Mega-Entwicklung! Warum?!</b>',
    'Is it... you\'re not here for me? You\'re here for $playername$? That\'s no fair! I\'m the chosen one!': 'Kann es sein ... dass du nicht meinetwegen hier bist? Du bist wegen $playername$ hier? Das ist unfair! Ich bin doch die Auserwählte!',
    '<i>You notice the Meteorite Shards you have been carrying have fused together and are emitting a powerful glow.</i></br><img src="assets/images/megaStone/Meteorite.png"/>': '<i>Dir fällt auf, dass die Meteoritensplitter, die du bei dir trägst, miteinander verschmolzen sind und ein starkes Leuchten ausstrahlen.</i></br><img src="assets/images/megaStone/Meteorite.png"/>',
    'You did it! Your bond with Rayquaza is strong enough to bring out its Mega Evolution!': 'Du hast es geschafft! Deine Bindung zu [[pokemon::Rayquaza]] ist stark genug, um seine Mega-Entwicklung hervorzurufen!',
    'Here, take this space suit! I put it together from parts I... Er... Borrowed from the Aqua and Magma Hideouts. It should keep you safe while you accompany Mega Rayquaza into space.': 'Hier, nimm diesen Raumanzug! Ich habe ihn aus Teilen zusammengebaut, die ich mir ... äh ... aus den Verstecken von Team Aqua und Team Magma geliehen habe. Er sollte dich schützen, während du [[pokemon::Mega Rayquaza]] ins All begleitest.',
    '<i>These strange markings seem to spell something out. The nearby Braille Enthusiast may know more.</i>': '<i>Diese seltsamen Zeichen scheinen etwas zu bedeuten. Der Brailleschrift-Fan in der Nähe weiß vielleicht mehr.</i>',
    '<i>You turn left and proceed to the next room.</i>': '<i>Du biegst nach links ab und gehst weiter in den nächsten Raum.</i>',
    '<i>You turn left, but it is a dead end.</i>': '<i>Du biegst nach links ab, aber es ist eine Sackgasse.</i>',
    '<i>You turn right and proceed to the next room.</i>': '<i>Du biegst nach rechts ab und gehst weiter in den nächsten Raum.</i>',
    '<i>You turn right, but it is a dead end.</i>': '<i>Du biegst nach rechts ab, aber es ist eine Sackgasse.</i>',
    '<i>You go straight and proceed to the next room.</i>': '<i>Du gehst geradeaus weiter in den nächsten Raum.</i>',
    '<i>You go straight, but it is a dead end.</i>': '<i>Du gehst geradeaus, aber es ist eine Sackgasse.</i>',
    'The markings at the entrance to the Sealed Chamber seem to say that some sort of secret is inside. Try to find more braille messages, and I can decode them for you!': 'Die Zeichen am Eingang der Sealed Chamber scheinen zu besagen, dass sich darin eine Art Geheimnis befindet. Versuch, weitere Botschaften in Brailleschrift zu finden, dann kann ich sie für dich entschlüsseln!',
    'There are a few carvings inside this maze. The carving with five dots on the top row says "LEFT".': 'In diesem Labyrinth gibt es ein paar Inschriften. Die Inschrift mit fünf Punkten in der oberen Reihe bedeutet „LINKS“.',
    'The carving with nine dots on the top row says "STRAIGHT".': 'Die Inschrift mit neun Punkten in der oberen Reihe bedeutet „GERADEAUS“.',
    'The carving with six dots on the top row says "RIGHT".': 'Die Inschrift mit sechs Punkten in der oberen Reihe bedeutet „RECHTS“.',
    'If you get totally lost, just wander around. You will find the right path eventually.': 'Wenn du dich völlig verirrst, lauf einfach herum. Irgendwann findest du schon den richtigen Weg.',
    'The first carving says DESERT. There is a desert near Route 111, right?': 'Die erste Inschrift bedeutet WÜSTE. In der Nähe von Route 111 gibt es doch eine Wüste, oder?',
    'The second carving says ISLAND. There are a lot of islands on Route 105.': 'Die zweite Inschrift bedeutet INSEL. Auf Route 105 gibt es viele Inseln.',
    'The third carving says ANCIENT. I remember seeing some ancient ruins on Route 120.': 'Die dritte Inschrift bedeutet ANTIK. Ich erinnere mich, auf Route 120 ein paar antike Ruinen gesehen zu haben.',
    'You did a good thing, freeing that Plusle from those goons. I think they were all part of the evil organization I\'ve been hearing about: Team Cipher!': 'Das war gut, dass du dieses [[pokemon::Plusle]] von diesen Schlägern befreit hast. Ich glaube, sie gehörten alle zu der bösen Organisation, von der ich gehört habe: Team Cipher!',
    'My grandfather might know more about them, he\'s a smart guy. Let\'s go see him in Agate Village!': 'Mein Großvater weiß vielleicht mehr über sie, er ist ein schlauer Kerl. Lass uns ihn in Agate Village besuchen!',
    'Yow! You\'re too tough!': 'Autsch! Du bist zu stark!',
    'I know the Plusle you\'re looking for, it got taken by the infamous dance machine, Miror B.': 'Ich kenne das [[pokemon::Plusle]], nach dem du suchst. Es wurde von der berüchtigten Tanzmaschine Miror B. entführt.',
    'You don\'t want to mess with him, I promise! Oh? You do?': 'Mit dem willst du dich nicht anlegen, glaub mir! Oh? Doch?',
    'Well, his hideout is in the Pyrite Cave. But you shouldn\'t go there.': 'Na ja, sein Versteck ist in der Pyrite Cave. Aber da solltest du nicht hingehen.',
    'Your victory doesn\'t matter, we got what we came for!': 'Dein Sieg spielt keine Rolle, wir haben, weswegen wir gekommen sind!',
    '<i>Exol shouts to his assembled peons:</i>': '<i>Exol ruft seinen versammelten Handlangern zu:</i>',
    'Troops, move out! On to Phenac!': 'Truppen, abrücken! Auf nach Phenac!',
    '<i>Miror B. flees, leaving Plusle behind. Plusle runs off in the direction of Pyrite Town.</i>': '<i>Miror B. flieht und lässt [[pokemon::Plusle]] zurück. [[pokemon::Plusle]] rennt in Richtung Pyrite Town davon.</i>',
    'Rui! And you are? $playername$? Nice to meet you!': 'Rui! Und wer bist du? $playername$? Freut mich, dich kennenzulernen!',
    'Thank you both for saving me from those goons. They were disrupting the peace and tranquility of this whole area.': 'Danke euch beiden, dass ihr mich vor diesen Schlägern gerettet habt. Sie haben den Frieden und die Ruhe dieser ganzen Gegend gestört.',
    '$playername$, if you ever have troubled or downright evil Pokémon, take them to the nearby Relic Stone. Its power, combined with the power of friendship you share with your Pokémon, may purify their souls.': '$playername$, wenn du jemals verstörte oder sogar richtig böse Pokémon hast, bring sie zum nahe gelegenen Relic Stone. Seine Kraft kann zusammen mit der Freundschaft, die dich mit deinen Pokémon verbindet, ihre Seelen vielleicht reinigen.',
    'Have you seen this crazy broadcast on TV?': 'Hast du diese verrückte Sendung im Fernsehen gesehen?',
    '<i>Rui shows you a TV broadcast coming out of a dark room underground, in which a beautiful woman is encouraging her minions to steal Pokémon.</i>': '<i>Rui zeigt dir eine Fernsehsendung aus einem dunklen unterirdischen Raum, in der eine schöne Frau ihre Handlanger dazu anstachelt, Pokémon zu stehlen.</i>',
    '<i>Scripts litter Venus\' desk, as well as other, more suspicious files addressing what trainers in town have which Pokémon. There are also several letters labeled "Mayor\'s Office".</i>': '<i>Auf Venus\' Schreibtisch liegen Drehbücher verstreut, außerdem weitere, verdächtigere Akten darüber, welche Trainer der Stadt welche Pokémon besitzen. Es gibt auch mehrere Briefe mit der Aufschrift „Büro des Bürgermeisters“.</i>',
    '<i>Rui calls to you from across the room:</i>': '<i>Rui ruft dir vom anderen Ende des Raums zu:</i>',
    'Hey $playername$! I found a button! I\'m gonna press it!': 'Hey, $playername$! Ich habe einen Knopf gefunden! Ich drück ihn jetzt!',
    '<i>An explosion rocks the room, revealing a tunnel out of a secret entrance. The scripts and letters are scattered all over the studio, making them impossible to sort out.</i>': '<i>Eine Explosion erschüttert den Raum und legt einen Tunnel frei, der aus einem geheimen Eingang führt. Die Skripte und Briefe sind im ganzen Studio verstreut, sodass man sie unmöglich ordnen kann.</i>',
    'Ooh, I so hate to say this! I can\'t beat you right now. Master Greevil will so be cross with me but… But that\'s okay.': 'Uuh, ich sag das sooo ungern! Ich kann dich gerade nicht besiegen. Meister Greevil wird sooo sauer auf mich sein, aber… Aber das ist okay.',
    'I\'ll let you owe me this one time. But you have to promise you will think of my plan next time. If you see XD001 you will so want to help me. I\'ll so be waiting for you!': 'Dieses eine Mal lasse ich dich bei mir in der Schuld stehen. Aber du musst versprechen, beim nächsten Mal an meinen Plan zu denken. Wenn du XD001 siehst, wirst du mir sooo gerne helfen wollen. Ich werde sooo auf dich warten!',
    'And don\'t bother looking for Professor Krane here, he\'s like long gone.': 'Und such hier gar nicht erst nach Professor Krane, der ist sowas von längst weg.',
    '<i>Before the helicopter can land, a fireball shoots across the sky, blowing it up!</i>': '<i>Bevor der Helikopter landen kann, schießt ein Feuerball über den Himmel und sprengt ihn in die Luft!</i>',
    '<i>A Ho-oh flies low, screeching a thanks to you for stopping the evil Team Cipher.</i>': '<i>Ein [[pokemon::Ho-Oh]] fliegt tief vorbei und kreischt dir einen Dank dafür zu, dass du das böse Team Cipher aufgehalten hast.</i>',
    'How is this possible?! I\'ve never seen a trainer so strong! But, no matter! Surely I\'ve bought Gorigan enough time.': 'Wie ist das möglich?! Ich habe noch nie einen so starken Trainer gesehen! Aber egal! Ich habe Gorigan sicher genug Zeit verschafft.',
    'His precious recovery operation must be finished by now. Today, we will leave quietly. But don\'t you forget us!': 'Seine kostbare Bergungsaktion muss inzwischen abgeschlossen sein. Heute ziehen wir uns leise zurück. Aber vergiss uns nicht!',
    'Welcome to Sinnoh! There are many legends and myths here. For example, it is said that trainers that conquer the Lake nearby, Lake Verity, will meet a mythical Pokémon known for Emotion roaming around the region. It sure would have been awesome to partner with that Pokémon in one of my routines!': 'Willkommen in Sinnoh! Hier gibt es viele Legenden und Mythen. Zum Beispiel heißt es, dass Trainer, die den nahegelegenen See, Lake Verity, bezwingen, einem mythischen Pokémon der Emotionen begegnen, das durch die Region streift. Es wäre echt toll gewesen, mit diesem Pokémon in einer meiner Vorführungen aufzutreten!',
    'Hey, $playername$! According to Prof. Rowan\'s research, 90% of all Pokémon are somehow tied to evolution! Yup, you can also see a Pokémon\'s evolution line in your Pokédex.': 'Hey, $playername$! Laut Prof. Eibes Forschung sind 90% aller Pokémon irgendwie mit der Entwicklung verbunden! Jep, du kannst die Entwicklungsreihe eines Pokémon auch in deinem Pokédex sehen.',
    'Hmmm… Oh! Sorry, I didn’t see you there! Sometimes the strangest things wash up on this beach, so I just got caught up in the search.': 'Hmmm… Oh! Entschuldige, ich hab dich gar nicht gesehen! Manchmal werden die seltsamsten Dinge an diesen Strand gespült, da war ich ganz in die Suche vertieft.',
    'Just last week a weird blue stone with a red center showed up. A rather slow-looking guy with a slowpoke found it first, and took it to the Pokémon Lab.': 'Erst letzte Woche ist ein seltsamer blauer Stein mit rotem Kern aufgetaucht. Ein ziemlich träge wirkender Typ mit einem [[pokemon::Slowpoke]] hat ihn zuerst gefunden und ins Pokémon-Labor gebracht.',
    'I think I\'ve seen that stone before - it was on a book of an old legend about the sea.': 'Ich glaube, ich habe diesen Stein schon einmal gesehen - er war in einem Buch über eine alte Legende des Meeres abgebildet.',
    'I think it went something like... "When the Prince of the Seas is born, all of his kin will come to this region to celebrate."': 'Ich glaube, sie ging ungefähr so... „Wenn der Prinz der Meere geboren wird, kommen all seine Verwandten in diese Region, um zu feiern.“',
    'Does that mean when this Prince comes, Pokémon like him will start roaming the region?': 'Heißt das, wenn dieser Prinz kommt, fangen Pokémon wie er an, durch die Region zu streifen?',
    'Ah, are you a strong trainer? I\'d like to leave this to a Pokémon Ranger, but the ones in this region are far away, and the crooks could escape by the time they caught up!': 'Ah, bist du ein starker Trainer? Ich würde das gern einem Pokémon Ranger überlassen, aber die in dieser Region sind weit weg, und die Gauner könnten entkommen sein, bis sie hier sind!',
    'I was robbed of a precious Pokémon Egg by the Go-Rock Squad! The egg was coloured a transparent blue...  Like the colour of the sea!': 'Die Go-Rock Squad hat mir ein kostbares Pokémon-Ei gestohlen! Das Ei war durchsichtig blau...  Wie die Farbe des Meeres!',
    'The Go-Rock Squad were troublemakers the Pokémon Rangers dealt with in my home region. I don\'t know why they took it, but the Go-Rock Squad is trying to regroup!': 'Die Go-Rock Squad waren Unruhestifter, mit denen sich die Pokémon Ranger in meiner Heimatregion herumgeschlagen haben. Ich weiß nicht, warum sie es genommen haben, aber die Go-Rock Squad versucht, sich neu zu formieren!',
    'I was robbed in the forest to the north. Please, you have to hurry!': 'Ich wurde im Wald im Norden ausgeraubt. Bitte, du musst dich beeilen!',
    'Thanks for retrieving the Egg!': 'Danke, dass du das Ei zurückgeholt hast!',
    'The Go-Rock Squad was already beaten once. That was probably their very last gasp of trouble-making.': 'Die Go-Rock Squad wurde schon einmal besiegt. Das war wahrscheinlich ihr allerletzter Versuch, Ärger zu machen.',
    'While you were gone I discovered that the egg belongs to Manaphy! No wonder the Go-Rock Squad was after it.': 'Während du weg warst, habe ich herausgefunden, dass das Ei zu [[pokemon::Manaphy]] gehört! Kein Wunder, dass die Go-Rock Squad hinter ihm her war.',
    'Canalave\'s Library has several books detailing the legends of Manaphy. Perhaps one of them can help us find out how to hatch this egg.': 'Die Bibliothek von Canalave hat mehrere Bücher über die Legenden von [[pokemon::Manaphy]]. Vielleicht kann uns eines davon verraten, wie wir dieses Ei ausbrüten können.',
    'No time to waste - I\'ll see you at the Canalave Library!': 'Keine Zeit zu verlieren - wir sehen uns in der Canalave Library!',
    'Damn, that Happiny got away. Just when I had it cornered, a Pichu and a Glameow came out and attacked me.': 'Mist, das [[pokemon::Happiny]] ist entwischt. Gerade als ich es in die Enge getrieben hatte, kamen ein [[pokemon::Pichu]] und ein [[pokemon::Glameow]] und haben mich angegriffen.',
    '...Hey, I recognize you! You pinched the egg we pinched in Eterna Forest!': '...Hey, dich kenne ich doch! Du hast uns das Ei geklaut, das wir im Eterna Forest geklaut haben!',
    'I\'m gonna pinch that Pokémon first, so if you want to try and stop me, you\'ll have to get through my Pokémon!': 'Ich klau mir das Pokémon zuerst, und wenn du mich aufhalten willst, musst du erst an meinen Pokémon vorbei!',
    'Did you know?! The Gym Leaders of Canalave and Oreburgh are father and son! And what\'s more- there\'s a third person in the mix! Apparently he\'s such a dedicated digger he travelled all the way to Kanto to set up shop selling Explorer Kits! Talk about a family tradition!': 'Wusstest du schon?! Die Arenaleiter von Canalave und Oreburgh sind Vater und Sohn! Und nicht nur das - es gibt noch eine dritte Person im Bunde! Anscheinend ist er so ein leidenschaftlicher Gräber, dass er bis nach Kanto gereist ist, um dort Forscher-Sets zu verkaufen! Das nenne ich mal Familientradition!',
    'Too bad there are only two new fossils in the Sinnoh region. If there was one more, maybe he could be a Gym Leader too!': 'Schade, dass es in der Sinnoh-Region nur zwei neue Fossilien gibt. Gäbe es noch eins, könnte er vielleicht auch Arenaleiter werden!',
    'What? Oh you didn\'t know? The ace Pokémon of Gym Leaders Byron and Roark are resurrected from fossils!': 'Was? Oh, das wusstest du nicht? Die Top-Pokémon der Arenaleiter Adam und Veit wurden aus Fossilien wiederbelebt!',
    'A Happiny with a blue egg?': 'Ein [[pokemon::Happiny]] mit einem blauen Ei?',
    'I did see a Happiny like that. They were heading north, across Route 204.': 'Ich habe so ein [[pokemon::Happiny]] gesehen. Es lief nach Norden, über Route 204.',
    'Some guy in a weird white outfit was chasing a Happiny!': 'Irgendein Typ in einem seltsamen weißen Outfit hat ein [[pokemon::Happiny]] gejagt!',
    'They were heading south, towards Professor Rowan\'s lab!': 'Sie liefen nach Süden, in Richtung von Professor Eibes Labor!',
    'You\'re chasing after them too, right? Good luck catching up to them!': 'Du jagst ihnen auch hinterher, oder? Viel Glück beim Einholen!',
    'I was doing some exploring in Mt. Coronet last week, and my Nosepass gained a lot of levels.': 'Ich war letzte Woche ein bisschen am Mt. Coronet auf Erkundungstour, und mein [[pokemon::Nosepass]] hat viele Level aufgestiegen.',
    'I had a big suprise when he reached level 20 though!': 'Aber als es Level 20 erreicht hat, war ich echt überrascht!',
    'Oh hey! Still chasing that Happiny, huh?': 'Oh, hey! Immer noch hinter dem [[pokemon::Happiny]] her, was?',
    'When I saw it still running, I tried to catch up to it, but it got into the Oreburgh Tunnel and I lost track of it.': 'Als ich gesehen habe, dass es immer noch rennt, habe ich versucht, es einzuholen, aber es ist in den Oreburgh Tunnel gelaufen und ich habe es aus den Augen verloren.',
    '...Say, are you alright? You look a little... bug-eyed.': '...Sag mal, geht\'s dir gut? Du siehst ein bisschen... glubschäugig aus.',
    '<i>...This annoying little twerp has been taking you in one big loop, hasn\'t it...</i>': '<i>...Dieser nervige kleine Racker hat dich in einer großen Runde im Kreis geführt, oder...</i>',
    'Something amazing just happened!': 'Gerade ist etwas Unglaubliches passiert!',
    'My friend was taking their Eevee on a walk through Eterna Forest, and it suddenly evolved!': 'Ein Freund von mir ist mit seinem [[pokemon::Eevee]] durch den Eterna Forest spaziert, und plötzlich hat es sich entwickelt!',
    'Can you believe that?': 'Kannst du das glauben?',
    'A Happiny with a blue egg? Are you its trainer?': 'Ein [[pokemon::Happiny]] mit einem blauen Ei? Bist du sein Trainer?',
    'I was just minding my own business, when a little pink thing knocked me right over! By the time I got up, it was long gone, racing for the Eterna Forest.': 'Ich war ganz mit mir selbst beschäftigt, als mich ein kleines rosa Ding einfach umgerannt hat! Als ich wieder aufgestanden bin, war es längst weg und raste in Richtung Eterna Forest.',
    'I was worried its trainer had lost it, so I came here to ask around. I hope you catch up to it soon.': 'Ich hatte Sorge, dass sein Trainer es verloren hat, also bin ich hergekommen, um mich umzuhören. Ich hoffe, du holst es bald ein.',
    '<i>If it has a better sense of direction than the Go-Rock Squad, it\'ll probably pop out at Eterna City.</i>': '<i>Wenn es einen besseren Orientierungssinn hat als die Go-Rock Squad, taucht es wahrscheinlich in Eterna City wieder auf.</i>',
    'Oh, you came from the Forest! That Old Chateau is so creepy, isn’t it? I’ve heard that trainers that catch the weird ghost in the TV have found ghosts in other appliances. Even lawnmowers!': 'Oh, du kommst aus dem Wald! Das Old Chateau ist so gruselig, oder? Ich habe gehört, dass Trainer, die den seltsamen Geist im Fernseher fangen, auch Geister in anderen Haushaltsgeräten gefunden haben. Sogar in Rasenmähern!',
    'A Happiny with a blue egg? Ah yeah, I saw it.': 'Ein [[pokemon::Happiny]] mit einem blauen Ei? Ah ja, das habe ich gesehen.',
    'It ran right through here and went across Route 211, straight for Mt. Coronet.': 'Es ist direkt hier durchgerannt und dann über Route 211 schnurstracks zum Mt. Coronet.',
    '<i>Did the Happiny really leave Eterna and brave Mt. Coronet with the egg in tow? Maybe it\'s reached the other side by now.</i>': '<i>Hat das [[pokemon::Happiny]] wirklich Eterna verlassen und sich mit dem Ei im Schlepptau auf den Mt. Coronet gewagt? Vielleicht hat es inzwischen schon die andere Seite erreicht.</i>',
    'My favourite contestant had a big reveal for us this week!': 'Mein Lieblingsteilnehmer hatte diese Woche eine große Überraschung für uns!',
    'Their prized Magneton had evolved into a Magnezone!': 'Sein wertvolles [[pokemon::Magneton]] hatte sich zu einem [[pokemon::Magnezone]] entwickelt!',
    'I\'m so happy for them, all of that training in Mt. Coronet must have paid off!': 'Ich freue mich so für ihn, das ganze Training am Mt. Coronet hat sich wohl ausgezahlt!',
    'I have so many Gracidea right now, so i\'ll sell you one.': 'Ich habe gerade so viele Gracidea, da verkaufe ich dir eine.',
    'If you give it to your Shaymin, it can change form!': 'Wenn du sie deinem [[pokemon::Shaymin]] gibst, kann es seine Form ändern!',
    'Greetings trainer! I own the Trophy Garden down south!': 'Sei gegrüßt, Trainer! Mir gehört der Trophy Garden weiter südlich!',
    'Every day I bring in different Pokémon for trainers to catch. Some of them are extremely rare! I just love watching trainers catching Pokémon in my garden.': 'Jeden Tag bringe ich andere Pokémon her, die Trainer fangen können. Manche davon sind extrem selten! Ich liebe es einfach, Trainern dabei zuzusehen, wie sie in meinem Garten Pokémon fangen.',
    'I make sure the experience is perfectly tailored to each individual trainer. I only ever bring in Pokémon that the trainer already owns. Hunting familiar prey, as it were. Oh it\'s so exciting!': 'Ich sorge dafür, dass das Erlebnis perfekt auf jeden einzelnen Trainer zugeschnitten ist. Ich bringe nur Pokémon her, die der Trainer bereits besitzt. Jagd auf vertraute Beute, sozusagen. Oh, das ist so aufregend!',
    'Hm? You want to know what the point of that is? Well, some trainers really like to catch the same Pokémon over and over again. Maybe, some day, you\'ll find a reason to want to do that too.': 'Hm? Du willst wissen, was das Ganze soll? Nun, manche Trainer fangen einfach gern immer wieder dasselbe Pokémon. Vielleicht findest du eines Tages auch einen Grund, das tun zu wollen.',
    'Who sent you to talk to me? Howard Clifford himself? That\'s a little suspicious, but you seem trustworthy enough.': 'Wer hat dich zu mir geschickt? Howard Clifford persönlich? Das ist ein wenig verdächtig, aber du wirkst vertrauenswürdig genug.',
    'I\'ve been doing some research on this R compound, and have reason to believe it is being manufactured or used in research at the P2 Lab in Unova.': 'Ich habe zu dieser R-Substanz recherchiert und habe Grund zu der Annahme, dass sie im P2 Lab in Unova hergestellt oder in der Forschung verwendet wird.',
    'We should investigate!': 'Wir sollten das untersuchen!',
    'Me and my buddy Slowpoke are trying to catch a Happiny that just went running into Mt. Coronet.': 'Mein Kumpel [[pokemon::Slowpoke]] und ich versuchen, ein [[pokemon::Happiny]] zu fangen, das gerade in den Mt. Coronet gerannt ist.',
    'It had a blue egg on its belly - I\'ve definitely seen an egg like that before, back in Fiore.': 'Es hatte ein blaues Ei am Bauch - so ein Ei habe ich definitiv schon mal gesehen, damals in Fiore.',
    'My Slowpoke\'s gone ahead, I hope I can catch up to them soon.': 'Mein [[pokemon::Slowpoke]] ist schon vorausgegangen, ich hoffe, ich hole sie bald ein.',
    'Ah, you\'re the one chasing after that Happiny? You look a bit puffed, are you okay?': 'Ah, du bist derjenige, der diesem [[pokemon::Happiny]] hinterherjagt? Du siehst ein bisschen außer Atem aus, alles in Ordnung?',
    'I tried to capture it, but it barrelled right through my Capture Disc\'s trail! It went for Hearthome City. It wasn\'t showing any signs of slowing down yet.': 'Ich habe versucht, es einzufangen, aber es ist einfach durch die Spur meiner Fangscheibe hindurchgebrettert! Es lief Richtung Hearthome City. Es zeigte noch keinerlei Anzeichen, langsamer zu werden.',
    'Hello young one, have you come here to learn of Sinnoh’s mysteries?': 'Hallo, junger Mensch, bist du hergekommen, um etwas über die Geheimnisse Sinnohs zu erfahren?',
    'Did you know that in Johto they don’t see Pokémon like Mamoswine? It’s strange too, because you don’t even need a stone to evolve Piloswine… maybe they should try the Day Care?': 'Wusstest du, dass man in Johto keine Pokémon wie [[pokemon::Mamoswine]] sieht? Das ist auch seltsam, denn man braucht nicht einmal einen Stein, um [[pokemon::Piloswine]] zu entwickeln… vielleicht sollten sie es mal mit der Pension versuchen?',
    'I was just finishing up my shift at the Café Cabin when a little pink puffball ran past! It was heading south, for the ruins down there.': 'Ich hatte gerade meine Schicht in der Café Cabin beendet, als ein kleiner rosa Flauschball vorbeirannte! Er lief nach Süden, zu den Ruinen dort unten.',
    '...Eh, it was a Happiny? ...That\'s one fast Happiny, then, isn\'t it?': '...Äh, das war ein [[pokemon::Happiny]]? ...Dann ist das aber ein ganz schön schnelles [[pokemon::Happiny]], oder?',
    'Hey, welcome to the Pal Park! Have you been to my Dad’s Safari Zone in Kanto? We don’t have as many Pokémon here, but I’ve heard that a flower Pokémon found here can bloom when it’s sunny outside!': 'Hey, willkommen im Pal Park! Warst du schon in der Safari Zone meines Vaters in Kanto? Wir haben hier nicht so viele Pokémon, aber ich habe gehört, dass ein Blumen-Pokémon, das man hier findet, erblühen kann, wenn draußen die Sonne scheint!',
    'A lot of scary stuff can happen at night. For example, I only see people using Razor Claw and Razor Fang at night.': 'Nachts können viele unheimliche Dinge passieren. Zum Beispiel sehe ich Leute nur nachts Scharfklaue und Scharfzahn benutzen.',
    'I wonder why that is? Maybe it doesn\'t work during the day?': 'Ich frage mich, woran das liegt? Vielleicht funktioniert es tagsüber nicht?',
    '<i>You\'ve seen \'boulders\' like this before.</i>': '<i>Solche „Felsbrocken“ hast du schon einmal gesehen.</i>',
    '<i>According to the murmuring crowd around them, a Happiny ran this way and threw the boulders behind it to block any pursuers.</i>': '<i>Laut der murmelnden Menge um sie herum ist ein [[pokemon::Happiny]] hier entlanggelaufen und hat die Felsbrocken hinter sich geworfen, um Verfolger aufzuhalten.</i>',
    '<i>You spray the boulders with your water types, and they... don\'t move. Huh, guess they really are boulders this time.</i>': '<i>Du bespritzt die Felsbrocken mit deinen Wasser-Pokémon, und sie... bewegen sich nicht. Hm, diesmal sind es wohl wirklich Felsbrocken.</i>',
    '<i>Well, that just means that you can get some fighting-types and crush them with no regrets.</i>': '<i>Tja, das heißt nur, dass du ein paar Kampf-Pokémon holen und sie ohne Reue zertrümmern kannst.</i>',
    'My partner Lucario evolved from a Riolu during daytime when I used a Soothe Bell.': 'Mein Partner [[pokemon::Lucario]] hat sich tagsüber aus einem [[pokemon::Riolu]] entwickelt, als ich eine Sanftglocke benutzt habe.',
    'Oh, hello! Say, have you ever heard of Cresselia? Once when I was really little I had a really bad dream I couldn’t wake up from, but then a kind trainer went to an island near here and got help from Cresselia to cure me!': 'Oh, hallo! Sag mal, hast du schon mal von [[pokemon::Cresselia]] gehört? Als ich noch ganz klein war, hatte ich einmal einen furchtbaren Albtraum, aus dem ich nicht aufwachen konnte, aber dann ist ein freundlicher Trainer zu einer Insel hier in der Nähe gegangen und hat [[pokemon::Cresselia]] um Hilfe gebeten, um mich zu heilen!',
    'Maybe if you can prove yourself by conquering that island, you could find Cresselia roaming around the region...': 'Wenn du dich beweist, indem du diese Insel bezwingst, findest du [[pokemon::Cresselia]] vielleicht, wie es durch die Region streift...',
    '<i>Three Pokémon there were.</i>': '<i>Drei Pokémon gab es dort.</i>',
    '<i>Into the lakes they dove.</i>': '<i>In die Seen tauchten sie.</i>',
    '<i>Deep, deep, drawing no breath.</i>': '<i>Tief, tief, ohne Atem zu holen.</i>',
    '<i>Deeper, deeper they dove.</i>': '<i>Tiefer, tiefer tauchten sie.</i>',
    '<i>Into suffocating depths they dove.</i>': '<i>In erstickende Tiefen tauchten sie.</i>',
    '<i>Deeper, then deepest they alight.</i>': '<i>Tiefer, dann am tiefsten ließen sie sich nieder.</i>',
    '<i>From the lake floor they rise.</i>': '<i>Vom Grund des Sees steigen sie empor.</i>',
    '<i>Bearing with them the power to make vast lands, they rise again.</i>': '<i>Mit der Macht, weite Länder zu erschaffen, steigen sie erneut empor.</i>',
    'Trainer, there\'s trouble afoot!': 'Trainer, es gibt Ärger!',
    'The egg was stolen again - this time by a Happiny who belongs to a little girl here. It went eastward at top speed - it\'s probably left this city far behind it now.': 'Das Ei wurde schon wieder gestohlen - diesmal von einem [[pokemon::Happiny]], das einem kleinen Mädchen hier gehört. Es ist in Höchstgeschwindigkeit nach Osten gerannt - wahrscheinlich hat es diese Stadt längst weit hinter sich gelassen.',
    'We must retrieve that egg at all costs! Please, you have to chase down the egg-napper!': 'Wir müssen das Ei um jeden Preis zurückholen! Bitte, du musst den Eierdieb verfolgen!',
    'Ah, Manaphy hatched, did it? Looks like all that running around you and Happiny did incubated it enough to hatch it.': 'Ah, [[pokemon::Manaphy]] ist geschlüpft? Sieht so aus, als hätte die ganze Rennerei von dir und [[pokemon::Happiny]] es genug ausgebrütet, damit es schlüpft.',
    'There is something I\'ve discovered researching the Manaphy stories here. Apparently, Manaphy can be bred to produce an entirely different species of Pokémon!': 'Bei meinen Nachforschungen zu den [[pokemon::Manaphy]]-Geschichten hier habe ich etwas entdeckt. Anscheinend kann [[pokemon::Manaphy]] gezüchtet werden, um eine völlig andere Pokémon-Art hervorzubringen!',
    'Quite frankly, it\'s probably for the best if Manaphy stays with you. Apparently many things want to take that Pokémon for themselves, and I don\'t have the strength to fend them off.': 'Ehrlich gesagt ist es wahrscheinlich das Beste, wenn [[pokemon::Manaphy]] bei dir bleibt. Anscheinend wollen viele dieses Pokémon für sich haben, und ich habe nicht die Kraft, sie abzuwehren.',
    'Someone told me that training an Eevee on Route 217 will make it evolve.': 'Jemand hat mir erzählt, dass sich ein [[pokemon::Eevee]] entwickelt, wenn man es auf Route 217 trainiert.',
    'They must be lying, how can that be true?!': 'Das muss gelogen sein, wie soll das denn stimmen?!',
    'I recently traded with my friend Mindy expecting to get a Gengar. Instead, her Haunter came with this useless rock! I can\'t believe she would do this to me!': 'Ich habe neulich mit meiner Freundin Mindy getauscht und ein [[pokemon::Gengar]] erwartet. Stattdessen kam ihr [[pokemon::Haunter]] mit diesem nutzlosen Stein! Ich kann nicht glauben, dass sie mir das antut!',
    'Here, you can have <code class="text-nowrap">MINDY\'S-GIFT</code> for all I care! I pity whoever decides to trade with her in the future.': 'Hier, von mir aus kannst du <code class="text-nowrap">MINDY\'S-GIFT</code> haben! Wer auch immer in Zukunft mit ihr tauscht, tut mir leid.',
    'I\'ve been seeing a lot of Snover near the north of Route 217 recently.': 'Ich habe in letzter Zeit viele [[pokemon::Snover]] im Norden von Route 217 gesehen.',
    'Some of them are completely covered in berries, whereas others seem to be completely bare!': 'Manche von ihnen sind komplett mit Beeren bedeckt, während andere völlig kahl zu sein scheinen!',
    '...Come to think of it, only the ones going south were bare.': '...Wenn ich so drüber nachdenke, waren nur die kahl, die nach Süden gingen.',
    'I wonder what\'s happening to their berries then?': 'Ich frage mich, was dann mit ihren Beeren passiert?',
    'I\'ve been finding ways to grow Snover Berries using humane methods.': 'Ich habe Wege gefunden, [[pokemon::Snover]]-Beeren auf artgerechte Weise anzubauen.',
    'Snover are happy to let you pick their berries.  They then wander away into the wilderness. Please be kind to them!': '[[pokemon::Snover]] lassen dich gern ihre Beeren pflücken.  Danach wandern sie in die Wildnis davon. Bitte sei nett zu ihnen!',
    '<i>Several friendly Pokémon are snacking on a Grotle\'s acorns.</i>': '<i>Mehrere freundliche Pokémon knabbern an den Eicheln eines [[pokemon::Grotle]].</i>',
    'Oh! I don’t get visitors often. My husband is a sailor who visits faraway lands… he always tells me these fantastic things.': 'Oh! Ich bekomme nicht oft Besuch. Mein Mann ist Seemann und bereist ferne Länder… er erzählt mir immer die fantastischsten Dinge.',
    'One time he came back and his Wailmer looked funny. We took it to the Pokécenter and they said it had caught some weird virus called Pokérus!': 'Einmal kam er zurück und sein [[pokemon::Wailmer]] sah komisch aus. Wir haben es ins Pokémon-Center gebracht, und dort sagte man uns, es hätte sich mit einem seltsamen Virus namens Pokérus angesteckt!',
    'They said that it is a virus that can spread in the Pokémon Day Care. They said that Pokémon can only spread or catch the virus if they aren’t ready to hatch yet, and that they need to share a type with one another.': 'Sie sagten, das Virus könne sich in der Pokémon-Pension ausbreiten. Pokémon könnten das Virus nur verbreiten oder sich anstecken, wenn sie noch nicht bereit zum Schlüpfen sind, und sie müssten einen gemeinsamen Typ haben.',
    'If you have a Pokémon with Pokérus, try catching more of that type of Pokémon. When he got back from his next trip, oddly enough Wailmer seemed stronger than ever!': 'Wenn du ein Pokémon mit Pokérus hast, versuch, mehr Pokémon dieses Typs zu fangen. Als er von seiner nächsten Reise zurückkam, wirkte [[pokemon::Wailmer]] seltsamerweise stärker als je zuvor!',
    'Something amazing happened on top of Mt. Coronet. We could see it all the way from here. I\'m sure everyone in the entire region saw it.': 'Auf dem Gipfel des Mt. Coronet ist etwas Unglaubliches passiert. Wir konnten es von hier aus sehen. Ich bin sicher, die ganze Region hat es gesehen.',
    'What? You were there? What happened? What was that purple thing?': 'Was? Du warst dort? Was ist passiert? Was war dieses lila Ding?',
    'The Distortion World? Hold on, I think I\'ve heard that name before, there was a guy around here named Zero looking for a way to enter that place.': 'Die Zerrwelt? Moment, ich glaube, den Namen habe ich schon mal gehört. Hier in der Gegend war ein Typ namens Zero, der nach einem Weg gesucht hat, diesen Ort zu betreten.',
    'I doubt he\'d be interested in talking to you unless you could help him find a way to get there... Can\'t the lake guardians help you with that?': 'Ich bezweifle, dass er mit dir reden will, außer du kannst ihm helfen, einen Weg dorthin zu finden... Können dir die Hüter der Seen nicht dabei helfen?',
    'You\'re the Champion, right? I need your help on a small errand.': 'Du bist doch der Champ, oder? Ich brauche deine Hilfe bei einer kleinen Besorgung.',
    'My old friend Newton used to study the Distortion World, he was working on opening a gate to it. I\'ve heard that you were able to enter the Distortion World from a portal at the top of Mt. Coronet, so I was wondering if you could help me open a new portal to fulfill my friend\'s wish.': 'Mein alter Freund Newton hat die Zerrwelt erforscht und daran gearbeitet, ein Tor dorthin zu öffnen. Ich habe gehört, dass du die Zerrwelt durch ein Portal auf dem Gipfel des Mt. Coronet betreten konntest, also habe ich mich gefragt, ob du mir helfen könntest, ein neues Portal zu öffnen, um den Wunsch meines Freundes zu erfüllen.',
    'An old book about Sinnoh\'s history was recently discovered at the Canalave City Library, it may have useful information.': 'In der Bibliothek von Canalave City wurde kürzlich ein altes Buch über die Geschichte Sinnohs entdeckt. Es könnte nützliche Informationen enthalten.',
    'What was in that book? Did you find any information on the Distortion World?': 'Was stand in dem Buch? Hast du Informationen über die Zerrwelt gefunden?',
    'It didn\'t mention it once? That\'s a shame.': 'Sie wurde kein einziges Mal erwähnt? Wie schade.',
    'Wait, you said the book mentioned the Lake Trio, right? Legends say they have existed since the creation of the world, they may know how to enter the Distortion World.': 'Moment, du sagtest, das Buch erwähnt das Seen-Trio, oder? Legenden besagen, dass sie seit der Erschaffung der Welt existieren. Vielleicht wissen sie, wie man die Zerrwelt betritt.',
    'I spotted a bunch of roaming Pokémon on {ROUTE_NAME}!': 'Ich habe auf {ROUTE_NAME} jede Menge umherstreifende Pokémon entdeckt!',
    'Huff... huff... we should have been out of the forest by now!': 'Keuch... keuch... wir hätten längst aus dem Wald raus sein müssen!',
    'The plan was so simple. One of our grunts pre-planted a bunch of big red mushrooms with yellow spots to make a path out of the forest and to our hideout.': 'Der Plan war so einfach. Einer unserer Rüpel hat vorher einen Haufen großer roter Pilze mit gelben Punkten gepflanzt, um einen Weg aus dem Wald zu unserem Versteck zu markieren.',
    'But it feels like we\'ve been going in circles! The only reason I know we aren\'t is because every time we reach a similar crossroads, the mushrooms are in different places.': 'Aber es fühlt sich an, als würden wir im Kreis laufen! Ich weiß nur deshalb, dass wir es nicht tun, weil die Pilze jedes Mal an anderen Stellen stehen, wenn wir zu einer ähnlichen Kreuzung kommen.',
    'Unless... the mushrooms are moving somehow?': 'Es sei denn... die Pilze bewegen sich irgendwie?',
    '<i>What she\'s describing... could it be they\'re using Parasect? It\'s never a good idea to use living landmarks.</i>': '<i>Was sie da beschreibt... könnte es sein, dass sie [[pokemon::Parasect]] benutzen? Lebende Wegmarken zu verwenden, ist nie eine gute Idee.</i>',
    '<i>If you can take out a few of the Parasect, that should quickly corner them.</i>': '<i>Wenn du ein paar der [[pokemon::Parasect]] ausschaltest, solltest du sie schnell in die Enge treiben können.</i>',
    'You... are you a Pokémon Ranger? ...No? Well, no matter.': 'Du... bist du ein Pokémon Ranger? ...Nein? Nun, egal.',
    'Allow me to explain something to you. This egg is meaningful only if we possess it.': 'Lass mich dir etwas erklären. Dieses Ei hat nur dann eine Bedeutung, wenn wir es besitzen.',
    'We\'re going to hatch Manaphy from this egg and get it to guide us to its Sea Temple.': 'Wir werden [[pokemon::Manaphy]] aus diesem Ei schlüpfen lassen und es dazu bringen, uns zu seinem Meerestempel zu führen.',
    'With the power contained within, I will become the King of the Sea - far stronger than the old fool guiding us before!': 'Mit der Macht, die darin verborgen liegt, werde ich zum König des Meeres - weit stärker als der alte Narr, der uns früher geführt hat!',
    '<i>The Commander flees into the forest, with the Go-Rock Grunts covering his escape!</i>': '<i>Der Kommandant flieht in den Wald, während die Go-Rock-Rüpel seine Flucht decken!</i>',
    '<i>One of the pathways into the forest is blocked by a trio of large boulders.</i>': '<i>Einer der Pfade in den Wald ist von drei großen Felsbrocken blockiert.</i>',
    '<i>However, all three of the boulders look very similar... and they almost seem to have arms, as well.</i>': '<i>Allerdings sehen sich alle drei Felsbrocken sehr ähnlich... und sie scheinen fast auch Arme zu haben.</i>',
    '<i>Perhaps these aren\'t boulders after all... and if they are what you think they are, a good soaking should settle the matter.</i>': '<i>Vielleicht sind das doch keine Felsbrocken... und wenn sie das sind, wofür du sie hältst, sollte eine ordentliche Dusche die Sache klären.</i>',
    '<i>Mesprit told me you would come.</i>': '<i>[[pokemon::Mesprit]] hat mir gesagt, dass du kommen würdest.</i>',
    '<i>In order to enter the Distortion World, we need to open a gate to it. The materials you gathered for Mesprit are only a third of the ones needed to open such gate.</i>': '<i>Um die Zerrwelt zu betreten, müssen wir ein Tor dorthin öffnen. Die Materialien, die du für [[pokemon::Mesprit]] gesammelt hast, sind nur ein Drittel dessen, was nötig ist, um ein solches Tor zu öffnen.</i>',
    '<i>Obtain 10 Ochre Shards and then visit Uxie at Lake Acuity. These Shards can be found in a few dungeons from the Hoenn region.</i>': '<i>Besorge 10 Ockersplitter und besuche dann [[pokemon::Uxie]] am Lake Acuity. Diese Splitter findest du in einigen Dungeons der Hoenn-Region.</i>',
    '<i>You are the trainer looking for the Distortion World, right?</i>': '<i>Du bist der Trainer, der nach der Zerrwelt sucht, richtig?</i>',
    '<i>We can help you in your mission, but we will need a few materials.</i>': '<i>Wir können dir bei deiner Mission helfen, aber wir brauchen ein paar Materialien.</i>',
    '<i>Collect 10 Purple Shards in dungeons from the Johto region and then visit my two siblings. They will also help you in your quest.</i>': '<i>Sammle 10 Lila Splitter in Dungeons der Johto-Region und besuche dann meine beiden Geschwister. Auch sie werden dir bei deiner Aufgabe helfen.</i>',
    '<i>My siblings had informed me of your arrival.</i>': '<i>Meine Geschwister haben mich über deine Ankunft informiert.</i>',
    '<i>Looks like you have already gathered more than half of the necessary materials. The only materials left to make the key are 10 Crimson Shards, which can be found in various Sinnoh Dungeons.</i>': '<i>Wie es aussieht, hast du bereits mehr als die Hälfte der nötigen Materialien gesammelt. Die einzigen Materialien, die noch für den Schlüssel fehlen, sind 10 Karmesinsplitter, die man in verschiedenen Dungeons in Sinnoh finden kann.</i>',
    '<i>We will be waiting at Sendoff Spring, meet us there after you have collected the shards.</i>': '<i>Wir warten an der Sendoff Spring auf dich. Triff uns dort, nachdem du die Splitter gesammelt hast.</i>',
    '<i>You are finally here.</i>': '<i>Endlich bist du da.</i>',
    '<i>We have been able to create a key to the Distortion World using the materials you collected, but it is unable to work in its current state.</i>': '<i>Mit den Materialien, die du gesammelt hast, konnten wir einen Schlüssel zur Zerrwelt erschaffen, aber in seinem jetzigen Zustand funktioniert er nicht.</i>',
    '<i>We bestow it upon you, charge it with the ghostly energy of the Distortion World.</i>': '<i>Wir vertrauen ihn dir an. Lade ihn mit der geisterhaften Energie der Zerrwelt auf.</i>',
    '<i>In order to do so, you must collect Ghost gems by defeating Ghost type Pokémon and find a Spooky Plate. There should be some in this dungeon, we can sense their energy.</i>': '<i>Dazu musst du Geist-Edelsteine sammeln, indem du Pokémon vom Typ Geist besiegst, und eine Spuktafel finden. In diesem Dungeon sollte es welche geben, wir können ihre Energie spüren.</i>',
    'I couldn\'t wait anymore for you to report about your progress, so I asked around and discovered you were coming here.': 'Ich konnte nicht länger auf deinen Fortschrittsbericht warten, also habe ich mich umgehört und herausgefunden, dass du hierherkommst.',
    'Wait, is that the key to the Distortion World? With that, I could open the gate myself.': 'Moment, ist das der Schlüssel zur Zerrwelt? Damit könnte ich das Tor selbst öffnen.',
    'You know what? You are fired, I no longer need you. Now, give me the key to the Distortion World or I will take it by force!': 'Weißt du was? Du bist gefeuert, ich brauche dich nicht mehr. Und jetzt gib mir den Schlüssel zur Zerrwelt, oder ich nehme ihn mir mit Gewalt!',
    'Seems like you have managed to catch the Pokémon that rules the Distortion World.': 'Wie es scheint, hast du es geschafft, das Pokémon zu fangen, das über die Zerrwelt herrscht.',
    'But this doesn\'t look like the Renegade Pokémon from legend, it seems like some sort of altered form.': 'Aber das sieht nicht aus wie das abtrünnige Pokémon aus der Legende, es scheint eine Art veränderte Form zu sein.',
    'I once read that, deep within the Distortion World, there is an object capable of carrying the realm\'s power. Maybe, if you train Giratina while it has such object equipped, it can turn into its true form.': 'Ich habe einmal gelesen, dass es tief in der Zerrwelt einen Gegenstand gibt, der die Macht dieses Reiches in sich tragen kann. Wenn du [[pokemon::Giratina]] trainierst, während es einen solchen Gegenstand trägt, kann es vielleicht seine wahre Form annehmen.',
    'Sup. Ya like jazz? No? Well then you should check out me and my band at the Sonata Cafe where we never play Jazz.': 'Na? Stehst du auf Jazz? Nein? Na dann solltest du dir mal mich und meine Band im Sonata Cafe anschauen, wo wir niemals Jazz spielen.',
    'Sometimes a cool singing Pokémon shows up and joins in on our set. I’ve heard that trainers as strong as the Champion have found it roaming around the region looking for Pokémon battles… but even I wouldn’t challenge it to a Music battle.': 'Manchmal taucht ein cooles singendes Pokémon auf und spielt bei unserem Set mit. Ich habe gehört, dass Trainer, die so stark sind wie der Champ, es auf der Suche nach Pokémon-Kämpfen durch die Region streifen gesehen haben… aber nicht mal ich würde es zu einem Musik-Duell herausfordern.',
    '<i>The Red Genesect and a powerful Pokémon you don\'t recognize exchange energy blasts. The Red Genesect flees the battle, heading east.</i>': '<i>Das rote [[pokemon::Genesect]] und ein mächtiges Pokémon, das du nicht erkennst, beschießen sich mit Energiestrahlen. Das rote [[pokemon::Genesect]] flieht aus dem Kampf in Richtung Osten.</i>',
    'Why hello there. Nothing strange going on here. Please move along.': 'Na, hallo. Hier geht nichts Seltsames vor sich. Bitte geh weiter.',
    'Oh that business in the sewers? Yes, we should not have gone in there. Very unfortunate situation. A complete misunderstanding. We were just curious about what was down there.': 'Oh, die Sache in der Kanalisation? Ja, da hätten wir nicht reingehen sollen. Sehr unglückliche Situation. Ein komplettes Missverständnis. Wir waren nur neugierig, was dort unten ist.',
    'Bye now.': 'Tschüss dann.',
    'Whew! The desert is rough out there, glad you\'ve made it all the way to Nimbasa.': 'Puh! Die Wüste da draußen ist hart, schön, dass du es bis nach Nimbasa geschafft hast.',
    'Sometimes I find some weird stuff out in the sand, sometimes even Pokémon hiding in Chests. Like this one time in Relic Castle, I found a Pokémon that looks like a statue that I\'ve never seen before!': 'Manchmal finde ich seltsame Sachen draußen im Sand, manchmal sogar Pokémon, die sich in Truhen verstecken. Einmal habe ich im Relic Castle ein Pokémon gefunden, das wie eine Statue aussieht und das ich noch nie zuvor gesehen hatte!',
    'I told you. There\'s nothing suspicious going on here. We aren\'t stealing any Pokémon.': 'Ich hab\'s dir doch gesagt. Hier geht nichts Verdächtiges vor sich. Wir stehlen keine Pokémon.',
    'If you won\'t leave, we\'ll have to remove you.': 'Wenn du nicht gehst, müssen wir dich entfernen.',
    'YOU!': 'DU!',
    'Once again we will use the legendary Dragon-type Pokémon and we will rule the Unova region!': 'Erneut werden wir das legendäre Pokémon vom Typ Drache benutzen und über die Unova-Region herrschen!',
    'Curious Trainers, we shall not let you run around as you please!': 'Neugierige Trainer, wir werden euch nicht nach Belieben herumlaufen lassen!',
    'Shadow Triad! Get them out of here!': 'Schattentriade! Schafft sie hier raus!',
    'Hey, $playername$. It\'s not your fault Kyurem fled, but I\'m thinking it has probably gone into hiding. We should search the Giant Chasm for its lair at once.': 'Hey, $playername$. Es ist nicht deine Schuld, dass [[pokemon::Kyurem]] geflohen ist, aber ich denke, es hat sich wahrscheinlich versteckt. Wir sollten sofort den Giant Chasm nach seinem Unterschlupf absuchen.',
    'Remember when I told you that there was nothing suspicious about this frigate? I was lying, of course.': 'Weißt du noch, als ich dir gesagt habe, dass an dieser Fregatte nichts Verdächtiges ist? Das war natürlich gelogen.',
    'But truth be told, I didn\'t know that this thing could fly. I was not prepared for this.': 'Aber ehrlich gesagt wusste ich nicht, dass dieses Ding fliegen kann. Darauf war ich nicht vorbereitet.',
    'I\'m gonna be sick...': 'Mir wird schlecht...',
    'Did you hear? Did you see? It was on TV!': 'Hast du\'s gehört? Hast du\'s gesehen? Es kam im Fernsehen!',
    'I was just watching my favorite show, The National Gymquirer. It was a live segment! Some hot shot trainer from Kanto defeated Drayden! It was amazing! That trainer is so cool! Drayden is like unbeatable.': 'Ich habe gerade meine Lieblingssendung geschaut, den National Gymquirer. Es war ein Live-Beitrag! Irgendein toller Trainer aus Kanto hat Lysander besiegt! Es war unglaublich! Dieser Trainer ist so cool! Lysander ist doch quasi unbesiegbar.',
    'Then my programme got interrupted by an emergency broadcast. A report on the first confirmed sightings of Tornadus and Thundurus in over twenty-five years! I\'ve read so much about them, they are my favorites.': 'Dann wurde meine Sendung von einer Sondermeldung unterbrochen. Ein Bericht über die ersten bestätigten Sichtungen von [[pokemon::Tornadus]] und [[pokemon::Thundurus]] seit über fünfundzwanzig Jahren! Ich habe so viel über sie gelesen, sie sind meine Lieblinge.',
    'Last time they were spotted they just roamed around, causing all kinds of mischief. According to my books anyway. I\'m sure that amazing trainer from the TV will want to catch these mighty forces of nature.': 'Als sie das letzte Mal gesichtet wurden, sind sie einfach herumgestreift und haben allerlei Unfug angestellt. Zumindest laut meinen Büchern. Ich bin sicher, dieser tolle Trainer aus dem Fernsehen will diese mächtigen Naturgewalten fangen.',
    'Legends say Kyurem is missing a part of itself. It is waiting for a hero to fill in the missing parts of its body with Truth or Ideals.': 'Legenden besagen, dass [[pokemon::Kyurem]] ein Teil von sich fehlt. Es wartet auf einen Helden, der die fehlenden Teile seines Körpers mit Wahrheit oder Idealen füllt.',
    'The legendary dragons of Dragonspiral Tower are said to embody these very concepts. They sometimes leave a piece of their DNA behind after a battle.': 'Die legendären Drachen des Dragonspiral Tower sollen genau diese Konzepte verkörpern. Manchmal hinterlassen sie nach einem Kampf ein Stück ihrer DNS.',
    'If you have DNA splicers, perhaps you can make Kyurem whole again.': 'Wenn du DNS-Keile hast, kannst du [[pokemon::Kyurem]] vielleicht wieder vollständig machen.',
    'I\'ve never seen it, but supposedly it works just like any other evolution item.': 'Ich habe es nie gesehen, aber angeblich funktioniert es genau wie jedes andere Entwicklungs-Item.',
    'Welcome to my laboratory, trainer! I am working here to understand the mysterious Interdream Zone.': 'Willkommen in meinem Labor, Trainer! Ich arbeite hier daran, die geheimnisvolle Interdream-Zone zu verstehen.',
    'My laboratory equipment can convert the energy of dreams you experience while sleeping, or "Offline" into orbs. We can then open these orbs and see what your mind experienced in the Interdream Zone.': 'Meine Laborausrüstung kann die Energie der Träume, die du im Schlaf erlebst, also „Offline“, in Kugeln umwandeln. Diese Kugeln können wir dann öffnen und sehen, was dein Geist in der Interdream-Zone erlebt hat.',
    'A trainer like you surely dreams of rare Pokémon. The more rare Pokémon you find from the Interdream Zone, the more we can explore to find others!': 'Ein Trainer wie du träumt sicher von seltenen Pokémon. Je mehr seltene Pokémon du in der Interdream-Zone findest, desto mehr können wir erforschen, um weitere zu finden!',
    'I have been helping Professor Burnet explore the Interdream Zone with the help of my Audino.': 'Ich helfe Professor Burnet mithilfe meines [[pokemon::Audino]] dabei, die Interdream-Zone zu erforschen.',
    'Audino\'s excellent hearing lets it pick up even the quietest hints from Dream Orbs. If you can help the professor advance her research, I may be able to help you in return.': 'Dank seines hervorragenden Gehörs kann [[pokemon::Audino]] selbst die leisesten Hinweise aus Traumkugeln wahrnehmen. Wenn du der Professorin hilfst, ihre Forschung voranzubringen, kann ich dir vielleicht im Gegenzug helfen.',
    'What a battle! That Audinite will let you Mega Evolve your Audino, under certain circumstances.': 'Was für ein Kampf! Mit diesem Ohrdochnit kannst du dein [[pokemon::Audino]] unter bestimmten Umständen mega-entwickeln.',
    'I used to have my Pokémon maxed out on Protein, but then I found out about the new Vitamins!': 'Früher hatte ich meine Pokémon mit Protein voll ausgereizt, aber dann habe ich von den neuen Vitaminen erfahren!',
    'I swapped out some of my Proteins for the new Vitamins, but then I was left with a bunch of extra Protein I couldn\'t use.': 'Ich habe einen Teil meiner Proteine gegen die neuen Vitamine ausgetauscht, aber dann blieb mir ein Haufen Protein übrig, den ich nicht verwenden konnte.',
    'Luckily I was able to use the code <code class="text-nowrap">REFUND-VITAMINS</code> to get my money back! Too bad it only has one use though...': 'Zum Glück konnte ich mit dem Code <code class="text-nowrap">REFUND-VITAMINS</code> mein Geld zurückbekommen! Schade nur, dass er bloß einmal funktioniert...',
    'It will also only refund Vitamins you bought after hitting the price cap.': 'Er erstattet außerdem nur Vitamine, die du gekauft hast, nachdem die Preisobergrenze erreicht war.',
    'Hello! Would you like a seat indoors or on the patio? We have a lovely view of the museum, it used to double as a Gym you know! Business may have slowed down since the new Normal Gym moved to Aspertia, but our ex-Gym Leader Lenora is still at it with her husband restoring fossils!': 'Hallo! Möchtest du drinnen oder auf der Terrasse sitzen? Wir haben einen schönen Blick auf das Museum, das früher übrigens auch eine Arena war! Das Geschäft läuft vielleicht ruhiger, seit die neue Normal-Arena nach Aspertia gezogen ist, aber unsere ehemalige Arenaleiterin Aloe restauriert immer noch fleißig mit ihrem Mann Fossilien!',
    'Just last week they had an exhibit on a prehistoric bird and turtle! There was quite the crowd!': 'Erst letzte Woche hatten sie eine Ausstellung über einen urzeitlichen Vogel und eine Schildkröte! Da war ganz schön was los!',
    '... Do you think they\'re hiring?': '... Meinst du, die stellen gerade ein?',
    'Our research indicates a higher concentration of roaming Pokémon on {ROUTE_NAME}!': 'Unsere Forschung deutet auf eine höhere Konzentration umherstreifender Pokémon auf {ROUTE_NAME} hin!',
    'Did you see it come through? The Paleozoic Pokémon, Genesect?': 'Hast du es vorbeikommen sehen? Das paläozoische Pokémon, [[pokemon::Genesect]]?',
    'They haven\'t been seen in Unova for millions of years! If one is here now, it\'s sure to be a little confused about what the world is like.': 'Es wurde seit Millionen von Jahren nicht mehr in Unova gesehen! Wenn jetzt eines hier ist, ist es bestimmt ein wenig verwirrt darüber, wie die Welt heute aussieht.',
    'I worry it might attack the city out of fear.': 'Ich fürchte, es könnte die Stadt aus Angst angreifen.',
    'Wow! A real, live Genesect!': 'Wow! Ein echtes, lebendiges [[pokemon::Genesect]]!',
    'I hear that when you equip them with powerful Drive devices, they change forms!': 'Ich habe gehört, dass sie ihre Form ändern, wenn man sie mit mächtigen Modulen ausrüstet!',
    'They also have a high-speed form, which I hear has been sighted across Unova.': 'Sie haben auch eine Hochgeschwindigkeitsform, die angeblich überall in Unova gesichtet wurde.',
    'I\'ve heard tell of a secret room in this ruin. A room that supposedly contains a very rare Pokémon.': 'Ich habe von einem geheimen Raum in dieser Ruine gehört. Einem Raum, in dem sich angeblich ein sehr seltenes Pokémon befindet.',
    'Apparently this secret room is only accessible via a secret entrance in Relic Passage. Relic Passage runs from Driftveil City all the way under the river to Relic Castle. It\'s very impressive. Once I\'m done investigating this part of the ruin I\'m definitely going to check it out!': 'Anscheinend ist dieser geheime Raum nur über einen geheimen Eingang in der Relic Passage erreichbar. Die Relic Passage verläuft von Driftveil City bis unter dem Fluss hindurch zum Relic Castle. Sehr beeindruckend. Sobald ich mit der Untersuchung dieses Teils der Ruine fertig bin, schaue ich sie mir auf jeden Fall an!',
    'Hello kiddo. You must be $playername$, nice to meet you.': 'Hallo, Kleines. Du musst $playername$ sein, freut mich, dich kennenzulernen.',
    'You might\'ve heard about the Swords of Justice. They seem to be really worried recently and that also worries me, but you seem to be a really nice fellow so I\'ll tell you how to find their leader, Cobalion.': 'Du hast vielleicht schon von den Rittern der Redlichkeit gehört. Sie scheinen in letzter Zeit sehr besorgt zu sein, und das beunruhigt auch mich, aber du scheinst ein wirklich netter Mensch zu sein, also verrate ich dir, wie du ihren Anführer [[pokemon::Cobalion]] findest.',
    'It usually lurks around the deepest layers of Mistralton Cave so you might be able to find it by exploring around here.': 'Es hält sich meist in den tiefsten Ebenen der Mistralton Cave auf, also findest du es vielleicht, wenn du hier herumforschst.',
    'Greetings, may I ask who are you? Oh, you\'re a friend of the Old Man? That\'s great, and he sent you here to find me, I assume.': 'Sei gegrüßt, darf ich fragen, wer du bist? Oh, du bist ein Freund des alten Mannes? Das ist schön. Und er hat dich hergeschickt, um mich zu finden, nehme ich an.',
    'Well, since he told you to find me, there must be a reason. Unless you\'re here to help me re-form the Swords of Justice? If so, then thank you for your aid. Meet me in the Moor of Icirrus after you find them. You should look for Terrakion first, somewhere in the depths of the Unova Victory Road. Good luck, Trainer.': 'Nun, wenn er dir gesagt hat, mich zu finden, muss es einen Grund geben. Es sei denn, du bist hier, um mir zu helfen, die Ritter der Redlichkeit wieder zu vereinen? Wenn ja, dann danke ich dir für deine Hilfe. Triff mich im Moor of Icirrus, nachdem du sie gefunden hast. Such zuerst nach [[pokemon::Terrakion]], irgendwo in den Tiefen der Unova Victory Road. Viel Glück, Trainer.',
    'Welcome! I was asked by an acquaintance to help with his research. What I desire is to bring out the entirety in Pokémon potential! If I can accomplish that, I don\'t care what it takes!': 'Willkommen! Ein Bekannter hat mich gebeten, ihm bei seiner Forschung zu helfen. Mein Wunsch ist es, das gesamte Potenzial der Pokémon hervorzubringen! Wenn ich das erreichen kann, ist mir egal, was es kostet!',
    'If it means the strength must be brought out by the interactions between Pokémon and Trainers, then so be it! If it means you have to use a merciless approach, like Team Plasma\'s, and force out all of the Pokémon\'s power, then so be it! And yes, if the entire world is destroyed as a result, then so be it...': 'Wenn die Stärke durch das Zusammenspiel von Pokémon und Trainern hervorgebracht werden muss, dann soll es so sein! Wenn man dafür einen gnadenlosen Ansatz wie den von Team Plasma braucht und alle Kraft aus den Pokémon herauspressen muss, dann soll es so sein! Und ja, wenn dabei die ganze Welt zerstört wird, dann soll es eben so sein...',
    'That aside! The reason I have been traveling all over Unova and battling many Pokémon Trainers is because I was testing the viability of this approach to bringing out the full strength of Pokémon. In that respect, you\'ve done an amazing job.': 'Wie dem auch sei! Der Grund, warum ich durch ganz Unova gereist bin und gegen viele Pokémon-Trainer gekämpft habe, ist, dass ich die Tauglichkeit dieses Ansatzes getestet habe, die volle Stärke der Pokémon hervorzubringen. In dieser Hinsicht hast du hervorragende Arbeit geleistet.',
    'Well now! Tell me if you have the answer I desire or not! If you\'re ready, come at me!': 'Nun denn! Sag mir, ob du die Antwort hast, die ich mir wünsche, oder nicht! Wenn du bereit bist, greif mich an!',
    'Listen well! We swore to be loyal to Lord Ghetsis since he saved us! The only thing we want is the world Lord Ghetsis desires! Even if we lose, Lord Ghetsis simply has to win...': 'Hör gut zu! Wir haben geschworen, Meister G-Cis treu zu sein, seit er uns gerettet hat! Das Einzige, was wir wollen, ist die Welt, die Meister G-Cis sich wünscht! Selbst wenn wir verlieren, muss Meister G-Cis nur gewinnen...',
    'The only thing you can do is watch Lord Ghetsis use Kyurem to freeze Unova solid. That\'s all...': 'Das Einzige, was du tun kannst, ist zuzusehen, wie Meister G-Cis [[pokemon::Kyurem]] benutzt, um Unova komplett einzufrieren. Das ist alles...',
    '$playername$... Don\'t worry about us... We\'ll be fine... Defeat Kyurem once and for all so we can live in peace.': '$playername$... Mach dir keine Sorgen um uns... Uns geht es gut... Besiege [[pokemon::Kyurem]] ein für alle Mal, damit wir in Frieden leben können.',
    'Thank you for all your help, $playername$. You really were a great ally, and I hope we can meet again. As thanks for helping us, I\'ll be waiting for you in Mistralton Cave if you\'d wish for me to join your team.': 'Danke für all deine Hilfe, $playername$. Du warst wirklich ein großartiger Verbündeter, und ich hoffe, wir sehen uns wieder. Als Dank für deine Hilfe werde ich in der Mistralton Cave auf dich warten, falls du möchtest, dass ich mich deinem Team anschließe.',
    'Hey, you were a really great partner! It was really nice doing this mission with you, and you seem like a strong trainer, so if you want me to join your team, I\'ll be waiting at Victory Road!': 'Hey, du warst ein echt toller Partner! Es hat richtig Spaß gemacht, diese Mission mit dir zu erledigen, und du scheinst ein starker Trainer zu sein. Wenn du willst, dass ich mich deinem Team anschließe, warte ich auf der Victory Road auf dich!',
    'You were a great ally, $playername$. I feel it\'d be a wise decision on my part if I joined your team, but that\'s a decision for you to make. If you decide you wish for me to join your team, you can look for me in the depths of Pinwheel Forest.': 'Du warst ein großartiger Verbündeter, $playername$. Ich glaube, es wäre eine weise Entscheidung, mich deinem Team anzuschließen, aber diese Entscheidung liegt bei dir. Falls du möchtest, dass ich mich deinem Team anschließe, suche mich in den Tiefen des Pinwheel Forest.',
    '<i>Deep inside the Giant Chasm you find a Gemstone. It\'s moving, almost as if it was alive...</i>': '<i>Tief im Inneren des Giant Chasm findest du einen Edelstein. Er bewegt sich, fast als wäre er lebendig ...</i>',
    '<i>As you decide to pick up the stone you hear a roar, followed by an explosion in the distance.</i>': '<i>Als du den Stein aufheben willst, hörst du ein Brüllen, gefolgt von einer Explosion in der Ferne.</i>',
    'Hey, good job on chasing away those Pokémon. My name is Professor Lund and I\'m leading the science team in this area.': 'Hey, gute Arbeit, wie du diese Pokémon verjagt hast. Ich heiße Professor Lund und leite das Forschungsteam in dieser Gegend.',
    'You must know a meteorite has landed in this area... What are you saying? You already found it?!': 'Du weißt sicher, dass in dieser Gegend ein Meteorit eingeschlagen ist ... Was sagst du da? Du hast ihn schon gefunden?!',
    'It\'s truly spectacular... We\'re going to move the gemstone to our laboratory in Hoenn. If you like you can come with us, our lab is near the Battle Frontier. While we analyze the Gemstone you can use the local facilities.': 'Wirklich spektakulär ... Wir bringen den Edelstein in unser Labor in Hoenn. Wenn du willst, kannst du mitkommen, unser Labor liegt in der Nähe der Battle Frontier. Während wir den Edelstein untersuchen, kannst du die Einrichtungen vor Ort nutzen.',
    'How did you find me? Cobalion told me this place was well hidden! Anyways, what do you want from me? Cobalion wants to reunite the Swords of Justice? Do you think I\'m dumb enough to fall for lies of a human?': 'Wie hast du mich gefunden? [[pokemon::Cobalion]] hat mir gesagt, dieser Ort sei gut versteckt! Wie auch immer, was willst du von mir? [[pokemon::Cobalion]] will die Ritter der Redlichkeit wiedervereinen? Hältst du mich für so dumm, auf die Lügen eines Menschen hereinzufallen?',
    'I\'ll consider your worth only if you prove your strength and can beat me in battle!': 'Ich erkenne deinen Wert nur an, wenn du deine Stärke beweist und mich im Kampf besiegst!',
    'Thank you, $playername$. Your assistance with reuniting the Swords of Justice is greatly appreciated.': 'Danke, $playername$. Deine Hilfe bei der Wiedervereinigung der Ritter der Redlichkeit wissen wir sehr zu schätzen.',
    'Now that you\'ve found and brought back Terrakion, you should probably look for Virizion. Virizion usually likes to meditate to the sound of nature, so Pinwheel Forest might be a good place to search in. Good luck, and report back once you\'ve found each other.': 'Jetzt, da du [[pokemon::Terrakion]] gefunden und zurückgebracht hast, solltest du nach [[pokemon::Virizion]] suchen. [[pokemon::Virizion]] meditiert gern zu den Klängen der Natur, also wäre der Pinwheel Forest ein guter Ort für die Suche. Viel Glück, und meldet euch, sobald ihr euch gefunden habt.',
    'Welcome back, $playername$! I can see you\'ve brought back Virizion. Thank you for your assistance towards reuniting the Swords of Justice.': 'Willkommen zurück, $playername$! Wie ich sehe, hast du [[pokemon::Virizion]] mitgebracht. Danke für deine Hilfe bei der Wiedervereinigung der Ritter der Redlichkeit.',
    'Now, let\'s discuss the plan. Wait, you want to help too? You should know this will be a very dangerous mission, $playername$. We may not be able to fully protect you from the dangers we may face. The only way we can be sure of your safety is if you can hold your own against all three of us in battle. If you succeed, we will happily accept your assistance, but should you fail, then I apologise, but we cannot allow you to join the mission. What say you? Shall we spar?': 'Lass uns nun den Plan besprechen. Moment, du willst auch helfen? Du solltest wissen, dass dies eine sehr gefährliche Mission wird, $playername$. Wir können dich vielleicht nicht vollständig vor den Gefahren schützen, denen wir begegnen. Wir können uns deiner Sicherheit nur sicher sein, wenn du im Kampf gegen uns alle drei bestehen kannst. Gelingt dir das, nehmen wir deine Hilfe gern an. Scheiterst du jedoch, so tut es mir leid, aber dann können wir dich nicht an der Mission teilnehmen lassen. Was sagst du? Wollen wir kämpfen?',
    'Greetings, $playername$. I assume you couldn\'t find much, but I was able to find that Kyurem has been seen near Lacunosa Town. We should check it out immediately, before it decides to attack. You go ahead, I\'ll warn the others.': 'Sei gegrüßt, $playername$. Ich nehme an, du hast nicht viel gefunden, aber ich habe herausgefunden, dass [[pokemon::Kyurem]] in der Nähe von Lacunosa Town gesichtet wurde. Wir sollten sofort nachsehen, bevor es beschließt anzugreifen. Geh schon vor, ich warne die anderen.',
    'Hello, who are you, may I ask? You say you were sent here by Cobalion to reunite the Swords of Justice? I\'m sorry dear, you\'ll have to create a much more believable lie to deceive me. I\'m not so easily fooled.': 'Hallo, wer bist du, wenn ich fragen darf? Du sagst, [[pokemon::Cobalion]] hat dich geschickt, um die Ritter der Redlichkeit wiederzuvereinen? Tut mir leid, Liebes, da musst du dir schon eine viel glaubwürdigere Lüge ausdenken, um mich zu täuschen. Ich lasse mich nicht so leicht hinters Licht führen.',
    'To earn my trust, you need to prove your patience to me. If you can gather 5,000 Grass Gems and bring them to me, then I\'ll trust your word. If you cannot handle such a task, do not return.': 'Um mein Vertrauen zu gewinnen, musst du mir deine Geduld beweisen. Wenn du 5,000 Pflanzenjuwelen sammelst und sie mir bringst, werde ich dir glauben. Wenn du dieser Aufgabe nicht gewachsen bist, komm nicht wieder.',
    'Oh, you\'re back? And you\'ve brought the 5,000 Grass Gems. I\'m impressed. Very well, you\'ve earned my trust. So, Cobalion wants us to meet at the Moor of Icirrus to reunite the Swords of Justice? Sounds just like the old Cobalion I remember. I\'ll make my way there now, you should come too. I\'m sure your assistance is still desired.': 'Oh, du bist zurück? Und du hast die 5,000 Pflanzenjuwelen mitgebracht. Ich bin beeindruckt. Nun gut, du hast dir mein Vertrauen verdient. [[pokemon::Cobalion]] will also, dass wir uns im Moor of Icirrus treffen, um die Ritter der Redlichkeit wiederzuvereinen? Das klingt ganz nach dem alten [[pokemon::Cobalion]], das ich kenne. Ich mache mich gleich auf den Weg, du solltest auch mitkommen. Deine Hilfe ist sicher immer noch gefragt.',
    'So you defeated Ghetsis. Interesting. You must be a very strong trainer.': 'Du hast G-Cis also besiegt. Interessant. Du musst ein sehr starker Trainer sein.',
    'A rare Pokémon is hiding somewhere inside this abandoned laboratory. You can catch it if you want. I have no interest in it.': 'Irgendwo in diesem verlassenen Labor versteckt sich ein seltenes Pokémon. Du kannst es fangen, wenn du willst. Ich habe kein Interesse daran.',
    'However, I do have an interest in you! I want to taste your power. Defeat me, and I\'ll let you search for the rare Pokémon.': 'An dir hingegen habe ich sehr wohl Interesse! Ich will deine Stärke kosten. Besiege mich, und ich lasse dich nach dem seltenen Pokémon suchen.',
    'I\'ll be waiting for you inside.': 'Ich warte drinnen auf dich.',
    '<i>A bright red Pokémon flies past you at a high speed, heading west.</i>': '<i>Ein leuchtend rotes Pokémon fliegt mit hoher Geschwindigkeit an dir vorbei Richtung Westen.</i>',
    'Trainers report on sightings of various Genesect holding the same Drives as the Genesect they own.': 'Trainer berichten von Sichtungen verschiedener [[pokemon::Genesect]], die dieselben Module tragen wie das [[pokemon::Genesect]], das sie selbst besitzen.',
    'It seems like this Dungeon\'s Genesect is choosing its Drive based on the Moon Cycle!': 'Es scheint, als würde das [[pokemon::Genesect]] dieses Dungeons sein Modul je nach Mondzyklus wählen!',
    'Meanwhile the high-speed form races to different Dungeons all across Unova.': 'Die Hochgeschwindigkeitsform rast derweil zu verschiedenen Dungeons in ganz Unova.',
    'I\'ve heard a Pokémon detective is sniffing around here for mysteries! He might be interested in an enigmatic berry, too.': 'Ich habe gehört, hier schnüffelt ein Pokémon-Detektiv nach Rätseln herum! Vielleicht interessiert er sich auch für eine rätselhafte Beere.',
    '<i>Viola has sent some of her Vivillon photographs in to the local Pokémon Center as a photobook, to celebrate the Lunar New Year. You flip through the pages...</i>': '<i>Viola hat dem örtlichen Pokémon Center einige ihrer [[pokemon::Vivillon]]-Fotos als Fotobuch geschickt, um das Mondneujahr zu feiern. Du blätterst durch die Seiten ...</i>',
    '<i>You see both a Meadow and a Fancy Vivillon flying together in the skies above Kalos. Strangely, the Meadow Vivillon is wearing a necklace of exotic flowers, and the Fancy has a tiny tea cup in its grip.</i>': '<i>Du siehst ein [[pokemon::Vivillon]] im Blumenmeermuster und ein [[pokemon::Vivillon]] im Fantasiemuster zusammen am Himmel über Kalos fliegen. Seltsamerweise trägt das Blumenmeer-[[pokemon::Vivillon]] eine Kette aus exotischen Blumen, und das Fantasie-[[pokemon::Vivillon]] hält eine winzige Teetasse.</i>',
    '<i>You see a Marine Vivillon flying above the surface of a lake. It\'s got one foot trailing through the water.</i>': '<i>Du siehst ein [[pokemon::Vivillon]] im Marinemuster über einer Seeoberfläche fliegen. Ein Fuß streift dabei durchs Wasser.</i>',
    '<i>You see what was seemingly meant to be a photo of a Pokémon with a bulbous purple tail. However, a Modern Vivillon has jumped in front, and you can\'t get a good look at the other Pokémon.</i>': '<i>Du siehst etwas, das wohl ein Foto eines Pokémon mit einem knolligen lila Schwanz werden sollte. Allerdings ist ein [[pokemon::Vivillon]] im Modernmuster davorgesprungen, und du kannst das andere Pokémon nicht richtig erkennen.</i>',
    '<i>You see a Jungle Vivillon resting on a blue frog-like Pokémon. The two of them seem to be in the center of a deep bog, but neither looks very concerned.</i>': '<i>Du siehst ein [[pokemon::Vivillon]] im Dschungelmuster, das sich auf einem blauen, froschartigen Pokémon ausruht. Die beiden scheinen mitten in einem tiefen Sumpf zu sein, aber keines von ihnen wirkt besonders besorgt.</i>',
    '<i>You see a Monsoon Vivillon. It\'s been startled by a light shone in its face. As far as you can see, the area around the spotlight is darker than pitch.</i>': '<i>Du siehst ein [[pokemon::Vivillon]] im Monsunmuster. Es ist von einem Licht erschrocken, das ihm ins Gesicht leuchtet. Soweit du erkennen kannst, ist die Umgebung des Scheinwerfers pechschwarz.</i>',
    '<i>You see a Tundra Vivillon, watching a conveyor belt full of Poké Balls. A worker in the background looks mildly perplexed, as if he was expecting a different Pokémon there.</i>': '<i>Du siehst ein [[pokemon::Vivillon]] im Tundramuster, das ein Förderband voller Pokébälle beobachtet. Ein Arbeiter im Hintergrund wirkt leicht verwirrt, als hätte er dort ein anderes Pokémon erwartet.</i>',
    '<i>You see a Sun Vivillon bursting through a cloud of smoke. It\'s sweating, but seems to be enjoying itself.</i>': '<i>Du siehst ein [[pokemon::Vivillon]] im Sonnenmuster, das durch eine Rauchwolke bricht. Es schwitzt, scheint aber seinen Spaß zu haben.</i>',
    '<i>You see an Archipelago Vivillon staring in shock at a swaying pillar. A Hoothoot sits next to it, completely unfazed.</i>': '<i>Du siehst ein [[pokemon::Vivillon]] im Archipelmuster, das schockiert auf eine schwankende Säule starrt. Ein [[pokemon::Hoothoot]] sitzt völlig unbeeindruckt daneben.</i>',
    '<i>You see an Elegant Vivillon frantically pulling at a doorknob. A Klefki seems to be giggling in the background.</i>': '<i>Du siehst ein [[pokemon::Vivillon]] im Elegantmuster, das verzweifelt an einem Türknauf zieht. Ein [[pokemon::Klefki]] scheint im Hintergrund zu kichern.</i>',
    '<i>You see an Ocean Vivillon snoozing peacefully. An Audino is carefully laying a blanket atop it.</i>': '<i>Du siehst ein [[pokemon::Vivillon]] im Ozeanmuster friedlich schlummern. Ein [[pokemon::Audino]] legt vorsichtig eine Decke darüber.</i>',
    '<i>You see a shocked Continental Vivillon staring into a chest. A Voltorb stares back, already primed to explode.</i>': '<i>Du siehst ein schockiertes [[pokemon::Vivillon]] im Kontinentalmuster, das in eine Truhe starrt. Ein [[pokemon::Voltorb]] starrt zurück, bereit zu explodieren.</i>',
    '<i>You see a River Vivillon flying through a forest. A spooky old mansion is in the background.</i>': '<i>Du siehst ein [[pokemon::Vivillon]] im Flussmuster durch einen Wald fliegen. Im Hintergrund steht ein unheimliches altes Herrenhaus.</i>',
    '<i>You see a Polar Vivillon peering over the edge of a tower. Clouds travel distantly below.</i>': '<i>Du siehst ein [[pokemon::Vivillon]] im Polarmuster, das über den Rand eines Turms späht. Tief unten ziehen Wolken vorbei.</i>',
    '<i>You see a Sandstorm Vivillon atop some desert ruins. It\'s trying to communicate with a large, orange moth-like Pokémon.</i>': '<i>Du siehst ein [[pokemon::Vivillon]] im Sandsturmmuster auf einigen Wüstenruinen. Es versucht, sich mit einem großen, orangefarbenen, mottenartigen Pokémon zu verständigen.</i>',
    '<i>You see a Garden Vivillon playing in a field of flowers. The flowers extend far, far into the distance...</i>': '<i>Du siehst ein [[pokemon::Vivillon]] im Gartenmuster in einem Blumenfeld spielen. Die Blumen erstrecken sich bis weit, weit in die Ferne ...</i>',
    '<i>You see a High Plains Vivillon dancing with a group of Clefairy. Their dance is illuminated only by the full moon.</i>': '<i>Du siehst ein [[pokemon::Vivillon]] im Präriemuster mit einer Gruppe [[pokemon::Clefairy]] tanzen. Ihr Tanz wird nur vom Vollmond erleuchtet.</i>',
    '<i>You see a Savanna Vivillon running for its life through a ruined tower. Several dragon-type Pokémon are chasing it relentlessly.</i>': '<i>Du siehst ein [[pokemon::Vivillon]] im Savannenmuster, das um sein Leben durch einen zerstörten Turm rennt. Mehrere Drachen-Pokémon verfolgen es unerbittlich.</i>',
    '<i>You see an Icy Snow Vivillon bundled up with its trainer. It\'s enjoying a much-needed warm cup of cocoa to counteract the icy cave around it.</i>': '<i>Du siehst ein [[pokemon::Vivillon]] im Frostmuster, das sich mit seinem Trainer eingemummelt hat. Es genießt eine dringend nötige Tasse heißen Kakao, um der eisigen Höhle ringsum zu trotzen.</i>',
    '<i>Lastly, you see a Poké Ball Vivillon in a darkened mall. It\'s trying to scare the camerawoman, completely unaware of the sinister eyes peering from the darkness behind it.</i>': '<i>Zuletzt siehst du ein [[pokemon::Vivillon]] im Pokéballmuster in einem dunklen Einkaufszentrum. Es versucht, die Kamerafrau zu erschrecken, und bemerkt dabei nicht die finsteren Augen, die es aus der Dunkelheit dahinter beobachten.</i>',
    'Ever since growing old I\'m no longer the Pokémon Trainer that I used to be. Now I always like to keep my garden full of Kasib Berries.': 'Seit ich alt geworden bin, bin ich nicht mehr der Pokémon-Trainer, der ich einmal war. Heute halte ich meinen Garten immer voller Zitarzbeeren.',
    'One day, I forgot to harvest them, and within its withered husk, I found a small stone that enabled my Banette to perform a Mega Evolution.': 'Eines Tages vergaß ich, sie zu ernten, und in ihrer verdorrten Hülle fand ich einen kleinen Stein, mit dem mein [[pokemon::Banette]] eine Mega-Entwicklung durchführen konnte.',
    'Hey there! I\'m one of Professor Sycamore\'s assistants. If you\'ve made it to Kalos, you probably have a pretty impressive Pokédex by now, right?': 'Hallo! Ich bin einer der Assistenten von Professor Platan. Wenn du es bis nach Kalos geschafft hast, hast du inzwischen bestimmt einen ziemlich beeindruckenden Pokédex, oder?',
    'When you\'ve got your Pokédex open, you can click on a Pokémon\'s image to see more detailed stats about the Pokémon.': 'Wenn dein Pokédex geöffnet ist, kannst du auf das Bild eines Pokémon klicken, um genauere Werte zu diesem Pokémon zu sehen.',
    'Even if you don\'t remember details like how many times you\'ve encountered a particular species in the wild, or how many times you\'ve captured a Pokémon, your Pokédex does!': 'Auch wenn du dir Details nicht merkst, etwa wie oft du einer bestimmten Art in freier Wildbahn begegnet bist oder wie oft du ein Pokémon gefangen hast, dein Pokédex weiß es!',
    'And if some of the rumours about Mega Stones are true... it\'ll be worth keeping track of those sorts of things.': 'Und wenn einige der Gerüchte über Mega-Steine stimmen ... dann lohnt es sich, solche Dinge im Blick zu behalten.',
    'I\'m glad to be back in the city after so long at the Power Plant; it\'s so dusty out there!': 'Ich bin froh, nach so langer Zeit im Kraftwerk wieder in der Stadt zu sein. Da draußen ist es so staubig!',
    'Rumor has it that if you conquer the Kalos Power Plant enough times, a strong Pokémon made out of Fire and Water will challenge you. But I bet you’d have to be the Champion before it finds you worthy… I certainly have never seen it!': 'Gerüchten zufolge fordert dich ein starkes Pokémon aus Feuer und Wasser heraus, wenn du das Kalos Power Plant oft genug bezwingst. Aber ich wette, du müsstest Champ sein, bevor es dich für würdig hält ... Ich habe es jedenfalls noch nie gesehen!',
    'I\'m selling some peculiar stones for gems at my new shop, the Stone Emporium. Let me know if anything there strikes your fancy!': 'Ich verkaufe in meinem neuen Laden, dem Stone Emporium, ein paar merkwürdige Steine gegen Juwelen. Sag Bescheid, wenn dir dort etwas gefällt!',
    'Oh! You\'ve already met Professor Sycamore, how wonderful! That is a wonderful thing, indeed. You are one of the chosen ones.': 'Oh! Du hast Professor Platan bereits getroffen, wie wunderbar! Das ist wirklich etwas Wunderbares. Du bist einer der Auserwählten.',
    'I am Lysandre. I\'ve tried to learn as much about Pokémon as I can to help build a brighter future. Professor Sycamore has taught me so much.': 'Ich bin Flordelis. Ich habe versucht, so viel wie möglich über Pokémon zu lernen, um eine bessere Zukunft zu schaffen. Professor Platan hat mir so viel beigebracht.',
    'Now listen! It is vital that this world becomes a better place. The people and Pokémon chosen to make the world better must work tirelessly to achieve this goal.': 'Hör jetzt zu! Es ist von größter Bedeutung, dass diese Welt ein besserer Ort wird. Die Menschen und Pokémon, die auserwählt sind, die Welt zu verbessern, müssen unermüdlich auf dieses Ziel hinarbeiten.',
    'Well, I\'ll be off. Please give Professor Sycamore my best. My desire... it is for a more beautiful world!': 'Nun, ich mache mich auf den Weg. Bitte richte Professor Platan meine besten Grüße aus. Mein Wunsch ... ist eine schönere Welt!',
    'Hi $playername$, I just saw Diantha, a really cool and pretty actress, talking with a funny looking guy with orange spiky hair.': 'Hi $playername$, ich habe gerade Diantha gesehen, eine echt coole und hübsche Schauspielerin. Sie hat mit einem komisch aussehenden Typen mit orangefarbenen Stachelhaaren geredet.',
    'He was such a weirdo. He kept telling her how everything should be beautiful forever and how he would end the world in an instant so that beauty never fades.': 'Der war so ein Spinner. Er hat ihr ständig erzählt, dass alles für immer schön sein sollte und dass er die Welt in einem Augenblick beenden würde, damit die Schönheit nie verblasst.',
    'Anyway, I\'m gonna continue forward. I\'ll wait for you in Ambrette Town.': 'Wie auch immer, ich gehe weiter. Ich warte in Ambrette Town auf dich.',
    'I\'m a descendant of the king\'s younger brother. That being said, that story is 3,000 years old, so it might not be entirely reliable.': 'Ich bin ein Nachfahre des jüngeren Bruders des Königs. Allerdings ist diese Geschichte 3,000 Jahre alt, also ist sie vielleicht nicht ganz zuverlässig.',
    'People can be divided into two groups. Those who give... And those who take... It\'s just as how the Kalos region\'s two Legendary Pokémon gave life and took life.': 'Menschen lassen sich in zwei Gruppen einteilen. Jene, die geben ... und jene, die nehmen ... Genau wie die beiden legendären Pokémon der Kalos-Region Leben gaben und Leben nahmen.',
    'I want to be the kind of person who gives... But in this world, some foolish humans exist who would show their strength by taking what isn\'t theirs. They\'re filth!': 'Ich möchte zu denen gehören, die geben ... Doch auf dieser Welt gibt es törichte Menschen, die ihre Stärke zeigen, indem sie nehmen, was ihnen nicht gehört. Sie sind Abschaum!',
    'Long, long ago, the king of Kalos sought to take everything for his own, and he created a terrible weapon. Then the fire of destruction was unleashed... That is the legend that has been passed down.': 'Vor langer, langer Zeit wollte der König von Kalos alles für sich allein und erschuf eine schreckliche Waffe. Dann wurde das Feuer der Zerstörung entfesselt ... So lautet die Legende, die überliefert wurde.',
    'Kalos is beautiful right now! There will be no foolish actions if the number of people and Pokémon do not increase. That being said, the future isn\'t decided. You can\'t be sure each day will be like the one before.': 'Kalos ist gerade wunderschön! Es wird keine törichten Taten geben, wenn die Zahl der Menschen und Pokémon nicht wächst. Allerdings ist die Zukunft nicht entschieden. Man kann nie sicher sein, dass jeder Tag wie der vorherige sein wird.',
    'What the king of Kalos did was reprehensible, but... The ultimate weapon did manage to wash the world clean of that era\'s filth. Thank you for listening.': 'Was der König von Kalos tat, war verwerflich, aber ... Die ultimative Waffe hat die Welt immerhin vom Abschaum jener Zeit reingewaschen. Danke, dass du mir zugehört hast.',
    'Welcome. I guess you found my secret labs, inside my own café. The world was just too vast...and too full of fools that I couldn\'t save through my hard work alone...': 'Willkommen. Du hast also meine geheimen Labore gefunden, in meinem eigenen Café. Die Welt war einfach zu groß ... und zu voller Narren, als dass ich sie allein durch harte Arbeit hätte retten können ...',
    'That\'s why I decided the only way to save the world was to take it all for myself. I don\'t expect that I will ever make you understand how I think and feel...': 'Darum habe ich beschlossen, dass der einzige Weg, die Welt zu retten, darin besteht, sie ganz für mich zu nehmen. Ich erwarte nicht, dass du je verstehen wirst, wie ich denke und fühle ...',
    'Try to stop the ultimate weapon if you must. Saving everything... The world is suffering because of this absurd dream...': 'Versuch die ultimative Waffe aufzuhalten, wenn es sein muss. Alles retten ... Die Welt leidet wegen dieses absurden Traums ...',
    'Listen, trainer who will face Lysandre. A terribly long time ago... There was a man and a Pokémon. A war began. The man\'s beloved Pokémon took part in the war.': 'Hör zu, Trainer, der sich Flordelis stellen wird. Vor schrecklich langer Zeit ... gab es einen Mann und ein Pokémon. Ein Krieg brach aus. Das geliebte Pokémon des Mannes nahm am Krieg teil.',
    'The Pokémon died. The man wanted to bring the Pokémon back. No matter what it took. The man built a machine to give it life and succeeded.': 'Das Pokémon starb. Der Mann wollte das Pokémon zurückholen. Koste es, was es wolle. Der Mann baute eine Maschine, um ihm Leben zu schenken, und es gelang ihm.',
    'The lives of many Pokémon were taken to restore its life. The resurrected Pokémon left the man.': 'Die Leben vieler Pokémon wurden genommen, um sein Leben wiederherzustellen. Das wiederbelebte Pokémon verließ den Mann.',
    'The man had suffered too much. His rage had not subsided. He turned the machine into the ultimate weapon. The man became a bringer of destruction that ended the war.': 'Der Mann hatte zu sehr gelitten. Seine Wut ließ nicht nach. Er verwandelte die Maschine in die ultimative Waffe. Der Mann wurde zum Bringer der Zerstörung, der den Krieg beendete.',
    'You pressed it! Oh ho ho! You pressed the blue switch! Winner, winner! Congratulations!': 'Du hast ihn gedrückt! Ohoho! Du hast den blauen Schalter gedrückt! Gewonnen, gewonnen! Herzlichen Glückwunsch!',
    'But I\'m still going to activate the ultimate weapon! I\'ll just use my remote, here! Click-click! And the power is ON!': 'Aber ich werde die ultimative Waffe trotzdem aktivieren! Ich nehme einfach meine Fernbedienung hier! Klick-klick! Und der Strom ist AN!',
    'The ultimate weapon is reborn! The poisonous flower has bloomed! All shall perish! Except for Team Flare! Look at Geosenge! It has bloomed in Geosenge Town!': 'Die ultimative Waffe ist wiedergeboren! Die giftige Blume ist erblüht! Alle werden vergehen! Außer Team Flare! Sieh nach Geosenge! Sie ist in Geosenge Town erblüht!',
    'The boss\'s dream of creating a beautiful world will come true! Add it all up, and it equals... a victory for our SCIENCE!': 'Der Traum des Bosses von einer schönen Welt wird wahr! Rechnet man alles zusammen, ergibt das ... einen Sieg für unsere WISSENSCHAFT!',
    'You pushed it! Oh ho ho! You pushed the little red button! Too bad...for you!': 'Du hast ihn gedrückt! Ohoho! Du hast den kleinen roten Knopf gedrückt! Pech gehabt ... für dich!',
    'Pushing that button has enabled us to use the ultimate weapon! Don\'t feel too down, though. I would have activated it even if you had guessed correctly.': 'Durch das Drücken dieses Knopfes können wir die ultimative Waffe einsetzen! Sei aber nicht zu niedergeschlagen. Ich hätte sie auch aktiviert, wenn du richtig geraten hättest.',
    'Floette... It\'s been 3,000 years...': '[[pokemon::Floette]] ... Es ist 3,000 Jahre her ...',
    'And with you... another of your kind?': 'Und mit dir ... noch eines deiner Art?',
    'Ah... it seems to be interested in you, $playername$. Would you like to take it with you?': 'Ah ... es scheint sich für dich zu interessieren, $playername$. Möchtest du es mitnehmen?',
    'Ah, isn\'t Flabébé such an eye-catching Pokémon? All these different lovely colors…': 'Ach, ist [[pokemon::Flabébé]] nicht ein echter Hingucker? All diese verschiedenen hübschen Farben ...',
    'If you\'re searching for the yellow and blue kinds, look no further than the Farm!': 'Wenn du die gelbe und die blaue Sorte suchst, musst du nicht weiter als bis zur Farm schauen!',
    'They simply can\'t resist berries that match their colors - just plant a few and they\'ll soon come wandering in.': 'Beeren in ihren Farben können sie einfach nicht widerstehen - pflanz ein paar an, und schon bald kommen sie angewandert.',
    'I must find one! I simply must!': 'Ich muss eins finden! Ich muss einfach!',
    'I sent my husband to buy tickets for the aquarium but it was all a ploy to get some alone time so I can find him a Pokémon fossil found only here in Kalos!': 'Ich habe meinen Mann losgeschickt, um Karten für das Aquarium zu kaufen, aber das war nur ein Trick, damit ich etwas Zeit für mich habe und ihm ein Pokémon-Fossil suchen kann, das man nur hier in Kalos findet!',
    'According to my brochure, there\'s a pretty cave past these cliffs that\'s filled with them! It says reviving a Jaw Fossil can give you a Tyrunt, the perfect anniversary gift for my sweetie pie!': 'Laut meiner Broschüre gibt es hinter diesen Klippen eine hübsche Höhle, die voll davon ist! Darin steht, dass man aus einem Kieferfossil ein [[pokemon::Tyrunt]] wiederbeleben kann, das perfekte Jahrestagsgeschenk für meinen Schnuckel!',
    'I WILL find a Jaw Fossil! Nothing will get in the way of seeing my booboo\'s smile! Anything is possible with the power of love! And don\'t you forget that either!': 'Ich WERDE ein Kieferfossil finden! Nichts wird mich davon abhalten, das Lächeln meines Schatzis zu sehen! Mit der Kraft der Liebe ist alles möglich! Und vergiss das bloß nicht!',
    'Oh, you\'ve found all the fossil Pokémon native to Kalos! We tried too, but our search ended in failure. No, that\'s not entirely true...!': 'Oh, du hast alle in Kalos heimischen Fossil-Pokémon gefunden! Wir haben es auch versucht, aber unsere Suche ist gescheitert. Nein, das stimmt nicht ganz ...!',
    'We may not have found those fossils, but our real goal was making each other smile! No Pokémon can compare to the feeling of catching your loved one in the same secret act as you! To think we split up to surprise each other with a fossil when the real present is the time we spend together!': 'Wir haben diese Fossilien zwar nicht gefunden, aber unser eigentliches Ziel war es, einander zum Lächeln zu bringen! Kein Pokémon kommt an das Gefühl heran, den geliebten Menschen bei derselben heimlichen Tat zu ertappen wie man selbst! Da haben wir uns getrennt, um uns gegenseitig mit einem Fossil zu überraschen, dabei ist das wahre Geschenk die Zeit, die wir zusammen verbringen!',
    'Safe travels, Trainer! And may the blessing of love follow you!': 'Gute Reise, Trainer! Und möge der Segen der Liebe dich begleiten!',
    'Oh $playername$, you made it here. I wanted to learn about fossils so I went to the fossil lab, but the head scientist is not here.': 'Oh $playername$, du hast es hierher geschafft. Ich wollte etwas über Fossilien lernen und bin deshalb zum Fossillabor gegangen, aber der leitende Wissenschaftler ist nicht da.',
    'I heard he\'s in Glittering Cave but I also saw some weird guys in orange going there. Will you come with me and check it out?': 'Ich habe gehört, er ist in der Glittering Cave, aber ich habe auch ein paar seltsame Typen in Orange dorthin gehen sehen. Kommst du mit und siehst es dir mit mir an?',
    'You see that beautiful gemstone in Grant\'s gym? There is no mistake, that is a genuine Mega Stone!': 'Siehst du diesen wunderschönen Edelstein in Linos Arena? Kein Zweifel, das ist ein echter Mega-Stein!',
    'Oh, what I would pay to add it to my collection! But money is of no help here. I bet Grant would be willing to part with it if I challenge him enough times and prove my skills to him.': 'Oh, was würde ich dafür zahlen, ihn meiner Sammlung hinzuzufügen! Aber Geld hilft hier nicht weiter. Ich wette, Lino würde sich davon trennen, wenn ich ihn oft genug herausfordere und ihm mein Können beweise.',
    'Unfortunately my skills as a collector far surpass my skills as a Pokémon trainer. But anyone who can become the Champion of Kalos surely can convince Grant that this stone will be in good hands.': 'Leider übertreffen meine Fähigkeiten als Sammler meine Fähigkeiten als Pokémon-Trainer bei Weitem. Aber wer Champ von Kalos werden kann, kann Lino bestimmt davon überzeugen, dass dieser Stein in guten Händen sein wird.',
    'Hey uh.... twerp. Would you happen to have any Dungeon Tokens? We\'ve, uh, run out.': 'Hey, äh ... Knirps. Hast du zufällig ein paar Dungeon-Token? Uns sind, äh, die ausgegangen.',
    'I\'ll give you that Pikachu costume my Inkay was wearing for some?': 'Ich gebe dir dafür das [[pokemon::Pikachu]]-Kostüm, das mein [[pokemon::Inkay]] getragen hat?',
    '...Give me a break. I know that you knew that the Pikachu was a costume. You could see right through us, as if you could just see its name over its head or something.': '... Jetzt mach mal halblang. Ich weiß, dass du wusstest, dass das [[pokemon::Pikachu]] ein Kostüm war. Du hast uns komplett durchschaut, als könntest du einfach seinen Namen über seinem Kopf sehen oder so.',
    'Stop right there! I remember you! You\'re the one who foiled our fossil-finding plans!': 'Halt, stehen bleiben! Ich erinnere mich an dich! Du bist doch der, der unsere Fossilsuche vereitelt hat!',
    'And now you\'re here, standing around these stones. Do you have any idea what they even are?': 'Und jetzt stehst du hier zwischen diesen Steinen herum. Hast du überhaupt eine Ahnung, was das ist?',
    'Of course you don\'t! You know nothing about the legend of 3000 years ago that says...': 'Natürlich nicht! Du weißt nichts über die Legende von vor 3000 Jahren, die besagt ...',
    'Oh, whatever! Who cares about all of that? It\'s time for me to get some sweet revenge... with style!': 'Ach, egal! Wen kümmert das schon? Zeit für meine süße Rache ... mit Stil!',
    'I met just the nicest people the other day.': 'Ich habe neulich die nettesten Leute kennengelernt.',
    'A young couple and their Pikachu set up a little shop to the west, and their customer service was just exquisite!': 'Ein junges Paar und sein [[pokemon::Pikachu]] haben im Westen einen kleinen Laden eröffnet, und ihr Kundenservice war einfach exquisit!',
    '...Mind you, though. Their Pikachu looked a little unhealthy. When I asked them about it though, they just claimed he was Alolan.': '... Aber wohlgemerkt: Ihr [[pokemon::Pikachu]] sah etwas kränklich aus. Als ich sie darauf ansprach, behaupteten sie nur, es käme aus Alola.',
    'I guess that makes sense, it would also explain why it was floating.': 'Das ergibt wohl Sinn, es würde auch erklären, warum es geschwebt ist.',
    'What\'s that? Alolan Pikachu don\'t exist? Are you sure? Well, if you say so. I guess whatever that poor Pikachu has is serious then.': 'Wie bitte? Alola-[[pokemon::Pikachu]] gibt es nicht? Bist du sicher? Na, wenn du das sagst. Dann ist das, was dieses arme [[pokemon::Pikachu]] hat, wohl etwas Ernstes.',
    'What an explosive battle! I could tell that you didn\'t hold anything back!': 'Was für ein explosiver Kampf! Ich habe gemerkt, dass du dich kein bisschen zurückgehalten hast!',
    'To Mega Evolve your Lucario, you need an even stronger bond!': 'Um dein [[pokemon::Lucario]] mega-entwickeln zu können, brauchst du eine noch stärkere Bindung!',
    'You can follow your progress in your Pokédex.': 'Deinen Fortschritt kannst du in deinem Pokédex verfolgen.',
    'When your bond is strong enough, you can Mega Evolve it using a Key Stone! You can buy them in this city!': 'Wenn eure Bindung stark genug ist, kannst du es mit einem Schlüsselstein mega-entwickeln! Die kannst du hier in der Stadt kaufen!',
    '<i>Aegislash wants to join you on your adventure.</i>': '<i>[[pokemon::Aegislash]] möchte dich auf deinem Abenteuer begleiten.</i>',
    'Thank you for your help saving the Diamond Domain. I will be waiting for you in Reflection Cave.': 'Danke für deine Hilfe bei der Rettung des Diamond Domain. Ich warte in der Reflection Cave auf dich.',
    'There are many threats in this world, and I think we will both be safer if we work together!': 'Es gibt viele Bedrohungen auf dieser Welt, und ich glaube, wir sind beide sicherer, wenn wir zusammenarbeiten!',
    'I\'ve heard there is a cave you can find if you go out on the ocean a little ways.': 'Ich habe gehört, es gibt eine Höhle, die man findet, wenn man ein Stückchen aufs Meer hinausfährt.',
    'Apparently defeating a strong creature there unleashes some energy.': 'Angeblich setzt es Energie frei, wenn man dort ein starkes Wesen besiegt.',
    'There are rumors that the energy calls some legendary birds to roam Kalos!': 'Gerüchten zufolge lockt diese Energie einige legendäre Vögel an, die dann durch Kalos streifen!',
    'My Ampharos has gotten a boost since a friendly soul gave me an Ampharosite!': 'Mein [[pokemon::Ampharos]] hat einen Schub bekommen, seit mir eine freundliche Seele ein Ampharosinit geschenkt hat!',
    'Luckily my Ampharos was already strong enough to use it!': 'Zum Glück war mein [[pokemon::Ampharos]] schon stark genug, um es zu nutzen!',
    'If you find that fella, tell him the code <code class="text-nowrap">DO-MAGEARNA-DREAM-OF-MAREEP?</code> and he might help you too!': 'Wenn du diesen Kerl findest, nenn ihm den Code <code class="text-nowrap">DO-MAGEARNA-DREAM-OF-MAREEP?</code>, dann hilft er dir vielleicht auch!',
    'Bonds... They really are important to us all, aren\'t they? When I\'m acting, I think I\'m always trying to forge a bond between myself and the character I\'m playing.': 'Bindungen ... Sie sind für uns alle wirklich wichtig, nicht wahr? Wenn ich schauspielere, versuche ich, glaube ich, immer eine Bindung zwischen mir und der Figur aufzubauen, die ich spiele.',
    'If all I think about is how I\'m nothing like a character, then I\'ll just hate playing it.': 'Wenn ich nur daran denke, wie wenig ich einer Figur ähnle, dann werde ich es hassen, sie zu spielen.',
    'But if I focus on what I have in common with the character and put myself in her shoes, I might be able to understand her. It\'s the same for people, or Pokémon.': 'Aber wenn ich mich auf das konzentriere, was ich mit der Figur gemeinsam habe, und mich in sie hineinversetze, kann ich sie vielleicht verstehen. Bei Menschen und Pokémon ist es genauso.',
    'Oh, never mind me! I\'m just babbling about my own things. Let\'s have a battle the next we meet, shall we? I\'m looking forward to it!': 'Oh, beachte mich gar nicht! Ich plappere nur über meine eigenen Sachen. Lass uns kämpfen, wenn wir uns das nächste Mal treffen, ja? Ich freue mich darauf!',
    'Professor Sycamore told me how much stronger you\'ve become.': 'Professor Platan hat mir erzählt, wie viel stärker du geworden bist.',
    'That is truly wonderful. With that power, you can steer your future in a better direction!': 'Das ist wahrlich wunderbar. Mit dieser Kraft kannst du deine Zukunft in eine bessere Richtung lenken!',
    'We can\'t just cover up the old filth with new filth!': 'Wir können den alten Schmutz nicht einfach mit neuem Schmutz überdecken!',
    'I implore you to consider what we need to do to change the world into a new, beautiful world!': 'Ich bitte dich inständig, darüber nachzudenken, was wir tun müssen, um die Welt in eine neue, schöne Welt zu verwandeln!',
    'Don\'t you find Goomy to be an interesting Pokémon? I certainly think so, even though it isn\'t a problem for my Pokémon~': 'Findest du [[pokemon::Goomy]] nicht auch ein interessantes Pokémon? Ich jedenfalls schon, auch wenn es für meine Pokémon kein Problem darstellt~',
    'I\'ve heard its evolutionary line loves damp conditions, and apparently if you train a Sliggoo during rainy or foggy weather something marvelous happens!': 'Ich habe gehört, seine Entwicklungsreihe liebt feuchte Bedingungen, und wenn man ein [[pokemon::Sliggoo]] bei Regen oder Nebel trainiert, soll etwas Wundervolles geschehen!',
    'I\'m shocked... You have a Pokédex, but you still don\'t know... you really don\'t know anything about Pokémon connected to Gengar, do you?': 'Ich bin schockiert ... Du hast einen Pokédex, aber du weißt immer noch nicht ... du weißt wirklich gar nichts über Pokémon, die mit [[pokemon::Gengar]] verbunden sind, oder?',
    'Well then, I guess I\'ll just have to keep this wonderful item I was going to give you...': 'Na dann muss ich wohl dieses wundervolle Item behalten, das ich dir geben wollte ...',
    'If you want to change my mind... you will have to encounter at least 666 wild Gastly, 444 wild Haunter, and 13 wild Gengar.': 'Wenn du mich umstimmen willst ... musst du mindestens 666 wilden [[pokemon::Gastly]], 444 wilden [[pokemon::Haunter]] und 13 wilden [[pokemon::Gengar]] begegnen.',
    'And do bring a Gengar of your own, won\'t you?': 'Und bring doch bitte ein eigenes [[pokemon::Gengar]] mit, ja?',
    'Some Pokémon evolve when exposed to a Linking Cord, or sent through a trade.': 'Manche Pokémon entwickeln sich, wenn sie einem Linkkabel ausgesetzt oder getauscht werden.',
    'That\'s right. Haunter is one of those Pokemon.': 'Genau. [[pokemon::Haunter]] ist eines dieser Pokémon.',
    'I don\'t have enough Quest Points to buy a Linking Cord, but a girl named Mindy from Snowpoint City offered to trade me her Haunter for a Medicham.': 'Ich habe nicht genug Questpunkte, um ein Linkkabel zu kaufen, aber ein Mädchen namens Mindy aus Snowpoint City hat mir angeboten, mir ihr [[pokemon::Haunter]] gegen ein [[pokemon::Medicham]] zu tauschen.',
    'Hopefully I\'ll have a Gengar soon...': 'Hoffentlich habe ich bald ein [[pokemon::Gengar]] ...',
    'My partner Medicham and I are always training to become the strongest in the world.': 'Mein Partner [[pokemon::Medicham]] und ich trainieren ständig, um die Stärksten der Welt zu werden.',
    'Our favorite way to train is by doing quests. Someday my Medicham even found a Mega Stone while claiming some.': 'Am liebsten trainieren wir, indem wir Quests erledigen. Einmal hat mein [[pokemon::Medicham]] sogar einen Mega-Stein gefunden, als wir einige abgeschlossen haben.',
    'I can\'t quite remember what Quest Level we were at, but it was probably 16 or higher.': 'Ich weiß nicht mehr genau, welches Quest-Level wir hatten, aber es war wohl 16 oder höher.',
    'I adore wolf Pokémon! The most precious of all have to be the brave little Electrike - I\'ve gathered five hundred of the darlings in my home.': 'Ich liebe Wolf-Pokémon! Die süßesten von allen sind die tapferen kleinen [[pokemon::Electrike]] - ich habe fünfhundert dieser Schätzchen bei mir zu Hause.',
    'They\'re so loyal, and so fast! I give them letters to take to a friend in Galar in the morning, and I have a response back by supper!': 'Sie sind so treu und so schnell! Morgens gebe ich ihnen Briefe für eine Freundin in Galar mit, und bis zum Abendessen habe ich eine Antwort!',
    'But now that I have so many of them, their behaviour has taken a... regrettable turn.': 'Aber jetzt, wo ich so viele von ihnen habe, hat ihr Verhalten eine ... bedauerliche Wendung genommen.',
    'When storms come along the horizon, they\'ll run en masse out to Route 16.': 'Wenn am Horizont Gewitter aufziehen, rennen sie in Scharen hinaus auf Route 16.',
    'They fortunately do return home when the weather changes, at least. I wonder what sort of creature is calling them? A strong Pokémon, perhaps?': 'Zum Glück kommen sie wenigstens nach Hause zurück, wenn das Wetter umschlägt. Ich frage mich, was für ein Wesen sie wohl ruft? Vielleicht ein starkes Pokémon?',
    'I\'ve been debating asking someone else to collect five hundred of their own Electrike and investigate, but if it can call such a fearsome pack with its presence alone, I don\'t imagine anyone less than Diantha herself could handle it.': 'Ich überlege, ob ich jemand anderen bitten soll, fünfhundert eigene [[pokemon::Electrike]] zu sammeln und der Sache nachzugehen. Aber wenn es allein durch seine Anwesenheit ein so furchteinflößendes Rudel rufen kann, könnte wohl niemand Geringeres als Diantha selbst damit fertigwerden.',
    'Dog Pokémon are the best of all! I\'m particularly fond of Houndour - I\'ve caught about five hundred of them.': 'Hunde-Pokémon sind die allerbesten! Ich mag besonders [[pokemon::Houndour]] - ich habe ungefähr fünfhundert davon gefangen.',
    'There\'s no such thing as a cold night in my house, no sir! The most fierce chill of winter is completely defeated by their warm, cozy presence.': 'In meinem Haus gibt es keine kalten Nächte, o nein! Selbst die bitterste Winterkälte wird von ihrer warmen, gemütlichen Gegenwart völlig besiegt.',
    'But recently, now that I\'ve got so many Houndour, they have been acting rather curiously.': 'Aber in letzter Zeit, seit ich so viele [[pokemon::Houndour]] habe, benehmen sie sich ziemlich merkwürdig.',
    'When the weather turns really sunny, they\'ll all run barking out onto Route 16. Honestly, it\'s quite a racket, and has gotten me into no small amount of trouble.': 'Wenn das Wetter richtig sonnig wird, rennen sie alle bellend hinaus auf Route 16. Ehrlich gesagt ist das ein ziemlicher Lärm und hat mir schon so manchen Ärger eingebracht.',
    'They come wandering back when the weather changes, though. I wonder if a strong Pokémon is calling them?': 'Wenn das Wetter umschlägt, kommen sie allerdings zurück. Ich frage mich, ob ein starkes Pokémon sie ruft?',
    'You could build your own Houndour pack and find out, but if it\'s strong enough to call five hundred Pokémon, it probably wouldn\'t give anyone weaker than Diantha the time of day.': 'Du könntest dein eigenes [[pokemon::Houndour]]-Rudel aufbauen und es herausfinden, aber wenn es stark genug ist, fünfhundert Pokémon zu rufen, würde es wohl niemanden beachten, der schwächer als Diantha ist.',
    'Hello $playername$! Do you remember the Pokémon Lysandre mentioned in that café? Kalos\'s Legendary Pokémon are called... Xerneas and Yveltal!': 'Hallo $playername$! Erinnerst du dich an das Pokémon, das Flordelis in diesem Café erwähnt hat? Die legendären Pokémon von Kalos heißen ... [[pokemon::Xerneas]] und [[pokemon::Yveltal]]!',
    'Apparently, these Pokémon can control energy or absorb energy, respectively. Xerneas gives life energy to plants and Pokémon, whereas Yveltal steals all of the spirits around it.': 'Offenbar können diese Pokémon Energie spenden beziehungsweise Energie absorbieren. [[pokemon::Xerneas]] schenkt Pflanzen und Pokémon Lebensenergie, während [[pokemon::Yveltal]] allen Lebewesen in seiner Umgebung die Seele raubt.',
    'When they lose all of their vitality, they go to sleep in a secret place. It would be absolutely astounding if you found it!': 'Wenn sie ihre gesamte Lebenskraft verlieren, schlafen sie an einem geheimen Ort ein. Es wäre absolut erstaunlich, wenn du ihn finden würdest!',
    'By the way, I heard Frost Cavern has a lot of cool Pokémon, why don\'t you go check it out?': 'Übrigens habe ich gehört, dass es in der Frost Cavern viele coole Pokémon gibt. Warum siehst du nicht mal nach?',
    'The spirits tell me roaming Pokémon have been spotted on {ROUTE_NAME}!': 'Die Geister sagen mir, dass auf {ROUTE_NAME} umherstreifende Pokémon gesichtet wurden!',
    'Pokémon Trainers. I come to you to make an important announcement. Listen well.': 'Pokémon-Trainer. Ich wende mich mit einer wichtigen Ankündigung an euch. Hört gut zu.',
    'Team Flare will revive the ultimate weapon, eliminate everyone who isn\'t in our group, and return the world to a beautiful, natural state.': 'Team Flare wird die ultimative Waffe wiederbeleben, jeden auslöschen, der nicht zu unserer Gruppe gehört, und die Welt in einen schönen, natürlichen Zustand zurückversetzen.',
    'Unproductive fools are consuming our future... If nothing changes, the world will become ugly and conflicts will raze the land from end to end.': 'Unproduktive Narren verschlingen unsere Zukunft ... Wenn sich nichts ändert, wird die Welt hässlich werden und Konflikte werden das Land von einem Ende zum anderen verwüsten.',
    'I repeat. We will use the ultimate weapon and wipe the slate clean. I\'m sorry, those of you who are not members of Team Flare, but this is adieu to you all.': 'Ich wiederhole. Wir werden die ultimative Waffe einsetzen und reinen Tisch machen. Es tut mir leid für alle, die keine Mitglieder von Team Flare sind, aber dies ist euer Adieu.',
    'I love going on walks at <b>dusk</b>. It\'s my favourite part of the day, everything\'s so calm...': 'Ich gehe so gern in der <b>Abenddämmerung</b> spazieren. Das ist meine liebste Tageszeit, alles ist so ruhig ...',
    'Though lately, I\'ve been hearing roars near the waterfalls, but I\'m too scared to see for myself what kind of monster is making those sounds.': 'Allerdings höre ich in letzter Zeit ein Brüllen in der Nähe der Wasserfälle, aber ich habe zu viel Angst, selbst nachzusehen, was für ein Ungeheuer diese Geräusche macht.',
    'I would ask you to go, but I\'m sure you\'re really busy either dealing with Team Flare or the Pokémon League challenge.': 'Ich würde dich ja bitten hinzugehen, aber du bist sicher sehr beschäftigt, entweder mit Team Flare oder mit der Herausforderung der Pokémon-Liga.',
    'Once you are done, you could come back at dusk. Maybe you can do something about it...': 'Wenn du damit fertig bist, könntest du in der Abenddämmerung zurückkommen. Vielleicht kannst du etwas dagegen unternehmen ...',
    'Whoa! What the- Where am I? How did I get here? Last thing I can remember I was in Reflection Cave when this little Pokémon with hoops threw something at me… Oh you’ve beaten the Pokémon League? Maybe you can find it roaming around the region so you can tame that little prankster. Now how am I gonna get home…': 'Wow! Was zum- Wo bin ich? Wie bin ich hierhergekommen? Das Letzte, woran ich mich erinnere, ist, dass ich in der Reflection Cave war, als dieses kleine Pokémon mit Ringen etwas nach mir geworfen hat ... Oh, du hast die Pokémon-Liga besiegt? Vielleicht findest du es irgendwo in der Region herumstreifen und kannst diesen kleinen Witzbold zähmen. Und wie komme ich jetzt nach Hause ...',
    'Hello, $playername$! My name is Baraz, and my people have a complicated history with Hoopa.': 'Hallo, $playername$! Ich heiße Baraz, und mein Volk hat eine komplizierte Geschichte mit [[pokemon::Hoopa]].',
    'I have come to this region to search for a Prison Bottle, in which the spirit of a powerful Hoopa is bound.': 'Ich bin in diese Region gekommen, um nach einer Bannflasche zu suchen, in der der Geist eines mächtigen [[pokemon::Hoopa]] gebannt ist.',
    'Can you help with my search? My search indicates it is nearby, maybe one of the local Psychic Pokémon has it?': 'Kannst du mir bei meiner Suche helfen? Meinen Nachforschungen zufolge ist sie in der Nähe, vielleicht hat sie eines der hiesigen Psycho-Pokémon?',
    '$playername$! No luck?': '$playername$! Kein Glück?',
    'Maybe beating the Pokémon isn\'t enough. Try catching some of these Psychic Pokémon.': 'Vielleicht reicht es nicht, die Pokémon zu besiegen. Versuch, einige dieser Psycho-Pokémon zu fangen.',
    'There\'s only one Pokémon who could keep the Prison Bottle from us for so long: Hoopa!': 'Es gibt nur ein Pokémon, das uns die Bannflasche so lange vorenthalten konnte: [[pokemon::Hoopa]]!',
    'You\'ll have to catch a ton before you find the Prison Bottle. Maybe... 100?': 'Du wirst jede Menge fangen müssen, bevor du die Bannflasche findest. Vielleicht ... 100?',
    'Wow, you caught 100 that fast?': 'Wow, du hast so schnell 100 gefangen?',
    'No? There\'s no other way, I\'m sorry...': 'Nein? Es gibt keinen anderen Weg, tut mir leid ...',
    '<i>While Baraz is talking, a hoop appears behind him and the Prison Bottle falls out.</i>': '<i>Während Baraz spricht, erscheint hinter ihm ein Ring, und die Bannflasche fällt heraus.</i>',
    'Aha! There it is!': 'Aha! Da ist sie!',
    '<i>Baraz grabs the Prison Bottle, and an eerie glow surrounds him. A massive Pokémon picks him up and flies away into a nearby hoop.</i>': '<i>Baraz greift nach der Bannflasche, und ein unheimliches Leuchten umgibt ihn. Ein riesiges Pokémon packt ihn und fliegt mit ihm in einen nahen Ring davon.</i>',
    'Welcome to the Friend Safari!': 'Willkommen in der Friend Safari!',
    'This place is a lot like the Kanto Safari Zone, except we get a much wider variety of Pokémon coming through here.': 'Dieser Ort ähnelt stark der Safari Zone in Kanto, nur dass hier eine viel größere Vielfalt an Pokémon vorbeikommt.',
    'Our park staff stocks the Safari with different hard-to-find Pokémon every day. Many of these Pokémon can\'t be caught anywhere else in the world!': 'Unser Parkpersonal bestückt die Safari jeden Tag mit anderen schwer zu findenden Pokémon. Viele dieser Pokémon kann man nirgendwo sonst auf der Welt fangen!',
    'As new and rare types of Pokémon are discovered, park staff will add them to our rotation of potential stock!': 'Sobald neue und seltene Pokémon entdeckt werden, nimmt das Parkpersonal sie in unser wechselndes Angebot auf!',
    'I heard there was a stone hidden in the Friend Safari that makes Scizor stronger!': 'Ich habe gehört, in der Friend Safari sei ein Stein versteckt, der [[pokemon::Scizor]] stärker macht!',
    'It takes a very experienced trainer to find it, though.': 'Allerdings braucht man einen sehr erfahrenen Trainer, um ihn zu finden.',
    'I have to find one! I just have to!': 'Ich muss eins finden! Ich muss einfach!',
    'I told my wife I was going buy tickets for the aquarium in the town back there but little did she know it was a white lie so I could search for a Pokémon fossil found only here in Kalos!': 'Ich habe meiner Frau gesagt, ich kaufe Karten für das Aquarium in der Stadt dort hinten, aber sie weiß nicht, dass das eine Notlüge war, damit ich nach einem Pokémon-Fossil suchen kann, das man nur hier in Kalos findet!',
    'According to my travel guide, this cave is filled with them! It says reviving a Sail Fossil can nab you an Amaura, the perfect anniversary gift for my pumpkin!': 'Laut meinem Reiseführer ist diese Höhle voll davon! Darin steht, dass man aus einem Flossenfossil ein [[pokemon::Amaura]] wiederbeleben kann, das perfekte Jahrestagsgeschenk für mein Schätzchen!',
    'I MUST find a Sail Fossil! Nothing will get in the way of making my sunshine happy! She\'s taught me that anything is possible with the power of love!': 'Ich MUSS ein Flossenfossil finden! Nichts wird mich davon abhalten, meinen Sonnenschein glücklich zu machen! Sie hat mir beigebracht, dass mit der Kraft der Liebe alles möglich ist!',
    'Why, hello! Here to look for fossils as well?': 'Na, hallo! Bist du auch hier, um nach Fossilien zu suchen?',
    'What did you say? Teemphlair was here? What\'s that? A Pokémon?': 'Was hast du gesagt? Teemphlair war hier? Was ist das? Ein Pokémon?',
    'You are very lucky! I just now found a fossil! But it\'s one I already have, so I\'ll give it to you!': 'Du hast großes Glück! Ich habe gerade eben ein Fossil gefunden! Aber das habe ich schon, also gebe ich es dir!',
    'Well, I\'m going back to the lab, goodbye!': 'Nun, ich gehe zurück ins Labor. Auf Wiedersehen!',
    'I\'ve heard that a hidden realm lies beneath this cave, ruled by a Pokémon Princess. She might come out for a powerful and helpful trainer.': 'Ich habe gehört, dass unter dieser Höhle ein verborgenes Reich liegt, das von einer Pokémon-Prinzessin regiert wird. Vielleicht zeigt sie sich einem starken und hilfsbereiten Trainer.',
    'That would be big news, sure to be reported on local bulletin boards!': 'Das wären große Neuigkeiten, über die bestimmt an den örtlichen Schwarzen Brettern berichtet würde!',
    'You saved us! Thank you so much! You\'re an astounding Pokémon Trainer.': 'Du hast uns gerettet! Vielen, vielen Dank! Du bist ein erstaunlicher Pokémon-Trainer.',
    'Very well, then. I want to show my appreciation. I\'ll give you a Master Ball.': 'Nun gut. Ich möchte mich erkenntlich zeigen. Ich gebe dir einen Meisterball.',
    'I have a feeling you will put it to great use. You\'re different from those Team Flare people.': 'Ich habe das Gefühl, dass du ihn sinnvoll einsetzen wirst. Du bist anders als diese Leute von Team Flare.',
    'What were they planning to accomplish by taking all the Poké Balls for themselves...': 'Was wollten die bloß damit erreichen, alle Pokébälle für sich selbst zu stehlen ...',
    'The ultimate weapon\'s flower has finally bloomed above the soil. Don\'t you find its beauty captivating? As we speak, it draws its energy from the Legendary Pokémon.': 'Die Blüte der ultimativen Waffe hat sich endlich über dem Erdboden geöffnet. Findest du ihre Schönheit nicht auch fesselnd? In diesem Augenblick bezieht sie ihre Energie aus dem legendären Pokémon.',
    'Even though resources, space, and energy on this planet are limited, the number of people and Pokémon has increased to an unsustainable level. Whether it\'s money or energy, the ones who steal are the ones who win in this world.': 'Obwohl Ressourcen, Raum und Energie auf diesem Planeten begrenzt sind, ist die Zahl der Menschen und Pokémon auf ein untragbares Maß angewachsen. Ob Geld oder Energie – in dieser Welt gewinnen diejenigen, die stehlen.',
    'Pokémon... Shall no longer exist. Pokémon are wonderful beings. Humans have worked with Pokémon, and we have helped each other flourish. But precisely because of that, they will inevitably become tools for war and theft!': 'Pokémon ... werden nicht länger existieren. Pokémon sind wundervolle Wesen. Menschen haben mit Pokémon zusammengearbeitet und wir haben einander geholfen, zu gedeihen. Doch genau deshalb werden sie unweigerlich zu Werkzeugen für Krieg und Diebstahl!',
    'You\'re as strong as ever. But... It\'s too late! There\'s no hope for you now! Go down to the lowest floor, and see for yourself!': 'Du bist so stark wie eh und je. Aber ... Es ist zu spät! Es gibt keine Hoffnung mehr für dich! Geh hinunter ins unterste Stockwerk und sieh selbst!',
    'What a startling development! I never would\'ve thought you were really a chosen one!': 'Was für eine verblüffende Wendung! Ich hätte nie gedacht, dass du wirklich ein Auserwählter bist!',
    'So THESE were the mighty Xerneas and Yveltal?! I expected more from Pokémon called legend! You desire help from people? YOU need help from a human?': 'DAS also sollen das mächtige [[pokemon::Xerneas]] und [[pokemon::Yveltal]] sein?! Von Pokémon, die man Legenden nennt, hätte ich mehr erwartet! Du suchst Hilfe bei Menschen? DU brauchst die Hilfe eines Menschen?',
    'For me, victory is using the ultimate weapon. In order to do that, I need to reclaim the Legendary Pokémon\'s power and send that power to that weapon once again.': 'Für mich bedeutet Sieg, die ultimative Waffe einzusetzen. Dafür muss ich mir die Kraft des legendären Pokémon zurückholen und sie erneut in diese Waffe leiten.',
    'I\'ll be taking the Legendary Pokémon back now! This time, I won\'t lose.': 'Ich hole mir das legendäre Pokémon jetzt zurück! Dieses Mal werde ich nicht verlieren.',
    'So, you’ve managed to calm the Aura Duo… Quite the feat. But your Xerneas… it seems to have entered a dormant state. That form you see now is but a shadow of its true power. To awaken its full potential, you must strengthen its bond through training. Only then, when its strength has grown a hundredfold, will the light of its true form shine once more.': 'Du hast es also geschafft, das Aura-Duo zu beruhigen … Eine beachtliche Leistung. Aber dein [[pokemon::Xerneas]] … es scheint in einen Ruhezustand gefallen zu sein. Die Gestalt, die du jetzt siehst, ist nur ein Schatten seiner wahren Kraft. Um sein volles Potenzial zu erwecken, musst du eure Bindung durch Training stärken. Erst wenn seine Kraft um das Hundertfache gewachsen ist, wird das Licht seiner wahren Gestalt wieder erstrahlen.',
    '<i>This place is... beautiful. I am amazed such a place truly exists.</i>': '<i>Dieser Ort ist ... wunderschön. Ich bin erstaunt, dass es einen solchen Ort wirklich gibt.</i>',
    '<i>.......Thank you.</i>': '<i>.......Danke.</i>',
    '<i>I would like to give you something, but first, may I ask two things of you?</i>': '<i>Ich möchte dir gerne etwas geben, doch zuerst – darf ich dich um zwei Dinge bitten?</i>',
    '<i>First, I would like to gather 110,000 each of Psychic and Fighting Gems to boost the power of my attacks.</i>': '<i>Erstens möchte ich je 110,000 Psycho- und Kampfjuwelen sammeln, um die Kraft meiner Attacken zu steigern.</i>',
    '<i>If you could gather 60,000 of each I can take care of the rest.</i>': '<i>Wenn du jeweils 60,000 davon sammeln könntest, kümmere ich mich um den Rest.</i>',
    '<i>Also, you have heard of Twisted Spoons, yes? They are items that greatly boost the power of psychic type Pokémon.</i>': '<i>Außerdem hast du doch sicher schon von Krummlöffeln gehört, nicht wahr? Das sind Items, die die Kraft von Pokémon des Typs Psycho stark erhöhen.</i>',
    '<i>When I was created, I had an enhanced version of this item created for me. I have heard it is now in the hands of an organisation named Team Plasma, in an area named P2 Laboratory.</i>': '<i>Als ich erschaffen wurde, ließ man eine verbesserte Version dieses Items für mich anfertigen. Ich habe gehört, dass es sich nun in den Händen einer Organisation namens Team Plasma befindet, an einem Ort namens P2 Laboratory.</i>',
    '<i>I would greatly appreciate it if you would retrieve this item for me.</i>': '<i>Ich wäre dir sehr dankbar, wenn du mir dieses Item zurückholen würdest.</i>',
    '<i>I am even more in your debt. But there is one more thing I would like to ask of you.</i>': '<i>Ich stehe noch tiefer in deiner Schuld. Aber es gibt noch eine Sache, um die ich dich bitten möchte.</i>',
    '<i>Would you be willing to fight me, one last time, in this new home you have given me?</i>': '<i>Wärst du bereit, ein letztes Mal gegen mich zu kämpfen, hier in diesem neuen Zuhause, das du mir gegeben hast?</i>',
    '<i>With my Twisted Spoon in hand, my moves boosted by Gems, and my Mega Evolution, I can finally show you the true heights of my power!</i>': '<i>Mit meinem Krummlöffel in der Hand, meinen durch Juwelen verstärkten Attacken und meiner Mega-Entwicklung kann ich dir endlich die wahren Höhen meiner Kraft zeigen!</i>',
    '<i>Hah! Your strength is truly unyielding!</i>': '<i>Hah! Deine Stärke ist wahrlich unerschütterlich!</i>',
    '<i>I would like to apologise for accusing you of merely possessing the Mewtwo in your care. It is clear that you greatly care for it, as well as all your other Pokémon. Take this.</i>': '<i>Ich möchte mich dafür entschuldigen, dass ich dir vorgeworfen habe, das [[pokemon::Mewtwo]] in deiner Obhut bloß zu besitzen. Es ist offensichtlich, dass dir sehr viel an ihm liegt, ebenso wie an all deinen anderen Pokémon. Nimm das.</i>',
    '</i></br><img src="assets/images/megaStone/Mewtwonite_Y.png"/></br><i>You obtained the Mewtwonite Y!</i>': '</i></br><img src="assets/images/megaStone/Mewtwonite_Y.png"/></br><i>Du hast Mewtunit Y erhalten!</i>',
    '<i>You are truly deserving of this Mega Stone. Use it to give your Mewtwo a truly unrivaled power.</i>': '<i>Du hast diesen Mega-Stein wahrlich verdient. Nutze ihn, um deinem [[pokemon::Mewtwo]] eine wahrhaft unvergleichliche Kraft zu verleihen.</i>',
    'Welcome to Pirate Island! This lawless haven only comes alive once a year, when every marauder, buccaneer, and filibuster gathers for the Pirate Summit.': 'Willkommen auf Pirate Island! Dieser gesetzlose Zufluchtsort erwacht nur einmal im Jahr zum Leben, wenn sich alle Plünderer, Freibeuter und Seeräuber zum Piratengipfel versammeln.',
    'The tougher the challengers, the fiercer the pirates that appear. I’ve heard that those who’ve proven themselves in battle at least a hundred times earn the title of the strongest among us.': 'Je stärker die Herausforderer, desto wilder die Piraten, die auftauchen. Ich habe gehört, dass diejenigen, die sich mindestens hundertmal im Kampf bewiesen haben, den Titel der Stärksten unter uns erhalten.',
    'As for me? I make my living hauling treasure and shuffling chests around for the others. Though... sometimes it feels like a trickster\'s messing with them.': 'Und ich? Ich verdiene meinen Lebensunterhalt damit, Schätze zu schleppen und für die anderen Truhen hin und her zu schieben. Wobei ... manchmal fühlt es sich an, als würde ein Schelm mit ihnen herumspielen.',
    'I love cats very much, but dogs aren\'t so bad either.': 'Ich liebe Katzen sehr, aber Hunde sind auch nicht so übel.',
    'Out of all the dog-like Pokémon, I think Rockruff is definitely the most adorable. And it even has three evolutions! One during the day, one at night and one in between, from 5 to 6 o\'clock.': 'Von allen hundeartigen Pokémon finde ich [[pokemon::Rockruff]] eindeutig am niedlichsten. Und es hat sogar drei Entwicklungen! Eine am Tag, eine in der Nacht und eine dazwischen, von 5 bis 6 Uhr.',
    'What\'s that? AM or PM?': 'Wie bitte? Morgens oder abends?',
    'Yes.': 'Ja.',
    'Welcome to Alola!': 'Willkommen in Alola!',
    'Here we don\'t have gyms. We have the Island Challenge. On each of our four islands you will complete one or more trials.': 'Hier gibt es keine Arenen. Wir haben die Inselwanderschaft. Auf jeder unserer vier Inseln musst du eine oder mehrere Prüfungen bestehen.',
    'After completing all of an island\'s trials, you will battle that island\'s kahuna in a Grand trial.': 'Nachdem du alle Prüfungen einer Insel bestanden hast, trittst du in einer großen Prüfung gegen den Inselkönig oder die Inselkönigin dieser Insel an.',
    'This island only has one trial: Captain Ilima\'s trial in Verdant Cavern, below the Melemele Woods. Come back here after clearing that challenge for your Grand trial battle.': 'Auf dieser Insel gibt es nur eine Prüfung: Captain Elimas Prüfung in der Verdant Cavern, unterhalb des Melemele Woods. Komm hierher zurück, nachdem du diese Herausforderung gemeistert hast, um deine große Prüfung zu bestreiten.',
    'Greetings, $playername$. May I help you with something? Oh, you\'re looking for things called Silvally Memories? Something like this one?': 'Sei gegrüßt, $playername$. Kann ich dir mit etwas helfen? Oh, du suchst nach etwas, das sich [[pokemon::Silvally]]-Discs nennt? So etwas wie das hier?',
    'I found that while getting back here after helping Ilima in the Verdant Cavern. If you need it, I can give it to you. Here it is. Oh, also Kahuna Olivia told me she found one of these on Akala Island somewhere. Maybe you should go and ask her for it too. She\'ll probably give it to you as she also doesn\'t know what it is.': 'Die habe ich gefunden, als ich auf dem Rückweg war, nachdem ich Elima in der Verdant Cavern geholfen hatte. Wenn du sie brauchst, kann ich sie dir geben. Hier, bitte. Ach, übrigens hat Inselkönigin Mayla mir erzählt, dass sie irgendwo auf Akala Island auch so eine gefunden hat. Vielleicht solltest du sie auch danach fragen. Sie gibt sie dir bestimmt, da sie auch nicht weiß, was das ist.',
    'Nebby is... Its real home is far away from here. And I want to help it get home. Thank you for helping me. The two of us will be heading to the next island as well!': 'Wölkchen ist ... Sein wahres Zuhause ist weit weg von hier. Und ich möchte ihm helfen, nach Hause zu kommen. Danke, dass du mir hilfst. Wir beide machen uns auch auf den Weg zur nächsten Insel!',
    'Oh, and here, $playername$. Some Revives. It\'s the least I can do after all the running around I\'ve made you do.': 'Ach, und hier, $playername$. Ein paar Beleber. Das ist das Mindeste, was ich tun kann, nachdem ich dich so viel herumgescheucht habe.',
    'Zzzzt!!! How\'zzz it going, kiddo? Havin\' fun in the Alolan sun?': 'Bzzzt!!! Wie geht\'zzz, Kleines? Hast du Spaß unter der Sonne Alolas?',
    'Zzzzt!!! How\'zzz it going, kiddo? Feelin\' calm under the Alolan moon?': 'Bzzzt!!! Wie geht\'zzz, Kleines? Fühlst du dich ruhig unter dem Mond Alolas?',
    'There haven\'t been any new reports of Ultra Beasts in Alola, but I did see something strange over in Ten Carat Hill. It was black, yet shining. It seemed to be fleeing, no doubt about that. Must have been in a weakened state. Was it involved in some kind of battle? If you find it, I doubt it will have much energy left.': 'Es gab keine neuen Berichte über Ultrabestien in Alola, aber ich habe drüben am Ten Carat Hill etwas Seltsames gesehen. Es war schwarz und schimmerte trotzdem. Es schien auf der Flucht zu sein, daran besteht kein Zweifel. Es muss geschwächt gewesen sein. War es in irgendeinen Kampf verwickelt? Falls du es findest, hat es vermutlich kaum noch Energie übrig.',
    'Dooot doo doo, just a kahuna on a stroll to the laguna. ♪': 'Düüüt düü düü, nur ein Inselkönig auf dem Weg zur Laguna. ♪',
    'I\'m very grateful that you accepted my invitation. My name is Looker. This here is my boss, Chief Anabel, head of the UB Taskforce.': 'Ich bin sehr dankbar, dass du meine Einladung angenommen hast. Mein Name ist LeBelle. Das hier ist meine Chefin, Anabel, Leiterin der UB-Einsatztruppe.',
    'Ever since the incident at Aether Paradise, where you encountered UB-01 Symbiont, also known as Nihilego, we have heard reports of other Symbiont appearing in Alola. And other types of UBs too.': 'Seit dem Vorfall im Aether Paradise, bei dem du UB-01 Symbiont, auch bekannt als [[pokemon::Nihilego]], begegnet bist, haben wir Berichte über weitere Symbionten erhalten, die in Alola auftauchen. Und auch über andere Arten von UBs.',
    'They came here from a different world. Dropped rudely into our world against their will. We know nothing about them. They could be dangerous. They are almost certainly extremely wary and combative.': 'Sie kamen aus einer anderen Welt hierher. Gegen ihren Willen rücksichtslos in unsere Welt geworfen. Wir wissen nichts über sie. Sie könnten gefährlich sein. Sie sind mit ziemlicher Sicherheit äußerst misstrauisch und angriffslustig.',
    'We must find a way to calm their nerves. To make them feel at home in our world. Or we must destroy them. Either way, we must understand them. We must catch them.': 'Wir müssen einen Weg finden, sie zu beruhigen. Damit sie sich in unserer Welt zu Hause fühlen. Oder wir müssen sie vernichten. So oder so müssen wir sie verstehen. Wir müssen sie fangen.',
    'That is where you come in. The Champion of Alola. We do not have the battle power, but hopefully you do. Please allow Anabel to test your battle ability to ensure that you can handle this job.': 'Und da kommst du ins Spiel. Der Champ von Alola. Uns fehlt die Kampfkraft, aber du hast sie hoffentlich. Bitte erlaube Anabel, deine Kampffähigkeiten zu testen, um sicherzustellen, dass du dieser Aufgabe gewachsen bist.',
    'The testing is complete. I see no problem at all with your skills. Rather I would have to praise you for them. Welcome to the team!': 'Der Test ist abgeschlossen. Ich sehe keinerlei Probleme mit deinen Fähigkeiten. Im Gegenteil, ich muss dich dafür loben. Willkommen im Team!',
    'There is no more time to waste. UB-01 Symbiont, Nihilego, has been spotted on Akala Island! I will protect the nearby population centers, you must go and confront the Beast!': 'Wir haben keine Zeit mehr zu verlieren. UB-01 Symbiont, [[pokemon::Nihilego]], wurde auf Akala Island gesichtet! Ich werde die nahegelegenen Ortschaften beschützen, du musst losgehen und dich der Bestie stellen!',
    'Looker will stay here to coordinate reinforcements if needed. You can ask him about the special Beast Balls you will be using on this mission. I have given you a couple of them, but they are expensive so you will have to pitch in if you need more.': 'LeBelle bleibt hier, um bei Bedarf Verstärkung zu koordinieren. Du kannst ihn nach den speziellen Ultrabällen fragen, die du bei diesem Einsatz verwenden wirst. Ich habe dir ein paar davon gegeben, aber sie sind teuer, also musst du dich beteiligen, wenn du mehr brauchst.',
    'Catching lots of Ultra Beasts? Oh you want to know more about Beast Balls!': 'Du fängst viele Ultrabestien? Oh, du willst mehr über Ultrabälle wissen!',
    'Beast Balls can only be used to catch Ultra Beasts. You can\'t even try to use them against normal Pokémon, and any other Poké Ball type won\'t work against Ultra Beasts.': 'Ultrabälle können nur zum Fangen von Ultrabestien verwendet werden. Du kannst sie nicht einmal gegen normale Pokémon einsetzen, und keine andere Pokéball-Art wirkt gegen Ultrabestien.',
    'To help you out, I\'ve added an "Ultra Beast" option to the Encounter Type Pokéball filter setting. You can use this to set up a filter just for Ultra Beasts. Don\'t forget to enable it and assign Beast Balls!': 'Um dir zu helfen, habe ich der Pokéball-Filtereinstellung „Encounter Type“ die Option „Ultra Beast“ hinzugefügt. Damit kannst du einen Filter nur für Ultrabestien einrichten. Vergiss nicht, ihn zu aktivieren und Ultrabälle zuzuweisen!',
    'Congratulations on a job well done. I\'ve had contact with our colleagues at HQ. They have agreed to let you keep the UBs you catch.': 'Glückwunsch zu dieser hervorragenden Arbeit. Ich habe mit unseren Kollegen im Hauptquartier gesprochen. Sie sind einverstanden, dass du die UBs, die du fängst, behalten darfst.',
    'I\'m sure the UBs will truly flourish in the company of a competent trainer like yourself. It\'ll be much better for them than being locked up in some stuffy lab. Just be sure to let us know how they are doing.': 'Ich bin mir sicher, dass die UBs in der Obhut eines so fähigen Trainers wie dir richtig aufblühen werden. Das ist viel besser für sie, als in irgendeinem stickigen Labor eingesperrt zu sein. Halte uns nur auf dem Laufenden, wie es ihnen geht.',
    'Now, enough chit-chat. UB-02 Absorption and UB-02 Beauty, Buzzwole and Pheromosa, have been sighted on Melemele Island. You know what to do!': 'Genug geplaudert. UB-02 Absorption und UB-02 Beauty, [[pokemon::Buzzwole]] und [[pokemon::Pheromosa]], wurden auf Melemele Island gesichtet. Du weißt, was zu tun ist!',
    'Congratulations once again. Looker told me he wants to take us to a great restaurant to celebrate. I don\'t know how he knows any restaurants around here, we\'ve only just arrived.': 'Nochmals herzlichen Glückwunsch. LeBelle hat mir erzählt, dass er uns zur Feier in ein tolles Restaurant ausführen will. Ich weiß nicht, woher er hier irgendwelche Restaurants kennt, wir sind doch gerade erst angekommen.',
    'It doesn\'t matter though. There is no rest for us. Captain Mina is here with news, but she insists on battling you before she\'ll tell us anything.': 'Aber das spielt keine Rolle. Für uns gibt es keine Pause. Captain Mina ist mit Neuigkeiten hier, aber sie besteht darauf, gegen dich zu kämpfen, bevor sie uns irgendetwas verrät.',
    'Still in tip top shape I see. Good. That means you\'re strong enough to take out this monster I heard about on Akala Island.': 'Immer noch topfit, wie ich sehe. Gut. Das heißt, du bist stark genug, um dieses Monster zu erledigen, von dem ich auf Akala Island gehört habe.',
    'According to your little list here its... uhm... this one! UB-03 Lighting. Xurkitree. These are some strange names you guys come up with.': 'Laut eurer kleinen Liste hier ist es ... ähm ... das hier! UB-03 Lighting. [[pokemon::Xurkitree]]. Ihr denkt euch echt seltsame Namen aus.',
    'Good luck out there!': 'Viel Glück da draußen!',
    'I let myself in. Hope you don\'t mind.': 'Ich hab mich selbst reingelassen. Hoffe, das stört dich nicht.',
    'I\'m here to tell you about sightings of monsters on Ula\'ula Island. I missed some big Kahuna meeting we were all supposed to go to, so I got stuck as the messenger.': 'Ich bin hier, um dir von Monstersichtungen auf Ula\'ula Island zu erzählen. Ich hab irgendein großes Treffen der Inselkönige verpasst, zu dem wir alle hätten gehen sollen, also bin ich jetzt der Bote.',
    'It\'s not like I\'ve seen them or anything. Your friend Looker knew them from the description though. UB-04 Blade and UB-04 Blaster he called them. Kartana and Celesteela.': 'Nicht, dass ich sie gesehen hätte oder so. Dein Freund LeBelle hat sie aber anhand der Beschreibung erkannt. UB-04 Blade und UB-04 Blaster hat er sie genannt. [[pokemon::Kartana]] und [[pokemon::Celesteela]].',
    'Good job on rounding up those creatures, kid.': 'Gute Arbeit, diese Kreaturen einzufangen, Kleines.',
    'Now, how about one more battle? I insist.': 'Wie wär\'s jetzt mit noch einem Kampf? Ich bestehe darauf.',
    'This is tiring work, but I have a feeling that we\'re almost done.': 'Das ist anstrengende Arbeit, aber ich habe das Gefühl, dass wir fast fertig sind.',
    'Looker\'s informants told us about monster sightings on Poni Island. It seems UB Assembly and UB Burst, Stakataka and Blacephalon, have taken up residence.': 'LeBelles Informanten haben uns von Monstersichtungen auf Poni Island berichtet. Es scheint, dass UB Assembly und UB Burst, [[pokemon::Stakataka]] und [[pokemon::Blacephalon]], sich dort niedergelassen haben.',
    'Please be careful.': 'Bitte sei vorsichtig.',
    'And so here we are. At the end. And back at the beginning.': 'Und so sind wir hier. Am Ende. Und zurück am Anfang.',
    'Our final target is UB-05 Glutton. Guzzlord. It is very dangerous. You must not underestimate this beast.': 'Unser letztes Ziel ist UB-05 Glutton. [[pokemon::Guzzlord]]. Es ist sehr gefährlich. Du darfst diese Bestie nicht unterschätzen.',
    'Ten years ago, a very similar incident occured. Looker and his team were assigned to fight Guzzlord. Nanu was there too. They lost. Looker lost a colleague that day.': 'Vor zehn Jahren gab es einen sehr ähnlichen Vorfall. LeBelle und sein Team wurden beauftragt, gegen [[pokemon::Guzzlord]] zu kämpfen. Nanu war auch dabei. Sie haben verloren. LeBelle hat an jenem Tag einen Kollegen verloren.',
    'After the battle they found something. A strange young girl, alone in the wilderness of Poni Island. They found me. It seems I came from another world as well. Not their world though. These creatures are strange to me too.': 'Nach dem Kampf fanden sie etwas. Ein seltsames junges Mädchen, allein in der Wildnis von Poni Island. Sie fanden mich. Anscheinend komme ich auch aus einer anderen Welt. Allerdings nicht aus ihrer Welt. Diese Kreaturen sind auch mir fremd.',
    'I have made myself at home here. I hope Glutton can do the same. Please catch this Guzzlord. End this once and for all.': 'Ich habe mich hier eingelebt. Ich hoffe, Glutton kann das auch. Bitte fang dieses [[pokemon::Guzzlord]]. Bring es ein für alle Mal zu Ende.',
    'Akala Island has three trials.': 'Auf Akala Island gibt es drei Prüfungen.',
    'Captain Lana\'s trial in Brooklet Hill, Captain Kiawe\'s trial in Wela Volcano Park and Captain Mallow\'s trial in Lush Jungle.': 'Captain Tracys Prüfung am Brooklet Hill, Captain Kiawes Prüfung im Wela Volcano Park und Captain Kianas Prüfung im Lush Jungle.',
    'For what it\'s worth, I say don\'t go to any of those places. Too wet, too hot and too... jungly. Why not stay here? Have a coffee! Enjoy the city!': 'Wenn du mich fragst: Geh zu keinem dieser Orte. Zu nass, zu heiß und zu ... dschungelig. Warum bleibst du nicht hier? Trink einen Kaffee! Genieß die Stadt!',
    'Or go to Konikoni City down south. You might even meet our kahuna there!': 'Oder geh weiter in den Süden nach Konikoni City. Vielleicht triffst du dort sogar unsere Inselkönigin!',
    'There\'s an ancient legend here on Akala Island that tells of Marshadow.': 'Hier auf Akala Island gibt es eine uralte Legende, die von [[pokemon::Marshadow]] erzählt.',
    'It is said that when Marshadow is defeated, it sometimes leaves behind a rare crystallized fragment of its shadow.': 'Es heißt, dass [[pokemon::Marshadow]], wenn es besiegt wird, manchmal ein seltenes kristallisiertes Fragment seines Schattens zurücklässt.',
    'According to the legend this fragment is known as the Crystallized Shadow and if you reunite Marshadow with it, Marshadow will unlock a hidden potential.': 'Der Legende nach ist dieses Fragment als Kristallisierter Schatten bekannt, und wenn man [[pokemon::Marshadow]] wieder damit vereint, entfaltet [[pokemon::Marshadow]] ein verborgenes Potenzial.',
    'I think Nebby might be interested in visiting the Ruins of Life. Apparently they house the sacred guardian of Akala Island. I wondered if you\'d like to come with us when we go to visit the ruins. I\'ll be here if you decide you want to come.': 'Ich glaube, Wölkchen würde gerne die Ruins of Life besuchen. Angeblich beherbergen sie den heiligen Schutzpatron von Akala Island. Ich habe mich gefragt, ob du vielleicht mitkommen möchtest, wenn wir die Ruinen besuchen. Ich warte hier, falls du dich entscheidest, mitzukommen.',
    'By chance, have you spoken to Professor Burnet? She and Professor Kukui have been so kind, helping me investigate Nebby\'s origins. She\'s not here at the moment, but I\'d like introduce you.': 'Hast du zufällig schon mit Professor Burnett gesprochen? Sie und Professor Kukui sind so nett und helfen mir, Wölkchens Herkunft zu erforschen. Sie ist gerade nicht da, aber ich würde sie dir gerne vorstellen.',
    'Professor Burnet has been so kind, and she\'s helping me try to find a way to get Nebby back to its own home... She\'s been like...like a real mother to me.': 'Professor Burnett ist so nett, und sie hilft mir dabei, einen Weg zu finden, Wölkchen zurück nach Hause zu bringen ... Sie ist für mich wie ... wie eine richtige Mutter.',
    'I\'ll be waiting here until you\'re ready to join us to the Ruins of Life. I\'ve heard that there is a group of terrible people called Team Skull who try to steal Pokémon. We need to be careful if we want to escape the notice of such a collection of villains... Isn\'t that right, $playername$?': 'Ich warte hier, bis du bereit bist, uns zu den Ruins of Life zu begleiten. Ich habe gehört, dass es eine Gruppe schrecklicher Leute namens Team Skull gibt, die versuchen, Pokémon zu stehlen. Wir müssen vorsichtig sein, wenn wir von solchen Schurken nicht bemerkt werden wollen ... Nicht wahr, $playername$?',
    'And Nebby! I\'ll have you stay in your bag, mister!': 'Und du, Wölkchen! Du bleibst schön in deiner Tasche, mein Herr!',
    'Nebby\'s Pokémon species, Cosmog, used to be known as the child of the stars. Its modern name was coined by a researcher in Aether Paradise!': 'Wölkchens Pokémon-Art, [[pokemon::Cosmog]], war früher als Kind der Sterne bekannt. Sein heutiger Name wurde von einem Forscher im Aether Paradise geprägt!',
    'Oh, where are my manners! Hi there! Have some Rare Candies! I\'m Burnet, a professor who researches Ultra Wormholes. They sometimes appear in the skies of Alola and give off similar signals to Cosmog\'s powers.': 'Oh, wo sind nur meine Manieren! Hallo! Hier, nimm ein paar Sonderbonbons! Ich bin Burnett, eine Professorin, die Ultrapforten erforscht. Sie erscheinen manchmal am Himmel von Alola und senden ähnliche Signale aus wie die Kräfte von [[pokemon::Cosmog]].',
    'Legends of Pokémon appearing from the Ultra Wormhole also exist and are called Ultra Beasts, but it\'s all legends and folktales. It\'s hard to know how much is true.': 'Es gibt auch Legenden über Pokémon, die aus Ultrapforten erscheinen und Ultrabestien genannt werden, aber das sind alles nur Legenden und Volksmärchen. Es ist schwer zu sagen, wie viel davon wahr ist.',
    'Long ago, Cosmog was called the child of the stars. Its powers seem to have some connection with Ultra Wormholes.': 'Vor langer Zeit wurde [[pokemon::Cosmog]] das Kind der Sterne genannt. Seine Kräfte scheinen irgendwie mit Ultrapforten zusammenzuhängen.',
    'The mysteries of the Ultra Wormhole and Ultra Beasts...  I would be very happy if I could somehow unravel them!': 'Die Geheimnisse der Ultrapforten und Ultrabestien ...  Ich wäre so glücklich, wenn ich sie irgendwie lüften könnte!',
    'You say I look familiar? Oh, you\'ve probably seen me with Kukui. He\'s my husband!': 'Ich komme dir bekannt vor? Oh, du hast mich wahrscheinlich mit Kukui gesehen. Er ist mein Ehemann!',
    'I love Oricorio. I can tell you all about it!': 'Ich liebe [[pokemon::Oricorio]]. Ich kann dir alles darüber erzählen!',
    'Each of the four islands in Alola has its own meadow, and each meadow has its own form of Oricorio. Each island, except for Akala Island. So you\'d think there\'s only three forms of Oricorio, right?': 'Jede der vier Inseln Alolas hat ihre eigene Wiese, und auf jeder Wiese gibt es eine eigene Form von [[pokemon::Oricorio]]. Auf jeder Insel, außer auf Akala Island. Da könnte man meinen, es gibt nur drei Formen von [[pokemon::Oricorio]], oder?',
    'Wrong! There is a fourth! Did you know you can find all of the Oricorio forms on the farm? One of them doesn\'t appear anywhere else!': 'Falsch! Es gibt eine vierte! Wusstest du, dass man alle [[pokemon::Oricorio]]-Formen auf der Farm finden kann? Eine davon taucht nirgendwo sonst auf!',
    'Each Oricorio form is attracted to the berry color that matches its own style. Red for Baile style, yellow for Pom-Pom style, pink for Pa\'u style and purple for Sensu style.': 'Jede [[pokemon::Oricorio]]-Form wird von der Beerenfarbe angelockt, die zu ihrem eigenen Stil passt. Rot für den Flamenco-Stil, Gelb für den Cheerleading-Stil, Pink für den Hula-Stil und Lila für den Buyo-Stil.',
    'You want to know which one can only be found on the farm? I\'m sure you can figure that out yourself. Simple process of elimination, really.': 'Du willst wissen, welche man nur auf der Farm finden kann? Das kannst du sicher selbst herausfinden. Einfaches Ausschlussverfahren, wirklich.',
    'I like sneaking snacks inside the Battle Royal Dome. One time I snuck in pancakes and there were two trainers from Kanto who both had a Pikachu. I ended up sharing some with one.': 'Ich schmuggle gerne Snacks in den Battle Royal Dome. Einmal habe ich Pfannkuchen reingeschmuggelt, und da waren zwei Trainer aus Kanto, die beide ein [[pokemon::Pikachu]] hatten. Am Ende habe ich mit einem davon geteilt.',
    'Weird thing is, both trainers evolved their Pikachu after the battle, but one had a different form from usual! Maybe there\'s something about Alola that makes certain Pokémon evolve differently? I would check my Evolution Items if I were you.': 'Das Seltsame ist, dass beide Trainer ihr [[pokemon::Pikachu]] nach dem Kampf entwickelt haben, aber eines hatte eine andere Form als sonst! Vielleicht hat Alola etwas an sich, das bestimmte Pokémon anders entwickeln lässt? An deiner Stelle würde ich mal meine Entwicklungsitems überprüfen.',
    'Hello there, $playername$! Have you perchance caught sight of my advertisement? I\'m on the lookout for a formidable opponent to assist me in honing my Pokémon\'s skills. And let me assure you, the rewards are quite substantial! Should you best me in battle, you shall be granted a most wondrous prize: a Silvally Memory that I found inside the Hokulani Observatory.': 'Hallo, $playername$! Hast du womöglich meine Anzeige gesehen? Ich halte Ausschau nach einem ebenbürtigen Gegner, der mir hilft, die Fähigkeiten meiner Pokémon zu verfeinern. Und ich versichere dir, die Belohnung ist äußerst beträchtlich! Solltest du mich im Kampf bezwingen, erhältst du einen ganz wundervollen Preis: eine [[pokemon::Silvally]]-Disc, die ich im Hokulani Observatory gefunden habe.',
    'As you may already know, I am both a Steel-type expert and a stickler for precision in combat. I desire nothing more than to elevate my team to the utmost degree of mastery. But in order to do so, I must face off against trainers of the highest caliber. That is where you come in, my friend! If you are prepared for the challenge, step forward and engage me in a duel for the ages!': 'Wie du vielleicht schon weißt, bin ich sowohl ein Experte für den Typ Stahl als auch ein Verfechter von Präzision im Kampf. Ich wünsche mir nichts sehnlicher, als mein Team zur höchsten Meisterschaft zu führen. Doch dafür muss ich mich Trainern höchsten Kalibers stellen. Und genau da kommst du ins Spiel, mein Freund! Wenn du für die Herausforderung bereit bist, tritt vor und stelle dich mir in einem Duell für die Ewigkeit!',
    'What do you mean Grand trials are just like gym battles? It\'s a totally different thing!': 'Was soll das heißen, große Prüfungen sind wie Arenakämpfe? Das ist was völlig anderes!',
    'Come fight me in our very special and unique brand new Pokémon League and see if you still think our Island Challenge is nothing special!': 'Komm und kämpf gegen mich in unserer ganz besonderen, einzigartigen, brandneuen Pokémon-Liga, und dann sehen wir mal, ob du unsere Inselwanderschaft immer noch für nichts Besonderes hältst!',
    'Hey, kiddo. What are you doing here? Just visiting Akala Island? Cus y\'know lots of tourists come here to see the Battle Royal. So, what\'re you doing here? Looking for something?': 'Hey, Kleines. Was machst du denn hier? Besuchst du nur Akala Island? Weißt du, viele Touristen kommen her, um sich den Battle Royal anzusehen. Also, was machst du hier? Suchst du etwas?',
    'Oh, you\'re looking for something called a Silvally Memory and Hala told you I found one? Do you mean this thing?': 'Oh, du suchst nach etwas, das sich [[pokemon::Silvally]]-Disc nennt, und Hala hat dir erzählt, dass ich eine gefunden habe? Meinst du dieses Ding hier?',
    'I found it while helping Mallow with her trial. If you want it, you can have it. It\'s useless to me anyway.': 'Ich habe sie gefunden, als ich Kiana bei ihrer Prüfung geholfen habe. Wenn du sie willst, kannst du sie haben. Für mich ist sie sowieso nutzlos.',
    'Some very rare Pokémon have been sighted on {ROUTE_NAME}. I hope we can learn more about them.': 'Auf {ROUTE_NAME} wurden einige sehr seltene Pokémon gesichtet. Ich hoffe, wir können mehr über sie herausfinden.',
    'Nebby changed forms... and it\'s not moving...': 'Wölkchen hat seine Form verändert ... und es bewegt sich nicht ...',
    'I feel like there\'s so much I have to do now... to save Nebby... to save my mother... That\'s why I\'m going to try my hardest! This is my Z-Powered form! Come on! Let\'s show the world what we can really do!': 'Ich habe das Gefühl, dass ich jetzt so viel tun muss ... um Wölkchen zu retten ... um meine Mutter zu retten ... Deshalb werde ich mein Bestes geben! Das ist meine Z-Power-Form! Komm schon! Zeigen wir der Welt, was wir wirklich können!',
    'The Sun Flute and the Moon Flute. When sounded together, it\'s said that they can call the Legendary Pokémon... That is, if you believe in old myths, anyway. I found one of them downstairs and gave it to Lillie.': 'Die Sonnenflöte und die Mondflöte. Wenn man sie zusammen erklingen lässt, sollen sie das legendäre Pokémon herbeirufen können ... Das heißt, falls man an alte Mythen glaubt. Ich habe eine davon unten gefunden und sie Lilly gegeben.',
    'Here. Take this Master Ball with you. I\'m counting on you to help Lillie. This is the least I can do.': 'Hier. Nimm diesen Meisterball mit. Ich zähle darauf, dass du Lilly hilfst. Das ist das Mindeste, was ich tun kann.',
    'Even if she is...like that, Lusamine is still our mother. We can\'t just leave her in the beast\'s world.': 'Auch wenn sie ... so ist, Samantha ist immer noch unsere Mutter. Wir können sie nicht einfach in der Welt der Bestien zurücklassen.',
    'At first I\'d taken Nebby with me, but I didn\'t have the courage to protect it myself. But I\'m not that person anymore!': 'Anfangs hatte ich Wölkchen mitgenommen, aber ich hatte nicht den Mut, es selbst zu beschützen. Aber dieser Mensch bin ich nicht mehr!',
    'Traveling around Alola with you, learning all the things you knew... And seeing Nebby evolve into Solgaleo under that radiant sun... I\'ll never forget those precious memories, $playername$!': 'Mit dir durch Alola zu reisen, all die Dinge zu lernen, die du wusstest ... Und zu sehen, wie sich Wölkchen unter dieser strahlenden Sonne zu [[pokemon::Solgaleo]] entwickelt hat ... Diese kostbaren Erinnerungen werde ich nie vergessen, $playername$!',
    'You, Professor Kukui, Professor Burnet, Hau, Hapu, and everyone else... I\'m so glad I got to meet everyone!': 'Du, Professor Kukui, Professor Burnett, Hau, Hapu und alle anderen ... Ich bin so froh, dass ich euch alle kennenlernen durfte!',
    'Traveling around Alola with you, learning all the things you knew... And seeing Nebby evolve into Lunala under that brilliant moon... I\'ll never forget those precious memories, $playername$!': 'Mit dir durch Alola zu reisen, all die Dinge zu lernen, die du wusstest ... Und zu sehen, wie sich Wölkchen unter diesem leuchtenden Mond zu [[pokemon::Lunala]] entwickelt hat ... Diese kostbaren Erinnerungen werde ich nie vergessen, $playername$!',
    'Oh, welcome $playername$, the Champion of Alola! I see you <i>still</i> haven\'t lost that title. You\'re a pretty... <i>worthy</i> trainer, aren\'t you? Anyways, I think you should come visit us another time we\'re... er.. busy! Yes, we\'re extremely busy right now... ': 'Oh, willkommen, $playername$, Champ von Alola! Wie ich sehe, hast du diesen Titel <i>immer noch</i> nicht verloren. Du bist ein ziemlich ... <i>würdiger</i> Trainer, nicht wahr? Wie auch immer, ich finde, du solltest uns ein andermal besuchen, wenn wir ... äh ... beschäftigt sind! Ja, wir sind gerade extrem beschäftigt ...',
    'Oh, you\'re looking for a Silvally Memory? Well I can\'t help you with it so bye! What? You\'re not leaving until I help you? Ugh.. kids are so annoying these days.. er... I mean I\'d gladly help, I\'m just <i>busy</i> right now. <i>LikeISaidTwoSecondsAgo.</i>': 'Oh, du suchst nach einer [[pokemon::Silvally]]-Disc? Tja, dabei kann ich dir nicht helfen, also tschüss! Was? Du gehst nicht, bis ich dir helfe? Uff ... Kinder sind heutzutage so nervig ... äh ... ich meine, ich würde gerne helfen, ich bin nur gerade <i>beschäftigt</i>. <i>WieIchVorZweiSekundenGesagtHabe.</i>',
    'Well, I guess you can already tell. We\'ve been in Haina Desert looking for Tapu Bulu, but the search team stumbled upon this Silvally Memory instead and it looks pretty rare because we couldn\'t find much information about it. We want to take it in for some experiments, but we knew you wouldn\'t let us do that so I tried to hide it. Now that you know, my only choice is battling you.': 'Na ja, du hast es wohl schon gemerkt. Wir waren in der Haina Desert auf der Suche nach [[pokemon::Tapu Bulu]], aber das Suchteam ist stattdessen auf diese [[pokemon::Silvally]]-Disc gestoßen, und sie scheint ziemlich selten zu sein, weil wir kaum Informationen darüber finden konnten. Wir wollen sie für ein paar Experimente mitnehmen, aber wir wussten, dass du das nicht zulassen würdest, also habe ich versucht, sie zu verstecken. Jetzt, wo du es weißt, bleibt mir nur, gegen dich zu kämpfen.',
    'Let\'s make a deal first though: If I defeat you, you\'ll let us do our experiments on that thing and leave us alone forever, but if you defeat me I\'ll give that Memory to you. Sounds like a deal? Then let\'s see if you can take the new Faba!': 'Machen wir aber zuerst einen Deal: Wenn ich dich besiege, lässt du uns unsere Experimente mit dem Ding machen und uns für immer in Ruhe, aber wenn du mich besiegst, gebe ich dir die Disc. Klingt das nach einem Deal? Dann wollen wir mal sehen, ob du es mit dem neuen Faba aufnehmen kannst!',
    'What do I think of Grand trials? They\'re just like gym battles. Yup, it\'s totally the same thing. They\'re even making a Pokémon League.': 'Was ich von großen Prüfungen halte? Die sind genau wie Arenakämpfe. Jep, ist total dasselbe. Die bauen sogar eine Pokémon-Liga.',
    'What? Why are you looking at me like that? If you don\'t wanna battle, I\'m going home.': 'Was? Warum schaust du mich so an? Wenn du nicht kämpfen willst, geh ich nach Hause.',
    'Oh, hello. How can I help you? You\'re looking for Silvally Memories? What do they look like? Oh, so like a disk with a broken part. I think I <i>have</i> seen one while helping Acerola with her trial. Here, you can take it.': 'Oh, hallo. Wie kann ich dir helfen? Du suchst nach [[pokemon::Silvally]]-Discs? Wie sehen die aus? Ach, so wie eine Scheibe mit einem kaputten Teil. Ich glaube, ich <i>habe</i> so eine gesehen, als ich Lola bei ihrer Prüfung geholfen hab. Hier, du kannst sie haben.',
    'I don\'t know how to use it, so you can keep it.': 'Ich weiß nicht, wie man sie benutzt, also kannst du sie behalten.',
    'There\'s an old book with myths about Alola\'s Legendary Pokémon here. It seems to suggest they came from another world and brought life to an heir that was to be protected by the island guardians.': 'Hier gibt es ein altes Buch mit Mythen über die legendären Pokémon Alolas. Es deutet darauf hin, dass sie aus einer anderen Welt kamen und einem Erben das Leben schenkten, der von den Schutzpatronen der Inseln beschützt werden sollte.',
    'I ended up getting lost, and then I saw this outfit, and it was the last one they had in stock, so I bought it... Hah...': 'Ich habe mich am Ende verlaufen, und dann habe ich dieses Outfit gesehen, und es war das letzte, das sie noch auf Lager hatten, also habe ich es gekauft ... Hah ...',
    '<i>Beast of sun and beast of moon</i>... That\'s what was written in the book from the library. It must be referring to the legendary Pokémon of Alola. I thought I could find something about Nebby in there but...': '<i>Bestie der Sonne und Bestie des Mondes</i> ... Das stand in dem Buch aus der Bibliothek. Damit müssen die legendären Pokémon Alolas gemeint sein. Ich dachte, ich könnte darin etwas über Wölkchen finden, aber ...',
    '$playername$. Been a while, friend. And who might this be?': '$playername$. Lange nicht gesehen, Freund. Und wer ist das hier?',
    'Lillie? And she plans to visit Ula\'ula\'s ruins? Well, that\'s some fine initiative. I\'d be happy to show her the way whenever she\'d like to go.': 'Lilly? Und sie will die Ruinen von Ula\'ula besuchen? Na, das nenne ich Eigeninitiative. Ich zeige ihr gerne den Weg, wann immer sie gehen möchte.',
    'Yesterday was my first day working on Mount Lanakila. I was up there maintaining the paths to the new Pokémon League.': 'Gestern war mein erster Arbeitstag auf dem Mount Lanakila. Ich war oben und habe die Wege zur neuen Pokémon-Liga instand gehalten.',
    'My trusty Crabrawler was with me. He was smashing some rocks that were blocking the path, having a grand ol\' time like usual, when suddenly we were attacked by a wild Pokémon!': 'Mein treues [[pokemon::Crabrawler]] war bei mir. Es hat ein paar Felsen zertrümmert, die den Weg versperrten, und hatte wie immer einen Riesenspaß, als wir plötzlich von einem wilden Pokémon angegriffen wurden!',
    'After the battle, Crabrawler evolved! I didn\'t even know he could do that. He\'s so different now. But I still love him. He\'s my best friend, and he\'s even better at rock smashing now!': 'Nach dem Kampf hat sich [[pokemon::Crabrawler]] entwickelt! Ich wusste gar nicht, dass es das kann. Es ist jetzt so anders. Aber ich liebe es immer noch. Es ist mein bester Freund, und im Felsenzertrümmern ist es jetzt sogar noch besser!',
    'Pokémon being abducted like that... Maybe even hurt... I just can\'t stand the idea! $playername$! Please...help them!': 'Pokémon, die einfach so entführt werden ... Vielleicht sogar verletzt ... Diese Vorstellung ertrage ich einfach nicht! $playername$! Bitte ... hilf ihnen!',
    'We don\'t have a kahuna on Poni, so I don\'t have an actual trial or anything...': 'Wir haben keinen Inselkönig auf Poni, also habe ich keine richtige Prüfung oder so ...',
    'Old man Nanu has been looking after our grand trials up until now. I\'m the captain and all, so I\'ve gotta come up with a trial.': 'Der alte Nanu hat sich bisher um unsere großen Prüfungen gekümmert. Ich bin ja Captain und so, also muss ich mir eine Prüfung ausdenken.',
    'My trial is in this town. Right there, inside my very own houseboat. Normally you\'d have to clear my trial to find our kahuna on Exeggutor Island, but I guess you took care of some things, huh?': 'Meine Prüfung findet in diesem Ort statt. Genau da drüben, in meinem eigenen Hausboot. Normalerweise müsstest du meine Prüfung bestehen, um unsere Inselkönigin auf Exeggutor Island zu finden, aber du hast dich wohl schon um einiges gekümmert, was?',
    'Well, in that case, I\'d better add a little something more. This is the final trial of your island challenge, after all. I hope you\'re ready for your toughest opponents yet!': 'Na, in dem Fall lege ich besser noch etwas drauf. Das ist schließlich die letzte Prüfung deiner Inselwanderschaft. Ich hoffe, du bist bereit für deine bisher härtesten Gegner!',
    'Hello, $playername$. Here to do my trial again? Oh, I see you\'re looking for Silvally Memories. Well, I have just the right thing for you. Here, take it.': 'Hallo, $playername$. Willst du meine Prüfung noch mal machen? Oh, ich sehe, du suchst nach [[pokemon::Silvally]]-Discs. Da habe ich genau das Richtige für dich. Hier, nimm sie.',
    'Kahuna Hapu gave me that as a gift. She even told me how to use it, but I couldn\'t afford to buy a Silvally. You can keep it.': 'Inselkönigin Hapu hat sie mir geschenkt. Sie hat mir sogar erklärt, wie man sie benutzt, aber ich konnte mir kein [[pokemon::Silvally]] leisten. Du kannst sie behalten.',
    'So Hapu lives here on Poni Island? Let\'s go, $playername$! She can help us find the kahuna! It will be good to see her and Mudsdale again!': 'Hapu lebt also hier auf Poni Island? Los geht\'s, $playername$! Sie kann uns helfen, die Inselkönigin zu finden! Es wird schön sein, sie und [[pokemon::Mudsdale]] wiederzusehen!',
    'Poni Island... It\'s a completely different kind of island, isn\'t it?': 'Poni Island ... Das ist eine ganz andere Art von Insel, nicht wahr?',
    'Oh my goodness, Nebby! To think you would be the emissary of the sun, Solgaleo!': 'Du meine Güte, Wölkchen! Wer hätte gedacht, dass du der Gesandte der Sonne bist, [[pokemon::Solgaleo]]!',
    'Oh my goodness, Nebby! To think you would be the emissary of the moon, Lunala!': 'Du meine Güte, Wölkchen! Wer hätte gedacht, dass du der Gesandte des Mondes bist, [[pokemon::Lunala]]!',
    'My mother is— She\'s selfish. She lavishes her love only on those she deems worthy, not caring whether it is wanted or not.': 'Meine Mutter ist – Sie ist selbstsüchtig. Sie überschüttet nur diejenigen mit Liebe, die sie für würdig hält, ganz egal, ob diese Liebe erwünscht ist oder nicht.',
    'But I will save her. I still have something I need to tell her. I am alive. Cosmog is alive.': 'Aber ich werde sie retten. Ich muss ihr noch etwas sagen. Ich lebe. [[pokemon::Cosmog]] lebt.',
    'Nebby. Please. I need to see my mother!': 'Wölkchen. Bitte. Ich muss zu meiner Mutter!',
    'All right, $playername$! Let\'s go!': 'Also gut, $playername$! Los geht\'s!',
    'Nebby... all I ever wanted to do was to help you get back to your own home... But instead you helped me, over and over... I got the chance to finally talk with my mother. Thank you... Thank you so much!': 'Wölkchen ... Ich wollte dir doch nur helfen, in dein eigenes Zuhause zurückzukehren ... Aber stattdessen hast du mir geholfen, immer und immer wieder ... Ich hatte endlich die Gelegenheit, mit meiner Mutter zu reden. Danke ... Vielen, vielen Dank!',
    'And thank you too, $playername$! You\'ve helped me gain so much confidence in myself. I am very grateful for that. I was able to achieve things I had never dreamed I could... Getting to meet you, traveling together with you... I\'m so glad I got to be part of your journey!': 'Und danke auch dir, $playername$! Du hast mir geholfen, so viel Selbstvertrauen zu gewinnen. Dafür bin ich dir sehr dankbar. Ich konnte Dinge erreichen, von denen ich nie zu träumen gewagt hätte ... Dich kennenzulernen, mit dir zusammen zu reisen ... Ich bin so froh, dass ich ein Teil deiner Reise sein durfte!',
    'Wait- what is this darkness in the sky? Oh my goodness! $playername$! In the sky! Another Ultra Wormhole!': 'Moment – was ist das für eine Dunkelheit am Himmel? Du meine Güte! $playername$! Am Himmel! Noch eine Ultrapforte!',
    'I was concerned so I ascended. And what do I find but the Legendary Pokémon... and a strange hole in the sky.': 'Ich habe mir Sorgen gemacht, also bin ich hinaufgestiegen. Und was finde ich? Das legendäre Pokémon ... und ein seltsames Loch im Himmel.',
    'I\'ll await your arrival on Exeggutor Island, if training is something you desire before challenging this beast.': 'Ich erwarte dich auf Exeggutor Island, falls du trainieren möchtest, bevor du dich dieser Bestie stellst.',
    'Necrozma...and us ourselves... we have both suffered so many long years in this darkness, living a life we did not wish for...': '[[pokemon::Necrozma]] ... und wir selbst ... wir haben beide so viele lange Jahre in dieser Dunkelheit gelitten und ein Leben geführt, das wir nicht wollten ...',
    'Our Ultra Megalopolis was once a world filled with light... Necrozma was called the Blinding One, and it gave us all the energy we needed.': 'Unsere Ultra-Megalopolis war einst eine Welt voller Licht ... [[pokemon::Necrozma]] wurde der Blendende genannt, und es gab uns alle Energie, die wir brauchten.',
    'Our ancestors were greedy, though. They sought to control all of Necrozma\'s light... They hurt Necrozma... They left it incomplete, and in such a state, it went mad with fury... And so our light was stolen by Necrozma. Now, the one that wields light to its will... It would steal all of Alola\'s light!': 'Doch unsere Vorfahren waren gierig. Sie wollten das gesamte Licht von [[pokemon::Necrozma]] kontrollieren ... Sie haben [[pokemon::Necrozma]] verletzt ... Sie haben es unvollständig zurückgelassen, und in diesem Zustand verfiel es in rasende Wut ... Und so wurde unser Licht von [[pokemon::Necrozma]] gestohlen. Jetzt wird jenes Wesen, das das Licht nach seinem Willen lenkt ... das gesamte Licht Alolas stehlen!',
    'Necrozma... It seems like it is also suffering somehow... It seems to hurt it, to be without its light...': '[[pokemon::Necrozma]] ... Es scheint, als würde es auch irgendwie leiden ... Es scheint ihm wehzutun, ohne sein Licht zu sein ...',
    '$playername$! Please help Nebby for me! But also... if you can... try to help Necrozma, like you did mother.': '$playername$! Bitte hilf Wölkchen für mich! Aber auch ... wenn du kannst ... versuch, [[pokemon::Necrozma]] zu helfen, so wie du Mutter geholfen hast.',
    'Care for a Poipole? It only costs a few thousand Quest Points!': 'Wie wär\'s mit einem [[pokemon::Poipole]]? Es kostet nur ein paar tausend Questpunkte!',
    'I...I\'ve been wanting to thank you for saving Nebby that day. Back then I was so desperate... It hasn\'t all been easy... but I\'m really glad that I came to Alola! I\'ve decided I\'m going to become a real Trainer and meet all kinds of wonderful Pokémon!': 'Ich ... ich wollte dir schon lange dafür danken, dass du Wölkchen an jenem Tag gerettet hast. Damals war ich so verzweifelt ... Es war nicht immer leicht ... aber ich bin wirklich froh, dass ich nach Alola gekommen bin! Ich habe beschlossen, eine richtige Trainerin zu werden und alle möglichen wundervollen Pokémon kennenzulernen!',
    'I\'m going to go back to Aether Paradise for a bit to help my mother recover. I need to see for myself that she\'ll be all right, but before that... $playername$! Won\'t you have a battle with me?': 'Ich gehe für eine Weile zurück zum Aether Paradise, um meiner Mutter bei ihrer Genesung zu helfen. Ich muss mich selbst davon überzeugen, dass es ihr gut gehen wird, aber vorher ... $playername$! Willst du nicht gegen mich kämpfen?',
    'I have been studying Cosmoem and noticed that it needs the light from either the sun or the moon to reach its fullest potential.': 'Ich habe [[pokemon::Cosmoem]] studiert und bemerkt, dass es das Licht der Sonne oder des Mondes braucht, um sein volles Potenzial zu erreichen.',
    'When exposed to the light of the sun and leveling up, it will transform into Solgaleo. And it will turn into Lunala with the light of the moon.': 'Wenn es dem Licht der Sonne ausgesetzt ist und ein Level aufsteigt, verwandelt es sich in [[pokemon::Solgaleo]]. Und mit dem Licht des Mondes wird es zu [[pokemon::Lunala]].',
    'Zzzzt!!! You\'ve almost made it, kiddo! Championship is on the horizzzon! I\'m rootin\' for ya!': 'Bzzzt!!! Du hast es fast geschafft, Kleines! Der Champ-Titel ist in Reichweite! Ich drück dir die Daumen!',
    'Congratulationzzz, bucko! You\'re the new reigning Alola Champion! You really are something, kiddo!': 'Herzlichen Glückwunzzzch, Kumpel! Du bist der neue amtierende Champ von Alola! Du bist echt was Besonderes, Kleines!',
    'Hello there champ! Fancy seeing you here.': 'Hallo, Champ! Was für ein Zufall, dich hier zu treffen.',
    'We just planted this sapling here. Maybe it will grow into something great some day.': 'Wir haben diesen Setzling gerade hier gepflanzt. Vielleicht wird eines Tages etwas Großartiges daraus.',
    'Yo, traveler! The name\'s Ryuki! You\'ve come here to battle against a star like me, haven\'t you? No? Why\'s that? I see, you\'re looking for something?': 'Yo, Reisender! Ich bin Ryuki! Du bist hergekommen, um gegen einen Star wie mich zu kämpfen, oder? Nein? Warum nicht? Verstehe, du suchst nach etwas?',
    'Speaking of which, I stumbled upon a gnarly disk in my travels recently. It was unlike any music disk I had ever seen before, it has a rockin\' dark blue coloration. But for all its uniqueness, I can\'t make out what it is, see?': 'Apropos, ich bin auf meinen Reisen neulich über eine krasse Scheibe gestolpert. Sie war anders als jede Musikscheibe, die ich je gesehen habe, sie hat eine rockige dunkelblaue Färbung. Aber so einzigartig sie auch ist, ich werd nicht schlau draus, was sie ist, verstehst du?',
    'A Dragon-type Silvally Memory, you say? Rock on! I had a feeling it was something rare and powerful, but I never would have guessed it was a Silvally Memory! But now that I know what I have, I can\'t simply give it to you. I\'m a rock star, not a trial captain! We\'re on stage and the crowd wants a show!': 'Eine [[pokemon::Silvally]]-Disc vom Typ Drache, sagst du? Rock on! Ich hatte so ein Gefühl, dass sie etwas Seltenes und Mächtiges ist, aber dass sie eine [[pokemon::Silvally]]-Disc ist, hätte ich nie gedacht! Aber jetzt, wo ich weiß, was ich habe, kann ich sie dir nicht einfach geben. Ich bin ein Rockstar, kein Captain! Wir stehen auf der Bühne und das Publikum will eine Show!',
    'If you want this Silvally Memory, you have to defeat me in a burning hot battle! It won\'t be easy, mind you. My babies are dying to play a set, and I won\'t be holding back! But if you truly have what it takes to be the champion, then you should be up for the challenge, yeah? Right on! Let\'s rock!': 'Wenn du diese [[pokemon::Silvally]]-Disc willst, musst du mich in einem glühend heißen Kampf besiegen! Das wird nicht leicht, wohlgemerkt. Meine Babys brennen darauf, ein Set zu spielen, und ich werde mich nicht zurückhalten! Aber wenn du wirklich das Zeug zum Champ hast, dann bist du der Herausforderung doch gewachsen, oder? Genau so! Lass uns rocken!',
    'Welcome to the region of Magikarp!': 'Willkommen in der Region von [[pokemon::Magikarp]]!',
    'This is a magical place where everybody loves Magikarp!': 'Dies ist ein magischer Ort, an dem jeder [[pokemon::Magikarp]] liebt!',
    'You\'re good at raising Pokémon, right? We called you here to compete in the ten leagues around the island and pick up our poor Magikarp\'s spirits!': 'Du bist gut darin, Pokémon großzuziehen, oder? Wir haben dich hergerufen, damit du in den zehn Ligen rund um die Insel antrittst und die Stimmung unserer armen [[pokemon::Magikarp]] hebst!',
    'Around these parts, folks love to compete to see whose Magikarp can splash harder and jump higher! No other Pokémon are allowed to compete in these events. So, do your best to raise up some fine Magikarp!': 'Hier in der Gegend lieben es die Leute, sich darin zu messen, wessen [[pokemon::Magikarp]] kräftiger platschen und höher springen kann! Bei diesen Wettbewerben dürfen keine anderen Pokémon antreten. Also gib dein Bestes, um ein paar prächtige [[pokemon::Magikarp]] großzuziehen!',
    'Our island is a special place, home to Magikarp patterns that aren\'t found anywhere else in the world! Collect and raise them all to increase your jump power and take on our league champion!': 'Unsere Insel ist ein besonderer Ort, Heimat von [[pokemon::Magikarp]]-Mustern, die man nirgendwo sonst auf der Welt findet! Sammle sie alle und zieh sie groß, um deine Sprungkraft zu steigern und gegen unseren Liga-Champ anzutreten!',
    'There are some singularly stunning individuals down at {ROUTE_NAME}! Some Magikarp with real personality!': 'Unten auf {ROUTE_NAME} gibt es einige einzigartig umwerfende Exemplare! Ein paar [[pokemon::Magikarp]] mit echter Persönlichkeit!',
    'We have been looking for a Shady Salesman.': 'Wir suchen nach einem zwielichtigen Verkäufer.',
    'He is trying to sell overpriced Magikarps to clueless children.': 'Er versucht, ahnungslosen Kindern überteuerte [[pokemon::Magikarp]] anzudrehen.',
    'Please keep an <i>eye</i> open for him.': 'Bitte halte die <i>Augen</i> nach ihm offen.',
    'Welcome to my laboratory!': 'Willkommen in meinem Labor!',
    'Well... it\'s not much of a laboratory yet. I\'m working on several projects to help Magikarps reach their full potential. Can you help me out?': 'Na ja ... so richtig ein Labor ist es noch nicht. Ich arbeite an mehreren Projekten, um [[pokemon::Magikarp]] zu helfen, ihr volles Potenzial zu erreichen. Kannst du mir helfen?',
    'The first step in unlocking this potential will be to formulate the perfect diet. Can you gather some berries for me to experiment with?': 'Der erste Schritt, um dieses Potenzial zu entfesseln, ist die Entwicklung der perfekten Ernährung. Kannst du ein paar Beeren für meine Experimente sammeln?',
    'Thank you for the berries! These should be enough for my experiments.': 'Danke für die Beeren! Die sollten für meine Experimente reichen.',
    'While you were gone, I was working on optimizing the training regimen for Magikarps. According to my calculations, we are missing a LOT of equipment.': 'Während du weg warst, habe ich daran gearbeitet, das Trainingsprogramm für [[pokemon::Magikarp]] zu optimieren. Laut meinen Berechnungen fehlt uns eine MENGE Ausrüstung.',
    'I\'m going to need some sand for sandbags, springs for a jump counter, wood for a pell post, rocks and ice for smashing, a TON of Pokéballs, electricity generation...': 'Ich brauche Sand für Sandsäcke, Federn für einen Sprungzähler, Holz für einen Trainingspfahl, Steine und Eis zum Zertrümmern, eine TONNE Pokébälle, Stromerzeugung ...',
    'There\'s a lot more, but that should get you started.': 'Es gibt noch viel mehr, aber damit kannst du schon mal anfangen.',
    'Wow, that\'s a lot of stuff! This place is starting to look like a proper lab now!': 'Wow, das ist ja eine Menge Zeug! Der Ort sieht langsam aus wie ein richtiges Labor!',
    'I have discovered that a critical part of any Magikarp training program is pushing other Pokémon around in a field. This form of exercise rounds out the muscle groups and really boosts performance.': 'Ich habe herausgefunden, dass ein entscheidender Teil jedes [[pokemon::Magikarp]]-Trainingsprogramms darin besteht, andere Pokémon über ein Feld zu schieben. Diese Übung trainiert alle Muskelgruppen und steigert die Leistung enorm.',
    'According to my calculations, the ideal Pokémon to push around are Dwebble, Boldore, Forretress, Golem, and Steelix. Can you catch or hatch me some?': 'Laut meinen Berechnungen sind die idealen Pokémon zum Herumschieben [[pokemon::Dwebble]], [[pokemon::Boldore]], [[pokemon::Forretress]], [[pokemon::Golem]] und [[pokemon::Steelix]]. Kannst du mir welche fangen oder ausbrüten?',
    'Steer clear of the Alolan version of Golem, its electrical fields are too dangerous to use.': 'Halte dich von der Alola-Form von [[pokemon::Golem]] fern, ihre elektrischen Felder sind zu gefährlich für den Einsatz.',
    'These Pokémon are perfect! I\'ll put them out back in the training fields.': 'Diese Pokémon sind perfekt! Ich bringe sie nach hinten auf die Trainingsfelder.',
    'The last piece of equipment needed is a Tackle Machine. I have a prototype here, but it needs to be calibrated.': 'Das letzte benötigte Ausrüstungsstück ist eine Tackle-Maschine. Ich habe hier einen Prototyp, aber er muss noch kalibriert werden.',
    'Can you take it out for a spin? Defeating a ton of Pokémon should be enough to test it out.': 'Kannst du eine Probefahrt damit machen? Eine Menge Pokémon zu besiegen sollte reichen, um sie zu testen.',
    'Thank you for all your help!': 'Danke für all deine Hilfe!',
    'Now that the laboratory and training program are up and running, I\'ll be very busy!': 'Jetzt, wo das Labor und das Trainingsprogramm laufen, werde ich sehr beschäftigt sein!',
    'Please take this Magikarp as a thank you! Train them for greatness!': 'Bitte nimm dieses [[pokemon::Magikarp]] als Dankeschön! Trainiere sie zu Großem!',
    'Stop right there! This is the sacred land of Magikarp Jump. I can tell there is something suspicious about you... Yeah, I see! You have no Magikarp! How did you even make it this far without the best Pokémon, anyway?': 'Halt, stehen bleiben! Dies ist das heilige Land von Magikarp Jump. Ich merke doch, dass mit dir etwas nicht stimmt ... Ja, jetzt seh ich\'s! Du hast kein [[pokemon::Magikarp]]! Wie bist du überhaupt so weit gekommen ohne das beste Pokémon?',
    'In any case, everyone in town will run away from you until you get yourself a Magikarp. So, go catch one, or fish one at the Pond. Then, the residents may be willing to talk to you.': 'Wie dem auch sei, alle im Ort werden vor dir davonlaufen, bis du dir ein [[pokemon::Magikarp]] besorgst. Also fang dir eins oder angle dir eins am Teich. Dann sind die Bewohner vielleicht bereit, mit dir zu reden.',
    'Kid, I have a deal for you! And for you alone. Here\'s your chance. I will sell you the secret Magikarp... For an unbelievable price.': 'Hey, Kleines, ich hab ein Angebot für dich! Und nur für dich. Das ist deine Chance. Ich verkaufe dir das geheime [[pokemon::Magikarp]] ... zu einem unglaublichen Preis.',
    'Oh, yeah... Returns not accepted, got that?': 'Ach ja ... Umtausch ausgeschlossen, verstanden?',
    'Just as Alola has multiple islands, its dungeons have multiple floors! Hurry to the ladder to find your way to the next floor.': 'So wie Alola aus mehreren Inseln besteht, haben auch seine Dungeons mehrere Stockwerke! Beeil dich und geh zur Leiter, um ins nächste Stockwerk zu gelangen.',
    'Watch the clock, if you make it to the next floor you\'ll get a time boost to help you find the boss.': 'Behalte die Uhr im Auge – wenn du es ins nächste Stockwerk schaffst, bekommst du einen Zeitbonus, der dir hilft, den Boss zu finden.',
    'Good luck with your island challenge!': 'Viel Glück bei deiner Inselwanderschaft!',
    'Greetings. Captain Ilima here. In every locale where a captain holds his or her trials, you will encounter a particularly strong boss, known as a Totem Pokémon. To clear a Trial, all you have to do is defeat these Pokémon!': 'Sei gegrüßt. Hier ist Captain Elima. An jedem Ort, an dem ein Captain seine Prüfung abhält, triffst du auf einen besonders starken Boss, ein sogenanntes Herrscher-Pokémon. Um eine Prüfung zu bestehen, musst du nur diese Pokémon besiegen!',
    'Some Trial Sites are protected by different Pokémon depending on the time of day. The difficulty of each Trial isn\'t affected by these changes, but it makes for quite the interesting observance!': 'Manche Prüfungsorte werden je nach Tageszeit von unterschiedlichen Pokémon beschützt. Die Schwierigkeit der einzelnen Prüfungen ändert sich dadurch nicht, aber es sorgt für recht interessante Beobachtungen!',
    'Nebby! Oh thank goodness you\'re safe. Thank you $playername$, let me heal your Poké- No? Um, very well then.': 'Wölkchen! Oh, ein Glück, dass du in Sicherheit bist. Danke, $playername$, lass mich deine Poké- Nein? Ähm, na gut.',
    'It seems Hau is outside on Route 3. Are you two having another battle?': 'Hau scheint draußen auf Route 3 zu sein. Tragt ihr beiden noch einen Kampf aus?',
    'Nebby! Nebby, come back!': 'Wölkchen! Wölkchen, komm zurück!',
    'Nebby ran off into the meadow here... What if a wild Pokémon attacks it? It doesn\'t have any moves it can use to battle!': 'Wölkchen ist hier in die Wiese gelaufen... Was, wenn es von einem wilden Pokémon angegriffen wird? Es kennt keine Attacken, mit denen es kämpfen könnte!',
    'Hello, $playername$. Are you done with your battle against Hau on Route 3? We should all head back to Iki Town, now.': 'Hallo, $playername$. Bist du mit deinem Kampf gegen Hau auf Route 3 fertig? Wir sollten jetzt alle zurück nach Iki Town gehen.',
    'Hello there, $playername$! Today is a beautiful day for a walk. I found this disk while walking around. I\'m not so sure what it is, but it\'s an interesting find. What brings you here? Oh, you\'re here looking for this disk. Well, I can give it to you if you beat me in battle! What do you say? Fantastic!': 'Hallo, $playername$! Heute ist ein wunderschöner Tag für einen Spaziergang. Ich habe beim Spazierengehen diese Disc gefunden. Ich weiß nicht genau, was das ist, aber es ist ein interessanter Fund. Was führt dich hierher? Oh, du suchst nach dieser Disc. Nun, ich kann sie dir geben, wenn du mich im Kampf besiegst! Was sagst du? Fantastisch!',
    '<i>The Pikachu looks happy playing with all its friends!</i>': '<i>Das [[pokemon::Pikachu]] sieht beim Spielen mit all seinen Freunden glücklich aus!</i>',
    '<i>The Pikachu is waving at you supportively! Its goodwill carries you forward on your journey to Alola Championship!</i>': '<i>Das [[pokemon::Pikachu]] winkt dir aufmunternd zu! Sein Wohlwollen begleitet dich auf deiner Reise zum Champion von Alola!</i>',
    '<i>The Pikachu is staring at you intently! Is it waiting for you to become stronger?</i>': '<i>Das [[pokemon::Pikachu]] starrt dich eindringlich an! Wartet es darauf, dass du stärker wirst?</i>',
    'Hi, $playername$. How are you doing? I\'m not doing so well right now.': 'Hi, $playername$. Wie geht\'s dir? Mir geht es gerade nicht so gut.',
    'Why, you ask? That\'s because I need a lot of Dungeon Tokens to pay for an amazing rod so I can fish for every single water pokémon! Sadly, it costs too much and I can\'t afford it because I have to take care of my sisters. Oh, you can help me? Thank you, but I have nothing to offer in return.': 'Warum, fragst du? Weil ich jede Menge Dungeon-Token brauche, um eine tolle Angel zu bezahlen, mit der ich jedes einzelne Wasser-Pokémon angeln kann! Leider ist sie zu teuer und ich kann sie mir nicht leisten, weil ich mich um meine Schwestern kümmern muss. Oh, du kannst mir helfen? Danke, aber ich habe nichts, was ich dir dafür geben könnte.',
    'Have I a seen a Silvally Memory? Yes, I have. If you want it, I could sell it to you. The price is 125 million Dungeon Tokens. I\'ll be here for a long time, so you can get the Dungeon Tokens and come back later if you need to.': 'Ob ich eine [[pokemon::Silvally]]-Disc gesehen habe? Ja, habe ich. Wenn du sie willst, kann ich sie dir verkaufen. Der Preis beträgt 125 Millionen Dungeon-Token. Ich bin noch lange hier, du kannst also die Dungeon-Token sammeln und später wiederkommen, wenn du willst.',
    'Hey, good to see ya here. How are you doing? I\'m doing well, but I need some Battle Points. I need to get more materials for a school project, but I\'m not sure how I will get Battle Points in Alola, since the Battle Frontier is only in the Hoenn region. And I don\'t know anyone who could get them and deliver them to me.': 'Hey, schön, dich hier zu sehen. Wie geht\'s dir? Mir geht\'s gut, aber ich brauche ein paar Kampfpunkte. Ich muss mehr Material für ein Schulprojekt besorgen, aber ich weiß nicht, wie ich in Alola an Kampfpunkte kommen soll, da es die Kampfzone nur in der Hoenn-Region gibt. Und ich kenne niemanden, der sie besorgen und mir bringen könnte.',
    'Oh, Silvally Memory? The thing that\'s shaped like a disk? I have one right here, but I\'m not sure how it works. Wait, I just got an idea, what about a trade? I\'ll trade the Memory for some Battle Points. I\'ll be here for a while, probably long enough for you to take a trip to the Hoenn region to get some Battle Points.': 'Oh, eine [[pokemon::Silvally]]-Disc? Das Ding, das wie eine Scheibe aussieht? Ich habe hier eine, aber ich weiß nicht genau, wie sie funktioniert. Moment, mir ist gerade eine Idee gekommen: Wie wär\'s mit einem Tausch? Ich tausche die Disc gegen ein paar Kampfpunkte. Ich bin noch eine Weile hier, wahrscheinlich lange genug, damit du einen Ausflug in die Hoenn-Region machen und Kampfpunkte sammeln kannst.',
    'Hey, welcome to the Lush Jungle! How are you doing today? I\'m not so good. I wanted to try a new ingredient to see if it attracts Lurantis, but it costs too much. Like, a lot of Quest Points. I just can\'t afford it.': 'Hey, willkommen im Lush Jungle! Wie geht es dir heute? Mir geht\'s nicht so gut. Ich wollte eine neue Zutat ausprobieren, um zu sehen, ob sie [[pokemon::Lurantis]] anlockt, aber sie ist zu teuer. Also, sie kostet richtig viele Questpunkte. Das kann ich mir einfach nicht leisten.',
    'Oh, you\'re asking if I have a Silvally Memory? You mean from that weird fusion-like Pokémon? Yeah, I do. It has a weird green coloration on it, which weirdly enough reminds me of Pokémon resistant to Electric attacks and weak against Fire attacks.': 'Oh, du fragst, ob ich eine [[pokemon::Silvally]]-Disc habe? Du meinst von diesem seltsamen, fusionsartigen Pokémon? Ja, habe ich. Sie hat eine seltsame grüne Färbung, die mich komischerweise an Pokémon erinnert, die gegen Elektro-Attacken resistent und gegen Feuer-Attacken schwach sind.',
    'How about a trade? I will give you the Memory if you give me some Quest Points, how \'bout that? Ok, I\'ll be here in the Lush Jungle for a while, so you can get Quest Points and come back later to do the trade if you need to.': 'Wie wär\'s mit einem Tausch? Ich gebe dir die Disc, wenn du mir ein paar Questpunkte gibst, was hältst du davon? Ok, ich bin noch eine Weile hier im Lush Jungle, du kannst also Questpunkte sammeln und später für den Tausch wiederkommen, wenn du willst.',
    'Hey, $playername$! How are you doing? I\'ve been doing great, except that my equipment is getting old and rusted. I would like to buy some more, but I don\'t have enough money to buy any right now.': 'Hey, $playername$! Wie geht\'s dir? Mir geht\'s super, nur dass meine Ausrüstung alt und rostig wird. Ich würde gern neue kaufen, aber ich habe gerade nicht genug Geld dafür.',
    'So, how can I help you? Oh, you\'re looking for a Silvally Memory? I have been keeping one of them here and doing a little bit of testing to find out how it works. Maybe we could make a trade. I\'ll trade the Silvally Memory for some Pokédollars. I\'ll be trying to figure out how it works, so you can go get Pokédollars and come back later to trade if you need to.': 'Also, wie kann ich dir helfen? Oh, du suchst eine [[pokemon::Silvally]]-Disc? Ich bewahre hier eine auf und habe ein paar Tests durchgeführt, um herauszufinden, wie sie funktioniert. Vielleicht können wir tauschen. Ich tausche die [[pokemon::Silvally]]-Disc gegen ein paar Pokédollar. Ich versuche weiter herauszufinden, wie sie funktioniert, du kannst also Pokédollar besorgen und später zum Tauschen wiederkommen, wenn du willst.',
    'Mimikyu really cares about its costume.': '[[pokemon::Mimikyu]] liegt sehr viel an seinem Kostüm.',
    'The costume often gets busted in battles. It will then spend all night patching it. Poor thing...': 'Das Kostüm geht in Kämpfen oft kaputt. Dann verbringt es die ganze Nacht damit, es zu flicken. Das arme Ding...',
    'If you defeat enough Mimikyu, you might find one with a busted costume roaming around.': 'Wenn du genug [[pokemon::Mimikyu]] besiegst, findest du vielleicht eines mit kaputtem Kostüm, das herumstreift.',
    'But please leave it alone! It has been through too much already!': 'Aber bitte lass es in Ruhe! Es hat schon genug durchgemacht!',
    'Hey there, $playername$! Have you checked out the trail behind the Thrifty Megamart lately? It\'s been pretty wild! I ventured there the other day and stumbled upon a Mimikyu holding a Silvally Memory. It was quite a challenge to retrieve it, but I managed to befriend it and recover the disk eventually. I love the thrill of exploring new places and discovering new stuff, don\'t you?': 'Hey, $playername$! Hast du dir in letzter Zeit mal den Pfad hinter dem Thrifty Megamart angesehen? Da geht\'s ziemlich wild zu! Ich bin neulich dort gewesen und auf ein [[pokemon::Mimikyu]] gestoßen, das eine [[pokemon::Silvally]]-Disc hielt. Es war eine ziemliche Herausforderung, sie zurückzubekommen, aber schließlich habe ich mich mit ihm angefreundet und die Disc bekommen. Ich liebe den Nervenkitzel, neue Orte zu erkunden und Neues zu entdecken, du nicht auch?',
    'But enough about me, what brings you here? Hmm, I can sense that you have a burning desire for something... Ah, it must be the Silvally Memory I found in the trail, am I right? It was a challenge to befriend that Mimikyu holding it. If you want it, you\'ll have to battle me first! Don\'t worry, I won\'t hold back just because we\'re friends. I want to see what you\'re made of! So, what do you say, ready to face the challenge?': 'Aber genug von mir, was führt dich hierher? Hmm, ich spüre, dass du dir etwas sehnlichst wünschst... Ah, es muss die [[pokemon::Silvally]]-Disc sein, die ich auf dem Pfad gefunden habe, stimmt\'s? Es war eine Herausforderung, mich mit dem [[pokemon::Mimikyu]] anzufreunden, das sie hielt. Wenn du sie willst, musst du erst gegen mich kämpfen! Keine Sorge, ich halte mich nicht zurück, nur weil wir Freunde sind. Ich will sehen, was in dir steckt! Also, was sagst du, bist du bereit für die Herausforderung?',
    'A trial-goer, huh? Figures. Look, I\'m not gonna fight someone who is taking on Team Skull. So...go. Just go.': 'Ein Inselwanderer, was? Hätte ich mir denken können. Hör zu, ich kämpfe nicht gegen jemanden, der es mit Team Skull aufnimmt. Also... geh. Geh einfach.',
    'My house! My car! MY LAWN! What did those Team Skull kids do!?': 'Mein Haus! Mein Auto! MEIN RASEN! Was haben diese Team-Skull-Rüpel nur angestellt!?',
    'Huh? What are you doing in here? A what? Silvally Memory? I think I have what you\'re looking for. Yeah, I have it, if you want to see it. Anyways, I was just passing by and decided to visit this place again.': 'Hä? Was machst du denn hier drin? Eine was? [[pokemon::Silvally]]-Disc? Ich glaube, ich habe, was du suchst. Ja, ich habe sie, wenn du sie sehen willst. Jedenfalls kam ich gerade vorbei und hab beschlossen, diesen Ort mal wieder zu besuchen.',
    'If you need this Memory, let\'s battle. I miss the times when you got in the way of my plans for Team Skull and I used to battle you. I\'m not gonna lose this time.': 'Wenn du diese Disc brauchst, lass uns kämpfen. Ich vermisse die Zeiten, als du meinen Plänen für Team Skull in die Quere kamst und ich immer gegen dich gekämpft habe. Diesmal verliere ich nicht.',
    'So the foundation really was working together with Team Skull? Lillie, Gladion, and Lusamine all are a family?! This is, like, way too mind-blowing to think about right now. $playername$! Let\'s knock some skulls together for now!': 'Die Foundation hat also wirklich mit Team Skull zusammengearbeitet? Lilly, Gladio und Samantha sind alle eine Familie?! Das ist gerade echt zu krass, um darüber nachzudenken. $playername$! Lass uns jetzt erst mal ein paar Schädel zurechtrücken!',
    'Mother! You mustn\'t open the Ultra Wormhole. You cannot let the beasts run wild!': 'Mutter! Du darfst die Ultrapforte nicht öffnen. Du darfst die Bestien nicht frei herumlaufen lassen!',
    '$playername$! Stop the president!!! If we don\'t, Alola will be flooded with beasts!': '$playername$! Halte die Präsidentin auf!!! Wenn wir es nicht tun, wird Alola von Bestien überflutet!',
    'Mother! Do not sacrifice Cosmog for that beast\'s sake! Please... Stop... If Nebby isn\'t— If you make it use up too much of its power... you don\'t understand what will happen! If you use too much of its power, it will die!': 'Mutter! Opfere [[pokemon::Cosmog]] nicht für diese Bestie! Bitte... Hör auf... Wenn Wölkchen nicht— Wenn du es zu viel seiner Kraft verbrauchen lässt... du verstehst nicht, was dann passiert! Wenn du zu viel seiner Kraft benutzt, wird es sterben!',
    'Oh, it\'s you. I thought the professor would help when I put my request up at the Bulletin Board, but the Champion\'s even better.': 'Oh, du bist es. Ich dachte, der Professor würde helfen, als ich meine Anfrage am Schwarzen Brett aufgehängt habe, aber der Champion ist sogar noch besser.',
    'See, my Silvally has been acting strange lately, almost as if it\'s back to being haunted by its traumatizing past, the poor thing. Silvally are unique Pokémon who can download memories from artificial disks to change their type, but my Silvally\'s own memories somehow got mixed in with them. I need to get the disks back and recover its memories. That\'s where you come in.': 'Weißt du, mein [[pokemon::Silvally]] verhält sich in letzter Zeit seltsam, fast als würde es wieder von seiner traumatischen Vergangenheit heimgesucht, das arme Ding. [[pokemon::Silvally]] sind einzigartige Pokémon, die Erinnerungen von künstlichen Discs herunterladen können, um ihren Typ zu ändern, aber die eigenen Erinnerungen meines [[pokemon::Silvally]] haben sich irgendwie mit ihnen vermischt. Ich muss die Discs zurückbekommen und seine Erinnerungen wiederherstellen. Und da kommst du ins Spiel.',
    'Silvally has its memories divided in 17 parts and I lost all of them after traveling with it around Alola. Try talking with citizens of all four islands to find out if they know anything about them. If you help me restore its memories I\'ll maybe give you a reward, but don\'t expect any charity. The memories look like this:': 'Die Erinnerungen von [[pokemon::Silvally]] sind auf 17 Teile verteilt, und ich habe sie alle verloren, als ich mit ihm durch Alola gereist bin. Sprich mit den Bewohnern aller vier Inseln, um herauszufinden, ob sie etwas darüber wissen. Wenn du mir hilfst, seine Erinnerungen wiederherzustellen, gebe ich dir vielleicht eine Belohnung, aber erwarte keine Wohltätigkeit. Die Discs sehen so aus:',
    'Keep an eye out if you come across any of them.': 'Halte die Augen offen, falls du einer davon begegnest.',
    'Hey, I see you\'re back. Did you find any Silvally Memories? Oh, I see you found 4 of them, and in surprisingly relevant places too. Let me give them to Silvally.': 'Hey, wie ich sehe, bist du zurück. Hast du [[pokemon::Silvally]]-Discs gefunden? Oh, du hast 4 davon gefunden, und das an überraschend passenden Orten. Lass sie mich [[pokemon::Silvally]] geben.',
    '<i>Gladion uses the 4 memories on Silvally</i>': '<i>Gladio verwendet die 4 Discs bei [[pokemon::Silvally]]</i>',
    'As for that reward I mentioned, I\'ll put these memories in the Memory Replicator so I can make some Silvally Memories for you. The machine isn\'t powerful enough to create the Memories out of nothing, though. I\'ll be needing you to grab some gems of the Memory\'s type so I can replicate the Memory and insert it into a Silvally for you. It needs some fine-tuning first so the amount needed won\'t be the same after the first trade.': 'Was die Belohnung angeht, die ich erwähnt habe: Ich lege diese Discs in den Disc-Replikator, damit ich ein paar [[pokemon::Silvally]]-Discs für dich herstellen kann. Die Maschine ist allerdings nicht stark genug, um die Discs aus dem Nichts zu erschaffen. Du musst mir ein paar Juwelen vom Typ der Disc besorgen, damit ich die Disc nachbilden und für dich in ein [[pokemon::Silvally]] einsetzen kann. Sie muss erst noch feinjustiert werden, daher wird die benötigte Menge nach dem ersten Tausch nicht dieselbe sein.',
    'Oh and also, I\'ve heard of more sightings of strange disks across the region. I think they might be the Silvally Memories we\'re looking for. If you\'re ever lost, I got descriptions of them.': 'Ach ja, und ich habe von weiteren Sichtungen seltsamer Discs in der Region gehört. Ich glaube, das könnten die [[pokemon::Silvally]]-Discs sein, die wir suchen. Falls du mal nicht weiterweißt, ich habe Beschreibungen davon.',
    'I\'ll let you keep the Memories you\'ve found in the meantime so you keep track of your progress.': 'Die Discs, die du gefunden hast, kannst du in der Zwischenzeit behalten, damit du deinen Fortschritt im Blick behältst.',
    'I see you\'ve recovered more of the Silvally Memories. Thanks for helping me recover them. Silvally appreciates it too. How did it go, getting them back?': 'Wie ich sehe, hast du weitere [[pokemon::Silvally]]-Discs zurückgeholt. Danke, dass du mir hilfst, sie wiederzubekommen. [[pokemon::Silvally]] weiß das auch zu schätzen. Wie lief es, sie zurückzuholen?',
    'You had to <i>pay</i> for them? Wha- How did you even get that much money? Are you rich? I... Never mind. You\'re doing a great job. Buddy\'s feeling better already. What? No, I said Silvally\'s feeling better already. You must be hearing things. Go find those memories.': 'Du musstest für sie <i>bezahlen</i>? Wa- Wie bist du überhaupt an so viel Geld gekommen? Bist du reich? Ich... Vergiss es. Du machst das großartig. Meinem Kumpel geht es schon besser. Was? Nein, ich sagte, [[pokemon::Silvally]] geht es schon besser. Du musst dich verhört haben. Geh und finde diese Discs.',
    'Also I\'m not compensating you.': 'Außerdem werde ich dich nicht entschädigen.',
    'Hey there, $playername$! I gotta say, you\'ve done something truly incredible. You\'ve brought back every single one of Silvally\'s lost memories. I expected nothing less from the Champion. I can\'t even imagine how long all that must have taken you. Silvally\'s back to normal and I can\'t thank you enough.': 'Hey, $playername$! Ich muss sagen, du hast etwas wirklich Unglaubliches geschafft. Du hast jede einzelne verlorene Erinnerung von [[pokemon::Silvally]] zurückgebracht. Vom Champion habe ich nichts anderes erwartet. Ich kann mir nicht einmal vorstellen, wie lange du dafür gebraucht haben musst. [[pokemon::Silvally]] ist wieder ganz das Alte, und ich kann dir gar nicht genug danken.',
    'And... seeing my buddy suffer like that made me consider how many new memories I\'ve been taking for granted... I\'m glad to have met you, Hau... everyone. Like Hau said, people can achieve more if they do something together. Thank you for reminding me of that.': 'Und... meinen Kumpel so leiden zu sehen, hat mir klargemacht, wie viele neue Erinnerungen ich für selbstverständlich gehalten habe... Ich bin froh, dich kennengelernt zu haben, Hau... euch alle. Wie Hau gesagt hat: Menschen können mehr erreichen, wenn sie etwas gemeinsam tun. Danke, dass du mich daran erinnert hast.',
    'I can see what Lillie saw in you now... You\'ve been a true inspiration to me too. I hope our paths cross again someday. Until then... See you around.': 'Jetzt verstehe ich, was Lilly in dir gesehen hat... Du warst auch für mich eine echte Inspiration. Ich hoffe, unsere Wege kreuzen sich eines Tages wieder. Bis dahin... Man sieht sich.',
    'Here are the descriptions of them. You should look for:': 'Hier sind die Beschreibungen. Du solltest suchen nach:',
    'A blue-haired girl near Brooklet Hill,': 'einem blauhaarigen Mädchen beim Brooklet Hill,',
    'A green-haired girl in Lush Jungle,': 'einem grünhaarigen Mädchen im Lush Jungle,',
    'A black and red-haired guy at the Wela Volcano Park,': 'einem Typen mit schwarz-roten Haaren im Wela Volcano Park,',
    'A child with orange hair in the Hokulani Observatory,': 'einem Kind mit orangefarbenen Haaren im Hokulani Observatory,',
    'A dark blue-haired guy that looks like a Veteran inside Mount Lanakila,': 'einem dunkelblauhaarigen Typen, der wie ein Veteran aussieht, im Mount Lanakila,',
    'And a girl with a Mudsdale on Exeggutor Island Hill.': 'und einem Mädchen mit einem [[pokemon::Mudsdale]] auf dem Exeggutor Island Hill.',
    'For the next set of memories I\'ve been keeping an ear out and have heard some rumors:': 'Für die nächsten Discs habe ich die Ohren offen gehalten und ein paar Gerüchte gehört:',
    'People from Ula\'ula have seen Guzma walking around Po Town, so I suspect he might\'ve found a Silvally Memory. Go ask him in Po Town.': 'Leute aus Ula\'ula haben Bromley in Po Town herumlaufen sehen, deshalb vermute ich, dass er eine [[pokemon::Silvally]]-Disc gefunden haben könnte. Frag ihn in Po Town.',
    'Melemele Island inhabitants have seen Kahili taking daily walks on Ten Carat Hill, she might\'ve found a Silvally Memory during one of those walks.': 'Bewohner von Melemele Island haben gesehen, wie Kahili täglich auf dem Ten Carat Hill spazieren geht. Sie könnte bei einem dieser Spaziergänge eine [[pokemon::Silvally]]-Disc gefunden haben.',
    'Some people from Poni Island have seen Plumeria walking around with some old Team Skull grunts around the Vast Poni Canyon. That is really suspicious, so they probably found something rare or presumably a Silvally Memory.': 'Ein paar Leute von Poni Island haben Fuchsia mit einigen ehemaligen Team-Skull-Rüpeln im Vast Poni Canyon herumlaufen sehen. Das ist wirklich verdächtig, also haben sie wahrscheinlich etwas Seltenes gefunden, vermutlich eine [[pokemon::Silvally]]-Disc.',
    'Ula\'ula Island people have seen Captain Acerola inside the Thrifty Megamart with a Mimikyu carrying a disk-shaped item, which I suspect is a Silvally Memory.': 'Leute von Ula\'ula Island haben Captain Lola im Thrifty Megamart mit einem [[pokemon::Mimikyu]] gesehen, das einen scheibenförmigen Gegenstand trug, bei dem ich eine [[pokemon::Silvally]]-Disc vermute.',
    'Some people from Akala Island have seen some people in white suits with a lot of boxes travelling to the southwest of the island.': 'Ein paar Leute von Akala Island haben Leute in weißen Anzügen mit vielen Kisten gesehen, die in den Südwesten der Insel unterwegs waren.',
    'I\'ve heard Molayne wanted to brush up on his training a bit. He\'s at the Royal Avenue, and he\'s also offering a strange reward which I presume is a Silvally Memory.': 'Ich habe gehört, dass Molayne sein Training etwas auffrischen wollte. Er ist an der Royal Avenue und bietet außerdem eine seltsame Belohnung an, bei der ich eine [[pokemon::Silvally]]-Disc vermute.',
    'Also, while I was walking near A Tree Maybe I saw a guy dressed almost like an old Pokémon that doesn\'t exist anymore with a Silvally Memory.': 'Außerdem habe ich, als ich in der Nähe von A Tree Maybe unterwegs war, einen Typen mit einer [[pokemon::Silvally]]-Disc gesehen, der fast wie ein altes Pokémon gekleidet war, das es nicht mehr gibt.',
    'They are all tough trainers, so you might need to train more to defeat them.': 'Sie alle sind starke Trainer, du musst also vielleicht mehr trainieren, um sie zu besiegen.',
    'I\'d seen it in a movie... this man singing and dancing in the rain. I had to try it for myself. Mother was so shocked that she ran right out after me. And then...she smiled... and danced with me. But... then she changed. And I couldn\'t do anything...': 'Ich hatte es in einem Film gesehen... dieser Mann, der im Regen sang und tanzte. Ich musste es selbst ausprobieren. Mutter war so schockiert, dass sie mir sofort hinterherlief. Und dann... lächelte sie... und tanzte mit mir. Aber... dann hat sie sich verändert. Und ich konnte nichts tun...',
    'But you know what $playername$? Every time in this journey, you\'ve shown me that it\'s possible... to do something.': 'Aber weißt du was, $playername$? Auf dieser Reise hast du mir jedes Mal gezeigt, dass es möglich ist... etwas zu tun.',
    'I don\'t know if it will really summon the Legendary Pokémon, but we can at least try! Thank you for coming this far with me, $playername$!': 'Ich weiß nicht, ob es das Legendäre Pokémon wirklich herbeirufen wird, aber wir können es zumindest versuchen! Danke, dass du mich so weit begleitet hast, $playername$!',
    'Hey, $playername$. How\'s it going? Looking for a rematch, or did you come here explore the Poni Island secrets? Oh, I see. You\'re looking for a Silvally Memory. I found a memory in the ground here, so I took it and studied it a bit. All I could find out is that it was from some Silvally. I also found another memory while helping Mina out with her trial. I gave it to her, but I\'m not sure if she found out how it works.': 'Hey, $playername$. Wie läuft\'s? Suchst du einen Rückkampf, oder bist du hier, um die Geheimnisse von Poni Island zu erkunden? Oh, verstehe. Du suchst eine [[pokemon::Silvally]]-Disc. Ich habe hier im Boden eine Disc gefunden, also habe ich sie mitgenommen und ein bisschen untersucht. Ich konnte nur herausfinden, dass sie von irgendeinem [[pokemon::Silvally]] stammt. Ich habe auch noch eine Disc gefunden, als ich Mina bei ihrer Prüfung geholfen habe. Die habe ich ihr gegeben, aber ich weiß nicht, ob sie herausgefunden hat, wie sie funktioniert.',
    'Anyway. Can I ask you something? Do you know any farmers? I\'m needing to plant more palm trees around here on Exeggutor Island but I don\'t have enough Farm Points to buy all the seeds I need. If I got in contact with a farmer I could get them for much cheaper or even free! Oh? You know how to use the Farm? So that means you have a lot of Farm Points, right? Good! How about you give me some of those Farm Points for this Silvally Memory? Ok, I\'ll be here taking care of the Exeggutor for a while so you can come and visit me anytime to do this trade.': 'Wie auch immer. Darf ich dich etwas fragen? Kennst du irgendwelche Bauern? Ich muss hier auf Exeggutor Island mehr Palmen pflanzen, aber ich habe nicht genug Farmpunkte, um alle Samen zu kaufen, die ich brauche. Wenn ich mit einem Bauern in Kontakt käme, könnte ich sie viel billiger oder sogar umsonst bekommen! Oh? Du weißt, wie man die Farm benutzt? Dann hast du also jede Menge Farmpunkte, oder? Gut! Wie wäre es, wenn du mir ein paar dieser Farmpunkte für diese [[pokemon::Silvally]]-Disc gibst? Ok, ich kümmere mich noch eine Weile hier um die [[pokemon::Exeggutor]], du kannst mich also jederzeit besuchen, um den Tausch zu machen.',
    'People cannot survive all on their own. They have got to help one another out. Same for Pokémon, too. That is what my grandfather used to say.': 'Menschen können nicht ganz allein überleben. Sie müssen einander helfen. Dasselbe gilt auch für Pokémon. Das hat mein Großvater immer gesagt.',
    '$playername$... you have done well in guiding Lillie. The path to the shrine is through the canyon.': '$playername$... du hast Lilly gut geführt. Der Weg zum Schrein führt durch den Canyon.',
    'Look at the two of you. I think this might just work out. No, I am quite sure of it!': 'Seht euch beide an. Ich glaube, das könnte tatsächlich klappen. Nein, ich bin mir ganz sicher!',
    'Well, hey! Look who we have here! It\'s the Champ, wandering all the way into Vast Poni Canyon! You gotta have guts to do that, kid. Not many trainers dare to challenge this place.': 'Na, hey! Sieh mal einer an, wer da ist! Der Champ, der bis in den Vast Poni Canyon spaziert! Dafür braucht man Mumm, Kleines. Nicht viele Trainer wagen es, sich diesem Ort zu stellen.',
    'Let me guess, you\'re after this Silvally Memory I found around here, aren\'t you? I can tell by the way you carry yourself. You\'re not like the rest of the tourists and challengers who come here just for a sightseeing or a battle. You\'re on a mission, right?': 'Lass mich raten, du bist hinter dieser [[pokemon::Silvally]]-Disc her, die ich hier gefunden habe, stimmt\'s? Das erkenne ich an deinem Auftreten. Du bist nicht wie die anderen Touristen und Herausforderer, die nur für eine Besichtigung oder einen Kampf herkommen. Du hast eine Mission, oder?',
    'If you want it that bad, you gotta earn it. I won\'t just hand it over to you. I\'m starting from scratch as a Pokémon Trainer and doing it right this time, so you gotta show me what you\'re made of, in a battle. You and your Pokémon against me and mine! Are you up for the challenge, kid?': 'Wenn du sie so dringend willst, musst du sie dir verdienen. Ich gebe sie dir nicht einfach so. Ich fange als Pokémon-Trainerin wieder bei null an und mache es diesmal richtig, also musst du mir in einem Kampf zeigen, was in dir steckt. Du und deine Pokémon gegen mich und meine! Stellst du dich der Herausforderung, Kleines?',
    'It\'s been a while. You must be a formidable Trainer indeed if you are able to get Necrozma as one of your allies.': 'Lange nicht gesehen. Du musst wirklich ein beeindruckender Trainer sein, wenn du [[pokemon::Necrozma]] zu einem deiner Verbündeten machen konntest.',
    'Good! And this is from me! The Ultra Recon Squad asked me to develop a device that would be able to control Necrozma. But I improved it to my own liking! And now it is a device that makes it possible to draw out even more power from Necrozma!': 'Gut! Und das hier ist von mir! Der Ultra-Erkundungstrupp hat mich gebeten, ein Gerät zu entwickeln, mit dem man [[pokemon::Necrozma]] kontrollieren kann. Aber ich habe es nach meinen eigenen Vorstellungen verbessert! Und jetzt ist es ein Gerät, das es ermöglicht, noch mehr Kraft aus [[pokemon::Necrozma]] herauszuholen!',
    'Yes, in short, it makes it possible for Necrozma to fuse with the light of the Legendary Pokémon Solgaleo! This is the Colress Machine No. 1198, officially dubbed the N-Solarizer!': 'Ja, kurz gesagt ermöglicht es [[pokemon::Necrozma]], mit dem Licht des Legendären Pokémon [[pokemon::Solgaleo]] zu fusionieren! Das ist die Achromas-Maschine Nr. 1198, offiziell N-Solarisator genannt!',
    'In addition, this is the Colress Machine No. 1199, officially dubbed the N-Lunarizer! It makes it possible for Necrozma to fuse with the light of the Legendary Pokémon, Lunala!': 'Außerdem ist das hier die Achromas-Maschine Nr. 1199, offiziell N-Lunarisator genannt! Sie ermöglicht es [[pokemon::Necrozma]], mit dem Licht des Legendären Pokémon [[pokemon::Lunala]] zu fusionieren!',
    'If you wish to make use of them, you will require light from Solgaleo and Lunala respectively. I believe that they may drop the crystallised form of this light if you defeat them in battle! I believe each of them will be able to make good use of their own light, as well.': 'Wenn du sie nutzen möchtest, benötigst du das Licht von [[pokemon::Solgaleo]] beziehungsweise [[pokemon::Lunala]]. Ich glaube, sie lassen vielleicht die kristallisierte Form dieses Lichts fallen, wenn du sie im Kampf besiegst! Ich glaube, jedes von ihnen wird sein eigenes Licht ebenfalls gut nutzen können.',
    'I believe Necrozma may drop a crystal of its own light, as well. Although I doubt it can make any use of it in its current state. Perhaps if it was already fused with the light of Solgaleo or Lunala....': 'Ich glaube, auch [[pokemon::Necrozma]] könnte einen Kristall seines eigenen Lichts fallen lassen. Allerdings bezweifle ich, dass es in seinem jetzigen Zustand etwas damit anfangen kann. Vielleicht, wenn es bereits mit dem Licht von [[pokemon::Solgaleo]] oder [[pokemon::Lunala]] fusioniert wäre....',
    'At any rate, I believe that a Trainer like you will be able to use both Alola\'s Legendary Pokémon and the fearsome power of Necrozma properly! I happen to know quite a bit about Pokémon fusion myself... But that is a different tale. Good luck in your battles!': 'Jedenfalls glaube ich, dass ein Trainer wie du sowohl die Legendären Pokémon Alolas als auch die furchterregende Kraft von [[pokemon::Necrozma]] richtig einsetzen kann! Ich weiß selbst zufällig einiges über Pokémon-Fusionen... Aber das ist eine andere Geschichte. Viel Glück bei deinen Kämpfen!',
    'Hey, $playername$. Looking for a battle? Hm, ok. Can I say something to you anyway? It will be quick. I want to propose to my girlfriend, but I can\'t afford the ring she really wants. It\'s so expensive, and I feel guilty not being able to give her what she deserves. I don\'t know what to do! Maybe I could pick up some extra work to hire more Miners for some Diamonds.': 'Hey, $playername$. Suchst du einen Kampf? Hm, ok. Darf ich dir trotzdem etwas sagen? Es geht schnell. Ich möchte meiner Freundin einen Heiratsantrag machen, aber ich kann mir den Ring nicht leisten, den sie unbedingt will. Er ist so teuer, und ich fühle mich schuldig, ihr nicht geben zu können, was sie verdient. Ich weiß nicht, was ich tun soll! Vielleicht könnte ich zusätzliche Arbeit annehmen, um mehr Bergarbeiter für ein paar Diamanten anzuheuern.',
    'Anyway what did you want to ask me? Hmm, if I\'ve seen a Silvally Memory anywhere near? Sure, it\'s in my pocket right here. It even is coloured like a diamond! I wish I could trade it for some... hm? You\'re asking if we could do a trade? Sure, I\'ll sell it to you for 100,000 Diamonds, so I can buy my lovely fiancée-to-be an engagement ring. I\'ll always be here in the same place at all times, we can trade anytime you want.': 'Wie auch immer, was wolltest du mich fragen? Hmm, ob ich hier in der Nähe eine [[pokemon::Silvally]]-Disc gesehen habe? Klar, sie ist hier in meiner Tasche. Sie ist sogar gefärbt wie ein Diamant! Ich wünschte, ich könnte sie gegen ein paar... hm? Du fragst, ob wir tauschen könnten? Klar, ich verkaufe sie dir für 100,000 Diamanten, damit ich meiner lieben Bald-Verlobten einen Verlobungsring kaufen kann. Ich bin immer hier am selben Ort, wir können tauschen, wann immer du willst.',
    'Oh... Oh, thank goodness! So...you\'re also one of the professor\'s acquaintances? It\'s nice to meet you...': 'Oh... Oh, ein Glück! Also... du bist auch ein Bekannter des Professors? Freut mich, dich kennenzulernen...',
    'I am so grateful to you for helping us out of that dangerous spot. Come on. Into the bag, Nebby.': 'Ich bin dir so dankbar, dass du uns aus dieser gefährlichen Lage geholfen hast. Komm. Ab in die Tasche, Wölkchen.',
    'Oh...um...yes! You can call me Lillie. I know it\'s too much for me to ask it, but... Do you think you could see us back to town?': 'Oh... ähm... ja! Du kannst mich Lilly nennen. Ich weiß, es ist zu viel verlangt, aber... Meinst du, du könntest uns zurück in die Stadt begleiten?',
    'So you will be taking part in the festival battle? I\'ll be sure to watch you and Hau.': 'Du nimmst also am Kampf beim Fest teil? Ich werde dir und Hau auf jeden Fall zusehen.',
    'H-help... Save Nebby!': 'H-Hilfe... Rette Wölkchen!',
    'Please... Don\'t tell anyone about this... About seeing Nebby... It\'s...it\'s a secret, OK?': 'Bitte... Erzähl niemandem davon... Dass du Wölkchen gesehen hast... Es ist... es ist ein Geheimnis, OK?',
    'I work as Professor Kukui\'s assistant. He\'s told me to show you around the island, so come along now.': 'Ich arbeite als Assistentin von Professor Kukui. Er hat mich gebeten, dir die Insel zu zeigen, also komm jetzt mit.',
    'Nebby seems fond of the ruins for some reason, so I keep visiting them and hoping that maybe I will find some clue to help it get back to its home... But I don\'t have any idea how to do that...': 'Wölkchen scheint die Ruinen aus irgendeinem Grund zu mögen, deshalb besuche ich sie immer wieder in der Hoffnung, vielleicht einen Hinweis zu finden, der ihm hilft, nach Hause zurückzukehren... Aber ich habe keine Ahnung, wie ich das anstellen soll...',
    '$playername$ if it\'s all right with you, I think Nebby and I would like to watch your Grand Trial.': '$playername$, wenn es dir recht ist, würden Wölkchen und ich gern bei deiner großen Prüfung zuschauen.',
    'My grandfather died suddenly some years back, and we were left without a kahuna on Poni. So I set out on my own sort of island challenge, traveling Alola and trying to grow stronger. Lillie. The kahuna you wished to meet is now here.': 'Mein Großvater ist vor einigen Jahren plötzlich gestorben, und Poni stand ohne Inselkönig da. Also bin ich zu meiner eigenen Art Inselwanderschaft aufgebrochen, bin durch Alola gereist und habe versucht, stärker zu werden. Lilly. Die Inselkönigin, die du treffen wolltest, ist jetzt hier.',
    'There is a ceremony held for the Legendary Pokémon at the Altar of the Sunne and Moone that uses two particular flutes. Ho! You already have the one. The other is said to be held on Exeggutor Island.': 'Für das Legendäre Pokémon wird am Altar of the Sunne and Moone eine Zeremonie abgehalten, bei der zwei bestimmte Flöten verwendet werden. Oh! Die eine hast du ja schon. Die andere soll sich auf Exeggutor Island befinden.',
    'Don’t go too far into the Slumbering Weald.': 'Geh nicht zu weit in den Slumbering Weald.',
    'I’ve heard there are some very strong Pokémon in there.': 'Ich habe gehört, dass es dort drin sehr starke Pokémon gibt.',
    'Only those who beat the champion are strong enough to face them!': 'Nur wer den Champion besiegt hat, ist stark genug, um sich ihnen zu stellen!',
    'You have received a Mystery Gift for completing the National Shiny Dex!': 'Du hast ein Geheimgeschenk für das Vervollständigen des nationalen Schillernd-Dex erhalten!',
    'There are some areas around Galar that you can only reach after beating the Champion.': 'Es gibt einige Gebiete in Galar, die du erst erreichen kannst, nachdem du den Champion besiegt hast.',
    'One is an island paradise, the other a freezing wasteland.': 'Das eine ist ein Inselparadies, das andere eine eisige Ödnis.',
    'I’m sure if you go to these places you’ll find many unique and powerful Pokémon!': 'Ich bin sicher, wenn du diese Orte besuchst, findest du viele einzigartige und starke Pokémon!',
    'I’ve heard there’s been sightings of a never-before-seen, super strong Pokémon on {ROUTE_NAME}! You should go check it out!': 'Ich habe gehört, dass auf {ROUTE_NAME} ein nie zuvor gesehenes, super starkes Pokémon gesichtet wurde! Du solltest es dir ansehen!',
    'We know all the Wishing Stars that Chairman Rose had gathered are here. We celebrities have an advanced level of insight into such things!': 'Wir wissen, dass alle Wunschsterne, die Präsident Rose gesammelt hatte, hier sind. Wir Berühmtheiten haben in solchen Dingen eine überragende Einsicht!',
    'You non-celebrities are not suited to having such valuable things. Hand them over to us.': 'Ihr Nicht-Berühmtheiten seid nicht geeignet, solch wertvolle Dinge zu besitzen. Gib sie uns.',
    'You wish to keep them from us? No matter. This time we\'ve brought much stronger Pokémon to thoroughly trounce you with!': 'Du willst sie uns vorenthalten? Egal. Diesmal haben wir viel stärkere Pokémon mitgebracht, um dich vernichtend zu schlagen!',
    'There are many Pokémon in Galar that I heard look completely different in other regions of the world! They can also evolve in unique ways!': 'Ich habe gehört, dass es in Galar viele Pokémon gibt, die in anderen Regionen der Welt völlig anders aussehen! Sie können sich auch auf einzigartige Weise entwickeln!',
    'I know that reckless one, Linoone, will only evolve during the night time here. But, I also think I’ve seen its evolution wandering across the lake if you have a way to cross.': 'Ich weiß, dass sich dieses ungestüme [[pokemon::Linoone]] hier nur nachts entwickelt. Aber ich glaube auch, dass ich seine Entwicklung über den See wandern sehen habe, falls du eine Möglichkeit hast, ihn zu überqueren.',
    'Milcery can evolve when you spin around with it, while treating it to a Sweet.': '[[pokemon::Milcery]] kann sich entwickeln, wenn du dich mit ihm im Kreis drehst, während du ihm eine Zuckerzier gibst.',
    'For example, you can whip up a Vanilla Alcremie, by spinning clockwise for less than 5 seconds, during the day. Piece of cake! There’s a unique form for each Sweet under this circumstance, so bake it till you make it!': 'Du kannst zum Beispiel ein Vanille-[[pokemon::Alcremie]] zaubern, indem du dich tagsüber weniger als 5 Sekunden im Uhrzeigersinn drehst. Ein Kinderspiel! Unter diesen Umständen gibt es für jede Zuckerzier eine einzigartige Form, also back weiter, bis es klappt!',
    'There are more tiers to Alcremie than I can count. Mix up the direction, duration, time of day, and the given Sweet to discover all the flavours there are to find.': 'Es gibt mehr Varianten von [[pokemon::Alcremie]], als ich zählen kann. Variiere Richtung, Dauer, Tageszeit und die gegebene Zuckerzier, um alle Geschmacksrichtungen zu entdecken.',
    'I will suggest that you only do 3 spins a day if you don’t want to end up sick! You might be able to try more, when you get more experienced with a flavour...': 'Ich empfehle dir, nur 3 Drehungen am Tag zu machen, wenn dir nicht schlecht werden soll! Vielleicht kannst du mehr versuchen, wenn du mit einer Geschmacksrichtung erfahrener bist...',
    'Stop by the Battle Café, we sell all the Sweets you’ll need!': 'Schau im Battle Café vorbei, wir verkaufen alle Zuckerzierden, die du brauchst!',
    'My Kantonian Farfetch’d would never evolve no matter how many fresh Leeks I gave it.': 'Mein Kanto-[[pokemon::Farfetch\'d]] wollte sich nie entwickeln, egal wie viele frische Lauchstangen ich ihm gab.',
    'Lo and behold, here in Galar the Farfetch’d wield thick, tough leeks for battle!': 'Und siehe da, hier in Galar schwingen die [[pokemon::Farfetch\'d]] dicke, zähe Lauchstangen im Kampf!',
    'Once my Galarian Farfetch’d was holding a Leek.. Blimey, I was surprised how quickly he transformed into a noble ally! With the Leek growing into a mighty stalk for battle!': 'Als mein [[pokemon::Galarian Farfetch\'d]] einmal eine Lauchstange trug... Donnerwetter, ich war überrascht, wie schnell es sich in einen edlen Verbündeten verwandelte! Und die Lauchstange wurde zu einem mächtigen Stängel für den Kampf!',
    'I love Sweet and Tart Apples! Oh, this is Applin! He isn’t a snack, but helps me make all sorts of dishes!': 'Ich liebe Süße Äpfel und Saure Äpfel! Oh, das ist [[pokemon::Applin]]! Er ist kein Snack, sondern hilft mir, alle möglichen Gerichte zuzubereiten!',
    'Applin absolutely loves Sweet and Tart treats.': '[[pokemon::Applin]] liebt süße und saure Leckereien über alles.',
    'But, I could never give Applin a Sweet or Tart Apple, that just seems so... wrong...': 'Aber ich könnte [[pokemon::Applin]] niemals einen Süßen oder Sauren Apfel geben, das fühlt sich einfach so... falsch an...',
    'I can’t be missing out on much anyways, what could be more perfect than my Applin!': 'Ich verpasse sowieso nicht viel, was könnte perfekter sein als mein [[pokemon::Applin]]!',
    'The Pokémon in the Wild Area are very finicky, and many of them only appear in certain weathers.': 'Die Pokémon in der Naturzone sind sehr wählerisch, und viele von ihnen erscheinen nur bei bestimmtem Wetter.',
    'I\'ve also heard that the Pokémon in the Isle of Armor to the East, and the Crown Tundra to the South, are also like this.': 'Ich habe auch gehört, dass die Pokémon auf der Isle of Armor im Osten und in der Crown Tundra im Süden genauso sind.',
    'There are even some Pokémon, namely Cramorant and Eiscue, that only appear in certain forms depending on weather.': 'Es gibt sogar einige Pokémon, nämlich [[pokemon::Cramorant]] und [[pokemon::Eiscue]], die je nach Wetter nur in bestimmten Formen erscheinen.',
    '<i>It’s Stow-on-Side’s famous mural.</i>': '<i>Das ist das berühmte Wandbild von Stow-on-Side.</i>',
    '<i>It’s said to be a very deep work of art...</i>': '<i>Es soll ein sehr tiefgründiges Kunstwerk sein...</i>',
    '<i>It’s the statues that were hidden behind Stow-on-Side’s famous mural.</i>': '<i>Das sind die Statuen, die hinter dem berühmten Wandbild von Stow-on-Side verborgen waren.</i>',
    '<i>They depict two heroes and two Pokémon.</i>': '<i>Sie zeigen zwei Helden und zwei Pokémon.</i>',
    'I\'ve been studying the Galarian form of Yamask.': 'Ich habe die Galar-Form von [[pokemon::Yamask]] untersucht.',
    'It seems they do not evolve into Galarian Cofagrigus, but a completely different Pokémon instead.': 'Es scheint, dass sie sich nicht zu einem Galar-[[pokemon::Cofagrigus]] entwickeln, sondern stattdessen zu einem völlig anderen Pokémon.',
    'For some mysterious reason, they only evolve when trained in a specific area of the wild area known as the Dusty Bowl.': 'Aus irgendeinem mysteriösen Grund entwickeln sie sich nur, wenn sie in einem bestimmten Bereich der Naturzone trainiert werden, der als Dusty Bowl bekannt ist.',
    'Not a brilliant turn of events, but the ruins were brought into the light for us to see...': 'Keine glänzende Wendung der Ereignisse, aber die Ruinen wurden ans Licht gebracht, damit wir sie sehen können...',
    'What does this tell us about Galar’s legends? More than any hero, there’s those things that appear to be Pokémon that stand out!': 'Was sagt uns das über die Legenden Galars? Mehr als jeder Held stechen diese Wesen hervor, die wie Pokémon aussehen!',
    'Not just that, but those Pokémon appear to be holding a sword and shield as if they were using them!': 'Und nicht nur das, diese Pokémon scheinen ein Schwert und einen Schild zu halten, als würden sie sie benutzen!',
    'More than any statue of a hero or old tapestry, these ruins made in truly ancient times must show us the real truth.': 'Mehr als jede Heldenstatue oder jeder alte Wandteppich müssen diese Ruinen aus wahrhaft uralten Zeiten uns die wirkliche Wahrheit zeigen.',
    'Seems like at some point in history the sword and shield were combined with the two actual Pokémon and treated as the same thing...': 'Es scheint, als wären Schwert und Schild irgendwann in der Geschichte mit den beiden eigentlichen Pokémon verschmolzen und als dasselbe angesehen worden...',
    'Two young heroes... The sword and shield were actually Pokémon... But why would the truth of these ruins be hidden when their stories were depicted in artwork?': 'Zwei junge Helden... Schwert und Schild waren eigentlich Pokémon... Aber warum sollte die Wahrheit dieser Ruinen verborgen werden, wenn ihre Geschichten in Kunstwerken dargestellt wurden?',
    'Have you spotted a blue bird walking around with an Arrokuda in its throat? It’s quite a daft Pokémon, but it sure is hungry! I guess if it trains near water it tries to swallow Arrokudas, but they always get stuck in its throat.': 'Hast du einen blauen Vogel herumlaufen sehen, der ein [[pokemon::Arrokuda]] im Hals stecken hat? Es ist ein ziemlich dämliches Pokémon, aber hungrig ist es auf jeden Fall! Ich schätze, wenn es in der Nähe von Wasser trainiert, versucht es, [[pokemon::Arrokuda]] zu verschlucken, aber die bleiben ihm immer im Hals stecken.',
    'My mate told me a story of a Pikachu getting lodged in the gluttonous bird’s gullet while it was gorging in a thunderstorm! But that sounds ridiculous! How would it not be bothered by the big rat in its throat? It would drive me mad.': 'Mein Kumpel hat mir erzählt, dass ein [[pokemon::Pikachu]] im Schlund des gefräßigen Vogels stecken geblieben ist, als der sich bei einem Gewitter vollgefressen hat! Aber das klingt lächerlich! Wie könnte ihn die große Ratte im Hals nicht stören? Mich würde das wahnsinnig machen.',
    '<i>The ancient Hero’s Bath.</i>': '<i>Das uralte Heldenbad.</i>',
    '<i>They say this is where the two heroes came to soothe their wounds after the battle to bring down that evil presence, long ago.</i>': '<i>Man sagt, hier kamen die beiden Helden vor langer Zeit her, um ihre Wunden zu lindern, nachdem sie im Kampf jene böse Macht besiegt hatten.</i>',
    'I caught this Snom on Steamdrift Way and we’ve become really good mates.': 'Ich habe dieses [[pokemon::Snom]] auf dem Steamdrift Way gefangen, und wir sind richtig gute Kumpels geworden.',
    'I thought that friendship was all Snom needed to evolve, but I kept trying to give it a Soothe Bell during the day and nothing happened!': 'Ich dachte, Freundschaft wäre alles, was [[pokemon::Snom]] zur Entwicklung braucht, aber ich habe immer wieder versucht, ihm tagsüber eine Sanftglocke zu geben, und nichts ist passiert!',
    'I’m too busy playing gigs to scamper around with Snom in the evening!': 'Ich bin zu sehr mit meinen Auftritten beschäftigt, um abends mit [[pokemon::Snom]] herumzutollen!',
    'Based on the statues the sword and shield must have actually been two Pokémon, right?': 'Den Statuen nach müssen Schwert und Schild eigentlich zwei Pokémon gewesen sein, oder?',
    'You remember the Pokémon we met in the Slumbering Weald?': 'Erinnerst du dich an die Pokémon, denen wir im Slumbering Weald begegnet sind?',
    'Do you think...it could’ve been one of them? I mean the sword or the shield Pokémon?': 'Meinst du... es könnte eines von ihnen gewesen sein? Ich meine, das Schwert- oder das Schild-Pokémon?',
    'Perhaps when their duty was completed, they went into some kind of sleep?': 'Vielleicht sind sie, als ihre Aufgabe erfüllt war, in eine Art Schlaf gefallen?',
    'Hmm... Who exactly were the heroes that bathed here?': 'Hmm... Wer genau waren die Helden, die hier gebadet haben?',
    'Nowadays only Pokémon really use the Hero’s Bath...': 'Heutzutage nutzen eigentlich nur noch Pokémon das Heldenbad...',
    'I think I’ll have to look more into the history of the Slumbering Weald.': 'Ich glaube, ich muss mich näher mit der Geschichte des Slumbering Weald beschäftigen.',
    'Our Marnie’s Morpeko is so cute, don’tcha think?': 'Das [[pokemon::Morpeko]] unserer Mary ist so süß, findest du nicht?',
    'When it’s hungry, though, it gets so angry it changes forms.': 'Wenn es hungrig ist, wird es aber so wütend, dass es seine Form ändert.',
    'If you want to catch it in that form, you would probably be best trying to attract it with a berry that electric Pokémon like.': 'Wenn du es in dieser Form fangen willst, versuchst du am besten, es mit einer Beere anzulocken, die Elektro-Pokémon mögen.',
    'This might sound cheesy, but I love Milcery so much! I wasn\'t sure which Alcremie form I liked the most, so I just grabbed a Sweet at random and started to spin and spin for what seemed like an hour.': 'Das klingt vielleicht kitschig, aber ich liebe [[pokemon::Milcery]] so sehr! Ich wusste nicht, welche [[pokemon::Alcremie]]-Form mir am besten gefällt, also habe ich einfach zufällig eine Zuckerzier genommen und mich gedreht und gedreht, gefühlt eine Stunde lang.',
    'I saw my partner liked it a lot! Maybe you should try the same one day!': 'Ich habe gesehen, dass es meinem Partner sehr gefallen hat! Vielleicht solltest du das auch mal ausprobieren!',
    'Hello there, Leon! Just letting you know...': 'Hallo, Delion! Nur damit du Bescheid weißt...',
    'I think it\'s time I brought about the Darkest Day. For the sake of Galar\'s future, of course!': 'Ich denke, es ist an der Zeit, den Dunkelsten Tag herbeizuführen. Für die Zukunft Galars, versteht sich!',
    'But I\'m in a bit of a pickle. The energy released by the Darkest Day is too much for us to contain.': 'Aber ich stecke ein wenig in der Klemme. Die Energie, die der Dunkelste Tag freisetzt, ist zu viel, als dass wir sie eindämmen könnten.',
    'I\'m sorry it\'s come to this. But it\'s you who forced my hand, Leon. You refused to listen!': 'Es tut mir leid, dass es so weit gekommen ist. Aber du hast mich dazu gezwungen, Delion. Du wolltest ja nicht zuhören!',
    'That video stream... That was from Hammerlocke Stadium, right? What in the world did the chairman do...?': 'Diese Videoübertragung... Die kam aus dem Hammerlocke Stadium, oder? Was um alles in der Welt hat der Präsident getan...?',
    'I want to help my brother! I\'ve got to! But I can\'t even manage to beat you, so what sort of help could I ever be...?': 'Ich will meinem Bruder helfen! Ich muss! Aber ich schaffe es nicht mal, dich zu besiegen, also was für eine Hilfe könnte ich schon sein...?',
    'Hold the phone... The chairman was talking about the Darkest Day. That\'s the thing where the sky went all dark once, ages and ages ago, right? What does he mean, he\'s bringing that about? And where did we even hear that name...?': 'Moment mal... Der Präsident hat vom Dunkelsten Tag gesprochen. Das ist doch das, als der Himmel vor Ewigkeiten mal ganz dunkel wurde, oder? Was meint er damit, dass er das herbeiführt? Und wo haben wir diesen Namen überhaupt gehört...?',
    'Ah! That statue of the hero in Motostoke! Sonia said something back then, didn\'t she... Though it turned out to be wrong, since there were actually two heroes and all that.': 'Ah! Diese Heldenstatue in Motostoke! Sonia hat damals etwas gesagt, oder nicht... Auch wenn es sich als falsch herausgestellt hat, weil es eigentlich zwei Helden waren und so.',
    'Still! Those two managed to bring an end to the Darkest Day with the sword and shield Pokémon! Sonia thought the Pokémon might still be sleeping somewhere though, right?': 'Trotzdem! Die beiden haben es geschafft, den Dunkelsten Tag mit den Schwert- und Schild-Pokémon zu beenden! Sonia dachte, die Pokémon könnten noch irgendwo schlafen, oder?',
    'That\'s it! I\'m sure it\'s got to be the Slumbering Weald! Those illusions you tried to fight off that day—they must\'ve been the Pokémon that are supposed to be sleeping there!': 'Das ist es! Es muss der Slumbering Weald sein! Diese Trugbilder, gegen die du an dem Tag kämpfen wolltest – das müssen die Pokémon gewesen sein, die dort angeblich schlafen!',
    'Let\'s go back to the Slumbering Weald! If we\'re lucky, we\'ll find something that can help!': 'Lass uns zurück zum Slumbering Weald gehen! Wenn wir Glück haben, finden wir etwas, das uns helfen kann!',
    'My matches are always sold out, but this... I\'ve never seen a crowd this wild!': 'Meine Kämpfe sind immer ausverkauft, aber das hier... So ein wildes Publikum habe ich noch nie gesehen!',
    'Everyone knows what you did for us this week... They know you\'re the one who caught Eternatus and saved the future of the Galar region.': 'Alle wissen, was du diese Woche für uns getan hast... Sie wissen, dass du derjenige bist, der [[pokemon::Eternatus]] gefangen und die Zukunft der Galar-Region gerettet hat.',
    'A real hero, who battled alongside the Legendary Pokémon, Zacian and Zamazenta... I couldn\'t have dreamed of a better challenger to help increase my winning streak!': 'Ein echter Held, der Seite an Seite mit den Legendären Pokémon [[pokemon::Zacian]] und [[pokemon::Zamazenta]] gekämpft hat... Ich hätte mir keinen besseren Herausforderer erträumen können, um meine Siegesserie zu verlängern!',
    'Now that I\'ve seen just what kind of strength you possess as the greatest of challengers...crushing you into the dirt will show everyone just how strong their Champion truly is!': 'Jetzt, wo ich gesehen habe, welche Stärke du als größter aller Herausforderer besitzt... wird es allen zeigen, wie stark ihr Champion wirklich ist, wenn ich dich in den Staub zwinge!',
    'Come on, now! Let\'s make this a final match that\'ll go down in Galar\'s history! No! A match that\'ll change Galar forever!': 'Na los! Lass uns einen Finalkampf daraus machen, der in die Geschichte Galars eingeht! Nein! Einen Kampf, der Galar für immer verändert!',
    'We\'re gonna have an absolutely champion time!': 'Das wird eine absolut championmäßige Zeit!',
    'One of the other students said they saw a rare Pokémon on {ROUTE_NAME}. Might be worth having a look.': 'Einer der anderen Schüler sagte, er hätte ein seltenes Pokémon auf {ROUTE_NAME} gesehen. Vielleicht lohnt es sich, mal nachzusehen.',
    '... ... ... Why hello there! My name is Mustard! I\'m rather good at Pokémon battles, you know! I\'m pleased as cheese that you could join us!': '... ... ... Na, hallo! Mein Name ist Mastrich! Ich bin ziemlich gut in Pokémon-Kämpfen, weißt du! Ich freue mich wie ein Schneekönig, dass du zu uns gestoßen bist!',
    'Yaaay! This is my favorite part! I wanna see just how good you are! So, why not have a battle with little old me? Just say the word when you\'re ready!': 'Juhuu! Das ist mein Lieblingsteil! Ich will sehen, wie gut du bist! Also, warum kämpfst du nicht mal gegen mich altes Männlein? Sag einfach Bescheid, wenn du bereit bist!',
    'Bah ha ha! I lost! You\'re pretty strong, aren\'t you? The way you battle really shows me how much you care about your Pokémon! Even if you\'ve come because of a misunderstanding, as long as you have a will to learn... then you\'re welcome at the Master Dojo! I think we can all help each other become stronger! I\'m happy you\'ve come to join us!': 'Bah ha ha! Ich habe verloren! Du bist ziemlich stark, was? Deine Art zu kämpfen zeigt mir wirklich, wie viel dir an deinen Pokémon liegt! Auch wenn du wegen eines Missverständnisses hier bist: Solange du lernen willst... bist du im Master Dojo willkommen! Ich glaube, wir können uns alle gegenseitig helfen, stärker zu werden! Ich freue mich, dass du zu uns gekommen bist!',
    'Now then! The dojo\'s at max capacity! It\'s time to really start our training! You\'ll all be facing three trials. And there\'s more! The person who completes the three trials will receive the secret armor of this dojo!': 'Also dann! Das Dojo ist voll belegt! Zeit, mit unserem Training richtig loszulegen! Ihr werdet euch alle drei Prüfungen stellen. Und das ist noch nicht alles! Wer die drei Prüfungen besteht, erhält die geheime Rüstung dieses Dojos!',
    'For the first trial, my students... You\'ve all gotta defeat 6 of those fast Galarian Slowpoke, trained with care by little old me! But that\'s not all... You need to catch them, too!': 'Für die erste Prüfung, meine Schüler... müsst ihr alle 6 dieser flinken [[pokemon::Galarian Slowpoke]] besiegen, die ich altes Männlein mit Sorgfalt trainiert habe! Aber das ist nicht alles... Ihr müsst sie auch fangen!',
    'Well mustered! You cleared the first trial like it was nothing! Why, I think this is the first time since Leon that someone was able to handle all six fast Slowpoke on their own! The rest of you tried very hard, too! You were able to catch up to the Slowpoke, but I guess you couldn\'t defeat them.': 'Gut gemacht! Du hast die erste Prüfung gemeistert, als wäre es nichts! Ich glaube, seit Delion ist das das erste Mal, dass jemand alle sechs flinken [[pokemon::Slowpoke]] allein geschafft hat! Ihr anderen habt euch auch sehr angestrengt! Ihr konntet die [[pokemon::Slowpoke]] einholen, aber besiegen konntet ihr sie wohl nicht.',
    'Tell you what. Anyone who was able to catch up to a Slowpoke at least once gets a pass! Our new student here really outdid themselves, so it\'s only fair everyone else gets another chance. Try to make a comeback, everybody!': 'Wisst ihr was? Jeder, der mindestens einmal ein [[pokemon::Slowpoke]] eingeholt hat, kommt weiter! Unser neuer Schüler hier hat sich wirklich selbst übertroffen, also ist es nur fair, wenn alle anderen noch eine Chance bekommen. Versucht, wieder aufzuholen, alle zusammen!',
    'And for your second trial we have mushroom picking! I\'m tasking you with finding three Max Mushrooms! They are red with a spiral pattern. I\'m pretty sure they grow in dark, humid places! And with that, your next trial begins! I\'m countin\' on ya!': 'Und für eure zweite Prüfung geht es ans Pilzesammeln! Eure Aufgabe ist es, drei Dyna-Pilze zu finden! Sie sind rot mit einem Spiralmuster. Ich bin mir ziemlich sicher, dass sie an dunklen, feuchten Orten wachsen! Und damit beginnt eure nächste Prüfung! Ich zähle auf euch!',
    'Hey! My bad, my bad! It just dawned on me that you\'re brand-new to the Isle of Armor! I bet you have no idea where to even begin looking for Max Mushrooms! C\'mon--let\'s go for a walk, and I\'ll show you some mushroom hot spots.': 'Hey! Mein Fehler, mein Fehler! Mir ist gerade eingefallen, dass du ganz neu auf der Isle of Armor bist! Du hast bestimmt keine Ahnung, wo du überhaupt anfangen sollst, nach Dyna-Pilzen zu suchen! Komm – lass uns einen Spaziergang machen, und ich zeige dir ein paar Pilz-Hotspots.',
    'Dum dum dee dee... La la de daaa... Now, usually the Forest of Focus is chock-full of Max Mushrooms. But the thing is, a swarm of Greedent came through and ate every last one here! So I\'m thinking maybe you\'ll have more luck finding Max Mushrooms if you go check Warm-Up Tunnel.': 'Dum dum di di... La la di daaa... Normalerweise ist der Forest of Focus voller Dyna-Pilze. Aber ein Schwarm [[pokemon::Greedent]] ist durchgezogen und hat hier jeden einzelnen aufgefressen! Ich denke, du hast vielleicht mehr Glück beim Finden von Dyna-Pilzen, wenn du im Warm-Up Tunnel nachsiehst.',
    'It\'s out on the other side of the forest! Just watch where you\'re going in the forest, \'K? It\'s easy to get lost! Anyhoo... Good luck with the hunt for Max Mushrooms! Catch you back at the dojo!': 'Er liegt auf der anderen Seite des Waldes! Pass im Wald nur auf, wo du hingehst, ok? Man verirrt sich leicht! Wie auch immer... Viel Glück bei der Suche nach Dyna-Pilzen! Wir sehen uns im Dojo!',
    'Hey there! Welcome back! Looks like you nailed the trial! Congrats on finding the Max Mushrooms! Trial number two was no problem for you!': 'Hey! Willkommen zurück! Sieht so aus, als hättest du die Prüfung gemeistert! Glückwunsch zum Finden der Dyna-Pilze! Prüfung Nummer zwei war kein Problem für dich!',
    'All my other students ended up getting lost in the forest... Turns out finding Max Mushrooms was the least of their problems! It\'s a shame, but I guess everyone other than you will fail the trial...': 'Alle meine anderen Schüler haben sich im Wald verlaufen... Die Dyna-Pilze zu finden, war wohl ihr kleinstes Problem! Es ist schade, aber ich schätze, alle außer dir werden die Prüfung nicht bestehen...',
    'Oh! Klara and Avery! You two look out of breath... But you have some Max Mushrooms, so it looks like you both pass the second trial as well!': 'Oh! Klara und Avery! Ihr zwei seht ganz außer Atem aus... Aber ihr habt ein paar Dyna-Pilze, also habt ihr die zweite Prüfung wohl auch beide bestanden!',
    'Right! Well, I\'ve decided that you three... will now take the Master Dojo\'s...final...last...ultimate...third trial!': 'Richtig! Also, ich habe beschlossen, dass ihr drei... jetzt die... finale... letzte... ultimative... dritte Prüfung des Master Dojo ablegt!',
    'You three are the only ones who successfully finished the second trial! You\'ve pushed each other to greater heights and helped each other grow. So I\'d say it\'s time to finally see who is stronger... in a Pokémon battle!': 'Ihr drei seid die Einzigen, die die zweite Prüfung erfolgreich abgeschlossen haben! Ihr habt euch gegenseitig zu Höchstleistungen angespornt und einander geholfen, zu wachsen. Ich würde sagen, es ist endlich an der Zeit herauszufinden, wer stärker ist... in einem Pokémon-Kampf!',
    'Yep! The rules are simple. Whoever wins will complete the trial! The winner will be granted the secret armor of the Master Dojo!': 'Jawohl! Die Regeln sind einfach. Wer gewinnt, besteht die Prüfung! Der Sieger erhält die geheime Rüstung des Master Dojo!',
    'You are here.': 'Da bist du ja.',
    'When I beat you, I\'ll get the secret armor... and then I\'ll become a Poison-type Gym Leader! I\'ve got to win, no matter what.. I\'m gonna go all out and totally beat you. You ready?': 'Wenn ich dich besiege, bekomme ich die geheime Rüstung... und dann werde ich Arenaleiterin für Gift-Pokémon! Ich muss gewinnen, egal was passiert... Ich gebe alles und mach dich total fertig. Bist du bereit?',
    'I\'m not holding a single thing back anymore. Time to settle this-fair and square! Oh, and maybe watch your step... Looks like some Toxic Spikes somehow got on the Battle Court!': 'Ich halte mich jetzt kein bisschen mehr zurück. Zeit, das zu klären – fair und ehrlich! Oh, und pass vielleicht auf, wo du hintrittst... Sieht so aus, als wären irgendwie Giftspitzen auf das Kampffeld gelangt!',
    'So, you\'ve come at last.': 'Du bist also endlich gekommen.',
    'Defeating you will grant me the secret armor...then I will at last have what I need to become a Psychic-type Gym Leader! No matter what it takes, I refuse to accept anything but a complete and utter victory... I\'m coming at you with everything I have.': 'Wenn ich dich besiege, erhalte ich die geheime Rüstung... dann habe ich endlich, was ich brauche, um Arenaleiter für Psycho-Pokémon zu werden! Koste es, was es wolle, ich akzeptiere nichts anderes als einen vollständigen und absoluten Sieg... Ich greife dich mit allem an, was ich habe.',
    'Heh. Let us have an elegant battle worthy of being called a finale. Prepare to sink into despair...and into the weird battlefield beneath your feet!': 'Heh. Lass uns einen eleganten Kampf führen, der eines Finales würdig ist. Mach dich bereit, in Verzweiflung zu versinken... und im Wirrfeld unter deinen Füßen!',
    'The victor has been decided! The one to complete the third trial is you, our newest student! You gave it your best and triumphed, even when faced with an unfair challenge. To you, who has completed all the trials... I grant the secret armor of the Master Dojo!': 'Der Sieger steht fest! Wer die dritte Prüfung besteht, bist du, unser neuester Schüler! Du hast dein Bestes gegeben und triumphiert, selbst als du vor einer unfairen Herausforderung standest. Dir, der alle Prüfungen bestanden hat... überreiche ich die geheime Rüstung des Master Dojo!',
    'Now then... Come on out! This Pokémon is in fact the secret armor of the Master Dojo! Say hello to...Kubfu!': 'Also dann... Komm raus! Dieses Pokémon ist in Wahrheit die geheime Rüstung des Master Dojo! Sag hallo zu... [[pokemon::Kubfu]]!',
    'I know... I know... It\'s tiny... But raise it with diligence, and it\'ll become strong enough to see you through any battle, just like a suit of armor. No opponent will be able to get past it!': 'Ich weiß... Ich weiß... Es ist winzig... Aber zieh es mit Fleiß groß, und es wird stark genug, um dich durch jeden Kampf zu bringen, genau wie eine Rüstung. Kein Gegner wird an ihm vorbeikommen!',
    'Now, I give you permission to catch it!': 'Jetzt erlaube ich dir, es zu fangen!',
    'Good! Now then... The first thing for you to do is become best friends with Kubfu! You need to build trust! Kubfu hasn\'t really had a chance to explore the world outside the dojo, so... Maybe it\'ll help you become better friends if you train alongside it!': 'Gut! Also dann... Als Erstes musst du dich mit [[pokemon::Kubfu]] eng anfreunden! Ihr müsst Vertrauen aufbauen! [[pokemon::Kubfu]] hatte noch nicht wirklich die Gelegenheit, die Welt außerhalb des Dojos zu erkunden, also... Vielleicht hilft es euch, bessere Freunde zu werden, wenn du gemeinsam mit ihm trainierst!',
    'Hmm. Maybe you should train against Dark and Water-types. It will be useful for it to know their weaknesses, since they will be its own weaknesses when it evolves.': 'Hmm. Vielleicht solltest du gegen Unlicht- und Wasser-Pokémon trainieren. Es ist nützlich für es, ihre Schwächen zu kennen, denn das werden seine eigenen Schwächen sein, wenn es sich entwickelt.',
    'You\'re back! I can see already you look closer to Kubfu, and its training is going well! It isn\'t quite ready yet, however! To switch it up a little, you should now have it help you with catching some Water and Dark-type Pokémon!': 'Du bist zurück! Ich sehe schon, dass du und [[pokemon::Kubfu]] euch nähergekommen seid, und sein Training läuft gut! Es ist aber noch nicht ganz bereit! Zur Abwechslung solltest du dir jetzt von ihm helfen lassen, ein paar Wasser- und Unlicht-Pokémon zu fangen!',
    'Good, good! You two are just the best of friends now, aren\'t you? Kubfu\'s really become more confident. How wonderful! I daresay I think you\'re both ready.': 'Gut, gut! Ihr zwei seid jetzt die allerbesten Freunde, nicht wahr? [[pokemon::Kubfu]] ist wirklich selbstbewusster geworden. Wie wundervoll! Ich wage zu behaupten, dass ihr beide bereit seid.',
    'Now then! If you want Kubfu to become stronger... there are special training grounds just for Kubfu! Prepare yourselves for the...Towers of Two Fists! The blue tower is the Tower of Waters! And the red tower is the Tower of Darkness!': 'Also dann! Wenn du willst, dass [[pokemon::Kubfu]] stärker wird... gibt es spezielle Trainingsstätten nur für [[pokemon::Kubfu]]! Macht euch bereit für die... Türme der zwei Fäuste! Der blaue Turm ist der Turm des Wassers! Und der rote Turm ist der Turm des Unlichts!',
    'Each tower will help Kubfu learn a different fighting style! I\'m really looking forward to when you two make it to the top of those towers! It\'s going to be so exciting!': 'Jeder Turm hilft [[pokemon::Kubfu]], einen anderen Kampfstil zu erlernen! Ich freue mich schon riesig darauf, wenn ihr zwei die Spitze dieser Türme erreicht! Das wird so spannend!',
    'Hey! I didn\'t expect to see you again here. Fancy a ba-. Actually, no, I\'d like to ask a favour of you; a friend of mine living in Glimwood Tangle called me asking for some help.': 'Hey! Ich hatte nicht erwartet, dich hier wiederzusehen. Lust auf einen Kam-. Nein, eigentlich möchte ich dich um einen Gefallen bitten; ein Freund von mir, der im Glimwood Tangle lebt, hat mich angerufen und um Hilfe gebeten.',
    'I would go myself, but I promised one of the students here a battle and I don\'t want to bail on them. Would you be able to go for me?': 'Ich würde ja selbst gehen, aber ich habe einem der Schüler hier einen Kampf versprochen und will ihn nicht im Stich lassen. Könntest du für mich gehen?',
    'Great! My friend\'s name is Koko, tell him I sent you. This battle shouldn\'t take me too long, so come ask for my help if you need it!': 'Super! Mein Freund heißt Koko, sag ihm, dass ich dich schicke. Dieser Kampf sollte nicht allzu lange dauern, also komm zu mir, wenn du Hilfe brauchst!',
    'You\'re back! How did it go with the Zarude?': 'Du bist zurück! Wie lief es mit den [[pokemon::Zarude]]?',
    'Oh, I see, that\'s quite the problem... Still, you said they\'re all out cold for now, right? In that case, we should have time for a battle!': 'Oh, verstehe, das ist ein ganz schönes Problem... Trotzdem, du hast gesagt, sie sind alle erst mal bewusstlos, oder? Dann sollten wir Zeit für einen Kampf haben!',
    'The battlefield out the back of the Dojo is being used at the moment, so let\'s battle out in front of the Dojo.': 'Das Kampffeld hinter dem Dojo wird gerade benutzt, also lass uns vor dem Dojo kämpfen.',
    'With this amazing new team of mine, I\'ll finally beat you, my strongest rival!': 'Mit meinem fantastischen neuen Team werde ich dich endlich schlagen, mein stärkster Rivale!',
    'If my eyes didn\'t deceive me, I saw a rare Pokémon at {ROUTE_NAME}. Go and see if you can find it if you\'re interested.': 'Wenn meine Augen mich nicht getäuscht haben, habe ich auf {ROUTE_NAME} ein seltenes Pokémon gesehen. Wenn es dich interessiert, sieh doch mal nach, ob du es findest.',
    'Hey, Chief! I was talking to the locals and they were talking about some ancient king Pokémon! They also mentioned a couple of horsey Pokémon that it was ultra-mega-close to. There\'s a statue of it outside and I\'ve heard this rock I\'ve been using as a pillow is part of it!': 'Hey, Chef! Ich hab mit den Einheimischen geredet und die haben von irgendeinem uralten Königs-Pokémon erzählt! Sie haben auch ein paar Pferde-Pokémon erwähnt, mit denen es ultra-mega-eng verbunden war. Draußen steht eine Statue davon, und ich hab gehört, dass dieser Stein, den ich als Kopfkissen benutze, ein Teil davon ist!',
    'Could you go and put it back on for me?': 'Könntest du ihn für mich wieder dranmachen?',
    'Ah, yes. A sturdy body, just as I expected. I hope this man doesn\'t mind that I make use of it for the time being.': 'Ah, ja. Ein robuster Körper, ganz wie erwartet. Ich hoffe, dieser Mann hat nichts dagegen, dass ich ihn vorübergehend benutze.',
    'I am Calyrex. I am also known as the King of Bountiful Harvests. I have borrowed this man\'s body in order to thank you in person for restoring my statue...so to speak.': 'Ich bin [[pokemon::Calyrex]]. Man kennt mich auch als König der Fülle. Ich habe mir den Körper dieses Mannes geliehen, um dir persönlich dafür zu danken, dass du meine Statue wiederhergestellt hast ... sozusagen.',
    'I once reigned over these lands as king, but now I have lost all but a fraction of my former strength. Even my loyal steeds have abandoned me.': 'Einst herrschte ich als König über diese Lande, doch nun ist mir nur noch ein Bruchteil meiner früheren Kraft geblieben. Selbst meine treuen Rösser haben mich verlassen.',
    'Would you do me the favour of protecting me from wild Pokémon at the Old Cemetery and Snowslide Slope? I wish to grow a Shaderoot Carrot and an Iceroot Carrot which I believe could draw out my loyal steeds.': 'Würdest du mir den Gefallen tun, mich auf dem Old Cemetery und am Snowslide Slope vor wilden Pokémon zu beschützen? Ich möchte eine Schattenkarotte und eine Eiskarotte anbauen, die meine treuen Rösser hoffentlich anlocken werden.',
    'Thank you for your help in growing these carrots. It is my belief that they will draw my loyal steeds back to me...': 'Ich danke dir für deine Hilfe beim Anbau dieser Karotten. Ich glaube fest daran, dass sie meine treuen Rösser zu mir zurückbringen werden ...',
    'What?! They are here already! But they appear to be unable to tell exactly where the scent of the carrots is coming from!': 'Was?! Sie sind bereits hier! Aber sie scheinen nicht genau zu wissen, woher der Duft der Karotten kommt!',
    'The people of this place are in danger, you must fight them off!': 'Die Menschen hier sind in Gefahr, du musst sie abwehren!',
    'You have my thanks for protecting the village, human child. Although, unfortunately, this has also caused my loyal steeds to flee.': 'Du hast meinen Dank dafür, dass du das Dorf beschützt hast, Menschenkind. Leider hat das aber auch dazu geführt, dass meine treuen Rösser geflohen sind.',
    'Hmm... Perhaps now we know they are in this area, it would be better to search for them?': 'Hmm ... Jetzt, wo wir wissen, dass sie in dieser Gegend sind, wäre es vielleicht besser, nach ihnen zu suchen?',
    'I think that would be for the best. Once you capture them, I would appreciate it if you could bring them to the Crown Shrine at the mountain\'s peak.': 'Ich denke, das wäre das Beste. Wenn du sie gefangen hast, wäre ich dir dankbar, wenn du sie zum Crown Shrine auf dem Gipfel des Berges bringen könntest.',
    'Wait--you really caught Calyrex from the legends?! Thats\'s ultra-mega-brilliant! Report away!': 'Moment mal – du hast wirklich das legendäre [[pokemon::Calyrex]] gefangen?! Das ist ultra-mega-genial! Erzähl schon!',
    'Th-that noggin\'s MASSIVE! I-is that the King of Bountiful Harvests? The one calling the shots around here? Huh? I could swear I\'ve seen it before... Or then again, maybe not...': 'D-diese Birne ist RIESIG! I-ist das der König der Fülle? Der, der hier das Sagen hat? Hä? Ich könnte schwören, dass ich es schon mal gesehen hab ... Oder vielleicht auch nicht ...',
    'A-anyway! It\'s definitely regal of it to have steeds... and that massive head does sort of resemble a crown! It\'s kingly enough, at any rate! Let\'s just call this a successful expedition! Smashin\'!': 'W-wie auch immer! Rösser zu haben ist auf jeden Fall königlich ... und dieser riesige Kopf sieht schon irgendwie wie eine Krone aus! Königlich genug ist es jedenfalls! Nennen wir das mal eine erfolgreiche Expedition! Spitze!',
    'Hey, Chief! I was talking to the locals and they mentioned they had seen some bird Pokémon that looked like the legendary birds of Kanto at that ultra-mega-massive tree in the middle of Ballimere Lake!': 'Hey, Chef! Ich hab mit den Einheimischen geredet und die haben erwähnt, dass sie bei dem ultra-mega-riesigen Baum mitten im Ballimere Lake ein paar Vogel-Pokémon gesehen haben, die wie die legendären Vögel aus Kanto aussahen!',
    'You should go check it out!': 'Das solltest du dir mal ansehen!',
    'You\'re saying you saw some Pokémon that looked like.... Hang on, Chief! There\'s breaking news on the telly! They\'re sayin\' dodgy bird Pokémon are poppin\' up left and right!': 'Du sagst, du hast ein paar Pokémon gesehen, die so aussahen wie ... Moment, Chef! Da kommen gerade Eilmeldungen im Fernsehen! Die sagen, dass überall komische Vogel-Pokémon auftauchen!',
    'There\'s this fancy graceful one\'s apparently flyin\' about the Crown Tundra!': 'Ein schickes, anmutiges soll angeblich über die Crown Tundra fliegen!',
    'And there\'s this pointy feathered one runnin\' about in the Wild Area of Southern Galar!': 'Und ein stacheliges, gefiedertes rennt in der Wild Area im Süden von Galar herum!',
    'Plus a fiery-lookin\' one out on the Isle of Armor!': 'Und dazu noch ein feurig aussehendes draußen auf der Isle of Armor!',
    'You\'re sayin\' you saw them and that\'s what you were tellin\' me about? Ah, sorry \'bout that. Anyway, you should go find \'em.': 'Du sagst, du hast sie gesehen und genau davon wolltest du mir erzählen? Ah, sorry. Wie auch immer, du solltest sie suchen gehen.',
    'They look real strong, so you probably can\'t catch \'em right off the bat. I\'d try weakening them first.': 'Die sehen echt stark aus, also kannst du sie wahrscheinlich nicht auf Anhieb fangen. Ich würde versuchen, sie erst mal zu schwächen.',
    'Hang on--you really caught up to all three of them dodgy birds? Multiple times each? That\'s pretty impressive!': 'Moment mal – du hast wirklich alle drei komischen Vögel eingeholt? Und das jeweils mehrmals? Ziemlich beeindruckend!',
    'I think they should all be weakened enough that you can catch \'em now!': 'Ich glaube, die sollten jetzt alle schwach genug sein, dass du sie fangen kannst!',
    'I\'d imagine they\'d be in the same areas you chased \'em about in.': 'Ich schätze, sie sind in denselben Gegenden, in denen du ihnen hinterhergejagt bist.',
    'Wait--you really caught Articuno, Moltres, and Zapdos from the legends?! Thats\'s ultra-mega-brilliant! Report away!': 'Moment mal – du hast wirklich die legendären [[pokemon::Articuno]], [[pokemon::Moltres]] und [[pokemon::Zapdos]] gefangen?! Das ist ultra-mega-genial! Erzähl schon!',
    'So that\'s them is it? I can definitely see the resemblance, but they don\'t seem quite the same...': 'Das sind sie also? Eine Ähnlichkeit sehe ich auf jeden Fall, aber so ganz gleich scheinen sie nicht zu sein ...',
    'Maybe they\'re regional variants or somethin\'? At any rate, that\'s good enough for me. Let\'s call this expedition a success!': 'Vielleicht sind das regionale Formen oder so? Mir reicht das jedenfalls. Nennen wir die Expedition einen Erfolg!',
    'Hey, Chief! I was talking to the locals and they mentioned some weird purple and yellow ruins at Three-Point Pass. You should go check \'em out!': 'Hey, Chef! Ich hab mit den Einheimischen geredet und die haben ein paar seltsame lila-gelbe Ruinen am Three-Point Pass erwähnt. Die solltest du dir mal ansehen!',
    'So they wouldn\'t open... That\'s annoyin\'. Well, there are also 3 more ruins, 2 at opposite ends of Giant\'s Bed, and one at Snowslide Slope. Maybe you should have a look at those?': 'Die gehen also nicht auf ... Wie ärgerlich. Na ja, es gibt noch 3 weitere Ruinen, 2 an entgegengesetzten Enden des Giant\'s Bed und eine am Snowslide Slope. Vielleicht solltest du dir die mal ansehen?',
    'How \'bout clearin\' em 10 times each, and see if you find anythin\' to open up the ruins at Three-Point Pass.': 'Wie wär\'s, wenn du sie jeweils 10-mal abschließt und schaust, ob du was findest, womit sich die Ruinen am Three-Point Pass öffnen lassen.',
    'So that didn\'t work? Well, I heard there are some legendary Pokémon in those ruins, called Regirock, Regice, and Registeel. Apparently they\'ll show up to people who have done enough explorin\' in their ruins.': 'Das hat also nicht geklappt? Na ja, ich hab gehört, dass es in diesen Ruinen legendäre Pokémon gibt, nämlich [[pokemon::Regirock]], [[pokemon::Regice]] und [[pokemon::Registeel]]. Angeblich zeigen sie sich Leuten, die ihre Ruinen gründlich genug erkundet haben.',
    'Maybe if you caught them, the other ruins would open? What? You already have? Well, it might be worth doing it again, anyway.': 'Vielleicht öffnen sich die anderen Ruinen, wenn du sie fängst? Was? Hast du schon? Na ja, vielleicht lohnt es sich trotzdem, es noch mal zu machen.',
    'Looks like that didn\'t do it. But don\'t lose your hopes yet! I was just told that Regigigas appeared in Giant\'s Bed! Probably somethin\' to do with you catching those other three. Anyway! You should go on and catch it!': 'Sieht so aus, als hätte das nicht gereicht. Aber verlier noch nicht die Hoffnung! Mir wurde gerade gesagt, dass [[pokemon::Regigigas]] im Giant\'s Bed aufgetaucht ist! Hat wahrscheinlich was damit zu tun, dass du die anderen drei gefangen hast. Jedenfalls! Du solltest gleich losgehen und es fangen!',
    'Wait--so you really caught Regigigas from the legends? Well, that doesn\'t seem to have opened the ruins automatically or anythin\', but I imagine Regigigas can open those doors with sheer strength!': 'Moment – du hast also wirklich das legendäre [[pokemon::Regigigas]] gefangen? Na ja, dadurch scheinen sich die Ruinen nicht automatisch geöffnet zu haben, aber ich könnte mir vorstellen, dass [[pokemon::Regigigas]] diese Türen mit purer Kraft aufkriegt!',
    'You should go now and see what\'s there!': 'Du solltest jetzt hingehen und nachsehen, was da drin ist!',
    'You caught Regieleki and Regidrago from the legends? Well that\'s that then! Smashin\'! I\'ll mark this expedition done!': 'Du hast die legendären [[pokemon::Regieleki]] und [[pokemon::Regidrago]] gefangen? Na dann wär\'s das! Spitze! Ich hake diese Expedition als erledigt ab!',
    'Huh? Well how \'bout that, Chief! Looks like that was the last bit of the grand Peony Adven-tour that I had for you! Whoooooo! Now this is an occasion! What\'s the word? Ultra-mega-epic! Your passion for all this caught me off guard, Chief...': 'Hä? Na sieh mal einer an, Chef! Sieht so aus, als wäre das der letzte Teil der großen Peony-Aben-Tour gewesen, den ich für dich hatte! Juhuuuuu! Das ist ja mal ein Anlass! Wie sagt man da? Ultra-mega-episch! Deine Begeisterung für das alles hat mich echt überrascht, Chef ...',
    'This whole Adven-tour thing was built out of a load of rubbish I scraped together. Even I had my doubts about the whole thing. But you? You went at it with a ton of energy! Thanks for stickin\' around and finishin\' every part of my Adven-tour!': 'Diese ganze Aben-Tour-Sache hab ich aus einem Haufen Kram zusammengeschustert. Selbst ich hatte meine Zweifel daran. Aber du? Du bist mit jeder Menge Energie rangegangen! Danke, dass du drangeblieben bist und jeden Teil meiner Aben-Tour abgeschlossen hast!',
    'Hang on-I recognize you! You\'re that kid who was able to beat my dad earlier, right? That\'s impressive, he\'s no pushover!': 'Moment – ich kenne dich! Du bist doch das Kind, das vorhin meinen Vater besiegt hat, oder? Beeindruckend, der ist nämlich kein leichter Gegner!',
    'Actually, a strong trainer like you, I think might be interested in a nearby place I was just about to go to.': 'Weißt du, ein starker Trainer wie du könnte sich für einen Ort in der Nähe interessieren, zu dem ich gerade gehen wollte.',
    'It\'s a cave system just to the north of here, called the Max Lair. It\'s the only known place where you can catch wild Gigantamax Pokémon!': 'Es ist ein Höhlensystem direkt nördlich von hier, genannt Max Lair. Es ist der einzige bekannte Ort, an dem man wilde Gigadynamax-Pokémon fangen kann!',
    'If you\'re interested, you should go take a look!': 'Wenn es dich interessiert, solltest du mal vorbeischauen!',
    'Would you take a look at that! Now that\'s something you don\'t see every day... This place definitely feels like the stuff of legend. See that! The sword and the shield! The legends really were true!': 'Sieh dir das an! So was sieht man nicht alle Tage ... Dieser Ort fühlt sich echt wie aus einer Legende an. Sieh mal! Das Schwert und der Schild! Die Legenden waren wirklich wahr!',
    'That settles it! We\'re taking the sword and shield. Though...wow, would you look at the state of these things? They seem like they might fall to pieces if you so much as look at \'em funny.': 'Dann ist es beschlossen! Wir nehmen das Schwert und den Schild mit. Obwohl ... wow, sieh dir mal an, in was für einem Zustand die sind! Die sehen aus, als würden sie in Stücke fallen, wenn man sie nur schief ansieht.',
    'I don\'t know if these rusty old things will really be able to stop the Darkest Day, but... Well, I guess it can\'t hurt to have them along! Let\'s hope they bring us some good luck!': 'Ich weiß nicht, ob diese rostigen alten Dinger den Tag der Finsternis wirklich aufhalten können, aber ... Na ja, schaden kann es wohl nicht, sie dabeizuhaben! Hoffen wir, dass sie uns Glück bringen!',
    'Maybe the Pokémon themselves really are still asleep somewhere. So it seems we\'re on our own if we want to go help Lee. This is all the help we\'ve got!': 'Vielleicht schlafen die Pokémon selbst wirklich noch irgendwo. Sieht so aus, als wären wir auf uns allein gestellt, wenn wir Delion helfen wollen. Mehr Hilfe haben wir nicht!',
    'Huh? What\'re you doing here in the woods? Nobody ever comes in here, since this is the forest where Zacian and Zamazenta rested. It\'s the best place to do a bit of thinking, since it\'s so quiet and all.': 'Hä? Was machst du denn hier im Wald? Hierher kommt nie jemand, weil das der Wald ist, in dem [[pokemon::Zacian]] und [[pokemon::Zamazenta]] geruht haben. Es ist der beste Ort, um ein bisschen nachzudenken, weil es hier so ruhig ist und so.',
    'Oh, but I hadn\'t had the chance to tell you! Congrats on your victory! Honestly... I never thought you\'d manage to beat my brother. The greatest Champion Galar ever had! He was undefeatable till you came around! It\'s actually still pretty hard to believe...': 'Ach, ich hatte noch gar keine Gelegenheit, es dir zu sagen! Glückwunsch zu deinem Sieg! Ehrlich ... Ich hätte nie gedacht, dass du meinen Bruder schlagen würdest. Den größten Champ, den Galar je hatte! Er war ungeschlagen, bis du kamst! Ich kann es eigentlich immer noch kaum glauben ...',
    'Really... You\'re amazing. So amazing, maybe, that I don\'t even realize just how amazing you really are!': 'Wirklich ... Du bist unglaublich. So unglaublich, dass ich vielleicht nicht mal begreife, wie unglaublich du wirklich bist!',
    'So, do you think... Would you be up for one more battle?': 'Also, meinst du ... Hättest du Lust auf noch einen Kampf?',
    'Well, well, well... I thought I heard someone making some noise over this way!': 'Na, na, na ... Ich dachte mir doch, dass ich hier drüben jemanden Lärm machen gehört habe!',
    'I am Sordward!': 'Ich bin Sordward!',
    'I am Shielbert!': 'Ich bin Shielbert!',
    'We are the new kings of Galar! We\'re descendents of the first kings!': 'Wir sind die neuen Könige von Galar! Wir sind Nachfahren der ersten Könige!',
    'More than that, we\'re celebrities!': 'Mehr noch, wir sind Berühmtheiten!',
    'Well, well, well! Could these things here be the fabled sword and shield?': 'Na, na, na! Könnten diese Dinger hier etwa das sagenumwobene Schwert und der Schild sein?',
    'Well, well, well! They certainly are dirty! They must be fake! I fear to touch them with my bare hands.': 'Na, na, na! Die sind ja ganz schön schmutzig! Das müssen Fälschungen sein! Ich wage es nicht, sie mit bloßen Händen anzufassen.',
    'Oh, you want us to return them? Then perhaps we should settle this with a battle?': 'Oh, du willst, dass wir sie zurückgeben? Dann sollten wir das vielleicht mit einem Kampf klären?',
    'Hmm? Who are you? Oh, so Ash sent you to help me? That\'s great!': 'Hmm? Wer bist du? Oh, Ash hat dich geschickt, um mir zu helfen? Super!',
    'So, I\'m part of a tribe of Pokémon called Zarude, I was raised by them despite being a human. One of them has gone missing, I\'ve been told they were seen roaming, completely lost, around the Isle of Armor.': 'Also, ich gehöre zu einem Stamm von Pokémon namens [[pokemon::Zarude]] und wurde von ihnen großgezogen, obwohl ich ein Mensch bin. Einer von ihnen wird vermisst. Mir wurde erzählt, man hätte ihn völlig verirrt auf der Isle of Armor herumstreifen sehen.',
    'Could you go catch it and bring it back here? If you need help locating it, I\'m sure one of the students at the dojo they have there could help you.': 'Könntest du ihn fangen und hierher zurückbringen? Wenn du Hilfe brauchst, ihn zu finden, kann dir bestimmt einer der Schüler aus dem Dojo dort helfen.',
    'Great, you found it! Now if you could release it... hmm? It seems to like you. Well, if it wants to stay with you, that\'s its choice, so I guess it\'s fine.': 'Super, du hast ihn gefunden! Wenn du ihn jetzt freilassen könntest ... hmm? Er scheint dich zu mögen. Na ja, wenn er bei dir bleiben will, ist das seine Entscheidung, also ist das wohl in Ordnung.',
    'Oh, it looks like a group of Zarude from the tribe are here..... They... are angry, they think you caught Zarude against its will. I\'ll try and talk sense into them,': 'Oh, sieht so aus, als wäre eine Gruppe [[pokemon::Zarude]] aus dem Stamm hier ..... Sie ... sind wütend. Sie denken, du hättest das [[pokemon::Zarude]] gegen seinen Willen gefangen. Ich versuche, sie zur Vernunft zu bringen,',
    'Zaruza! Zaru Zaru! Zarude!.. Nope, they\'re too angry to listen. Looks like you\'ll have to fight them if we want to calm them down. Zarude are strong, but I\'m sure you\'ll be fine if you are anywhere near as strong as Ash.': 'Zaruza! Zaru Zaru! Zarude! ... Nein, sie sind zu wütend, um zuzuhören. Sieht so aus, als müsstest du gegen sie kämpfen, wenn wir sie beruhigen wollen. [[pokemon::Zarude]] sind stark, aber ich bin sicher, du schaffst das, wenn du auch nur annähernd so stark bist wie Ash.',
    'Well, they\'re all knocked out. I\'ll try to talk reason into them when they wake up. Thanks for your help, I\'m glad you found Zarude safe.': 'Na, die sind alle k.o. Ich versuche, sie zur Vernunft zu bringen, wenn sie aufwachen. Danke für deine Hilfe, ich bin froh, dass du das [[pokemon::Zarude]] sicher gefunden hast.',
    '...oh no. Another two groups of Zarude are coming and, as I\'m sure you can already guess, being surrounded by unconscious Zarude does not make you look good to them.': '... oh nein. Zwei weitere Gruppen [[pokemon::Zarude]] kommen, und wie du dir sicher schon denken kannst, macht es keinen guten Eindruck auf sie, wenn du von bewusstlosen [[pokemon::Zarude]] umgeben bist.',
    'I\'m really sorry, it seems you\'ll have to fight off these ones as well.': 'Es tut mir echt leid, aber es sieht so aus, als müsstest du auch gegen diese hier kämpfen.',
    'Okay... It\'s great that you were able to knock them all out without hurting them too much, but I don\'t think I\'ll be able to calm all of them on my own when they wake up.': 'Okay ... Toll, dass du sie alle besiegen konntest, ohne sie zu sehr zu verletzen, aber ich glaube nicht, dass ich sie alle allein beruhigen kann, wenn sie aufwachen.',
    'Would you be able to bring Ash here? I think the 3 of us together should be able to calm the lot of them down. He\'s probably still at the Master Dojo.': 'Könntest du Ash herbringen? Ich glaube, zu dritt sollten wir sie alle beruhigen können. Er ist wahrscheinlich noch im Master Dojo.',
    'You brought Ash? Fantastic! And just in time, the Zarude are starting to wake up. Ash, could you have your Pokémon help me explain to them what\'s going on?': 'Du hast Ash mitgebracht? Fantastisch! Und genau rechtzeitig, die [[pokemon::Zarude]] fangen an aufzuwachen. Ash, könnten deine Pokémon mir helfen, ihnen zu erklären, was los ist?',
    'Okay! It seems they finally understand. I\'m really sorry for all the trouble they caused for you.': 'Okay! Sieht so aus, als hätten sie es endlich verstanden. Es tut mir wirklich leid, dass sie dir so viel Ärger gemacht haben.',
    'Oh, Dada! Zaruza Zaru? Zaru. This is the Zarude that raised me, Dada. He says he was impressed watching you fight, and wants to fight you as well.': 'Oh, Dada! Zaruza Zaru? Zaru. Das ist das [[pokemon::Zarude]], das mich großgezogen hat, Dada. Er sagt, er war beeindruckt, als er dir beim Kämpfen zugesehen hat, und möchte auch gegen dich kämpfen.',
    'I should tell you, Dada is much stronger than the rest of the Zarude. Have a good fight, both of you!': 'Ich sollte dir sagen, dass Dada viel stärker ist als die anderen [[pokemon::Zarude]]. Viel Spaß beim Kampf, euch beiden!',
    'Amazing, you even beat Dada! It\'s really clear that he is really amazed by your strength!': 'Unglaublich, du hast sogar Dada besiegt! Man sieht deutlich, dass er von deiner Stärke total beeindruckt ist!',
    'Hang on, did you guys see something? Oh, over there, it\'s Celebi! It must have come now things are peaceful here. It looks like it wants to play!': 'Moment, habt ihr was gesehen? Oh, da drüben, das ist [[pokemon::Celebi]]! Es muss gekommen sein, weil hier jetzt Frieden herrscht. Sieht so aus, als wollte es spielen!',
    'Actually, it looks interested in you in particular. You should challenge it to a fight!': 'Eigentlich scheint es sich besonders für dich zu interessieren. Du solltest es zu einem Kampf herausfordern!',
    'Wow, you actually beat Celebi! It looked like it had fun! It\'s ran off for now, but maybe if you find it again, it\'ll let you catch it.': 'Wow, du hast [[pokemon::Celebi]] tatsächlich besiegt! Es sah so aus, als hätte es Spaß gehabt! Es ist erst mal weggelaufen, aber wenn du es wiederfindest, lässt es sich vielleicht von dir fangen.',
    'Oh, also, Dada said he would be interested in travelling with you. Although, he also said he needed to deal with the shortage of Quest Points the tribe is dealing with right now.': 'Ach, übrigens, Dada meinte, er hätte Interesse daran, mit dir zu reisen. Er meinte aber auch, dass er sich zuerst um den Mangel an Questpunkten kümmern muss, mit dem der Stamm gerade zu kämpfen hat.',
    'If you help him with that, I\'m sure he\'ll join you!': 'Wenn du ihm dabei hilfst, schließt er sich dir bestimmt an!',
    'Most impressive! I wouldn\'t expect any less from a challenger endorsed by the strongest Champion ever to grace our beloved Galar region!': 'Höchst beeindruckend! Von einem Herausforderer, der vom stärksten Champ empfohlen wurde, den unsere geliebte Galar-Region je hatte, hätte ich nichts anderes erwartet!',
    'I really do wish I could have seen the Championship Match between you two. And I\'m terribly sorry to have ruined the whole Gym Challenge and everything!': 'Ich hätte das Finale zwischen euch beiden wirklich gern gesehen. Und es tut mir schrecklich leid, dass ich die ganze Arena-Challenge und alles ruiniert habe!',
    'It\'s too bad, but it can\'t be helped... In order to solve the energy issue as soon as possible, we awakened Eternatus. But we couldn\'t control it. The Champion came to aid me, even at the cost of abandoning the match. Indeed, just like a knight in shining armor coming to rescue a princess from a dragon!': 'Es ist schade, aber es lässt sich nicht ändern ... Um das Energieproblem so schnell wie möglich zu lösen, haben wir [[pokemon::Eternatus]] erweckt. Aber wir konnten es nicht kontrollieren. Der Champ kam mir zu Hilfe, selbst wenn er dafür das Finale aufgeben musste. Wahrhaftig, wie ein Ritter in strahlender Rüstung, der eine Prinzessin vor einem Drachen rettet!',
    'I do tend to ramble on, I know. I love to make speeches. But I think I can stop talking now. I think the Champion should have captured Eternatus by now. If you\'re curious, you can take the lift up.': 'Ich neige dazu, abzuschweifen, ich weiß. Ich halte einfach gern Reden. Aber ich denke, jetzt kann ich aufhören. Der Champ sollte [[pokemon::Eternatus]] inzwischen gefangen haben. Wenn du neugierig bist, kannst du mit dem Aufzug nach oben fahren.',
    'And I trust you\'ll be going too, right, Hop? I certainly hope losing to me didn\'t discourage you too much. Go on now, both of you! Go see how our Champion is doing!': 'Und du gehst doch sicher auch, nicht wahr, Hop? Ich hoffe sehr, dass dich die Niederlage gegen mich nicht allzu sehr entmutigt hat. Nun geht schon, ihr beiden! Seht nach, wie es unserem Champ geht!',
    'You caught Eternatus!': 'Du hast [[pokemon::Eternatus]] gefangen!',
    'Well, well, well? It seems you have rescued the stadiums from their perils. As expected of the Champion.': 'Na, na, na? Es scheint, du hast die Stadien aus ihrer Not gerettet. Wie man es vom Champ erwartet.',
    'You want to know why we have been forcing those Pokémon to rampage? We did it in order to expose the true nature of Zacian and Zamazenta!': 'Du willst wissen, warum wir diese Pokémon zum Wüten gezwungen haben? Wir haben es getan, um das wahre Wesen von [[pokemon::Zacian]] und [[pokemon::Zamazenta]] zu entlarven!',
    'We have always been revered as the resplendent descendents of the real hero...': 'Wir wurden stets als die glanzvollen Nachfahren des wahren Helden verehrt ...',
    'It\'s all because you ruffians had to go and save Galar from Eternatus!': 'Und das alles nur, weil ihr Rüpel Galar unbedingt vor [[pokemon::Eternatus]] retten musstet!',
    'You said that the real heroes were Pokémon! You just carelessly changed history!': 'Ihr habt gesagt, die wahren Helden seien Pokémon gewesen! Ihr habt einfach leichtfertig die Geschichte umgeschrieben!',
    'What does that mean we are? You dare say that our esteemed ancestors were liars?': 'Was sind wir denn dann? Wagt ihr es etwa zu behaupten, unsere ehrwürdigen Vorfahren seien Lügner gewesen?',
    'It\'s obvious that the old history was better! It was right!': 'Es ist doch offensichtlich, dass die alte Geschichte besser war! Sie war richtig!',
    'To suddenly start creating heroes left and right... It\'s complete rubbish!': 'Einfach so links und rechts Helden zu erschaffen ... Das ist kompletter Unsinn!',
    'Ahem... If you want to take the lift up, you\'ll have to defeat us! This time we will show you the opulent Pokémon we have raised explicity for this battle!': 'Ähem ... Wenn du mit dem Aufzug nach oben willst, musst du uns besiegen! Diesmal zeigen wir dir die prachtvollen Pokémon, die wir eigens für diesen Kampf großgezogen haben!',
    'Fwahaheho! We did it! Zacian and Zamazenta came, following after the Rusted Sword and Shield!': 'Fwahaheho! Wir haben es geschafft! [[pokemon::Zacian]] und [[pokemon::Zamazenta]] sind dem Rostigen Schwert und dem Rostigen Schild gefolgt!',
    'Yes! Expose your true, barbaric, brutish nature...and reveal to us exactly who the false kings are!': 'Ja! Zeigt euer wahres, barbarisches, rohes Wesen ... und offenbart uns, wer genau die falschen Könige sind!',
    'W-wait! D-don\'t attack us! Go into town, and sow as much destruction as you can!': 'W-wartet! G-greift nicht uns an! Geht in die Stadt und richtet so viel Zerstörung an, wie ihr nur könnt!',
    'As expected of the Champion... You took complete control of the situation.': 'Wie man es vom Champ erwartet ... Du hattest die Lage voll im Griff.',
    'Plus it looks like those Pokémon are waiting for you, now they\'re calmed down an\' all.': 'Außerdem sieht\'s so aus, als würden diese Pokémon auf dich warten, jetzt wo sie sich beruhigt haben und so.',
    'Huh? Oh, hi. I forgot to say, congrats on catching Zacian and Zamazenta!': 'Hä? Oh, hi. Ich hab vergessen zu sagen: Glückwunsch, dass du [[pokemon::Zacian]] und [[pokemon::Zamazenta]] gefangen hast!',
    'Y\'know, Zacian and Zamazenta got the Rusted Sword and the Rusted Shield back, right?': 'Weißt du, [[pokemon::Zacian]] und [[pokemon::Zamazenta]] haben doch das Rostige Schwert und den Rostigen Schild zurückbekommen, oder?',
    'But when you caught them, neither were using them. But they must still have them, right?': 'Aber als du sie gefangen hast, hat keins von beiden sie benutzt. Sie müssen sie aber noch haben, oder?',
    'So.... Maybe if you keep defeating them, they\'ll occasionally drop them?': 'Also ... Vielleicht lassen sie sie ab und zu fallen, wenn du sie weiter besiegst?',
    'Champion?! What are you.... no matter, I\'m glad you\'re here!': 'Champ?! Was machst du ... egal, ich bin froh, dass du hier bist!',
    'Eternamax Eternatus has appeared again! There is no time to talk! Let\'s fight it together!': 'Unendynamax-[[pokemon::Eternatus]] ist wieder aufgetaucht! Keine Zeit zum Reden! Lass es uns gemeinsam bekämpfen!',
    'Wow. You\'re just as amazing as ever. You\'re truly worthy of your title.': 'Wow. Du bist so unglaublich wie eh und je. Du hast deinen Titel wirklich verdient.',
    'I think Eternatus absorbed the leftover power it used to transform the first time to do so again. There\'s none left now, though, so that should be the last time. It flew south...': 'Ich glaube, [[pokemon::Eternatus]] hat die übrig gebliebene Kraft von seiner ersten Verwandlung aufgenommen, um sich erneut zu verwandeln. Jetzt ist aber nichts mehr übrig, also sollte das das letzte Mal gewesen sein. Es ist nach Süden geflogen ...',
    'I have a feeling it\'ll come back here, but it shouldn\'t be a problem if it can\'t return to its Eternamax form here, right?': 'Ich habe das Gefühl, dass es hierher zurückkommt, aber das sollte kein Problem sein, wenn es hier nicht wieder seine Unendynamax-Form annehmen kann, oder?',
    'Anyway, thanks for your help! Feel free to come over to Wyndon Stadium anytime if you fancy a match!': 'Jedenfalls danke für deine Hilfe! Komm jederzeit ins Wyndon Stadium, wenn du Lust auf einen Kampf hast!',
    'Hold up a sec! *wheeze*... *wheeze*... Hellooo, what\'s this?! Three Max Mushrooms in one spot? Here I thought I\'d need to go find them one by one! I saw those mushrooms first! I swear! I\'ve been at the dojo longer and all. Sooo... It\'s only fair you let me have \'em. Riiight?': 'Halt mal \'ne Sekunde! *keuch* ... *keuch* ... Hallöchen, was haben wir denn da?! Drei Dyna-Pilze an einer Stelle? Und ich dachte, ich müsste sie einzeln suchen! Ich hab die Pilze zuerst gesehen! Ich schwör\'s! Ich bin schließlich schon länger im Dojo und so. Alsooo ... Es ist nur fair, wenn du sie mir überlässt. Stiiimmt\'s?',
    'Waaait... What\'s this, now? Are you givin\' me attitude? Pityin\' me, are you?! Gosh, you\'re such a pain in the neck... You just show up outta nowhere, and just happen to be young and talented... If you\'re looking to get in my way, well, I think some vile poisons will take care of that!': 'Waaarte ... Was soll das denn jetzt? Wirst du etwa frech? Hast du Mitleid mit mir, oder was?! Mann, du bist echt eine Nervensäge ... Du tauchst einfach aus dem Nichts auf und bist zufällig jung und talentiert ... Wenn du mir in die Quere kommen willst, dann werden sich ein paar fiese Gifte darum kümmern!',
    'Wait just one moment! *pant*... *pant*... Hah! Just as I expected! Multiple Max Mushrooms growing in a bunch! My psychic powers picked up on these Max Mushrooms eons before you found them. I believe I should be the first one to get those Max Mushrooms. First come, first served, and all!': 'Warte einen Moment! *schnauf* ... *schnauf* ... Ha! Genau wie ich es erwartet habe! Mehrere Dyna-Pilze, die auf einem Haufen wachsen! Meine Psychokräfte haben diese Dyna-Pilze schon Ewigkeiten vor dir aufgespürt. Ich finde, ich sollte als Erster diese Dyna-Pilze bekommen. Wer zuerst kommt, mahlt zuerst!',
    'What\'s this? Are you trying to show you\'re stronger than me? How distasteful! I find your presence most disturbing! You show up at the dojo unannounced and go on to show such talent, even though you\'re still so young... You dare get in my way? I warned you about my psychic powers, and now you\'ll experience them firsthand!': 'Was soll das? Willst du etwa zeigen, dass du stärker bist als ich? Wie geschmacklos! Deine Anwesenheit stört mich zutiefst! Du tauchst unangemeldet im Dojo auf und zeigst so viel Talent, obwohl du noch so jung bist ... Du wagst es, dich mir in den Weg zu stellen? Ich habe dich vor meinen Psychokräften gewarnt, und jetzt wirst du sie am eigenen Leib erfahren!',
    'Behold! Before you stands Urshifu! Sure to be unyielding armor that will shatter any blade turned against it... And it has mastered the styles of darkness and water!': 'Siehe da! Vor dir steht [[pokemon::Urshifu]]! Gewiss eine unnachgiebige Rüstung, die jede gegen sie gerichtete Klinge zerschmettert ... Und es hat die Stile der Dunkelheit und des Wassers gemeistert!',
    'Ha! You\'ve certainly grown, haven\'t you? And to think, not long ago you would\'ve run and hid behind me the moment you got scared! Indeed, no matter how old I get, witnessing someone grow always brings joy to my heart. Urshifu! And you as well! Thank you both, from the bottom of my heart.': 'Ha! Du bist wirklich gewachsen, was? Und wenn man bedenkt, dass du dich vor nicht allzu langer Zeit noch hinter mir versteckt hättest, sobald du Angst bekamst! Wahrlich, egal wie alt ich werde, es erfüllt mein Herz immer mit Freude, jemanden wachsen zu sehen. [[pokemon::Urshifu]]! Und du ebenso! Ich danke euch beiden von ganzem Herzen.',
    'Wow! The Crown Tundra is filled with wild fossil Pokémon! I\'ve heard stories of these snowfields protecting the Pokémon living here, but this level of sanctuary is insane!': 'Wow! Die Crown Tundra ist voller wilder Fossil-Pokémon! Ich habe Geschichten gehört, dass diese Schneefelder die hier lebenden Pokémon schützen, aber ein solches Ausmaß an Zuflucht ist unglaublich!',
    'And what\'s really interesting is that they only show up to trainers who have already caught one of their species. Could it be they are aware enough to use that as an appraisal of trust?': 'Und das wirklich Interessante ist, dass sie sich nur Trainern zeigen, die bereits ein Exemplar ihrer Art gefangen haben. Könnte es sein, dass sie bewusst genug sind, um das als Vertrauensbeweis zu werten?',
    'Whew! This place is quite a trek from Freezington.': 'Puh! Von Freezington bis hierher ist es ein ganz schöner Marsch.',
    'I\'ve heard that a rare Pokémon sometimes hides in the chests here. I was told that it is incredibly rare, but can\'t be found anywhere else!': 'Ich habe gehört, dass sich in den Truhen hier manchmal ein seltenes Pokémon versteckt. Mir wurde gesagt, dass es unglaublich selten ist, aber nirgendwo sonst zu finden ist!',
    'Finally, my loyal steeds have returned to me. There are truly no words with which to fully express my gratitude to you. But I can try. Take these Reins of Unity.': 'Endlich sind meine treuen Rösser zu mir zurückgekehrt. Es gibt wahrlich keine Worte, mit denen ich dir meine Dankbarkeit vollständig ausdrücken könnte. Doch ich kann es versuchen. Nimm dieses Band des Bundes.',
    'They can be used to combine myself and my steeds. However, they are incomplete. You must intertwine the hair from their manes for them to work. I expect they will occasionally leave such hair behind upon being defeated.': 'Mit ihm können meine Rösser und ich vereint werden. Es ist jedoch unvollständig. Du musst das Haar ihrer Mähnen hineinflechten, damit es wirkt. Ich vermute, dass sie solches Haar gelegentlich zurücklassen, wenn sie besiegt werden.',
    'And to that point... I have a suggestion. If you are able to capture me, it will prove your worth beyond any doubt, and I will lend you my strength on your journey. Once you have readied yourself, come face me!': 'Und in diesem Zusammenhang ... habe ich einen Vorschlag. Wenn du es schaffst, mich zu fangen, beweist das deinen Wert ohne jeden Zweifel, und ich werde dir auf deiner Reise meine Kraft leihen. Sobald du bereit bist, tritt mir entgegen!',
    '<i>Human child... I look forward to what adventures we might have together.</i>': '<i>Menschenkind ... Ich freue mich auf die Abenteuer, die wir gemeinsam erleben werden.</i>',
    '<i>May I remind you, if you ever wish to return my steeds and I to our true power, you must gather some hair from the manes of my steeds as they roam the Crown Tundra, and intertwine such hair with the Reins of Unity.</i>': '<i>Darf ich dich daran erinnern: Wenn du meinen Rössern und mir jemals unsere wahre Kraft zurückgeben möchtest, musst du etwas Haar von den Mähnen meiner Rösser sammeln, während sie durch die Crown Tundra streifen, und es in das Band des Bundes flechten.</i>',
    'I\'m sure you\'ll have noticed that there\'s quite a few Gigantamax Pokémon. As more get here, it\'s going to get progressively harder to find the one you want.': 'Dir ist bestimmt aufgefallen, dass es ziemlich viele Gigadynamax-Pokémon gibt. Je mehr hierherkommen, desto schwieriger wird es, das zu finden, das du suchst.',
    'I have some good news for you though! It seems that those you\'ve already caught will show up less often. That should make it easier to catch \'em all!': 'Ich habe aber gute Neuigkeiten für dich! Es scheint, dass diejenigen, die du schon gefangen hast, seltener auftauchen. Das sollte es leichter machen, sie alle zu fangen!',
    'You\'re back! So I take it you saw one? A Gigantamax Pikachu, huh? Yeah, I saw one of those too! I also saw 2 others: Meowth and Eevee. Maybe you\'ll see them when you go back in.': 'Du bist zurück! Dann hast du also eins gesehen? Ein Gigadynamax-[[pokemon::Pikachu]], was? Ja, so eins hab ich auch gesehen! Ich hab auch noch 2 andere gesehen: [[pokemon::Meowth]] und [[pokemon::Eevee]]. Vielleicht siehst du sie, wenn du wieder reingehst.',
    'Unfortunately, it seems these 3 are the only ones here at the moment. However, there\'s something you could do if you want to lure in more of them.': 'Leider scheinen diese 3 im Moment die einzigen hier zu sein. Aber es gibt etwas, das du tun kannst, wenn du mehr von ihnen anlocken willst.',
    'I imagine you\'ve noticed some hexagonal rock formations on your journey, right? Those are called Raid Dens. You can find them in the mainland\'s Wild Area, the Isle of Armor, and here in the Crown Tundra.': 'Dir sind auf deiner Reise bestimmt schon ein paar sechseckige Felsformationen aufgefallen, oder? Das sind sogenannte Raid-Nester. Du findest sie in der Wild Area auf dem Festland, auf der Isle of Armor und hier in der Crown Tundra.',
    'Every day some of them glow red and emit a purple beam. It seems there are 10 a day, consistently, for some unknown reason. Here, download this app, and they\'ll show up on your map!': 'Jeden Tag leuchten einige von ihnen rot und senden einen lila Strahl aus. Aus irgendeinem unbekannten Grund sind es immer genau 10 pro Tag. Hier, lad dir diese App runter, dann werden sie dir auf deiner Karte angezeigt!',
    'Anyway, in each of these Raid Dens, there\'s a Gigantamax Pokémon! You can\'t catch \'em though, they\'ll turn back to their regular form and run before you get the chance.': 'Jedenfalls ist in jedem dieser Raid-Nester ein Gigadynamax-Pokémon! Fangen kannst du sie aber nicht, sie verwandeln sich in ihre normale Form zurück und hauen ab, bevor du die Chance dazu hast.',
    'However! They\'ll each drop a stone called a Wishing Piece. If you gather enough of those stones here, more Gigantamax Pokémon\'ll show up! Dunno which ones, probably just your luck.': 'Allerdings! Sie lassen jeweils einen Stein namens Wunschstück fallen. Wenn du genug von diesen Steinen hier sammelst, tauchen mehr Gigadynamax-Pokémon auf! Keine Ahnung, welche, wahrscheinlich reine Glückssache.',
    'Including the 3 already here, there are 33 Gigantamax Pokémon. I imagine you\'ll need more than 200 Wishing Pieces to get all of \'em to show up.': 'Mit den 3, die schon hier sind, gibt es 33 Gigadynamax-Pokémon. Ich schätze, du brauchst mehr als 200 Wunschstücke, damit sie alle auftauchen.',
    'They\'re all here! That took quite a while, but it was well worth it!': 'Sie sind alle hier! Das hat ganz schön gedauert, aber es hat sich echt gelohnt!',
    'Hey, what\'s that purple glow? It looks to be around... Hammerlocke?': 'Hey, was ist das für ein lila Leuchten? Sieht so aus, als wäre es ungefähr bei ... Hammerlocke?',
    'Hang on, this looks a lot like when uncle Rose started the Darkest Day! You were the one who stopped that whole thing, right? You should probably get going!': 'Moment, das sieht ziemlich danach aus, wie damals, als Onkel Rose den Tag der Finsternis ausgelöst hat! Du warst doch derjenige, der das Ganze aufgehalten hat, oder? Du solltest dich wohl besser auf den Weg machen!',
    'So it really was Eternatus again? Given that the purple glow has vanished, I guess you\'ve already taken care of it. Congrats!': 'Es war also wirklich wieder [[pokemon::Eternatus]]? Da das lila Leuchten verschwunden ist, hast du dich wohl schon darum gekümmert. Glückwunsch!',
    'Actually, I just saw some purple and red Pokémon fly into the caves. Maybe that was Eternatus? I think this place might let it return to its Eternamax form. Maybe you can catch it!': 'Übrigens, ich hab gerade ein paar lila-rote Pokémon in die Höhlen fliegen sehen. Vielleicht war das [[pokemon::Eternatus]]? Ich glaube, an diesem Ort kann es wieder seine Unendynamax-Form annehmen. Vielleicht kannst du es fangen!',
    'At any rate, I\'m real thankful for all your help. There\'s so many more people coming here now there\'s more Gigantamax Pokémon to find.  It\'s been a lot of fun!': 'Jedenfalls bin ich dir echt dankbar für all deine Hilfe. Jetzt kommen so viel mehr Leute hierher, weil es mehr Gigadynamax-Pokémon zu finden gibt.  Es hat echt viel Spaß gemacht!',
    'I\'ve just been told of the foul plan Volo had concocted. Well, think no more on that scoundrel. Just another tale of passion burning too bright and consuming its bearer. This is what happens, if you allow it to.': 'Man hat mir gerade von dem niederträchtigen Plan erzählt, den Volo ausgeheckt hatte. Nun, verschwende keinen Gedanken mehr an diesen Schurken. Nur eine weitere Geschichte von einer Leidenschaft, die zu hell brennt und ihren Träger verzehrt. Das geschieht, wenn man es zulässt.',
    'But what of you? Are you making any progress with your...what do you call your studies of Pokémon? Surveying, was it?': 'Aber was ist mit dir? Machst du Fortschritte mit deinen ... wie nennst du deine Studien über Pokémon noch gleich? Forschung, war es?',
    'Indeed? Well, Hisui still holds more fascinating Pokémon.': 'Tatsächlich? Nun, Hisui birgt noch weitere faszinierende Pokémon.',
    'Such as Tornadus... In every direction it flies, stirring up tremendous storms as it goes. When a blizzard batters the Alabaster Icelands, Tornadus may be about.': 'Wie zum Beispiel [[pokemon::Tornadus]] ... Es fliegt in alle Richtungen und entfacht dabei gewaltige Stürme. Wenn ein Schneesturm über die Alabaster Icelands fegt, ist [[pokemon::Tornadus]] vielleicht in der Nähe.',
    'Also, Thundurus: as it flies around, it fires bolts of lightning every which way. When a rainstorm lashes the Cobalt Coastlands, Tornadus may be about.': 'Außerdem [[pokemon::Thundurus]]: Während es umherfliegt, schleudert es Blitze in alle Richtungen. Wenn ein Gewitterregen über die Cobalt Coastlands peitscht, ist [[pokemon::Tornadus]] vielleicht in der Nähe.',
    'Lastly, Landorus, the Pokémon hailed as the Guardian of the Fields. It seems it can be glimpsed in the Obsidian Fieldlands. Perhaps you\'d be so good as to catch it for me?': 'Und zuletzt [[pokemon::Landorus]], das Pokémon, das als Hüter der Felder gepriesen wird. Es scheint, dass man es in den Obsidian Fieldlands erblicken kann. Wärst du vielleicht so gut, es für mich zu fangen?',
    'I know not why these three have chosen to show themselves. Perhaps the cause lies with the space-time rift...or simply within their own whims...': 'Ich weiß nicht, warum sich diese drei entschieden haben, sich zu zeigen. Vielleicht liegt die Ursache beim Raum-Zeit-Riss ... oder einfach in ihren eigenen Launen ...',
    'Ah, you\'ve arrived. You now know much about Landorus, Tornadus and even Thundurus. Well done.': 'Ah, du bist angekommen. Du weißt nun viel über [[pokemon::Landorus]], [[pokemon::Tornadus]] und sogar [[pokemon::Thundurus]]. Gut gemacht.',
    'In more normal times, I would bid you to let these three fly free as is their nature.': 'In gewöhnlicheren Zeiten würde ich dich bitten, diese drei frei fliegen zu lassen, wie es ihrer Natur entspricht.',
    'But we are fresh from the tearing of the space-time rift. Until its aftereffects fade entirely, perhaps its best to keep our trio contained.': 'Doch der Raum-Zeit-Riss hat sich erst kürzlich aufgetan. Bis seine Nachwirkungen gänzlich verklungen sind, ist es vielleicht das Beste, unser Trio unter Kontrolle zu halten.',
    'And now, it is time to tell you the rest. There is one more of that cohort. Come.': 'Und nun ist es an der Zeit, dir den Rest zu erzählen. Es gibt noch eine weitere aus dieser Gruppe. Komm.',
    'This is Enamorus, a Pokémon hailed as the Herald of Spring. Enamorus is not particularly given to ill behaviour. But I imagine you\'d like to document her for your Pokédex, wouldn\'t you?': 'Das ist [[pokemon::Enamorus]], ein Pokémon, das als Frühlingsbotin gepriesen wird. [[pokemon::Enamorus]] neigt nicht sonderlich zu schlechtem Benehmen. Aber ich nehme an, du möchtest sie für deinen Pokédex erfassen, nicht wahr?',
    'Catch her then, if you like. She always flits about in the Crimson Mirelands.': 'Dann fang sie, wenn du möchtest. Sie flattert stets in den Crimson Mirelands umher.',
    'Aha, you\'ve caught Enamorus as well. And you know so much about her.': 'Aha, du hast also auch [[pokemon::Enamorus]] gefangen. Und du weißt so viel über sie.',
    'Enamorus arrives in Hisui once winter has passed. Hence the epithet Herald of Spring.': '[[pokemon::Enamorus]] kommt nach Hisui, sobald der Winter vorüber ist. Daher der Beiname Frühlingsbotin.',
    'Her company, when I have the pleasure, is of great help, she ferries me hither and yon across Hisui. But I\'ll leave her in your care for now, I suppose.': 'Ihre Gesellschaft, wenn ich das Vergnügen habe, ist mir eine große Hilfe, sie trägt mich kreuz und quer durch Hisui. Aber ich überlasse sie wohl vorerst deiner Obhut.',
    'Indeed, even you can hardly expect to live for all time, surely, but she will be in your care for now.': 'Gewiss kannst selbst du kaum erwarten, ewig zu leben, aber vorerst wird sie in deiner Obhut sein.',
    'You, Enamorus and her brethren have something in common: you tend to stir the pot of life. Do not mistake me - I mean this positively.': 'Du, [[pokemon::Enamorus]] und ihre Geschwister habt etwas gemeinsam: Ihr bringt gern Bewegung ins Leben. Versteh mich nicht falsch – ich meine das im positiven Sinne.',
    'If everything were straightforward, what meaning would there be in living as long as we do?': 'Wenn alles einfach wäre, welchen Sinn hätte es dann, so lange zu leben, wie wir es tun?',
    '"Once there was a god of field, and once there was a god of spring. Upon Hisui\'s winds it wheeled, brought life to every growing thing..." Was that how that old verse went?': '"Einst gab es einen Gott der Felder, und einst gab es einen Gott des Frühlings. Auf Hisuis Winden zog er seine Kreise, brachte Leben allem, was wächst ..." Ging der alte Vers nicht so?',
    'I have passed on to you all there is to pass. Where history goes from here...I leave to you and your companions to see through.': 'Ich habe dir alles weitergegeben, was es weiterzugeben gibt. Wohin die Geschichte von hier aus geht ... das überlasse ich dir und deinen Gefährten.',
    'So Volo finally showed his hand. He sought the Plates so that he might stand before Arceus and remake the world to his liking. Giratina was merely his tool.': 'Volo hat also endlich sein wahres Gesicht gezeigt. Er suchte die Tafeln, um vor [[pokemon::Arceus]] treten und die Welt nach seinem Belieben neu erschaffen zu können. [[pokemon::Giratina]] war bloß sein Werkzeug.',
    'I knew him long before he called himself a merchant of the Ginkgo Guild. I fear I did little to temper that ambition of his.': 'Ich kannte ihn schon lange, bevor er sich einen Händler der Ginkgo-Gilde nannte. Ich fürchte, ich habe wenig getan, um seinen Ehrgeiz zu zügeln.',
    'But you... You were brought to Hisui for a reason, and I suspect Arceus wishes to meet the one it summoned.': 'Aber du ... Du wurdest aus einem bestimmten Grund nach Hisui gebracht, und ich vermute, [[pokemon::Arceus]] möchte dem begegnen, den es gerufen hat.',
    'Legend says the deity split its power into eighteen Plates and scattered them across the land. Many now lie buried deep beneath the earth.': 'Die Legende besagt, dass die Gottheit ihre Kraft auf achtzehn Tafeln aufteilte und sie über das Land verstreute. Viele liegen nun tief unter der Erde begraben.',
    'Dig them up, all eighteen of them, the Blank Plate included. Then come back to me.': 'Grab sie aus, alle achtzehn, einschließlich der Neutraltafel. Dann komm zu mir zurück.',
    'All eighteen Plates... I can feel them humming in your bag. Even the stones of this retreat seem to lean towards you.': 'Alle achtzehn Tafeln ... Ich kann sie in deiner Tasche summen spüren. Selbst die Steine dieses Refugiums scheinen sich dir zuzuneigen.',
    'Take them to the Temple of Sinnoh. Climb to where Dialga and Palkia raged, and lay the Plates before the altar.': 'Bring sie zum Temple of Sinnoh. Steig dorthin hinauf, wo [[pokemon::Dialga]] und [[pokemon::Palkia]] tobten, und lege die Tafeln vor den Altar.',
    'If Arceus deems you worthy, it will descend. Whether it means to test you or to thank you, I cannot say.': 'Wenn [[pokemon::Arceus]] dich für würdig hält, wird es herabsteigen. Ob es dich prüfen oder dir danken will, kann ich nicht sagen.',
    'You met the Original One and it shared a part of itself with you. I have waited a very long time to hear that.': 'Du bist dem Ursprünglichen begegnet, und es hat einen Teil von sich mit dir geteilt. Ich habe sehr lange darauf gewartet, das zu hören.',
    'Hisui will change, as all lands do. The clans, the Galaxy Team, the Pokémon... they will learn to live side by side.': 'Hisui wird sich verändern, wie alle Länder. Die Clans, Team Galaktik, die Pokémon ... sie werden lernen, Seite an Seite zu leben.',
    'Whatever world you return to, remember that its foundations were laid here, by people who once feared the Pokémon they now call partners.': 'In welche Welt du auch zurückkehrst, denk daran, dass ihr Fundament hier gelegt wurde, von Menschen, die einst die Pokémon fürchteten, die sie heute Partner nennen.',
    'Oh, hey! You\'re the new transfer student, right? Welcome to Paldea!': 'Oh, hey! Du bist der neue Austauschschüler, oder? Willkommen in Paldea!',
    'Naranja and Uva Academies are starting their Treasure Hunt, and every student gets to explore the region however they want.': 'Die Akademien Orangerie und Uva starten ihre Schatzsuche, und alle Schüler dürfen die Region erkunden, wie sie wollen.',
    'I\'m going to challenge all eight Gyms again... and I want you to do it too! Beat all eight, then the Elite Four, and we\'ll battle as Champions. Deal?': 'Ich werde wieder alle acht Arenen herausfordern ... und ich will, dass du das auch tust! Besieg alle acht, dann die Top Vier, und dann kämpfen wir als Champs gegeneinander. Abgemacht?',
    'You\'re a student too? Then listen up, I need a hand.': 'Du bist auch Schüler? Dann hör zu, ich brauche Hilfe.',
    'There are five Herba Mystica hidden around Paldea, each guarded by a Titan Pokémon. They\'re the only thing that might heal my partner, Mabosstiff.': 'In Paldea sind fünf Herba Mystica versteckt, die jeweils von einem Herrscher-Pokémon bewacht werden. Sie sind das Einzige, was meinen Partner [[pokemon::Mabosstiff]] vielleicht heilen kann.',
    'Help me take down the Titans and I\'ll make sure you eat well. Deal?': 'Hilf mir, die Herrscher zu besiegen, und ich sorge dafür, dass du gut isst. Abgemacht?',
    'Hey, hey, did you hear? A group of students saw some super rare Pokémon on {ROUTE_NAME}!': 'Hey, hey, hast du schon gehört? Ein paar Schüler haben auf {ROUTE_NAME} ein paar super seltene Pokémon gesehen!',
    '<i>A message pops up on your phone from someone calling themselves Cassiopeia.</i>': '<i>Auf deinem Handy erscheint eine Nachricht von jemandem, der sich Cassiopeia nennt.</i>',
    'Team Star started as a group of kids who were bullied at this academy. Now they\'re the ones scaring everyone away.': 'Team Star hat als Gruppe von Schülern angefangen, die an dieser Akademie gemobbt wurden. Jetzt sind sie es, die alle anderen verscheuchen.',
    'Operation Starfall: take down all five Team Star bosses at their bases. I\'ll back you up with everything I\'ve got.': 'Operation Sternensturz: Besieg alle fünf Team-Star-Bosse in ihren Basen. Ich unterstütze dich mit allem, was ich habe.',
    '<i>A voice crackles over the intercom at the Zero Gate.</i>': '<i>Eine Stimme knistert aus der Sprechanlage am Zero Gate.</i>',
    'You\'ve come a long way, all of you. Nemona, Arven, Penny... and you.': 'Ihr habt einen weiten Weg zurückgelegt, ihr alle. Nemila, Arven, Penny ... und du.',
    'I need you to come down to the Zero Lab at the very bottom of Area Zero. There is something only you can stop. Please hurry.': 'Du musst zum Zero Lab ganz unten in der Area Zero kommen. Es gibt etwas, das nur du aufhalten kannst. Bitte beeil dich.',
    'So you\'re the hotshot from Naranja and Uva. Welcome to Kitakami, I guess.': 'Du bist also das Ass von Orangerie und Uva. Willkommen in Kitakami, schätze ich.',
    'Folks here tell an old story about the Loyal Three, heroes who protected the village from a terrible ogre. There\'s a festival for them and everything.': 'Die Leute hier erzählen eine alte Geschichte über die Treuen Drei, Helden, die das Dorf vor einem schrecklichen Unhold beschützt haben. Es gibt sogar ein Fest für sie und alles.',
    'My little brother Kieran\'s obsessed with that ogre. Don\'t encourage him. Now, how about you prove you\'re actually any good?': 'Mein kleiner Bruder Kieran ist total besessen von diesem Unhold. Ermutige ihn bloß nicht. Und jetzt beweis doch mal, ob du wirklich was draufhast.',
    'So Ogerpon chose you, huh. Kieran\'s taking it hard... but he\'ll get over it. Probably.': '[[pokemon::Ogerpon]] hat sich also für dich entschieden, was. Kieran nimmt das ziemlich schwer ... aber er kommt drüber hinweg. Wahrscheinlich.',
    'Hey, our school is Blueberry Academy, out in Unova. If you ever visit, I\'ll show you around. Kieran too, once he stops sulking.': 'Hey, unsere Schule ist die Blueberry Academy, drüben in Unova. Wenn du mal vorbeikommst, zeig ich dir alles. Kieran auch, sobald er aufhört zu schmollen.',
    'The Loyal Three... they weren\'t heroes at all. They stole the masks and blamed the ogre. The ogre is Ogerpon, and it was only trying to protect its family.': 'Die Treuen Drei ... sie waren überhaupt keine Helden. Sie haben die Masken gestohlen und dem Unhold die Schuld gegeben. Der Unhold ist [[pokemon::Ogerpon]], und es wollte nur seine Familie beschützen.',
    'Everyone has had it backwards for hundreds of years.': 'Hunderte von Jahren haben alle es falsch herum verstanden.',
    'With the Loyal Three gone, Ogerpon can finally rest. I... I want to catch it. But maybe it wants to go with you.': 'Jetzt, wo die Treuen Drei fort sind, kann [[pokemon::Ogerpon]] endlich Ruhe finden. Ich ... ich will es fangen. Aber vielleicht will es lieber mit dir gehen.',
    'Something weird is going on in Kitakami. Everybody\'s eating these strange mochi and acting like puppets!': 'In Kitakami geht irgendwas Seltsames vor. Alle essen diese merkwürdigen Mochi und benehmen sich wie Marionetten!',
    'Even the Loyal Three are back, and they look... possessed. Can you go catch them before they cause real trouble?': 'Sogar die Treuen Drei sind zurück, und sie sehen ... besessen aus. Kannst du sie fangen, bevor sie echten Ärger machen?',
    'The mochi spell is broken! Everyone\'s back to normal, and that little troublemaker Pecharunt is with you now.': 'Der Mochi-Bann ist gebrochen! Alle sind wieder normal, und dieser kleine Unruhestifter [[pokemon::Pecharunt]] ist jetzt bei dir.',
    'Guess even poison peaches deserve a second chance. Thanks for saving the village... again.': 'Schätze, selbst giftige Pfirsiche verdienen eine zweite Chance. Danke, dass du das Dorf gerettet hast ... schon wieder.',
    'Welcome to Blueberry Academy! Our school is all about the Terarium, a giant dome with four biomes full of Pokémon.': 'Willkommen an der Blueberry Academy! Bei unserer Schule dreht sich alles um das Terrarium, eine riesige Kuppel mit vier Biomen voller Pokémon.',
    'And this is the League Club. Students battle all day to climb the BB League ranks. Kieran is the Champion now... he\'s changed a lot since Kitakami.': 'Und das hier ist der Liga-Club. Die Schüler kämpfen den ganzen Tag, um in der Rangliste der Blueberry-Liga aufzusteigen. Kieran ist jetzt der Champ ... er hat sich seit Kitakami sehr verändert.',
    'If you want to get to him, you\'ll have to beat the Elite Four first: Crispin, Amarys, Lacey and Drayton.': 'Wenn du zu ihm willst, musst du zuerst die Top Vier besiegen: Crispin, Amarys, Lacey und Drayton.',
    'Oh my! You beat Kieran! You must be the one I\'ve been waiting for!': 'Oh je! Du hast Kieran besiegt! Du musst diejenige Person sein, auf die ich gewartet habe!',
    'I\'m Briar, a descendant of Heath, who wrote the Scarlet and Violet Books. There\'s a place even deeper than the Zero Lab: the Area Zero Underdepths.': 'Ich bin Briar, eine Nachfahrin von Heath, der die Bücher Karmesin und Purpur geschrieben hat. Es gibt einen Ort, der noch tiefer liegt als das Zero Lab: die Area Zero Underdepths.',
    'Legend says the Terastal phenomenon begins there, with a Pokémon called Terapagos. Will you join my expedition?': 'Der Legende nach beginnt dort das Terakristall-Phänomen, mit einem Pokémon namens [[pokemon::Terapagos]]. Schließt du dich meiner Expedition an?',
    'Terapagos... the Stellar form... I can hardly believe I saw it with my own eyes!': '[[pokemon::Terapagos]] ... die Stellarform ... Ich kann kaum glauben, dass ich sie mit eigenen Augen gesehen habe!',
    'Heath\'s book was right all along. Thank you for helping me finish what my ancestor started.': 'Heaths Buch hatte die ganze Zeit recht. Danke, dass du mir geholfen hast, zu vollenden, was mein Vorfahr begonnen hat.',
    'And Kieran... I think he finally found something more important than winning.': 'Und Kieran ... Ich glaube, er hat endlich etwas gefunden, das wichtiger ist als das Gewinnen.',
    // Professors, Berry Master hints and other generated NPC texts
    'Congratulations on completing your Kanto Pokédex!': 'Herzlichen Glückwunsch zur Vervollständigung deines Kanto-Pokédex!',
    'Your journey isn\'t over yet, a whole world awaits you! Onwards to Johto!': 'Deine Reise ist noch nicht zu Ende, eine ganze Welt wartet auf dich! Auf nach Johto!',
    'Oh, another regional Pokédex completed so soon?': 'Oh, schon wieder ein regionaler Pokédex vervollständigt?',
    'Amazing! Next stop is Hoenn, enjoy the sunshine while you\'re there!': 'Unglaublich! Nächster Halt ist Hoenn – genieß dort den Sonnenschein!',
    'Oh? Some of your Pokémon may find an extra egg if left in the hatchery. Would you care to find out what baby will hatch?': 'Oh? Einige deiner Pokémon finden vielleicht ein zusätzliches Ei, wenn du sie in der Brutstation lässt. Möchtest du herausfinden, welches Baby schlüpfen wird?',
    'That\'s another regional Pokédex completed! Fantastic.': 'Und wieder ein regionaler Pokédex vervollständigt! Fantastisch.',
    'I really appreciate being able to see your outstanding progress, thank you! Sinnoh is next up.': 'Ich bin wirklich dankbar, deine herausragenden Fortschritte sehen zu dürfen, danke! Als Nächstes ist Sinnoh dran.',
    'Congratulations, you\'re more than half-way completed on the national Pokédex!': 'Herzlichen Glückwunsch, du hast den nationalen Pokédex schon zu mehr als der Hälfte vervollständigt!',
    'Next stop is Unova! I\'ve always wanted to visit Castelia City, personally...': 'Nächster Halt ist Einall! Ich persönlich wollte schon immer mal Castelia City besuchen ...',
    'Speaking of Pokémon! How\'s your Pokédex coming along? Wow! You have so many Pokémon that can evolve!': 'Apropos Pokémon! Wie läuft\'s mit deinem Pokédex? Wow! Du hast so viele Pokémon, die sich entwickeln können!',
    'Let me see your progress...Ah, fantastic, as usual!': 'Lass mich deine Fortschritte sehen ... Ah, fantastisch, wie immer!',
    'Allow me some time to arrange tickets for your next destination.': 'Gib mir etwas Zeit, die Tickets für dein nächstes Reiseziel zu besorgen.',
    'You\'re encountering Pokémon at a really good clip, aren\'t you? Congratulations! You completed the Pokédex!': 'Du begegnest Pokémon in einem echt beachtlichen Tempo, oder? Herzlichen Glückwunsch! Du hast den Pokédex vervollständigt!',
    'Onward to Alola, shall we?': 'Wollen wir weiter nach Alola?',
    'This is truly an astounding feat! Congratulations on completing the Pokédex!': 'Das ist wahrlich eine erstaunliche Leistung! Herzlichen Glückwunsch zur Vervollständigung des Pokédex!',
    'With that, you can stamp your ticket to the noble Galar region!': 'Damit kannst du dein Ticket in die edle Galar-Region abstempeln lassen!',
    'Ahhh, how incredible. Look how far you have come, dear trainer. Congratulations on another complete Pokédex.': 'Ahhh, wie unglaublich. Sieh nur, wie weit du gekommen bist, lieber Trainer. Herzlichen Glückwunsch zu einem weiteren vollständigen Pokédex.',
    'Strange tears in space and time have been sighted over the sea. Those who pass through speak of Hisui, the land of old Sinnoh, long before Poké Balls were common. Be on your way, trainer!': 'Über dem Meer wurden seltsame Risse in Raum und Zeit gesichtet. Wer hindurchgeht, erzählt von Hisui, dem Land des alten Sinnoh, lange bevor Pokébälle verbreitet waren. Mach dich auf den Weg, Trainer!',
    'Splendid! Simply splendid! A complete Pokédex of Hisui... I shall have to write a dozen papers on the back of your research alone!': 'Großartig! Einfach großartig! Ein vollständiger Pokédex von Hisui ... Allein auf Grundlage deiner Forschung werde ich ein Dutzend Abhandlungen schreiben müssen!',
    'I\'ve heard whispers that the rift is opening once more, this time towards a sunny land far in the future called Paldea. It seems your journey isn\'t over yet!': 'Man munkelt, dass sich der Riss erneut öffnet, diesmal zu einem sonnigen Land weit in der Zukunft namens Paldea. Es scheint, als wäre deine Reise noch nicht zu Ende!',
    'I\'ve heard that growing Pecha and Oran Berries near each other will produce something interesting!': 'Ich habe gehört, dass Pirsif- und Sinelbeeren, die nahe beieinander wachsen, etwas Interessantes hervorbringen!',
    'I\'ve heard that growing Cheri and Leppa Berries near each other will produce something interesting!': 'Ich habe gehört, dass Kirschu- und Jonagobeeren, die nahe beieinander wachsen, etwas Interessantes hervorbringen!',
    'I\'ve heard that growing Chesto and Leppa Berries near each other will produce something interesting!': 'Ich habe gehört, dass Maron- und Jonagobeeren, die nahe beieinander wachsen, etwas Interessantes hervorbringen!',
    'I\'ve heard that growing Pecha and Aspear Berries near each other will produce something interesting!': 'Ich habe gehört, dass Pirsif- und Wilbirbeeren, die nahe beieinander wachsen, etwas Interessantes hervorbringen!',
    'I\'ve heard that growing Rawst and Oran Berries near each other will produce something interesting!': 'Ich habe gehört, dass Fragia- und Sinelbeeren, die nahe beieinander wachsen, etwas Interessantes hervorbringen!',
    'I\'ve heard that growing Sitrus and Aspear Berries near each other will produce something interesting!': 'Ich habe gehört, dass Tsitru- und Wilbirbeeren, die nahe beieinander wachsen, etwas Interessantes hervorbringen!',
    'I\'ve heard that a special Berry can appear if its surroundings get too spicy!': 'Ich habe gehört, dass eine besondere Beere erscheinen kann, wenn ihre Umgebung zu scharf wird!',
    'I\'ve heard that a special Berry can appear if its surroundings get too dry!': 'Ich habe gehört, dass eine besondere Beere erscheinen kann, wenn ihre Umgebung zu trocken wird!',
    'I\'ve heard that a special Berry can appear if its surroundings get too sweet!': 'Ich habe gehört, dass eine besondere Beere erscheinen kann, wenn ihre Umgebung zu süß wird!',
    'I\'ve heard that a special Berry can appear if its surroundings get too bitter!': 'Ich habe gehört, dass eine besondere Beere erscheinen kann, wenn ihre Umgebung zu bitter wird!',
    'I\'ve heard that a special Berry can appear if its surroundings get too sour!': 'Ich habe gehört, dass eine besondere Beere erscheinen kann, wenn ihre Umgebung zu sauer wird!',
    'I\'ve heard that there\'s a legendary Berry that only appears when fully surrounded by the 8 different Berries that wild Pokémon hold!': 'Ich habe gehört, dass es eine legendäre Beere gibt, die nur erscheint, wenn sie vollständig von den 8 verschiedenen Beeren umgeben ist, die wilde Pokémon tragen!',
    'I\'ve heard that growing Iapapa and Mago Berries near each other will produce something interesting!': 'Ich habe gehört, dass Yapa- und Magobeeren, die nahe beieinander wachsen, etwas Interessantes hervorbringen!',
    'I\'ve heard that growing Chesto and Persim Berries near each other will produce something interesting!': 'Ich habe gehört, dass Maron- und Persimbeeren, die nahe beieinander wachsen, etwas Interessantes hervorbringen!',
    'I\'ve heard that a special Berry can appear if its surroundings match its flavor profile! If I recall, it tasted a little spicy, a little sweet, and a little sour at the same time.': 'Ich habe gehört, dass eine besondere Beere erscheinen kann, wenn ihre Umgebung zu ihrem Geschmacksprofil passt! Wenn ich mich recht erinnere, schmeckte sie gleichzeitig ein wenig scharf, ein wenig süß und ein wenig sauer.',
    'I\'ve heard that a special Berry can appear if its surroundings match its flavor profile! If I recall, it tasted fairly spicy, dry, and bitter at the same time.': 'Ich habe gehört, dass eine besondere Beere erscheinen kann, wenn ihre Umgebung zu ihrem Geschmacksprofil passt! Wenn ich mich recht erinnere, schmeckte sie gleichzeitig ziemlich scharf, trocken und bitter.',
    'I\'ve heard that growing Aguav and Figy Berries near each other will produce something interesting!': 'Ich habe gehört, dass Gauve- und Giefebeeren, die nahe beieinander wachsen, etwas Interessantes hervorbringen!',
    'I\'ve heard that growing Razz Berries near Pomeg Berries can cause it to change!': 'Ich habe gehört, dass Himmihbeeren sich verändern können, wenn Grannabeeren in ihrer Nähe wachsen!',
    'I\'ve heard that growing Leppa, Bluk and Wiki Berries near each other will produce something interesting!': 'Ich habe gehört, dass Jonago-, Morb- und Wikibeeren, die nahe beieinander wachsen, etwas Interessantes hervorbringen!',
    'I\'ve heard that growing Pecha, Nanab and Mago Berries near each other will produce something interesting!': 'Ich habe gehört, dass Pirsif-, Nanab- und Magobeeren, die nahe beieinander wachsen, etwas Interessantes hervorbringen!',
    'I\'ve heard that growing Aspear Berries near Aguav Berries can cause it to change!': 'Ich habe gehört, dass Wilbirbeeren sich verändern können, wenn Gauvebeeren in ihrer Nähe wachsen!',
    'I\'ve heard that growing Wepear and Pinap Berries near each other will produce something interesting!': 'Ich habe gehört, dass Nirbe- und Sananabbeeren, die nahe beieinander wachsen, etwas Interessantes hervorbringen!',
    'I\'ve heard that a Tamato berry will change if its surroundings get extremely spicy!': 'Ich habe gehört, dass sich eine Tamotbeere verändert, wenn ihre Umgebung extrem scharf wird!',
    'I\'ve heard that a Cornn berry will change if its surroundings get extremely dry!': 'Ich habe gehört, dass sich eine Saimbeere verändert, wenn ihre Umgebung extrem trocken wird!',
    'I\'ve heard that growing Pamtre Berries can spread a new Berry into nearby empty plots!': 'Ich habe gehört, dass Pallmbeeren eine neue Beere auf leere Felder in der Nähe verbreiten können!',
    'I\'ve heard that a Magost berry will change if its surroundings get extremely sweet!': 'Ich habe gehört, dass sich eine Magostbeere verändert, wenn ihre Umgebung extrem süß wird!',
    'I\'ve heard that a Rabuta berry will change if its surroundings get extremely bitter!': 'Ich habe gehört, dass sich eine Rabutabeere verändert, wenn ihre Umgebung extrem bitter wird!',
    'I\'ve heard that a Nomel berry will change if its surroundings get extremely sour!': 'Ich habe gehört, dass sich eine Tronzibeere verändert, wenn ihre Umgebung extrem sauer wird!',
    'I\'ve heard that there\'s a special Pink Berry that only appears when surrounded by a bunch of different types of Pink Berries!': 'Ich habe gehört, dass es eine besondere rosa Beere gibt, die nur erscheint, wenn sie von vielen verschiedenen rosa Beeren umgeben ist!',
    'I\'ve heard that growing Razz, Figy, Tamato and Spelon Berries near each other will produce something interesting!': 'Ich habe gehört, dass Himmih-, Giefe-, Tamot- und Kiwanbeeren, die nahe beieinander wachsen, etwas Interessantes hervorbringen!',
    'I\'ve heard that growing some Berries near Occa Berries can cause it to change!': 'Ich habe gehört, dass Koakobeeren sich verändern können, wenn bestimmte Beeren in ihrer Nähe wachsen!',
    'I\'ve heard that growing Oran, Chesto, Kelpsy and Coba Berries near each other will produce something interesting!': 'Ich habe gehört, dass Sinel-, Maron-, Setang- und Kobabeeren, die nahe beieinander wachsen, etwas Interessantes hervorbringen!',
    'I\'ve heard that growing Pinap, Iapapa, Qualot and Grepa Berries near each other will produce something interesting!': 'Ich habe gehört, dass Sananab-, Yapa-, Qualot- und Labrusbeeren, die nahe beieinander wachsen, etwas Interessantes hervorbringen!',
    'I\'ve heard that a special Berry can appear if its surroundings match its flavor profile! If I recall, it tasted a little spicy and fairly bitter at the same time.': 'Ich habe gehört, dass eine besondere Beere erscheinen kann, wenn ihre Umgebung zu ihrem Geschmacksprofil passt! Wenn ich mich recht erinnere, schmeckte sie gleichzeitig ein wenig scharf und ziemlich bitter.',
    'I\'ve heard that growing Rindo Berries can spread a new Berry into nearby empty plots!': 'Ich habe gehört, dass Grindobeeren eine neue Beere auf leere Felder in der Nähe verbreiten können!',
    'I\'ve heard that growing a Passho Berry alone will cause it to change!': 'Ich habe gehört, dass sich eine Foepasbeere verändert, wenn sie ganz allein wächst!',
    'I\'ve heard that growing a Spelon Berry beside exactly three of its kind, with nothing else growing nearby, will cause it to change, especially when using the Magma Stone!': 'Ich habe gehört, dass sich eine Kiwanbeere verändert, wenn sie neben genau drei Beeren ihrer Art wächst und sonst nichts in der Nähe wächst – besonders, wenn man den Magmastein benutzt!',
    'I\'ve heard that growing a Pamtre Berry beside exactly three of its kind, with nothing else growing nearby, will cause it to change, especially when using the Rocky Helmet!': 'Ich habe gehört, dass sich eine Pallmbeere verändert, wenn sie neben genau drei Beeren ihrer Art wächst und sonst nichts in der Nähe wächst – besonders, wenn man den Beulenhelm benutzt!',
    'I\'ve heard that growing some Berries near Kebia Berries can cause it to change!': 'Ich habe gehört, dass Grarzbeeren sich verändern können, wenn bestimmte Beeren in ihrer Nähe wachsen!',
    'I\'ve heard that growing a Watmel Berry beside exactly three of its kind, with nothing else growing nearby, will cause it to change, especially when using the Sprinklotad!': 'Ich habe gehört, dass sich eine Wasmelbeere verändert, wenn sie neben genau drei Beeren ihrer Art wächst und sonst nichts in der Nähe wächst – besonders, wenn man die Sprinklotad benutzt!',
    'I\'ve heard that a special Berry can appear if its surroundings match its flavor profile! If I recall, it tasted a little dry and fairly bitter at the same time.': 'Ich habe gehört, dass eine besondere Beere erscheinen kann, wenn ihre Umgebung zu ihrem Geschmacksprofil passt! Wenn ich mich recht erinnere, schmeckte sie gleichzeitig ein wenig trocken und ziemlich bitter.',
    'I\'ve heard that growing Wiki, Bluk, Cornn and Pamtre Berries near each other will produce something interesting!': 'Ich habe gehört, dass Wiki-, Morb-, Saim- und Pallmbeeren, die nahe beieinander wachsen, etwas Interessantes hervorbringen!',
    'I\'ve heard that a special Berry can appear after being surrounded by Rindo Berries!': 'Ich habe gehört, dass eine besondere Beere erscheinen kann, wenn sie von Grindobeeren umgeben ist!',
    'I\'ve heard that growing a Cornn Berry beside exactly three of its kind, with nothing else growing nearby, will cause it to change, especially when using the Cell Battery!': 'Ich habe gehört, dass sich eine Saimbeere verändert, wenn sie neben genau drei Beeren ihrer Art wächst und sonst nichts in der Nähe wächst – besonders, wenn man den Akku benutzt!',
    'I\'ve heard that growing Occa, Rindo, Passho and Wacan Berries near each other will produce something interesting!': 'Ich habe gehört, dass Koako-, Grindo-, Foepas- und Kerzalbeeren, die nahe beieinander wachsen, etwas Interessantes hervorbringen!',
    'I\'ve heard that growing Rabuta, Kasib and Payapa Berries near each other will produce something interesting!': 'Ich habe gehört, dass Rabuta-, Zitarz- und Pyapabeeren, die nahe beieinander wachsen, etwas Interessantes hervorbringen!',
    'I\'ve heard that growing some Berries near Colbur Berries can cause it to change!': 'Ich habe gehört, dass Burleobeeren sich verändern können, wenn bestimmte Beeren in ihrer Nähe wachsen!',
    'I\'ve heard that a special Berry can appear after being surrounded by Shuca and Charti Berries!': 'Ich habe gehört, dass eine besondere Beere erscheinen kann, wenn sie von Schuke- und Chiaribeeren umgeben ist!',
    'I\'ve heard that Chople Berries will turn into a different Berry if surrounded by more than two of their own kind.': 'Ich habe gehört, dass sich Rospelbeeren in eine andere Beere verwandeln, wenn sie von mehr als zwei Beeren ihrer Art umgeben sind.',
    'I\'ve heard that growing Mago, Nanab, Magost and Watmel Berries near each other will produce something interesting!': 'Ich habe gehört, dass Mago-, Nanab-, Magost- und Wasmelbeeren, die nahe beieinander wachsen, etwas Interessantes hervorbringen!',
    'I\'ve heard of a Berry that can appear in a field of Babiri when Snover are around.': 'Ich habe von einer Beere gehört, die auf einem Feld voller Babiribeeren erscheinen kann, wenn Shnebedeck in der Nähe sind.',
    'I\'ve heard of a Berry that only appears in the driest of fields.': 'Ich habe von einer Beere gehört, die nur auf den trockensten Feldern erscheint.',
    'I\'ve heard of a Berry that only appears in the sweetest of fields.': 'Ich habe von einer Beere gehört, die nur auf den süßesten Feldern erscheint.',
    'I\'ve heard of a Berry that only appears in the most bitter of fields.': 'Ich habe von einer Beere gehört, die nur auf den bittersten Feldern erscheint.',
    'I\'ve heard of a Berry that only appears in the most sour of fields.': 'Ich habe von einer Beere gehört, die nur auf den sauersten Feldern erscheint.',
    'I\'ve heard that growing Liechi and Ganlon Berries near each other will produce something interesting!': 'Ich habe gehört, dass Lydzi- und Linganbeeren, die nahe beieinander wachsen, etwas Interessantes hervorbringen!',
    'I\'ve heard that growing Salac and Petaya Berries near each other will produce something interesting!': 'Ich habe gehört, dass Salka- und Tahaybeeren, die nahe beieinander wachsen, etwas Interessantes hervorbringen!',
    'Legends tell of a mysterious Berry that only appears in a field of Passho Berries and that the power of Kyogre helps reveal.': 'Legenden erzählen von einer mysteriösen Beere, die nur auf einem Feld voller Foepasbeeren erscheint und die durch die Kraft von Kyogre enthüllt wird.',
    'Legends tell of a mysterious Berry that only appears in a field of Shuca Berries and that the power of Groudon helps reveal.': 'Legenden erzählen von einer mysteriösen Beere, die nur auf einem Feld voller Schukebeeren erscheint und die durch die Kraft von Groudon enthüllt wird.',
    'Legends tell of a mysterious Berry that only appears in a field of Coba Berries and that the power of Rayquaza helps reveal.': 'Legenden erzählen von einer mysteriösen Beere, die nur auf einem Feld voller Kobabeeren erscheint und die durch die Kraft von Rayquaza enthüllt wird.',
    'Legends tell of a mysterious Berry that only appears while surrounded by all types of Berries.': 'Legenden erzählen von einer mysteriösen Beere, die nur erscheint, wenn sie von allen Arten von Beeren umgeben ist.',
    'Legends tell of a mysterious Berry that only appears in a field of Chilan Berries and that the power of Palkia helps reveal.': 'Legenden erzählen von einer mysteriösen Beere, die nur auf einem Feld voller Latchibeeren erscheint und die durch die Kraft von Palkia enthüllt wird.',
    'Legends tell of a mysterious Berry that only appears in a field of Roseli Berries and that the power of Dialga helps reveal.': 'Legenden erzählen von einer mysteriösen Beere, die nur auf einem Feld voller Hibisbeeren erscheint und die durch die Kraft von Dialga enthüllt wird.',
    'There\'s a mysterious berry that requires a specific configuration of Berries. However, there\'s still something missing...': 'Es gibt eine mysteriöse Beere, die eine bestimmte Anordnung von Beeren benötigt. Allerdings fehlt noch etwas ...',
    'There\'s a mysterious berry that requires a Durin Berry to the west.': 'Es gibt eine mysteriöse Beere, die eine Durinbeere im Westen benötigt.',
    'I\'ve heard that growing Passho Berries near Enigma Berries can cause it to change!': 'Ich habe gehört, dass Foepasbeeren sich verändern können, wenn Enigmabeeren in ihrer Nähe wachsen!',
    'I\'ve heard that growing Shuca Berries near Enigma Berries can cause it to change!': 'Ich habe gehört, dass Schukebeeren sich verändern können, wenn Enigmabeeren in ihrer Nähe wachsen!',
    'I\'ve heard that growing Coba Berries near Enigma Berries can cause it to change!': 'Ich habe gehört, dass Kobabeeren sich verändern können, wenn Enigmabeeren in ihrer Nähe wachsen!',
    'I\'ve heard that growing Payapa Berries near Enigma Berries can cause it to change!': 'Ich habe gehört, dass Pyapabeeren sich verändern können, wenn Enigmabeeren in ihrer Nähe wachsen!',
    'I\'ve heard that growing Chilan Berries near Enigma Berries can cause it to change!': 'Ich habe gehört, dass Latchibeeren sich verändern können, wenn Enigmabeeren in ihrer Nähe wachsen!',
    'I\'ve heard that growing Roseli Berries near Enigma Berries can cause it to change!': 'Ich habe gehört, dass Hibisbeeren sich verändern können, wenn Enigmabeeren in ihrer Nähe wachsen!',
    'I\'ve heard that growing Haban Berries near Enigma Berries can cause it to change!': 'Ich habe gehört, dass Terirobeeren sich verändern können, wenn Enigmabeeren in ihrer Nähe wachsen!',
    'Legends tell of a mysterious Berry that only appears in a field of Lansat, Apicot, Micle, Custap, Jaboca, Rowap Berries.': 'Legenden erzählen von einer mysteriösen Beere, die nur auf einem Feld voller Lansat-, Apiko-, Wunfru-, Eipfel-, Jaboca- und Roselbeeren erscheint.',
    'I\'ve heard of a Berry that only appears after a Berry plant has withered, but is repelled by Colbur plants.': 'Ich habe von einer Beere gehört, die nur erscheint, nachdem eine Beerenpflanze verwelkt ist, aber von Burleopflanzen abgestoßen wird.',
    'I\'ve heard of a Berry that only appears after a Shiny Pokémon wanders and is caught near open soil.': 'Ich habe von einer Beere gehört, die nur erscheint, nachdem ein schillerndes Pokémon umherstreift und in der Nähe von freiem Boden gefangen wird.',
    'Hello, new Champion, you\'ve come a long way!': 'Hallo, neuer Champ, du hast es weit gebracht!',
    'Come see me once you\'ve beat the Elite Four!': 'Komm zu mir, sobald du die Top Vier besiegt hast!',
    'To progress to the next region, you need to catch all Pokémon native to this region.': 'Um in die nächste Region zu gelangen, musst du alle Pokémon fangen, die in dieser Region heimisch sind.',
    'You still have {COUNT} left to catch in this region! You\'re almost there!': 'Du musst in dieser Region noch {COUNT} fangen! Du hast es fast geschafft!',
    'There haven\'t been any reports of roaming Pokémon around {REGION} lately.': 'In letzter Zeit gab es keine Berichte über umherstreifende Pokémon in {REGION}.',
    'The disciple has surpassed the master. I have nothing more to teach you.': 'Der Schüler hat den Meister übertroffen. Ich kann dir nichts mehr beibringen.',
    'It seems as though you have hit a roadblock in your Berry progress. Focus on other areas before returning.': 'Es scheint, als wärst du bei deinen Beeren-Fortschritten auf ein Hindernis gestoßen. Konzentriere dich auf andere Bereiche, bevor du zurückkehrst.',
};

